window.handleViewRawOcr = (studentUid: string) => {
    const report = assessmentReports.find(r => r.studentUid === studentUid);
    if (!report || !report.fullOcrText) {
        showFeedbackMessage("No raw OCR data available for this report.", "info");
        return;
    }

    const contentBox = document.getElementById('raw-ocr-content-box');
    if (contentBox) {
        // We use textContent to ensure technical tags like [Q:1] or [#P:y,x] aren't parsed as HTML
        contentBox.textContent = report.fullOcrText;
    }
    toggleModal('raw-ocr-modal', true);
};

