interface SpeechRecognitionStatic { new(): SpeechRecognition; }
interface SpeechRecognition extends EventTarget {
  continuous: boolean; lang: string; interimResults: boolean; maxAlternatives: number;
  start(): void; stop(): void; abort(): void;
  onresult: ((this: SpeechRecognition, ev: SpeechRecognitionEvent) => any) | null;
  onerror: ((this: SpeechRecognition, ev: SpeechRecognitionErrorEvent) => any) | null;
  onend: ((this: SpeechRecognition, ev: Event) => any) | null;
}

interface KnowledgeChunk {
    text: string;       // The content/definition
    topic: string;      // Topic Name
    chapter?: string;   // Added: Chapter Name (Optional but good for reference)
    board: string;      // Board Name
    embedding: number[]; // The Vector
}


interface SpeechRecognitionEvent extends Event { readonly results: SpeechRecognitionResultList; }
interface SpeechRecognitionResultList { readonly length: number; item(index: number): SpeechRecognitionResult; }
interface SpeechRecognitionResult { readonly isFinal: boolean; item(index: number): SpeechRecognitionAlternative; }
interface SpeechRecognitionAlternative { readonly transcript: string; }
interface SpeechRecognitionErrorEvent extends Event { readonly error: string; readonly message: string; }

