type QuestionType = 'MCQ' | 'Subjective' | 'Fill in the Blanks' | 'True/False' | 'Competency Based' | 'Case Study' | 'Assertion-Reason';

interface AIQuestion {
    // ── Identity ────────────────────────────────────────────────────────
    id: string;
    questionNumber?: string;

    // ── Core content ─────────────────────────────────────────────────────
    text: string;
    answer?: string;
    marks?: number;
    type: QuestionType;
    options?: string[];
    imagePrompt: string | null;
    imageUrl?: string | null;

    // ── Grading guidance ─────────────────────────────────────────────────
    checkingInstructions?: string;
    topicAnchors?: string[];      // OCR librarian boundary resolver — DO NOT REMOVE

    // ── Rubric ───────────────────────────────────────────────────────────
rubric?: {
    step_marking: string;     // Plain English for grading AI
    keywords?: string[];      // Rubric keyword list, used in full-details PDF
    steps?: Array<{
        marks: number;
        concept: string;      // Taxonomy concept ID e.g. "cm_0023"
    }>;
    // Clean, structured per-step marks — separate from `steps` above (that field is
    // owned by the concept-tagging pass and means something different). Populated
    // only when every step's mark value could be read as a clean number straight
    // from its own Excel column; otherwise omitted and the grader falls back to
    // parsing step_marking exactly as it always has.
    markingSteps?: Array<{
        stepNumber: number;
        description: string;
        marks: number;
    }>;
};

    // ── Analytics ────────────────────────────────────────────────────────
    primaryTopic?: string;        // Single topic e.g. "Depreciation"
    conceptTopics?: string[];     // Taxonomy IDs e.g. ["cm_0022","cm_0023"]
    chapterRef?: string;          // Chapter name e.g. "Chapter 5: Depreciation"

    // ── Structure ────────────────────────────────────────────────────────
    level?: number;
    subQuestions?: AIQuestion[];
    orQuestion?: AIQuestion;
    sectionLabel?: string;
}

