// ─────────────────────────────────────────────────────────────────────────────
// TAXONOMY SERVICE
// Fetches concept nodes from Firestore conceptTaxonomy collection.
// Called once before generation. Returns compact list for the AI prompt.
// ─────────────────────────────────────────────────────────────────────────────

async function fetchTaxonomyNodes(params: {
    subject: string;
    board: string;
    className: string;
    selectedChapters?: string[];
}): Promise<Array<{ id: string; concept: string; chapter: string; topic?: string; skillType?: string; dimension?: string; subjectType: string }>> {
    const { subject, board, className, selectedChapters } = params;

    const classNum = parseInt(className, 10);
    let classRange = '';
    if (classNum >= 9 && classNum <= 10) classRange = '9-10';
    else if (classNum >= 11 && classNum <= 12) classRange = '11-12';
    else classRange = 'Graduation/CA/CS';

    const boardNorm = board?.includes('CA') ? 'CA Foundation' : board;

    try {
        const snapshot = await fbFirestore.collection('conceptTaxonomy')
            .where('subject', '==', subject)
            .get();

        let nodes: any[] = snapshot.docs.map((d: any) => d.data());

        nodes = nodes.filter(n => Array.isArray(n.boards) && n.boards.includes(boardNorm));
        nodes = nodes.filter(n => Array.isArray(n.classRanges) && n.classRanges.includes(classRange));

        if (selectedChapters && selectedChapters.length > 0) {
            const chapterFiltered = nodes.filter(n =>
                selectedChapters.some(ch =>
                    n.chapter?.toLowerCase().includes(ch.toLowerCase()) ||
                    ch.toLowerCase().includes(n.chapter?.toLowerCase() || '')
                )
            );
            if (chapterFiltered.length > 0) nodes = chapterFiltered;
        }

        return nodes.map(n => ({
            id: n.id,
            concept: n.concept || n.dimension || '',
            chapter: n.chapter || '',
            topic: n.topic || '',
            skillType: n.skillType || '',
            dimension: n.dimension || '',
            subjectType: n.subjectType || 'STEM',
        }));
    } catch (e) {
        console.warn('[Taxonomy] Fetch failed, continuing without taxonomy:', e);
        return [];
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// PHASE 2: METADATA EXTRACTION
// Cheap gemini-2.0-flash-lite call after generation.
// Tags questions with primaryTopic, conceptTopics, chapterRef, rubric.steps.
// Non-fatal — if it fails, questions save without concept metadata.
// ─────────────────────────────────────────────────────────────────────────────

async function extractQuestionMetadata(
    questions: AIQuestion[],
    taxonomyNodes: Array<{ id: string; concept: string; chapter: string; skillType?: string; subjectType: string }>,
    subject: string,
    selectedChapters: string[]
): Promise<Map<string, { primaryTopic: string; conceptTopics: string[]; chapterRef: string; rubric: { step_marking: string; steps: Array<{ marks: number; concept: string }> } }>> {
    if (questions.length === 0) return new Map();

    const isHumanities = taxonomyNodes.length > 0 && taxonomyNodes[0].subjectType === 'HUMANITIES';
    const chapterList = selectedChapters.length > 0 ? selectedChapters.join(', ') : subject;

    const questionList = questions.map((q, i) => ({
        idx: i,
        id: q.id,
        text: q.text?.substring(0, 300),
        answer: q.answer?.substring(0, 200),
        marks: q.marks,
        type: q.type,
    }));

    const conceptVocab = isHumanities
        ? taxonomyNodes.map(n => `${n.id}: ${n.concept} [error dimension]`)
        : taxonomyNodes.map(n => `${n.id}: ${n.concept} [${n.skillType || 'apply'}] — ${n.chapter}`);

    const prompt = isHumanities
        ? `You are a metadata tagger for educational questions.
Subject: ${subject}
Available error dimensions (use ONLY these IDs):
${conceptVocab.join('\n')}
QUESTIONS:
${JSON.stringify(questionList, null, 2)}
For each question output a JSON array with: { "idx", "id", "primaryTopic", "conceptTopics": ["dim_id"], "chapterRef", "rubric": { "step_marking": "", "steps": [{"marks": n, "concept": "dim_id"}] } }
Return ONLY the JSON array.`
        : `You are a metadata tagger for educational questions.
Subject: ${subject}
Chapters: ${chapterList}
Available concept IDs (use ONLY these — do not invent IDs):
${conceptVocab.join('\n')}
QUESTIONS:
${JSON.stringify(questionList, null, 2)}
For each question output a JSON array with:
{ "idx", "id", "primaryTopic": "2-4 word topic", "conceptTopics": ["cm_xxxx","cm_yyyy"], "chapterRef": "chapter name", "rubric": { "step_marking": "Step 1: ... (Nm); Step 2: ...", "steps": [{"marks": n, "concept": "cm_xxxx"}] } }
Rules:
- conceptTopics: 2-4 concept IDs from the list above that this question actually tests
- steps[].marks must sum to total question marks
- MCQ (1 mark): one step, step_marking = "MCQ — correct option (1m)"
- VSA: 1-2 steps. SA: 2-3 steps. LA (5+ marks): 3-5 steps.
- If no concepts match, set conceptTopics:[] and steps:[]
Return ONLY the JSON array.`;

    try {
        const result = await getAiInstance().models.generateContent({
            model: 'gemini-2.0-flash-lite',
            contents: prompt,
            config: { responseMimeType: 'application/json', temperature: 0.0 }
        });

        const raw = (result.text || '[]').replace(/```json|```/g, '').trim();
        let parsed: any[] = [];
        try { parsed = JSON.parse(raw); } catch { return new Map(); }
        if (!Array.isArray(parsed)) return new Map();

        const resultMap = new Map<string, any>();
        parsed.forEach(item => {
            if (!item?.id) return;
            resultMap.set(item.id, {
                primaryTopic: item.primaryTopic || '',
                conceptTopics: Array.isArray(item.conceptTopics) ? item.conceptTopics : [],
                chapterRef: item.chapterRef || chapterList,
                rubric: {
                    step_marking: item.rubric?.step_marking || '',
                    steps: Array.isArray(item.rubric?.steps) ? item.rubric.steps : [],
                },
            });
        });
        return resultMap;
    } catch (e) {
        console.warn('[Phase2] Extraction call failed:', e);
        return new Map();
    }
}

const ragService = {
    // 1. MEMORY CACHE (NEW): Stores question vectors so we don't pay API costs twice for the same question
    vectorCache: new Map<string, number[]>(),

    // 2. Math function
    cosineSimilarity: (vecA: number[], vecB: number[]): number => {
        if (!Array.isArray(vecA) || !Array.isArray(vecB) || vecA.length !== vecB.length) return 0;
        let dotProduct = 0, normA = 0, normB = 0;
        for (let i = 0; i < vecA.length; i++) {
            dotProduct += vecA[i] * vecB[i];
            normA += vecA[i] * vecA[i];
            normB += vecB[i] * vecB[i];
        }
        return (dotProduct / (Math.sqrt(normA) * Math.sqrt(normB))) || 0;
    },

attachContextToAssessment: async (assessmentData: any) => {
        // 1. Validation
        if (!assessmentData.questions || assessmentData.questions.length === 0) return assessmentData;
        console.log("📘 RAG: Initializing knowledge base scan...");

        // 2. FETCH KNOWLEDGE BASE
        let kbDocs: any[] = [];
        try {
            let query: any = fbFirestore.collection('curriculumKnowledgeBase');
            
            // Filter by subject to reduce download size
if (assessmentData.subject && assessmentData.subject !== 'All' && assessmentData.subject !== 'Unknown Subject') {
    query = query.where('subject', '==', assessmentData.subject);
}
            const snapshot = await query.get();
            kbDocs = snapshot.docs.map(doc => doc.data());
            
            // IMPROVED LOG: Be specific about what happened
            console.log(`📘 RAG: Downloaded ${kbDocs.length} candidate documents for subject '${assessmentData.subject || 'All'}' to scan.`);
        } catch (e) {
            console.warn("RAG: Failed to download knowledge base.", e);
            return assessmentData; 
        }

        if (kbDocs.length === 0) {
            console.log("📘 RAG: No curriculum documents found for this subject. Skipping.");
            return assessmentData;
        }

        // 3. Process Questions
        const questions = assessmentData.questions;
        // Use a loop instead of map to prevent parallel embedding rate limits
        const updatedQuestions = [];
        
        for (const q of questions) {
            if (!q.text || q.text.length < 5) {
                updatedQuestions.push(q);
                continue;
            }

            try {
                // A. Generate Embedding
                let qVector = ragService.vectorCache.get(q.text);
                
                if (!qVector) {
                    // Add a small delay to prevent API rate limits
                    await new Promise(r => setTimeout(r, 100)); 
                    const embeddingResponse = await getAiInstance().models.embedContent({
                        model: "text-embedding-004",
                        contents: { parts: [{ text: q.text }] },
                    });
                    qVector = embeddingResponse.embeddings?.[0]?.values;
                    if (qVector) ragService.vectorCache.set(q.text, qVector);
                }

                if (!qVector) {
                    console.warn(`RAG: Failed to generate vector for Q: "${q.text.substring(0, 15)}..."`);
                    updatedQuestions.push(q);
                    continue;
                }

// B. PERFORM LOCAL MATCHING (ROBUST OBJECT-TO-ARRAY CONVERSION)
                const scoredDocs = kbDocs.map((doc, idx) => {
                    // 1. Get raw field (handle singular/plural/nested)
                    // CRITICAL FIX: Explicitly check for Arrays first to avoid accidentally 
                    // grabbing the .values() iterator function from a standard array.
                    let rawVector;
                    if (Array.isArray(doc.embedding)) {
                        rawVector = doc.embedding;
                    } else if (Array.isArray(doc.embedding?.values)) {
                        rawVector = doc.embedding.values;
                    } else if (Array.isArray(doc.embeddings)) {
                        rawVector = doc.embeddings;
                    } else if (Array.isArray(doc.embeddings?.values)) {
                        rawVector = doc.embeddings.values;
                    } else {
                        // Fallback for object-map formats or strings
                        rawVector = doc.embedding || doc.embeddings;
                    }

                    // 2. Handle stringified JSON (common CSV import artifact)
                    if (typeof rawVector === 'string') {
                        try { rawVector = JSON.parse(rawVector); } catch(e) { /* ignore */ }
                    }

                    // 3. FORCE CONVERSION TO ARRAY (The Critical Fix)
                    // If Firestore returns { "0": 0.1, "1": 0.2 }, this converts it to [0.1, 0.2]
                    let docVector: number[] | null = null;
                    
                    if (Array.isArray(rawVector)) {
                        docVector = rawVector;
                    } else if (typeof rawVector === 'object' && rawVector !== null) {
                        // Convert Object-Map to Array
                        docVector = Object.values(rawVector);
                    }

                    // 4. Validate Vector Length
                    if (!docVector || docVector.length < 50) { 
                        // Log only the first error to avoid console spam
                        if (idx === 0) {
                            console.warn("⚠️ RAG DEBUG: Document vector is still invalid after conversion.", {
                                docTopic: doc.topic,
                                rawType: typeof rawVector,
                                isArray: Array.isArray(rawVector),
                                convertedLength: docVector ? docVector.length : 0
                            });
                        }
                        return { doc, score: -1 };
                    }
                    
                    // 5. Calculate Score
                    return { 
                        doc, 
                        score: ragService.cosineSimilarity(qVector!, docVector) 
                    };
                });
                 // C. Sort by Score
                scoredDocs.sort((a, b) => b.score - a.score);

                // LOGGING: Show the top match score for debugging
                const topScore = scoredDocs.length > 0 ? scoredDocs[0].score : 0;
                console.log(`🔍 RAG Scan for Q: "${q.text.substring(0, 15)}..." | Top Match Score: ${topScore.toFixed(2)}`);

                // D. Pick Matches (UPDATE THIS BLOCK)
                // OLD CODE: .slice(0, 2);
                // NEW CODE: .slice(0, 5); 
                // Why: Allows multiple data sources (e.g. "pH Scale Part 1" + "Part 2") to be included simultaneously.
                const topMatches = scoredDocs
                    .filter(d => d.score > 0.45) 
                    .slice(0, 5); 

                // E. Attach Text
                if (topMatches.length > 0) {
                    const finalContext = topMatches.map(m => m.doc.text || m.doc.content || "").join("\n\n");
                    
                    // Create a visible summary of what was found
                    const contextSummary = topMatches.map(m => `[Source: ${m.doc.topic || 'Unknown Topic'} (${(m.score * 100).toFixed(0)}% match)]`).join(' ');

                    updatedQuestions.push({
                        ...q,
                        ragContext: finalContext,
                        // NEW: Temporarily store summary to append to instructions later
                        _ragSummary: contextSummary 
                    });
                } else {
                    updatedQuestions.push(q);
                }

            } catch (error) {
                console.warn(`RAG processing error for Q: "${q.text.substring(0, 15)}..."`, error);
                updatedQuestions.push(q);
            }
        }

        return {
            ...assessmentData,
            questions: updatedQuestions
        };
    },

    // 4. Fetch Rules
fetchRulesForSubject: async (subject: string): Promise<any[]> => {
    try {
const snapshot = await fbFirestore.collection("gradingCorrectionRules")
    .where("subject", "in", ["Global", "global", subject])
    .get();
        return snapshot.docs.map(doc => doc.data());
    } catch (e) {
        console.warn("RAG Fetch Error:", e);
        return [];
    }
},

  // 5. SEARCH LOCALLY (Optimized: Returns RAW data for deduplication)
    findMatchingRules: async (questionText: string, allCachedRules: any[]): Promise<any[]> => {
        if (!questionText || allCachedRules.length === 0) return [];

let queryVector: number[] | undefined;
// Clean the text to ensure the cache matches even with different spacing/casing
const cleanSearchText = questionText.trim().toLowerCase();

if (ragService.vectorCache.has(cleanSearchText)) {
    queryVector = ragService.vectorCache.get(cleanSearchText);
} else {
    try {
        const embeddingResponse = await getAiInstance().models.embedContent({
            model: "text-embedding-004",
            contents: { parts: [{ text: cleanSearchText }] },
            config: { taskType: 'RETRIEVAL_QUERY' } // Tells AI we are "Searching"
        });
        queryVector = embeddingResponse.embeddings?.[0]?.values;
        if (queryVector) ragService.vectorCache.set(cleanSearchText, queryVector);
    } catch (err) {
        console.warn("Embedding failed", err);
        return [];
    }
}
        
        if (!queryVector) return [];

        // 2. Score Rules
        const scoredRules = allCachedRules.map(rule => {
            let ruleVector = rule.embedding;
            if (!Array.isArray(ruleVector) && (ruleVector as any)?.values) {
                ruleVector = (ruleVector as any).values;
            }
            if (!ruleVector) return { rule, score: 0 };
            return { rule, score: ragService.cosineSimilarity(queryVector!, ruleVector) };
        });

        // 3. Filter & Sort (Top 3 matches)
const topMatches = scoredRules
    .filter(item => (item.score > 0.25) || (item.rule.subject === 'Global'))
    .sort((a, b) => b.score - a.score)
    .slice(0, 10);

        // RETURN RAW ARRAY (Do not format string here)
        return topMatches;
    },
};



