/**
 * Fetches the full set of teacherUids assigned to a class/section/subject
 * (from classRosters), so "all teachers verified" can be checked against the
 * REAL expected list rather than just whichever teachers happen to already
 * have an entry in teacherVerifications. A teacher who has never clicked
 * verify has no entry at all — Object.values(...).every() is vacuously true
 * over the entries that DO exist, which is the bug this fixes.
 */
async function getExpectedVerifierUids(className: string, section: string, subject: string, schoolName: string): Promise<string[]> {
    try {
        const snap = await fbFirestore.collection('classRosters')
            .where('className', '==', className)
            .where('section', '==', section)
            .where('subject', '==', subject)
            .where('schoolName', '==', schoolName)
            .get();
        return Array.from(new Set(snap.docs.map(d => d.data().teacherUid).filter(Boolean)));
    } catch (e) {
        console.error('[getExpectedVerifierUids] classRosters lookup failed:', e);
        return [];
    }
}

/**
 * True only when every teacher expected to teach this class/section/subject
 * has an explicit `verified: true` entry. Falls back to the previous
 * (single-teacher) behavior if the roster lookup returns nothing, so classes
 * without classRosters coverage keep working exactly as before.
 */
function isReportFullyVerified(report: AIFullAssessmentReport, expectedUids: string[]): boolean {
    const verifications = report.teacherVerifications || {};
    if (expectedUids.length === 0) {
        return Object.keys(verifications).length > 0
            ? Object.values(verifications).every(v => v.verified)
            : !!report.teacherVerified;
    }
    return expectedUids.every(uid => verifications[uid]?.verified === true);
}

/**
 * Cache of the expected co-teacher list (uid + name) for whichever
 * class/section/subject report view is currently open. Populated once by
 * ensureExpectedVerifiersCached() when the report view loads, so the chip
 * renderers below can synchronously show a chip for a teacher who is
 * expected to verify but has never clicked verify yet (previously they were
 * simply missing from the list, which is what made the "only 1 of 3
 * verified" state look identical to "fully verified").
 */
let expectedVerifiersCache: { key: string; teachers: { uid: string; name: string }[] } = { key: '', teachers: [] };

async function ensureExpectedVerifiersCached(className: string, section: string, subject: string, schoolName: string): Promise<void> {
    const key = `${schoolName}|${className}|${section}|${subject}`;
    if (expectedVerifiersCache.key === key) return; // already cached for this exact view
    try {
        const snap = await fbFirestore.collection('classRosters')
            .where('className', '==', className)
            .where('section', '==', section)
            .where('subject', '==', subject)
            .where('schoolName', '==', schoolName)
            .get();
        const seen = new Set<string>();
        const teachers: { uid: string; name: string }[] = [];
        snap.docs.forEach(d => {
            const data = d.data();
            const uid = data.teacherUid;
            if (!uid || seen.has(uid)) return;
            seen.add(uid);
            teachers.push({ uid, name: data.teacherName || data.teacherEmail || 'Unknown Teacher' });
        });
        expectedVerifiersCache = { key, teachers };
    } catch (e) {
        console.error('[ensureExpectedVerifiersCached] classRosters lookup failed:', e);
        expectedVerifiersCache = { key, teachers: [] }; // fail safe: chip renderers fall back to old behavior
    }
}

// Returns the HTML for per-teacher verification chips
function renderVerifyChips(report: AIFullAssessmentReport): string {
    const verifications = report.teacherVerifications || {};
    const expected = expectedVerifiersCache.teachers;

    const chip = (verified: boolean, name: string) => {
        const bg = verified ? '#dcfce7' : '#fee2e2';
        const color = verified ? '#16a34a' : '#dc2626';
        const label = verified ? `✓ ${name}` : `✗ ${name}`;
        return `<span style="font-size:0.65rem;padding:2px 7px;border-radius:5px;font-weight:600;background:${bg};color:${color};display:block;margin-bottom:2px;">${label}</span>`;
    };

    if (expected.length > 0) {
        // Show one chip per EXPECTED co-teacher (from classRosters), so a teacher who
        // has never clicked verify still shows as "Not Verified" instead of being
        // silently absent from the list.
        const shown = new Set<string>();
        const chips = expected.map(t => {
            shown.add(t.uid);
            return chip(verifications[t.uid]?.verified === true, verifications[t.uid]?.teacherName || t.name);
        });
        // Include any stale entries (e.g. a teacher removed from the roster later) so
        // existing verification history is never silently dropped.
        Object.entries(verifications).forEach(([uid, v]) => {
            if (!shown.has(uid)) chips.push(chip(v.verified, v.teacherName));
        });
        return chips.join('');
    }

    // Fallback (no classRosters coverage found) — previous behavior, unchanged.
    if (Object.keys(verifications).length === 0) {
        const bg = report.teacherVerified ? '#dcfce7' : '#fee2e2';
        const color = report.teacherVerified ? '#16a34a' : '#dc2626';
        const label = report.teacherVerified ? '✓ Verified' : '✗ Not Verified';
        return `<span style="font-size:0.68rem;padding:3px 8px;border-radius:5px;font-weight:600;background:${bg};color:${color};">${label}</span>`;
    }
    return Object.entries(verifications).map(([, v]) => chip(v.verified, v.teacherName)).join('');
}

window.handleTeacherVerify = async (reportIndex: number) => {
    const report = assessmentReports[reportIndex];
    if (!report || !currentAssessmentForReportView || !teacherProfile) return;

    // Toggle this teacher's own verification
    const verifications = report.teacherVerifications || {};
    const myCurrentState = verifications[teacherProfile.uid]?.verified || false;
    const newState = !myCurrentState;

    verifications[teacherProfile.uid] = { verified: newState, teacherName: teacherProfile.name };
    report.teacherVerifications = verifications;

    // Keep legacy teacherVerified = true only when ALL EXPECTED teachers have
    // verified (checked against classRosters, not just whoever has acted so far).
    const expectedVerifierUids = await getExpectedVerifierUids(
        currentAssessmentForReportView.className,
        currentAssessmentForReportView.section,
        currentAssessmentForReportView.subject,
        teacherProfile.schoolName
    );
    const allVerified = isReportFullyVerified(report, expectedVerifierUids);
    report.teacherVerified = allVerified;

    // Persist to Firestore
try {
const ownerUid = (report as any)._ownerTeacherUid || (currentAssessmentForReportView as any).createdByTeacherUid || teacherProfile!.uid;
const ownerAssessmentId = (report as any)._ownerAssessmentId || currentAssessmentForReportView.assessmentId;
const isHomeworkVerify = ownerAssessmentId.startsWith('hw_grade_');
const verifyRef = isHomeworkVerify
    ? fbFirestore.collection('completedHomeworkSubmissions').doc(report.submissionDocId)
    : fbFirestore
        .collection('teachers').doc(ownerUid)
        .collection('assessmentHistory').doc(ownerAssessmentId)
        .collection('submissions').doc(report.submissionDocId);
await verifyRef.update({ 
    teacherVerified: report.teacherVerified,
    teacherVerifications: verifications
});

            writeAuditLog({
            actionType: 'verified',
            studentUid: report.studentUid,
            studentName: (report as any).studentName || report.studentUid,
            newValue: newState ? 'Verified' : 'Unverified',
        });
} catch (e) {
        console.error('[TeacherVerify] Firestore update failed:', e);
        showFeedbackMessage("Failed to save verification status.", "error");
    }

    // Update the verify button in individual report view
    const btn = document.getElementById('teacher-verify-btn') as HTMLButtonElement;
    if (btn) {
        btn.style.background = newState ? '#16a34a' : '#dc2626';
        btn.textContent = newState ? '✓ Teacher Verified' : '✗ Not Verified';
    }

    // Update the student row chip in the list view
    const rowEl = document.getElementById(`report-row-${reportIndex}`);
    if (rowEl) {
        const chipsContainer = rowEl.querySelector('.teacher-verify-chips') as HTMLElement;
        if (chipsContainer) {
            chipsContainer.innerHTML = renderVerifyChips(report);
        }
    }
};
let _reorderDragSrc: string | null = null;

window.handleToggleReorderPanel = () => {
    gradingCardOrderVisible = !gradingCardOrderVisible;
    const panel = document.getElementById('grading-reorder-panel');
    if (!panel) return;
    if (gradingCardOrderVisible) {
        // Build the draggable list from current card order
        const list = document.getElementById('grading-reorder-list');
        if (list) {
            list.innerHTML = gradingCardCustomOrder.map(qNum => `
                <div draggable="true"
                    ondragstart="window.handleReorderDragStart(event, '${qNum}')"
                    ondragover="event.preventDefault()"
                    ondrop="window.handleReorderDrop(event, '${qNum}')"
                    style="padding:6px 10px; margin-bottom:4px; background:#f8fafc; border:1px solid #e2e8f0;
                           border-radius:6px; cursor:grab; font-size:0.75rem; font-weight:600;
                           color:#334155; display:flex; align-items:center; gap:6px; user-select:none;">
                    <span style="color:#94a3b8;">⠿</span> ${qNum}
                </div>`).join('');
        }
        panel.style.display = 'block';
    } else {
        panel.style.display = 'none';
    }
};

window.handleReorderDragStart = (e: DragEvent, qNum: string) => {
    _reorderDragSrc = qNum;
    if (e.dataTransfer) e.dataTransfer.effectAllowed = 'move';
};

window.handleReorderDrop = (e: DragEvent, targetQNum: string) => {
    e.preventDefault();
    if (!_reorderDragSrc || _reorderDragSrc === targetQNum) return;
    const fromIdx = gradingCardCustomOrder.indexOf(_reorderDragSrc);
    const toIdx = gradingCardCustomOrder.indexOf(targetQNum);
    if (fromIdx === -1 || toIdx === -1) return;
    // Reorder array
    gradingCardCustomOrder.splice(fromIdx, 1);
    gradingCardCustomOrder.splice(toIdx, 0, _reorderDragSrc);
    _reorderDragSrc = null;
    // Re-render cards
    const rIdx = (window as any).currentOsmReportIndex;
    const report = assessmentReports[rIdx];
    if (report !== undefined) renderReportPageUI(report, rIdx);
    // Refresh panel list
    window.handleToggleReorderPanel(); // close
    window.handleToggleReorderPanel(); // reopen with new order
};

window.handleResetCardOrder = () => {
    gradingCardCustomOrder = [];
    const rIdx = (window as any).currentOsmReportIndex;
    const report = assessmentReports[rIdx];
    if (report !== undefined) renderReportPageUI(report, rIdx);
    gradingCardOrderVisible = false;
    const panel = document.getElementById('grading-reorder-panel');
    if (panel) panel.style.display = 'none';
};


window.handleOsmDragStart = (event: DragEvent, stepIndex: number) => {
    draggedOsmStepIndex = stepIndex;
    if (event.dataTransfer) event.dataTransfer.effectAllowed = 'move';
    const markerEl = event.currentTarget as HTMLElement;
const markerRect = markerEl.getBoundingClientRect();
    osmDragOffsetX = event.clientX - (markerRect.left + markerRect.width / 2);
    osmDragOffsetY = event.clientY - (markerRect.top + markerRect.height / 2);
};

