window.generateOcrQcTable = (report: AIFullAssessmentReport | undefined) => {
    if (!report || !report.questionWiseReport) return "<p class='info-text'>No structured report data available.</p>";

    return `
        <div style="padding: 10px; overflow-x: auto;">
            <table class="step-wise-table" style="font-size: 0.75rem; border: 1px solid #eee; width: 100%;">
                <thead>
                    <tr style="background: #f8f9fa;">
                        <th style="width: 50px; text-align: center;">Page</th>
                        <th style="width: 100px;">System No. / Breakdown</th>
                        <th style="width: 120px;">Anchor [Y,X]</th>
                        <th>Stored Key (Key)</th>
                        <th>Stored Question Text</th>
                    </tr>
                </thead>
                <tbody>
                    ${[...report.questionWiseReport]
                        .sort((a, b) => {
                            const numA = parseInt(a.questionNumber.replace(/\D/g, '')) || 0;
                            const numB = parseInt(b.questionNumber.replace(/\D/g, '')) || 0;
                            if (numA !== numB) return numA - numB;
                            return a.questionNumber.localeCompare(b.questionNumber, undefined, { numeric: true });
                        })
                        .map(qr => {
                        const pageNum = (qr.answerPageIndex ?? 0) + 1;
                        const bestStep = qr.stepWiseEvaluation?.find(s => s.stepPoint && s.stepPoint.length === 2);
                        const coords = bestStep ? `[${bestStep.stepPoint.join(', ')}]` : 'N/A';
                        const modelKey = qr.modelAnswer || 'N/A';
                        const questionContent = qr.questionText || 'N/A';

                        return `
                            <tr>
                                <td style="text-align: center; font-weight: 700;">${pageNum}</td>
                                <td style="padding: 8px;">
                                    <div style="font-weight: 700; color: var(--action-color-primary); font-size: 0.9rem;">Q:${qr.questionNumber}</div>
                                    ${qr.topic ? `<div style="font-size: 0.65rem; color: #7f8c8d; margin-top: 2px; line-height: 1.1; font-weight: 500;">${qr.topic}</div>` : ''}
                                </td>
                                <td style="font-family: monospace; color: #7f8c8d;">${coords}</td>
                                <td style="font-weight: 600; color: #2c3e50;">${modelKey}</td>
                                <td style="color: #666; font-style: italic; max-width: 250px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${questionContent.replace(/"/g, '&quot;')}">
                                    ${questionContent}
                                </td>
                            </tr>
                        `;
                    }).join('')}
                </tbody>
            </table>
            <div style="margin-top: 15px; padding: 12px; background: #fffbe6; border-radius: 8px; border: 1px solid #ffe58f; font-size: 0.75rem; line-height: 1.4;">
                <h5 style="margin: 0 0 5px 0; color: #856404;">🔒 System Integrity Audit</h5>
                <p style="margin: 0;">This table reflects the actual structured data stored in the database. Parsing and mapping were performed by the <strong>Backend JS logic</strong>. No regex is applied in the viewer.</p>
            </div>
        </div>
    `;
};

window.toggleOcrQcView = () => {
    const ocrBox = document.getElementById('ocr-text-display');
    const btn = document.getElementById('toggle-qc-view-btn');
    if (!ocrBox || !btn || currentViewingReportIndex === null) return;

    const report = assessmentReports[currentViewingReportIndex];
    const isShowingTable = btn.dataset.viewMode === 'table';

    if (isShowingTable) {
        // Switch back to Transcript
        btn.dataset.viewMode = 'text';
        btn.textContent = '🔍 QC Table';
        // Trigger a re-render of the standard text view
        updateImageViewerContent(); 
    } else {
        // Switch to QC Table
        btn.dataset.viewMode = 'table';
        btn.textContent = '📄 Show Text';
        ocrBox.innerHTML = window.generateOcrQcTable(report);
    }
};

window.jumpToGradingCard = (qNum: string, pageIdx: number, studentUid?: string) => {
    const uidToUse = studentUid || currentStudentUidForReport;
    const reportIndex = assessmentReports.findIndex(r => r.studentUid === uidToUse);
    if (reportIndex === -1) return;
    
    const report = assessmentReports[reportIndex];
    const qr = report.questionWiseReport.find(q => normalizeForComparison(q.questionNumber) === normalizeForComparison(qNum));
    
    // Navigate to exactly the page the summary table shows for this question
    // (its answerPageIndex) so the clicked link and the displayed "Pg" column
    // always land on the same page. Only fall back to the page-range start, or
    // the value the caller passed, when answerPageIndex is missing/invalid.
    let targetPage = pageIdx;
    if (qr && typeof qr.answerPageIndex === 'number' && qr.answerPageIndex >= 0) {
        targetPage = qr.answerPageIndex;
    } else if (qr && qr.answerPageIndices && qr.answerPageIndices.length > 0) {
        targetPage = qr.answerPageIndices[0];
    }

    currentReportPageIdx = targetPage;
    renderReportPageUI(report, reportIndex);
        
        // 3. Wait for DOM render, then scroll
        setTimeout(() => {
            const cleanNum = normalizeForComparison(qNum);
            const element = document.getElementById(`q-card-ref-${cleanNum}`);
            if (element) {
                element.scrollIntoView({ behavior: 'smooth', block: 'center' });
                element.style.outline = "3px solid var(--action-color-primary)";
                element.style.borderRadius = "12px";
                setTimeout(() => { element.style.outline = "none"; }, 2000);
            }
        }, 200);
    
};



// ─────────────────────────────────────────────────────────────────────────────
// PDF ROW-BAND ANNOTATIONS
// Used only in the downloaded PDF (feedbackPages). Instead of exact-dot markers
// that can drift ±2cm when x-coord is imprecise, renders a full-width horizontal
// band at the y-coordinate only. Band spans 100% width so y-drift of ±10% still
// looks intentional — like a highlighter. Never looks misplaced.
// Teacher on-screen view keeps exact dots (createHumanAnnotationHtml unchanged).
// ─────────────────────────────────────────────────────────────────────────────
function createPdfBandAnnotationHtml(report: AIQuestionReport, currentPageIndex: number): string {
    const allSteps = report.stepWiseEvaluation || [];
    const steps = allSteps.filter(s =>
        (s.pageIndex - 1) === currentPageIndex &&
        s.stepPoint && s.stepPoint.length === 2
    );
    if (steps.length === 0) return '';

    // Deduplicate by y-row: if multiple steps land within 3% of each other,
    // merge into one band (avoids stacked overlapping bands on same line).
    const usedY: number[] = [];
    const bands: string[] = [];

    steps.forEach(step => {
        const [y] = step.stepPoint!;
        const safeY = (typeof y === 'number' && !isNaN(y))
            ? Math.max(1, Math.min(y / 10, 96))
            : 10;

        // Skip if a band already exists within 3% of this y
        if (usedY.some(uy => Math.abs(uy - safeY) < 3)) return;
        usedY.push(safeY);

        const commentLower = (step.comment || '').toLowerCase();
        const isMissing = !!(step as any).isMissing || (step.marks === 0 && (
            commentLower.includes('missing') ||
            commentLower.includes('no answer provided') ||
            commentLower.includes('not provided')
        ));
        const isCorrect = !isMissing && (step.marks > 0 || commentLower === 'correct');

        const earned = step.marks || 0;
        const marksSign = isCorrect ? '+' : '−';
        const marksDisplay = earned !== 0
            ? `${marksSign}${Math.abs(earned)}m`
            : (isCorrect ? '✓' : (isMissing ? '!' : '✗'));
        const label = `${report.questionNumber} ${marksDisplay}`;

        // Colors
        const bg     = isMissing ? 'rgba(217,119,6,0.13)'
                     : isCorrect  ? 'rgba(22,163,74,0.12)'
                     :              'rgba(220,38,38,0.15)';
        const border = isMissing ? '#d97706' : isCorrect ? '#16a34a' : '#dc2626';
        const text   = isMissing ? '#92400e' : isCorrect ? '#14532d' : '#7f1d1d';
        const labelBg = isMissing ? 'rgba(217,119,6,0.18)'
                      : isCorrect  ? 'rgba(22,163,74,0.18)'
                      :              'rgba(220,38,38,0.18)';

        bands.push(`<div style="
            position:absolute;
            top:${safeY}%;
            left:0; right:0;
            height:20px;
            background:${bg};
            border-left:3px solid ${border};
            display:flex;
            align-items:center;
            justify-content:flex-end;
            padding-right:8px;
            pointer-events:none;
            z-index:100;
            -webkit-print-color-adjust:exact;
            print-color-adjust:exact;
        "><span style="
            font-size:9px;
            font-weight:700;
            color:${text};
            background:${labelBg};
            padding:1px 6px;
            border-radius:3px;
            font-family:Arial,sans-serif;
            white-space:nowrap;
            -webkit-print-color-adjust:exact;
        ">${label}</span></div>`);
    });

    return bands.join('');
}

function createHumanAnnotationHtml(report: AIQuestionReport, currentPageIndex: number, qIdx: number, reportIndex: number, isPdfRender: boolean = false, sharedUsedY: number[] = []): string {
// ON-SCREEN MARKERS (dotted line + question-number dot overlay) — DISABLED 2026-08-17.
// Positions weren't reliably accurate and this was extra generation cost on the backend
// for a display-only field. Single choke point: this function is called from all 7
// teacher-facing report views (exam, homework, PDF export, fullscreen editor, PIP).
// To re-enable: delete the line below. Underlying marks/feedback text (finalFeedback,
// stepWiseEvaluation comments) are completely unaffected — only this visual dot/line is gated.
return '';
    // Skip markers entirely for unattempted / undetected questions
// Skip markers entirely for unattempted / undetected questions
const markerScale = isPdfRender ? 0.5 : 1.3;
const svgW = Math.round(10 * markerScale);
const svgH = Math.round(10 * markerScale);
const svgHw = Math.round(9 * markerScale);
const fSize1 = isPdfRender ? '4.5px' : '10px';
const fSize2 = isPdfRender ? '4px' : '8.5px';
const fSize3 = isPdfRender ? '3.5px' : '8px';
const fSize4 = isPdfRender ? '4px' : '8px';
const fSize5 = isPdfRender ? '5px' : '10px';
const hasManualSteps = (report.stepWiseEvaluation || []).length > 0;
if (isReportUnattempted(report) && !hasManualSteps) return '';
if ((report as any)._runtimeOrLoser) return ''; // suppress OSM dots for OR losers


// FIX: keep original index from stepWiseEvaluation so drag/delete handlers
// reference the correct step, not the index within the page-filtered subset.
const allSteps = report.stepWiseEvaluation || [];
const steps = allSteps
    .map((s, originalIdx) => ({ ...s, _originalIdx: originalIdx }))
    .filter(s => (s.pageIndex - 1) === currentPageIndex && s.stepPoint && s.stepPoint.length === 2);

   if (steps.length === 0) return '';

    // ── ONE MARKER PER QUESTION (collapsed mode) ─────────────────────────────
    // Pick the middle step by index for Y position.
    // Color: green = full marks, orange = partial, red = zero.
    const midStep = steps.length === 1
        ? steps[0]
        : steps[Math.floor((steps.length - 1) / 2)];
    const [_cy, _cx] = midStep.stepPoint;
    const safeY = (typeof _cy === 'number' && !isNaN(_cy)) ? Math.max(1, Math.min(_cy / 10, 98)) : 10;
    const safeX = (typeof _cx === 'number' && !isNaN(_cx)) ? Math.max(1, Math.min(_cx / 10, 75)) : 55;

    const _awarded = report.marksAwarded || 0;
    const _max = report.maxMarksForQuestion || 0;
    const dotColor = (_awarded >= _max && _max > 0) ? '#16a34a' : _awarded > 0 ? '#d97706' : '#dc2626';

    const _tickSvg = `<svg width="${svgW}" height="${svgH}" viewBox="0 0 30 30" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="15" cy="15" r="14" fill="#16a34a"/><polyline points="7.5,15 12.5,20.5 22.5,9.5" stroke="white" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg>`;
    const _crossSvg = `<svg width="${svgW}" height="${svgH}" viewBox="0 0 30 30" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="15" cy="15" r="14" fill="#dc2626"/><line x1="9.5" y1="9.5" x2="20.5" y2="20.5" stroke="white" stroke-width="3" stroke-linecap="round"/><line x1="20.5" y1="9.5" x2="9.5" y2="20.5" stroke="white" stroke-width="3" stroke-linecap="round"/></svg>`;
    const _warnSvg = `<svg width="${svgW}" height="${svgHw}" viewBox="0 0 32 28" fill="none" xmlns="http://www.w3.org/2000/svg"><polygon points="16,2 30,26 2,26" fill="#d97706" stroke="#92400e" stroke-width="1"/><text x="16" y="23" text-anchor="middle" font-size="13" font-weight="900" fill="white" font-family="Arial,sans-serif">!</text></svg>`;
    const _symbol = (_awarded >= _max && _max > 0) ? _tickSvg : _awarded > 0 ? _warnSvg : _crossSvg;

const _pointerEvents = isGlobalMarkerEdit ? 'auto' : 'none';
    const _displayLabel = report.questionNumber;
    const _midStepIdx = midStep._originalIdx;
    const _dragAttr = isGlobalMarkerEdit
        ? `onpointerdown="window.handleOsmGlobalPointerDown(event, ${qIdx}, ${_midStepIdx}, ${reportIndex})"`
        : '';
    const _cursor = isGlobalMarkerEdit ? 'grab' : 'default';

return `
  <div class="osm-marker-row" style="position:absolute; top:${safeY}%; left:0; right:0; height:0; pointer-events:none; z-index:500;">
<div class="osm-anchor-dot"
         style="position:absolute; top:0; left:${safeX}%; width:12px; height:12px; margin-top:-6px; margin-left:-6px; border-radius:50%; background:${dotColor}; border:2px solid white; box-shadow:0 0 0 1px ${dotColor}; pointer-events:${_pointerEvents}; cursor:${_cursor}; z-index:500;"
         title="${report.questionNumber} | ${_awarded}/${_max} marks"
         ${_dragAttr} 
         <div class="osm-marker-controls" style="position:absolute; top:0; right:2%; transform:translateY(-50%); display:inline-flex; align-items:center; gap:3px; pointer-events:none;"
         ${_dragAttr}>>
    </div>
<div class="osm-leader-line" style="position:absolute; top:-1px; left:calc(${safeX}% + 6px); right:2%; border-top:${isPdfRender ? '1px' : '2px'} dotted ${dotColor}; opacity:${isPdfRender ? '0.7' : '1'}; pointer-events:none;"></div>
    <div class="osm-marker-controls" style="position:absolute; top:0; right:2%; transform:translateY(-50%); display:inline-flex; align-items:center; gap:3px; pointer-events:none;">
      <div style="flex-shrink:0;line-height:0;">${_symbol}</div>
      <span style="font-size:${fSize1};font-weight:900;color:white;background:rgba(0,0,0,0.65);padding:2px 5px;border-radius:3px;letter-spacing:0.04em;white-space:nowrap;line-height:1.4;">${_displayLabel}</span>
    </div>
  </div>`;
}
function updateGradingPIP() {
    const pipWidget = document.getElementById('grading-pip-widget');
    const progressBar = document.getElementById('pip-progress-bar');
    const queueText = document.getElementById('pip-queue-text');
    const statusLabel = pipWidget?.querySelector('.pip-status-label');
    
    if (!pipWidget || !progressBar || !queueText || !statusLabel) return;

    // The count of students waiting + the one currently being graded
    const remaining = gradingQueue.length + (isGradingBusy ? 1 : 0);
    
    // Logic: Only show the PIP if grading is happening AND we are NOT looking at the grading page
    const shouldShow = remaining > 0 && currentStage !== 'teacher_assessment_checker';

    if (shouldShow) {
        pipWidget.classList.remove('grading-pip-hidden');
        queueText.textContent = `${gradingQueue.length} more students in queue`;
        
        // If the AI is actively working on someone, show their name
        if (isGradingBusy && currentGradingStudentName) {
            statusLabel.textContent = `Grading: ${currentGradingStudentName}`;
        } else {
            statusLabel.textContent = `Preparing next student...`;
        }
    } else {
        // Hide the widget if no grading is happening or if we are on the grading page
        pipWidget.classList.add('grading-pip-hidden');
    }
}

window.toggleMarkersVisibility = () => {
    isMarkersVisible = !isMarkersVisible;
    
    // Update the button appearance
    const btn = document.getElementById('osm-visibility-toggle');
    if (btn) {
        // When visible is false, text should be "Show Marks"
        btn.innerHTML = isMarkersVisible ? '<span class="icon">👁️</span> Hide Markers' : '<span class="icon">👁️‍🗨️</span> Show Markers';
        btn.classList.toggle('active', isMarkersVisible);
    }

// Toggle the class on overlays
    document.querySelectorAll('.osm-overlay').forEach(overlay => {
        if (isMarkersVisible) {
            overlay.classList.remove('markers-hidden');
        } else {
            overlay.classList.add('markers-hidden');
        }
    });
    if (typeof syncPaletteButtonStyles === 'function') syncPaletteButtonStyles();
};

