function showRemedialHistoryModal(worksheets: PersonalizedWorksheet[], submissions: WorksheetSubmission[]) {
    const assessmentGroups = new Map<string, { id: string, title: string }>();
    
worksheets.forEach(ws => {
        if (!assessmentGroups.has(ws.assessmentId)) {
            // Use the title stored in the worksheet document directly
            assessmentGroups.set(ws.assessmentId, {
                id: ws.assessmentId,
                title: ws.assessmentTitle || `Assessment ${ws.assessmentId.slice(-6)}`
            });
        }
    });

    historyListModalTitleEl.textContent = "Remedial Worksheets History";
    
    if (assessmentGroups.size === 0) {
        historyListModalContentEl.innerHTML = `<div class="empty-list-message"><p>No worksheets created yet.</p></div>`;
        toggleModal('view-history-list-modal', true);
        return;
    }

    let html = '<div class="student-submission-list">';
    assessmentGroups.forEach((group) => {
        const count = worksheets.filter(w => w.assessmentId === group.id).length;
        html += `
            <div class="student-submission-card" onclick="window.showStudentWorksheetRoster('${group.id}')" style="cursor:pointer; margin-bottom:10px;">
                <div class="student-info">
                    <span class="student-name">${group.title}</span>
                    <span class="description" style="font-size:0.8rem; color:var(--text-secondary);">${count} Students Assigned</span>
                </div>
                <div class="actions-cell">
                    <button class="button-primary small-button">View Roster</button>
                </div>
            </div>
        `;
    });
    html += '</div>';

    historyListModalContentEl.innerHTML = html;
    toggleModal('view-history-list-modal', true);
}

