const checkEnvironmentHealth = async (): Promise<{ healthy: boolean; reason?: string }> => {
    // 1. Check basic connectivity
    if (!navigator.onLine) return { healthy: false, reason: "Offline" };
    
    // 2. Check for slow connection (Mobile/3G)
    const conn = (navigator as any).connection;
    if (conn) {
        if (conn.saveData) return { healthy: false, reason: "Data Saver active" };
        if (conn.effectiveType === '2g' || conn.effectiveType === '3g') {
            return { healthy: false, reason: "Slow network (3G/2G) detected" };
        }
    }
    return { healthy: true };
};


