window.handleOpenRuleManager = async () => {
    if (!teacherProfile) return;
    toggleLoading(true, "Fetching your rules...");
    try {
        const subject = currentAssessmentToGrade?.subject || (document.getElementById('train-subject') as HTMLSelectElement).value || "Global";
        const snapshot = await fbFirestore.collection('gradingCorrectionRules')
            .where('subject', 'in', ['Global', subject])
            .get();
        
        const rules = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
        window.renderRuleList(rules);
        toggleModal('rule-manager-modal', true);
    } catch (e) {
        showFeedbackMessage("Failed to load rules.", "error");
    } finally {
        toggleLoading(false);
    }
};


window.handleDeleteRule = async (id: string) => {
    if (!confirm("Are you sure you want to delete this correction rule? This action cannot be undone and will affect future AI grading logic.")) {
        return;
    }

    toggleLoading(true, "Deleting rule...");
    try {
        await fbFirestore.collection('gradingCorrectionRules').doc(id).delete();
        showFeedbackMessage("Rule deleted successfully.", "success");
        
        // Refresh the list in the manager
        window.handleOpenRuleManager();
    } catch (e) {
        console.error("Error deleting rule:", e);
        showFeedbackMessage("Failed to delete the rule from Firestore.", "error");
    } finally {
        toggleLoading(false);
    }
};

window.renderRuleList = (rules: any[]) => {
    const container = document.getElementById('rule-manager-list');
    if (!container) return;
    if (rules.length === 0) {
        container.innerHTML = `<p class="info-text">No rules found for this subject.</p>`;
        return;
    }
    container.innerHTML = rules.map(rule => `
        <div class="student-submission-card" style="margin-bottom:12px; grid-template-columns: 1fr auto auto; padding: 15px; background: white; border: 1px solid #eee;">
            <div class="student-info">
                <span class="student-name" style="font-size:0.9rem; line-height:1.4;">${rule.correctionRule.substring(0, 100)}${rule.correctionRule.length > 100 ? '...' : ''}</span>
                <div style="display:flex; gap:10px; margin-top:5px;">
                    <span class="status-chip ${rule.targetStep === 'OCR' ? 'pending' : 'submitted'}">Step: ${rule.targetStep || 'Grading'}</span>
                    <span class="status-chip ${rule.subject === 'Global' ? 'active' : 'neutral'}">${rule.subject}</span>
                </div>
            </div>
            <div class="actions-cell" style="display: flex; gap: 8px; align-items: center;">
                <button class="button-primary small-button" onclick="window.handleEditRuleInManager('${rule.id}')">Edit</button>
                <button class="button-tertiary danger small-button" onclick="window.handleDeleteRule('${rule.id}')">Delete</button>
            </div>
        </div>
    `).join('');
};


