window.handleEditRuleInManager = async (id: string) => {
    const doc = await fbFirestore.collection('gradingCorrectionRules').doc(id).get();
    if (!doc.exists) return;
    const data = doc.data() as TrainingRule;
    editingRuleId = id;

    // Fill Form Fields
    (document.getElementById('train-subject') as HTMLSelectElement).value = data.subject;
    (document.getElementById('train-chapter') as HTMLInputElement).value = data.chapter;
    (document.getElementById('train-student-answer') as HTMLTextAreaElement).value = data.inputContext.studentAnswer;
    (document.getElementById('train-ai-mistake') as HTMLTextAreaElement).value = data.inputContext.aiMistake;
    (document.getElementById('train-correction-rule') as HTMLTextAreaElement).value = data.correctionRule;
    (document.getElementById('train-tags-input') as HTMLInputElement).value = data.conceptTags.join(', ');
    (document.getElementById('train-target-step') as HTMLSelectElement).value = data.targetStep || 'Grading';
    (document.getElementById('train-is-global') as HTMLInputElement).checked = data.subject === 'Global';

    toggleModal('rule-manager-modal', false, true); 
    toggleModal('ai-training-modal', true); 
    (document.getElementById('btn-save-training')!).innerHTML = `<span class="icon">💾</span> Update Rule`;
};



