async function handleSingleQuestionGeneration(event: Event) {
    event.preventDefault();
    if (!singleGenContext || !teacherProfile) return;

    const { index, mode, type, parentQuestion } = singleGenContext;
    const data = type === 'homework' ? temporaryHomeworkData : temporaryAssessmentData;
    
    // 1. Determine Topic Source (Dropdown vs Custom)
    const chapterVal = (document.getElementById('single-gen-chapter') as HTMLSelectElement).value;
    const selectedTopics = Array.from((document.getElementById('single-gen-topics') as HTMLSelectElement).selectedOptions).map(o => o.value);
    const customTopicVal = (document.getElementById('single-gen-topic') as HTMLInputElement).value;

    let finalTopic = "";
    if (chapterVal) {
        finalTopic = `Chapter: ${chapterVal}`;
        if (selectedTopics.length > 0) {
            finalTopic += `, Topics: ${selectedTopics.join(', ')}`;
        }
        // If user ALSO typed custom text, append it as focus
        if (customTopicVal) {
            finalTopic += `. Focus: ${customTopicVal}`;
        }
    } else {
        // Fallback to custom input or parent topic
        finalTopic = customTopicVal || parentQuestion.topic || "General";
    }

    const newMarks = parseFloat((document.getElementById('single-gen-marks') as HTMLInputElement).value);
    
    // 2. Determine Question Type
    // If we are in 'or' mode, the UI select is hidden, so we enforce the parent's type.
    let newType: string;
    if (mode === 'or') {
        newType = parentQuestion.type || 'Subjective';
    } else {
        newType = (document.getElementById('single-gen-type') as HTMLSelectElement).value;
    }

    // UI Feedback
    const btn = document.getElementById('btn-generate-single') as HTMLButtonElement;
    const originalText = btn.innerHTML;
    btn.innerHTML = `<div class="spinner-inline"></div> Generating...`;
    btn.disabled = true;

    try {
        const difficulty = data.difficultyLevel || 'Medium';
        const bloom = parentQuestion.bloom_level || 'L3: Apply'; 
       // Construct Prompt (using finalTopic and newType)
        const prompt = `
            You are an expert educator. Generate EXACTLY ONE atomic question based on the following constraints:
            
            **Goal:** Create a ${mode === 'or' ? "Alternative ('OR') option" : "Single Sub-part question"} for an existing question.
            
            **Parent Question Context:** "${parentQuestion.text}"
            **Topic/Concept Focus:** "${finalTopic}"
            **Question Type:** ${newType}
            **Marks:** ${newMarks}
            **Difficulty:** ${difficulty}
            **Bloom's Level:** ${bloom}

            **CRITICAL FORMATTING RULES:**
            1. **ATOMIC CONTENT:** You are generating ONE specific part (e.g., just part 'c' or 'ii'). DO NOT generate a parent question with children (a, b) inside it. 
            2. **NO NESTING IN ANSWER:** The "answer" field must contain ONLY the solution for this specific question part. Do NOT put sub-questions inside the answer field.
            3. **CLEAN TEXT:** The "text" field should contain the question content only.
            
            ${mode === 'or' ? "**Constraint:** This is an alternative choice. It must match the parent's complexity exactly." : "**Constraint:** This is a sub-part. It should be related to the parent topic but distinct."}
            
            ${LATEX_MATH_INSTRUCTIONS}

            **Output Format:** Return a SINGLE valid JSON object (no markdown) with keys: "text", "answer".
        `;
        const response = await getAiInstance().models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: { 
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        text: { type: Type.STRING },
                        answer: { type: Type.STRING }
                    },
                    required: ["text", "answer"]
                }
            }
        });

        const result = JSON.parse(response.text.trim());

          // Find this block inside handleSingleQuestionGeneration
        if (mode === 'or') {
            const orInstructions = "Alternative Question (OR). Grade first attempt only.";
            // NEW: Distinct instruction for the alternative question
            const alternativeInstructions = "Alternative Question (OR). Grade first attempt only.";
            
            // 1. Update the Parent Question's instructions
            parentQuestion.checkingInstructions = orInstructions;

            // 2. CRITICAL FIX: Ensure Parent has a hard-coded question number.
            if (!parentQuestion.questionNumber) {
                parentQuestion.questionNumber = (index + 1).toString();
            }
            
            // 3. Create the New Question Object
            const newOrQuestion: AIQuestion = {
                id: `or_${Date.now()}`,
                // Explicitly copy the parent's number so they are linked
                questionNumber: parentQuestion.questionNumber, 
                text: result.text,
                answer: result.answer,
                marks: newMarks,
                type: newType as any,
                topic: finalTopic,
                imagePrompt: null,
                checkingInstructions: alternativeInstructions, // <--- CHANGE THIS: Use the distinct string
                kept: true,
                bloom_level: parentQuestion.bloom_level,
            };

            // 4. Insert the new question immediately AFTER the parent question
            data.questions!.splice(index + 1, 0, newOrQuestion);

        } else {
           
    if (!data.questions![index].subQuestions) {
                data.questions![index].subQuestions = [];
            }
            // ... (rest of sub-question logic)
            const subLen = data.questions![index].subQuestions!.length;
            const label = String.fromCharCode(97 + subLen); 

            data.questions![index].subQuestions!.push({
                id: `sub_${Date.now()}`,
                questionNumber: `(${label})`,
                text: result.text,
                answer: result.answer,
                marks: newMarks,
                type: newType as any,
                topic: finalTopic, 
                imagePrompt: null,
                kept: true
            });
        }

        // Close and Refresh
        toggleModal('single-question-gen-modal', false);
        if (type === 'homework') displayAIQuestionsForReview();
        else displayAssessmentQuestionsForReview();
        
        if (type === 'homework') displayHomeworkReviewSummary();
        else displayAssessmentReviewSummary();

    } catch (error) {
        console.error("Single Gen Error", error);
        alert("Failed to generate question. Please try again.");
    } finally {
        btn.disabled = false;
        btn.innerHTML = originalText;
    }
}



window.handlePublishAllReports = async () => {
    if (featureFlags.teacherPublishing === false) {
        showFeedbackMessage('Publishing has been disabled by your school admin.', 'error');
        return;
    }
    if (!currentAssessmentForReportView || assessmentReports.length === 0) {
        showFeedbackMessage("No reports available to publish.", "info");
        return;
    }

    const reportsToPublish = assessmentReports.filter(r => !r.published);

    if (reportsToPublish.length === 0) {
        showFeedbackMessage("All available reports have already been published.", "info");
        return;
    }

    // Check all unverified — against the REAL expected teacher list (classRosters),
    // not just whichever teachers happen to already have a verification entry.
    const expectedVerifierUids = await getExpectedVerifierUids(
        currentAssessmentForReportView.className,
        currentAssessmentForReportView.section,
        currentAssessmentForReportView.subject,
        teacherProfile!.schoolName
    );
    const unverified = reportsToPublish.filter(r => !isReportFullyVerified(r, expectedVerifierUids));
    if (unverified.length > 0) {
        showFeedbackMessage(
            `${unverified.length} report(s) are not fully verified by all teachers yet.`,
            'error'
        );
        return;
    }

    if (!confirm(`This will publish ${reportsToPublish.length} new report(s) to the respective students. This action cannot be undone. Continue?`)) {
        return;
    }

    toggleLoading(true, `Publishing ${reportsToPublish.length} reports...`);

    const publishPromises = reportsToPublish.map(report => {
        return publishAssessmentReport(
            report.studentUid,
            report,
            currentAssessmentForReportView!.assessmentId,
            currentAssessmentForReportView!.assessmentTitle
        ).then(() => {
            // On success, update the local state for this specific report
            report.published = true;
            return { status: 'success', name: report.studentName };
        }).catch(error => {
            console.error(`Failed to publish report for ${report.studentName}:`, error);
            return { status: 'error', name: report.studentName };
        });
    });

    const results = await Promise.all(publishPromises);

    toggleLoading(false);

    const successCount = results.filter(r => r.status === 'success').length;
    const errorCount = results.filter(r => r.status === 'error').length;
    
    renderAssessmentReportView(); // Re-render the entire view to update all button states
    showFeedbackMessage(`Successfully published ${successCount} reports. ${errorCount > 0 ? `${errorCount} failed.` : ''}`, "success");
};


window.handlePublishGuard = async (reportIndex: number) => {
    if (featureFlags.teacherPublishing === false) {
        showFeedbackMessage('Publishing has been disabled by your school admin.', 'error');
        return;
    }
    const report = assessmentReports[reportIndex];
    if (!report || !currentAssessmentForReportView || !teacherProfile) return;
    const expectedVerifierUids = await getExpectedVerifierUids(
        currentAssessmentForReportView.className,
        currentAssessmentForReportView.section,
        currentAssessmentForReportView.subject,
        teacherProfile.schoolName
    );
    if (!isReportFullyVerified(report, expectedVerifierUids)) {
        showFeedbackMessage('All teachers must verify this report before publishing.', 'error');
        return;
    }
    window.handlePublishSingleReport(reportIndex);
};
