// --- SEND EMAIL TO ALL STUDENTS ---
window.handleSendEmailToAllStudents = async () => {
    if (!currentAssessmentForReportView || assessmentReports.length === 0) {
        showFeedbackMessage("No reports available to send.", "info");
        return;
    }

    const publishedReports = assessmentReports.filter(r => r.published);
    if (publishedReports.length === 0) {
        showFeedbackMessage("Please publish reports before sending emails.", "info");
        return;
    }

    const assessmentTitle = currentAssessmentForReportView.assessmentTitle || 'Assessment';
    const teacherName = teacherProfile?.name || 'Your Teacher';
    const subject = `Results: ${assessmentTitle}`;

    // Collect all student emails — search by uid AND by name as fallback
    const allRosterStudents = currentAssessmentRoster || [];
    const toEmails: string[] = [];
    let errorCount = 0;

    for (const report of publishedReports) {
        // Try matching by uid first, then by name
        let rosterStudent = allRosterStudents.find(s => s.uid === report.studentUid);
        if (!rosterStudent) {
            rosterStudent = allRosterStudents.find(s => s.name?.toLowerCase() === report.studentName?.toLowerCase());
        }
        const studentEmail = rosterStudent?.email || '';
        if (studentEmail) {
            toEmails.push(studentEmail);
        } else {
            errorCount++;
        }
    }

    if (toEmails.length === 0) {
        showFeedbackMessage("No student emails found. Check roster has emails.", "error");
        return;
    }

    if (!confirm(`This will open your Gmail to send results to ${toEmails.length} student(s). Continue?`)) return;

    // Build a combined body listing all students
    const bodyLines = publishedReports.map(report => {
        const pct = report.maximumMarks > 0 ? ((report.overallScore / report.maximumMarks) * 100).toFixed(0) : '0';
        return `• ${report.studentName}: ${report.overallScore.toFixed(1)} / ${report.maximumMarks} (${pct}%)`;
    }).join('\n');

    const body = `Dear Students,\n\nYour results for "${assessmentTitle}" are now available on ClassMap.\n\nScores:\n${bodyLines}\n\nPlease log in to ClassMap to view your detailed report and feedback.\n\nBest regards,\n${teacherName}`;

    // Open Gmail compose with all students in BCC (privacy) 
    const gmailUrl = `https://mail.google.com/mail/?view=cm&fs=1&bcc=${encodeURIComponent(toEmails.join(','))}&su=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    window.open(gmailUrl, '_blank');

    showFeedbackMessage(`Gmail opened with ${toEmails.length} student(s) in BCC.${errorCount > 0 ? ` ${errorCount} student(s) had no email on file.` : ''}`, "success");
};

function naturalSortQuestions(a: AIQuestion, b: AIQuestion): number {

    const numA = a.questionNumber || '';
    const numB = b.questionNumber || '';

    const re = /(\d+)|(\D+)/g;
    const partsA = numA.match(re) || [];
    const partsB = numB.match(re) || [];

    for (let i = 0; i < Math.min(partsA.length, partsB.length); i++) {
        const partA = partsA[i];
        const partB = partsB[i];

        if (isNaN(Number(partA)) || isNaN(Number(partB))) {
            if (partA < partB) return -1;
            if (partA > partB) return 1;
        } else {
            const numPartA = parseInt(partA, 10);
            const numPartB = parseInt(partB, 10);
            if (numPartA < numPartB) return -1;
            if (numPartA > numPartB) return 1;
        }
    }
    return partsA.length - partsB.length;
}


// ADD THIS NEW FUNCTION
async function typesetMathInContainer(element: HTMLElement) {
    // This function explicitly tells MathJax to find and render any math
    // inside the HTML element we give it.
    if (window.MathJax && typeof window.MathJax.typesetPromise === 'function') {
        await window.MathJax.typesetPromise([element]);
    }
}


/**
 * Checks if a given subject is a literature-based subject.
 * This is used to apply special grading rules.
 * @param subject The name of the subject.
 * @returns True if it's a literature subject, otherwise false.
 */
function isLiteratureSubject(subject: string): boolean {
    if (!subject) return false;
    // This list contains keywords for identifying literature subjects.
    const literatureKeywords = [
        "english", "hindi", "sociology", "political science", 
        "history", "civics", "social studies", "general studies",
        "mass media & communication"
    ];
    const normalizedSubject = subject.trim().toLowerCase();
    return literatureKeywords.includes(normalizedSubject);
}











/**
 * Polls the local state every few seconds to check if answer sheet images have finished
 * uploading and their URLs are available. If found, it updates the open report modal.
 * @param reportIndex The index of the report in the global `assessmentReports` array.
 */
function startImagePolling(reportIndex: number) {
    const report = assessmentReports[reportIndex];
    if (!report || !report.submissionDocId || activeImagePolls.has(report.submissionDocId)) {
        return; // Don't start a poll if one is already active for this report
    }

    activeImagePolls.add(report.submissionDocId);
    let attempts = 0;
    const maxAttempts = 60; // Poll for a maximum of 2 minutes (60 * 2 seconds)

    const intervalId = setInterval(() => {
        const currentReport = assessmentReports[reportIndex];
        const imagesAvailable = currentReport?.answerSheetImageUrls && currentReport.answerSheetImageUrls.length > 0;

        if (imagesAvailable || attempts >= maxAttempts) {
            clearInterval(intervalId);
            activeImagePolls.delete(report.submissionDocId!);
        }

        if (imagesAvailable) {
            const container = document.getElementById(`student-answer-sheets-container--${reportIndex}`);
            if (container) {
                // Use our new helper to generate and inject the final HTML
                container.innerHTML = generateAnswerSheetImagesHtml(currentReport.answerSheetImageUrls!, currentReport.questionWiseReport);
            }
        }
        
        attempts++;

    }, 2000); // Check every 2 seconds
}




// Add '= []' to the reports parameter to prevent 'undefined' crashes
function generateAnswerSheetImagesHtml(imageUrls: string[], reports: AIQuestionReport[] = []): string {
    return `
        <div class="annotated-sheets-wrapper">
            ${imageUrls.map((url, idx) => {
                // ADD THE '?' to make the filter null-safe
const _sharedY1: number[] = [];
const annotations = (reports || [])
   .map((r, rIdx) => createHumanAnnotationHtml(r, idx, rIdx, rIdx, false, _sharedY1)) 
   .join('');
return `
  <div class="osm-container" style="position:relative; display: inline-block; margin-bottom:30px; line-height:0;">
    <img src="${url}" style="max-width:100%; display:block; border-radius:8px; border:1px solid #ddd; background:#fff;">
<div class="osm-overlay ${!isMarkersVisible ? 'markers-hidden' : ''}" id="${prefix}osm-overlay-layer"
             ondragover="event.preventDefault()"
             ondrop="window.handleOsmDrop(event, ${idx}, ${reportIndex})"
             style="position: absolute; top: 0; left: 0; width: 100%; height: 100%; opacity: 1; pointer-events:${isGlobalMarkerEdit || isOsmEditing ? 'auto' : 'none'};">        ${annotations}
    </div>
  </div>`;
            }).join('')}
        </div>`;
}

// This is the NEW function you will add
/**
 * A robust utility to sanitize any value into a finite number suitable for Firestore.
 * It safely handles null, undefined, strings, Infinity, and NaN.
 * @param value The raw value to sanitize.
 * @param defaultValue The value to return if sanitization fails (defaults to 0).
 * @returns A safe, finite number.
 */
function sanitizeFirestoreNumber(value: any, defaultValue: number = 0): number {
    const num = Number(value);
    // This check is crucial: isFinite() returns false for Infinity, -Infinity, and NaN.
    return isFinite(num) ? num : defaultValue;
}


