    let targetQIdx = report.questionWiseReport.findIndex(qr => {
        const fb = (qr.finalFeedback || '').toLowerCase();

        return (qr.answerPageIndex === pageIdx) || 
               (qr.stepWiseEvaluation || []).some(s => (s as any).pageIndex - 1 === pageIdx);
    });
    
    if (targetQIdx === -1) {
        targetQIdx = report.questionWiseReport.findIndex(qr => {
            const fb = (qr.finalFeedback || '').toLowerCase();
return true;
        });
    }
    if (targetQIdx === -1) targetQIdx = 0;
    
    const targetQ = report.questionWiseReport[targetQIdx];
    
    const newStep: AIStepEvaluation = {
        stepDescription: 'Manual Marker',
        comment: isCorrect ? 'Correct' : 'Incorrect',
        marks: isCorrect ? (targetQ.maxMarksForQuestion || 1) : 0,
        pageIndex: pageIdx + 1, // 1-based for storage
        stepPoint: [y, x],
        manualQNum: targetQ.questionNumber || ''
    };
    
    if (!targetQ.stepWiseEvaluation) targetQ.stepWiseEvaluation = [];
    targetQ.stepWiseEvaluation.push(newStep);
    
