/**
 * Cleans a string to make it safe for use in a filename.
 * Replaces spaces with underscores and removes invalid characters.
 * @param text The string to sanitize.
 * @returns A filesystem-safe string.
 */
function sanitizeForFilename(text: string): string {
    if (!text) return 'untitled';
    // Replace spaces with underscores, and remove characters that are invalid in filenames.
    return text.replace(/\s+/g, '_').replace(/[\\?%*:|"<>]/g, '');
}

function normalizeForComparison(str: string | undefined): string {
    if (!str) return '';
    return str.toLowerCase()
              .replace(/\b(ans|answer|q|question|sol|solution|cont|continued|pt|part)\b/gi, '')
              .replace(/[^a-z0-9]/g, '') 
              .trim();
}


function generateRosterId(teacherUid: string, className: string, section: string, subject: string, stream?: string): string {
    const cleanStream = stream && stream !== 'N/A' ? `_${stream.trim().replace(/\s+/g, '_')}` : '';
    return `${teacherUid}_${className.trim()}_${section.trim()}_${subject.trim().replace(/\s+/g, '_')}${cleanStream}`;
}


