/**
 * Recursively sanitizes an object to be compatible with Firestore.
 * Replaces all `undefined` values with `null`.
 * @param obj The object to sanitize.
 * @returns A new object that is safe to save to Firestore.
 */
function sanitizeObjectForFirestore(obj: any): any {
    if (obj === null || typeof obj !== 'object') {
        return obj;
    }

    if (Array.isArray(obj)) {
        return obj.map(item => sanitizeObjectForFirestore(item));
    }

    const sanitizedObj: { [key: string]: any } = {};
    for (const key in obj) {
        if (Object.prototype.hasOwnProperty.call(obj, key)) {
            const value = obj[key];
            if (value !== undefined) {
                sanitizedObj[key] = sanitizeObjectForFirestore(value);
            } else {
                sanitizedObj[key] = null; // Replace undefined with null
            }
        }
    }
    return sanitizedObj;
}

/**
 * A robust utility to find and parse a JSON object or array from a larger string.
 * It handles common AI response patterns like markdown code blocks.
 * @param text The raw string from the AI, which may contain JSON.
 * @returns The parsed JavaScript object/array, or null if no valid JSON is found.
 */
function extractJsonFromString(text: string): any | null {
    if (!text || typeof text !== 'string') {
        return null;
    }

     // If the text is massive (near 4000 tokens) and doesn't have a closing brace,
    // it likely hit a limit. We attempt a "Brute Force Close".
    let processedText = text.trim();
if (!processedText.endsWith('}') && !processedText.endsWith(']')) {
    console.warn("OCR: Detected truncated or broken response, forcing closure...");
    // 1. Count non-escaped quotes to close open strings
    const matches = processedText.match(/(?<!\\)"/g) || [];
    if (matches.length % 2 !== 0) {
        processedText += '"';
    }
    // 2. Add closing markers
    if (processedText.startsWith('{') && !processedText.includes('}')) processedText += ' }';
    if (processedText.startsWith('[') && !processedText.endsWith(']')) processedText += ' ]';
    // 3. Final failsafe
    if (!processedText.endsWith('}') && processedText.includes('{')) processedText += ' }';
}

    // First, try to find JSON within markdown code blocks (e.g., ```json ... ```)
    const markdownMatch = text.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
    if (markdownMatch && markdownMatch[1]) {
        try {
            return JSON.parse(markdownMatch[1].trim());
        } catch (e) {
            console.warn("Found a markdown JSON block, but failed to parse it. Will search the full text.", e);
        }
    }

    // If no markdown block, find the first '{' or '[' and the last '}' or ']'
    const firstBrace = text.indexOf('{');
    const firstBracket = text.indexOf('[');
    let startIndex = -1;

    if (firstBrace === -1 && firstBracket === -1) return null; // No JSON structure found

    if (firstBrace === -1) startIndex = firstBracket;
    else if (firstBracket === -1) startIndex = firstBrace;
    else startIndex = Math.min(firstBrace, firstBracket);

    const lastBrace = text.lastIndexOf('}');
    const lastBracket = text.lastIndexOf(']');
    let endIndex = Math.max(lastBrace, lastBracket);

    if (startIndex === -1 || endIndex === -1) {
        return null;
    }
    
    // Ensure we have a complete structure (e.g., { ... } or [ ... ])
    const jsonString = text.substring(startIndex, endIndex + 1);

    try {
        return JSON.parse(jsonString);
    } catch (e) {
        console.error("Failed to parse the extracted JSON string:", jsonString, e);
        return null;
    }
}


// REPLACE the old parseStreamedJson function with this entire new one
function parseStreamedJson(jsonString: string): any | null {
    if (!jsonString || typeof jsonString !== 'string') return null;

    // Fast path: try direct parse first
    try {
        return JSON.parse(jsonString);
    } catch (e) {
        // Fall through to cleaning
    }

    // --- Robust multi-pass cleaning ---

    // Step 1: Fix literal (unescaped) newlines and carriage returns inside strings
    let cleanedString = jsonString
        .replace(/\r\n/g, '\\n')
        .replace(/\n/g, '\\n')
        .replace(/\r/g, '\\r');

    // Step 2: Protect already-correct double backslashes (LaTeX \frac, \\, etc.)
    //         Replace \\ with a placeholder so Step 3 doesn't touch them
    const PH = '___DBLBSLASH___';
    cleanedString = cleanedString.replace(/\\\\/g, PH);

    // Step 3: Fix lone backslashes before LaTeX/special characters that are NOT
    //         valid JSON escape sequences. In JSON, only \", \\, \/, \b, \f,
    //         \n, \r, \t, \uXXXX are valid. Anything else (\f in \frac,
    //         \r in \rho, \t in \tau etc.) must be doubled to \\frac etc.
    //         We match a single backslash NOT followed by valid JSON escape chars.
    cleanedString = cleanedString.replace(/\\(?!["\\\/bfnrtu])/g, '\\\\');

    // Step 4: Restore the protected double backslashes
    cleanedString = cleanedString.replace(new RegExp(PH, 'g'), '\\\\');

    try {
        return JSON.parse(cleanedString);
    } catch (e) {
        // Last resort: try stripping markdown fences and retry
        const stripped = cleanedString.replace(/```json|```/g, '').trim();
        try {
            return JSON.parse(stripped);
        } catch (e2) {
            console.error("[parseStreamedJson] Failed after all cleaning steps.", (e as Error).message);
            return null;
        }
    }
}

window.showSpeedDetails = () => {
    const conn = (navigator as any).connection;
    if (conn) {
        const speed = conn.downlink; // Estimated Mbps
        const type = conn.effectiveType; // e.g. 4g
        alert(`Current Connection Details:\n- Speed: ${speed} Mbps\n- Quality: ${type.toUpperCase()}\n\nRecommendation: ${speed > 5 ? 'Good for Batch Grading' : 'Slow. Grade 1-2 students at a time to prevent errors.'}`);
    }
};

function startNetworkMonitoring() {
    const textEl = document.getElementById('network-speed-text');
    const pillEl = document.getElementById('network-speed-pill');
    
    const updateStatus = () => {
    if (!textEl || !pillEl) return;
    
    if (!navigator.onLine) {
        pillEl.className = 'network-pill bad';
        textEl.textContent = "Offline";
        return;
    }

    const conn = (navigator as any).connection || (navigator as any).mozConnection || (navigator as any).webkitConnection;
    
    if (conn) {
        // downlink provides estimated Mbps
        const down = conn.downlink || 0;
        // Standard heuristic: Upload is typically ~40% of download on stable connections
        // We use this to provide a consistent UI display without consuming the user's data with a speed test.
        const up = down * 0.4; 

        pillEl.className = 'network-pill';
        
        // Threshold Logic:
        // Red (Bad): Download < 5 Mbps OR Upload < 2 Mbps
        if (down < 5 || up < 2) {
            pillEl.classList.add('bad');
        } 
        // Green (Good): Download > 10 Mbps AND Upload > 5 Mbps
        else if (down > 10 && up > 5) {
            pillEl.classList.add('good');
        } 
        // Yellow (Moderate): Everything else
        else {
            pillEl.classList.add('moderate');
        }

        // Updated Display String
        textEl.textContent = `D: ${down.toFixed(1)} | U: ${up.toFixed(1)} Mbps`;
    } else {
        pillEl.className = 'network-pill moderate';
        textEl.textContent = "Network: Connected";
    }
};

    // Listen for live fluctuations in network quality
    const conn = (navigator as any).connection;
    if (conn) {
        conn.addEventListener('change', updateStatus);
    }
    
    // Continuous 2-second polling to ensure the Mbps value is always fresh
    setInterval(updateStatus, 2000);
    updateStatus(); 
}

