function toggleModal(id: string, show: boolean, skipHistory: boolean = false) {
    const modal = document.getElementById(id) as HTMLElement;
    if (modal) {
        // --- RESTORED MISSING VARIABLE ---
        const isVisible = modal.style.display === 'flex';

      if (show && !isVisible) {
            const currentState = history.state || {};
            
            // Check if we are in a restricted sandbox
            const canPushState = window.history && typeof window.history.pushState === 'function';

            if (canPushState) {
                try {
                   history.pushState({ ...currentState, modalOpen: id }, "", window.location.hash);
                } catch (e) {
                    // Fail silently in sandbox environments
                }
            }
            
            modal.style.display = 'flex';
            modal.setAttribute('aria-hidden', 'false');

        } else if (!show) {
            // Closing: Hide the modal
            modal.style.display = 'none';
            modal.setAttribute('aria-hidden', 'true');

if (id === 'fullscreen-grading-modal' && currentStudentUidForReport) {
    renderIndividualStudentReportPage(currentStudentUidForReport);
}
            // If the current history state indicates this modal is open, 
            // go back one step to keep history clean.
            if (!skipHistory) { 
                try {
                    if (history.state && history.state.modalOpen === id) {
                        history.back();
                    }
                } catch (e) {
                    // Ignore history errors during close
                }
            }
        }
    }
}
window.toggleModal = toggleModal;

