async function processImageFile(file: File): Promise<File> {
    if (!file.type.startsWith('image/')) {
        return file;
    }

    // --- UPDATE THIS LINE ---
    const MAX_DIMENSION = 2048;

    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (event) => {
            const img = new Image();
            img.onload = async () => {
                const canvas = document.createElement('canvas');
                let { width, height } = img;

                // Resize Logic (Maintain Aspect Ratio)
                if (width > height) {
                    if (width > MAX_DIMENSION) {
                        height *= MAX_DIMENSION / width;
                        width = MAX_DIMENSION;
                    }
                } else {
                    if (height > MAX_DIMENSION) {
                        width *= MAX_DIMENSION / height;
                        height = MAX_DIMENSION;
                    }
                }
                canvas.width = width;
                canvas.height = height;

                const ctx = canvas.getContext('2d');
                if (!ctx) return reject(new Error('Could not get canvas context'));
                
                // Draw original image resized.
                ctx.drawImage(img, 0, 0, width, height);
                


                // --- ADD THIS BLOCK ---
if (window.cv && (isCVLoaded || (window.cv.Mat))) {
    if (!isCVLoaded) isCVLoaded = true; // Self-heal state
    const enhancedCanvas = await enhanceImageForOcr(canvas);
    // Replace the simple resized canvas with the enhanced one
    canvas.width = enhancedCanvas.width;
    canvas.height = enhancedCanvas.height;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(enhancedCanvas, 0, 0);
}
// ----------------------

                // Export as JPEG at 0.65 quality. 
                // This is the "Sweet Spot": High Resolution (2048px) + Medium Compression.
                // This makes text clearer for AI but keeps file size low for speed.
                canvas.toBlob(
                    (blob) => {
                        if (!blob) return reject(new Error('Image processing failed'));
                        const newFile = new File([blob], file.name, {
                            type: 'image/jpeg',
                            lastModified: Date.now(),
                        });
                        resolve(newFile);
                    },
                    'image/jpeg',
                    0.85 
                );
            };
            img.onerror = (err) => reject(new Error('Failed to load image: ' + err));
            if (event.target?.result) {
                img.src = event.target.result as string;
            } else {
                reject(new Error('FileReader failed to read file.'));
            }
        };
        reader.onerror = (err) => reject(new Error('FileReader error: ' + err));
        reader.readAsDataURL(file);
    });
}



// PASTE THIS NEW FUNCTION
function toggleFilterPopup(popupId: string, buttonId: string) {
    const allPopups = document.querySelectorAll('.filter-popup');
    const allButtons = document.querySelectorAll('.filter-icon-btn');
    const targetPopup = document.getElementById(popupId);
    const targetButton = document.getElementById(buttonId);

    // Close all other popups first
    allPopups.forEach(p => {
        if (p.id !== popupId) {
            p.classList.remove('active');
        }
    });
    allButtons.forEach(b => {
        if (b.id !== buttonId) {
            b.classList.remove('active');
        }
    });

    // Toggle the target popup
    if (targetPopup && targetButton) {
        targetPopup.classList.toggle('active');
        targetButton.classList.toggle('active');
    }
}

