async function handlePrintAssessment(printType: 'questions' | 'solutions' | 'full') {
    if (!temporaryAssessmentData || !temporaryAssessmentData.questions) {
        showFeedbackMessage("No questions to print.", "info");
        return;
    }

    const questionsToPrint = temporaryAssessmentData.questions.filter(q => q.kept !== false);
    if (questionsToPrint.length === 0) {
        showFeedbackMessage("No questions have been kept to print.", "info");
        return;
    }

    const { subject, className, section, assessmentTitle, source } = temporaryAssessmentData;
    const totalMarks = temporaryAssessmentData.totalMarks ?? questionsToPrint.reduce((sum, q) => sum + (q.marks || 0), 0);
    
    // This is the new part: call our generator function
    const printHtml = generateModernQuestionPaperHtml(
        assessmentTitle || 'Assessment',
        {
            schoolName: teacherProfile?.schoolName || 'Your School',
            subject: subject!,
            className: className!,
            section: section!
        },
        totalMarks,
        questionsToPrint,
        { printType, source }
    );
    
    const originalTitle = document.title;
    const sanitizedTitle = sanitizeForFilename(assessmentTitle || 'Assessment');
const fileType = printType === 'questions' ? 'Question_Paper' : printType === 'solutions' ? 'Answer_Key' : 'Full_Details';
    document.title = `${sanitizedTitle}_${fileType}`;
    
    printableContentEl.innerHTML = printHtml;
    await typesetMathInContainer(printableContentEl);
    
    // Add a brief delay to ensure math renders before printing
    setTimeout(() => {
        window.print();
        document.title = originalTitle;
    }, 250);
}


