async function uploadToTempStorage(file: File, studentUid: string, skipProcessing: boolean = false, assessmentId?: string): Promise<string> {
    if (!teacherProfile) throw new Error("Context missing.");
    const resolvedAssessmentId = assessmentId || currentAssessmentToGrade?.assessmentId;
    if (!resolvedAssessmentId) throw new Error("Context missing.");
    
    // If skipProcessing is true (for PDF pages already enhanced), use the raw file
    const fileToUpload = skipProcessing ? file : await processImageFile(file);
    
    const fileTime = file.lastModified || Date.now();
    const path = `gradedReports/${teacherProfile.uid}/${resolvedAssessmentId}/${studentUid}/${fileTime}_${file.name}`;
    
    const storageRef = fbStorage.ref(path);
    await storageRef.put(fileToUpload); // Changed from processedFile to fileToUpload
    
    return path;
}

/**
 * Pre-upload: called immediately when teacher selects files.
 * Splits PDFs → images, uploads all to Firebase Storage, saves URLs to Firestore.
 */
async function preUploadStudentFiles(studentUid: string, files: File[], assessmentId: string): Promise<{ paths: string[], urls: string[] }> {
    if (!teacherProfile || !fbStorage) throw new Error("Not initialized.");

    // Expand PDFs to image files
    const expandedPromises = files.map(async (file) => {
        if (file.type === 'application/pdf') return await processPdfToImageFiles(file);
        return [file];
    });
    const nested = await Promise.all(expandedPromises);
    const expanded = nested.flat();

    // Upload all files in parallel
    const uploadPromises = expanded.map(file =>
        uploadToTempStorage(file, studentUid, file.name.includes('_page_'), assessmentId)
    );
    const paths = await Promise.all(uploadPromises);

    // Get download URLs
    const urlPromises = paths.map(p => fbStorage.ref(p).getDownloadURL());
    const urls = await Promise.all(urlPromises);

    // Persist to Firestore so it survives refresh
    try {
        await fbFirestore
            .collection('teachers').doc(teacherProfile.uid)
            .collection('assessmentUploads').doc(assessmentId)
            .collection('students').doc(studentUid)
            .set({ paths, urls, uploadedAt: window.firebase.firestore.FieldValue.serverTimestamp() });
    } catch (e) {
        console.warn('[PreUpload] Firestore save failed, URLs still in memory:', e);
    }

    return { paths, urls };
}

/**
 * Load pre-uploaded URLs for all students in an assessment from Firestore.
 */
async function loadPreUploadedStudentData(assessmentId: string): Promise<void> {
    if (!teacherProfile || !fbFirestore) return;
    try {
        const snap = await fbFirestore
            .collection('teachers').doc(teacherProfile.uid)
            .collection('assessmentUploads').doc(assessmentId)
            .collection('students').get();
        snap.forEach(doc => {
            const data = doc.data();
            if (data.paths && data.urls) {
                studentPreUploadedData.set(doc.id, { paths: data.paths, urls: data.urls });
            }
        });
    } catch (e) {
        console.warn('[PreUpload] Could not load pre-upload data:', e);
    }
}



