async function handleExecuteRecheck(studentUid: string, targetPageNumbers: number[] | null) {
    const reportIndex = assessmentReports.findIndex(r => r.studentUid === studentUid);
    const report = assessmentReports[reportIndex];
    if (!report || !currentAssessmentToGrade) return;

    toggleModal('recheck-options-modal', false);
    toggleLoading(true, "Executing targeted recheck...");

    try {
        // 1. Identify which pages (indices) to process
        const totalPages = report.answerSheetImageUrls?.length || 0;
        const pageIndices = targetPageNumbers 
            ? targetPageNumbers.map(n => n - 1).filter(i => i >= 0 && i < totalPages)
            : Array.from({length: totalPages}, (_, i) => i);

        if (pageIndices.length === 0) throw new Error("Invalid page selection.");

        // 2. Fetch image blobs for these pages
        const selectedUrls = pageIndices.map(i => report.answerSheetImageUrls![i]);
const imageFiles = await Promise.all(selectedUrls.map(async (url, idx) => {
    const proxyResponse = await fetch(BACKEND_OCR_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: 'fetch_image', url: url })
    });

    if (!proxyResponse.ok) throw new Error("Proxy fetch failed during recheck");

    const data = await proxyResponse.json();
    const byteCharacters = atob(data.base64);
    const byteNumbers = new Array(byteCharacters.length);
    for (let j = 0; j < byteCharacters.length; j++) {
        byteNumbers[j] = byteCharacters.charCodeAt(j);
    }
    const byteArray = new Uint8Array(byteNumbers);
    const blob = new Blob([byteArray], { type: data.mimeType || 'image/jpeg' });

    // Replace the UI refresh block with this:
const isFullscreen = document.getElementById('fullscreen-grading-modal')?.style.display === 'flex';
if (isFullscreen) {
    // Just refresh the Fullscreen UI without resetting the scroll position or page
    renderReportPageUI(report, reportIndex);
} else {
    // If in Standard Modal, refresh it but preserve the current page
    const savedPageIdx = currentReportPageIdx;
    renderIndividualStudentReportPage(studentUid);
    currentReportPageIdx = savedPageIdx;
    renderReportPageUI(report, reportIndex);
}

renderAssessmentReportView(); // Update the background table

    return new File([blob], `page_${pageIndices[idx] + 1}.jpg`, { type: data.mimeType || 'image/jpeg' });
}));

        // 3. Re-OCR only selected pages
        const ocrResults = await extractTextFromImages(imageFiles, 'Recheck OCR');
        
        // 4. Update the full transcript (merging new data into old)
        const oldOcrLines = report.fullOcrText?.split('\n') || [];
        // Helper to reconstruct text
        pageIndices.forEach((pIdx, arrayIdx) => {
            const startTag = `[START_PAGE_${pIdx + 1}]`;
            const endTag = `[END_PAGE_${pIdx + 1}]`;
            const newText = `${startTag}\n${ocrResults[arrayIdx].text}\n${endTag}`;
            
            // This is a naive replacement, in a real system we'd use regex on fullOcrText
            const regex = new RegExp(`\\[START_PAGE_${pIdx + 1}\\][\\s\\S]*?\\[END_PAGE_${pIdx + 1}\\]`, 'g');
            report.fullOcrText = report.fullOcrText!.replace(regex, newText);
        });

        // 5. Identify questions linked to these pages
const detectedQNums = new Set<string>();

// 1. Scan the NEW OCR results for [Q:N] tags to find questions physically on these pages
ocrResults.forEach(res => {
    const matches = res.text.match(/\[Q\s*:\s*([^\]\s]+)\]/gi);
    if (matches) {
        matches.forEach(m => {
            const qNum = m.match(/\[Q\s*:\s*([^\]\s]+)\]/i)?.[1];
            if (qNum) detectedQNums.add(normalizeForComparison(qNum));
        });
    }
});

// 2. Also include questions previously mapped to these pages in the existing report
report.questionWiseReport.forEach(qr => {
if (pageIndices.includes(qr.answerPageIndex ?? 0)) {
        detectedQNums.add(normalizeForComparison(qr.questionNumber));
    }
});

// 3. Cross-reference with the master Assessment list to find full question data
const questionsToRegrade = currentAssessmentToGrade.questions.filter(q => 
    detectedQNums.has(normalizeForComparison(q.questionNumber))
);

        // 6. Re-grade only affected questions
        if (questionsToRegrade.length > 0) {
            const strictness = assessmentStudentStrictness.get(studentUid) || 'Moderate';
// Build a context window (Current Page N + Following Page N+1)
const contextPages = new Set<number>();
pageIndices.forEach(idx => {
    contextPages.add(idx + 1); // The actual Page N
    contextPages.add(idx + 2); // The context Page N+1
});
const sortedContext = Array.from(contextPages).sort((a, b) => a - b);

const batchOcr = sortedContext.map(pNum => {
    const text = getOcrTextForPage(report.fullOcrText, pNum);
    return text.includes("not found") ? "" : `[PAGE ${pNum}]\n${text}`;
}).filter(t => t !== "").join('\n\n');
            const newGrades = await gradeQuestionBatchFromOcrText(batchOcr, questionsToRegrade.map(q => ({
                questionNumber: q.questionNumber,
                questionText: q.text,
                modelAnswer: q.answer,
                maxMarks: q.marks,
                topic: q.topic,
                type: q.type
            })), strictness, currentAssessmentToGrade.subject);

            // 7. Update report state (merge new grades)
newGrades.forEach(newQ => {
    const idx = report.questionWiseReport.findIndex(qr => qr.questionNumber === newQ.questionNumber);
    if (idx !== -1) {
        report.questionWiseReport[idx] = { ...report.questionWiseReport[idx], ...newQ };
    } else {
        // PUSH new questions found by recheck that weren't in the report before
        report.questionWiseReport.push(newQ);
    }
});

// Re-sort questions numerically so they appear correctly in the UI
report.questionWiseReport.sort((a, b) => {
    const numA = parseInt(a.questionNumber.replace(/\D/g, '')) || 0;
    const numB = parseInt(b.questionNumber.replace(/\D/g, '')) || 0;
    return numA - numB;
});

            // 8. Recalculate totals
            report.overallScore = report.questionWiseReport.reduce((s, qr) => s + qr.marksAwarded, 0);
            
            // 9. Save to Firestore
            await saveUpdatedAssessmentReport(report);
            
            // 10. Refresh UI
            renderAssessmentReportView();
            renderIndividualStudentReportPage(studentUid);
            showFeedbackMessage(`Recheck complete for ${pageIndices.length} page(s).`, "success");
        }

    } catch (e) {
        console.error("Recheck Error:", e);
        showFeedbackMessage("Recheck failed: " + (e as Error).message, "error");
    } finally {
        toggleLoading(false);
    }
}

async function preloadTeacherData(uid: string) {
    if (isTeacherDataPreloaded) return;
    try {
        // Fetch all homeworks, assessment history, and submissions in parallel
        const hws = await getAssignedHomeworks(uid);
        const hwIds = hws.map(hw => hw.homeworkId);
        
        const [asmtHistory, allSubs] = await Promise.all([
            getAssessmentHistory(uid),
            getAllSubmissionsForTeacher(hwIds)
        ]);
        
allAssignedHomeworks = hws;
        globalAssessmentHistoryCache = asmtHistory;
        globalSubmissionsCache = allSubs;
        // Pre-fetch and cache created assessments too (avoids slow fetch on every class click)
        try {
            globalCreatedAssessmentsCache = await getCreatedAssessments(uid);
        } catch (e) {
            console.warn("Could not preload created assessments cache:", e);
        }
        isTeacherDataPreloaded = true;
        console.log("🚀 Background Cache Primed: Card clicks will now be instant.");
} catch (e) {
        isTeacherDataPreloaded = false; // ← ADD THIS — allows retry next time
        console.warn("Preload encountered an issue, falling back to live fetch.", e);
    }
}

