function renderNotes() {
    notesContainerEl.innerHTML = ''; // Clear everything first
    
    if (notes.length === 0) {
        notesContainerEl.innerHTML = `
            <div class="empty-notes-placeholder">
                <p>Your sticky notes will appear here. Click the '+' button to add your first note!</p>
            </div>
        `;
        return;
    }

    notes.forEach(note => {
        const wrapper = document.createElement('div');
        wrapper.className = 'sticky-note-wrapper';

        const noteEl = document.createElement('textarea');
        noteEl.className = 'sticky-note';
        noteEl.value = note.content;
        noteEl.style.backgroundColor = note.color;
        noteEl.placeholder = "Type your note...";

        noteEl.addEventListener('change', () => {
            note.content = noteEl.value;
            // No re-render needed on change, just save
            localStorage.setItem('teacherNotes', JSON.stringify(notes));
        });

        const removeBtn = document.createElement('button');
        removeBtn.className = 'remove-note-btn';
        removeBtn.innerHTML = '&times;';
        removeBtn.title = 'Remove note';
        removeBtn.onclick = () => {
            if (confirm('Are you sure you want to remove this note?')) {
                const noteIndex = notes.findIndex(n => n.id === note.id);
                if (noteIndex > -1) {
                    notes.splice(noteIndex, 1);
                    saveAndRenderNotes(); // This will save the change and re-render all notes
                }
            }
        };
        
        wrapper.appendChild(noteEl);
        wrapper.appendChild(removeBtn);
        notesContainerEl.appendChild(wrapper);
    });
}

function saveAndRenderNotes() {
    localStorage.setItem('teacherNotes', JSON.stringify(notes));
    renderNotes();
}

async function fileToPart(file: File): Promise<Part> {
    const base64 = await new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.onerror = error => reject(error);
        reader.readAsDataURL(file);
    });
    return { inlineData: { mimeType: file.type, data: base64 } };
}

async function fileToBase64(file: File): Promise<string> {
    return new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve((reader.result as string).split(',')[1]);
        reader.onerror = error => reject(error);
        reader.readAsDataURL(file);
    });
}


