/** Strip coordinate tags like [#P:1,36,200], [QLABEL:...], [Q:...] and OCR confidence markers from display text */
function stripOcrDisplayTags(text: string): string {
    if (!text) return '';
    return text
        .replace(/\[#P\s*:\s*[\d,\s]+\]/gi, '')
        .replace(/\[QLABEL:[^\]]*\]/gi, '')
        .replace(/\[Q:[^\]]*\]/gi, '')
        .replace(/\[START_PAGE_\d+\]/gi, '')
        .replace(/\[END_PAGE_\d+\]/gi, '')
        // Strip Gemini OCR confidence highlight markers: @@@word@@@ or @word@
        .replace(/@{1,3}([^@\n]*)@{1,3}/g, '$1')
        // Strip any remaining lone @ symbols that are artifacts
        .replace(/(?<![a-zA-Z0-9])@(?![a-zA-Z0-9])/g, '')
        .replace(/\n{3,}/g, '\n\n')
        .trim();
}

async function handlePALGenerateWorksheets(roster: ClassRoster) {
    const selectedExamIds = Array.from(
        document.querySelectorAll<HTMLInputElement>('.pal-exam-check:checked')
    ).map(c => c.value);

    const selectedStudents = Array.from(
        document.querySelectorAll<HTMLInputElement>('.pal-student-check:checked')
    ).map(c => ({ uid: c.value, name: c.dataset.name! }));

    if (selectedExamIds.length === 0) { showFeedbackMessage('Select at least one exam.', 'error'); return; }
    if (selectedStudents.length === 0) { showFeedbackMessage('Select at least one student.', 'error'); return; }
    if (!confirm(`Generate worksheets for ${selectedStudents.length} students from ${selectedExamIds.length} exam(s)?`)) return;

    toggleLoading(true, 'Generating Personalized Worksheets...');
    let count = 0;

    // Get assessment metadata (board, class, subject, chapters) from first exam
    const firstAssessDoc = await fbFirestore.collection('teachers').doc(teacherProfile!.uid)
        .collection('assessmentHistory').doc(selectedExamIds[0]).get();
    const assessMeta = firstAssessDoc.data() as CreatedAssessment;

    try {
        for (const student of selectedStudents) {
            // Merge weakness data across all selected exams for this student
            const allWeaknesses: string[] = [];
            const allClusters: string[] = [];
            let primaryFailureMode = '';

            for (const examId of selectedExamIds) {
// Try direct UID doc first, then query by studentUid field
let subDoc = await fbFirestore.collection('teachers').doc(teacherProfile!.uid)
    .collection('assessmentHistory').doc(examId)
    .collection('submissions').doc(student.uid).get();

if (!subDoc.exists) {
    const subQuery = await fbFirestore.collection('teachers').doc(teacherProfile!.uid)
        .collection('assessmentHistory').doc(examId)
        .collection('submissions').where('studentUid', '==', student.uid).limit(1).get();
    if (subQuery.empty) continue;
    subDoc = subQuery.docs[0] as any;
}

                const report = subDoc.data() as AIFullAssessmentReport;

                // Root cause clusters (highest priority)
                (report.studentIntelligence?.prerequisiteClusters || [])
                    .forEach(c => allClusters.push(c.concept));

                // Improvement areas
                (report.overallFeedback?.areasForImprovement || [])
                    .map(a => typeof a === 'object' ? a.text : a)
                    .filter(Boolean)
                    .forEach(a => allWeaknesses.push(a as string));

                if (!primaryFailureMode && report.studentIntelligence?.summary?.primaryFailureMode)
                    primaryFailureMode = report.studentIntelligence.summary.primaryFailureMode;
            }

            // Deduplicate
            const uniqueClusters = [...new Set(allClusters)];
            const uniqueWeaknesses = [...new Set(allWeaknesses)];
            const mergedTopics = [...uniqueClusters, ...uniqueWeaknesses.filter(w => !uniqueClusters.some(c => w.includes(c)))];

            if (mergedTopics.length === 0) continue;

            const selectedChapters = assessMeta.selectedChapters?.join(', ') || 'General Curriculum';

            const prompt = `You are a Senior Curriculum Designer for ${assessMeta.board}.

CURRICULUM CONTEXT:
- Board: ${assessMeta.board}
- Class: ${assessMeta.className}
- Subject: ${assessMeta.subject}
- Chapters: ${selectedChapters}

STUDENT WEAKNESS PROFILE:
- Root weakness topics: ${uniqueClusters.join(', ') || 'None identified'}
- Improvement areas: ${uniqueWeaknesses.slice(0, 10).join(', ')}
- Primary error pattern: ${primaryFailureMode || 'General'}

TASK:
Generate exactly 10 practice questions that address the student's weakness topics above.
Rules:
1. Merge related weaknesses into single questions where possible.
2. Vary question types: MCQ, short answer, application, case-based.
3. Do NOT generate one question per topic mechanically — synthesize.
4. Questions must be curriculum-appropriate for ${assessMeta.board} ${assessMeta.className} ${assessMeta.subject}.
5. Each question must have a model answer (2-4 bullet points max).

Return a JSON array of objects: { "topic": string, "caseStudy": string, "question": string, "answer": string }
caseStudy can be empty string "" for direct questions.`;

            try {
                const response = await getAiInstance().models.generateContent({
                    model: 'gemini-2.5-flash',
                    contents: prompt,
                    config: {
                        responseMimeType: "application/json",
                        responseSchema: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    topic: { type: Type.STRING },
                                    caseStudy: { type: Type.STRING },
                                    question: { type: Type.STRING },
                                    answer: { type: Type.STRING }
                                },
                                required: ["topic", "caseStudy", "question", "answer"]
                            }
                        },
                        temperature: 0.1,
                        maxOutputTokens: 2000,
                        thinkingConfig: { thinkingBudget: 0 }
                    }
                });

              const rawText = response.text.trim()
    .replace(/```json\n?/g, '').replace(/```/g, '').trim();
const questions = JSON.parse(rawText);
                const docId = `${student.uid}_pal_${Date.now()}`;
                const worksheet: PersonalizedWorksheet = {
                    studentUid: student.uid,
                    studentName: student.name,
                    assessmentId: selectedExamIds.join('_'),
                    assessmentTitle: `Personalized Practice — ${assessMeta.subject}`,
                    subject: assessMeta.subject,
                    className: assessMeta.className,
                    board: assessMeta.board,
                    questions: questions.map((q: any) => ({ ...q, marks: 2 })),
                    sentAt: new Date().toISOString()
                };
                await fbFirestore.collection('studentWorksheets').doc(docId).set(sanitizeObjectForFirestore(worksheet));
                count++;
            } catch (e) {
                console.error(`Worksheet generation failed for ${student.name}:`, e);
            }
        }
        showFeedbackMessage(`✅ Generated ${count} worksheets!`, 'success');
    } finally {
        toggleLoading(false);
    }
}

function formatMathExpressions(text: string, isMathSubject: boolean = true): string {
    if (!text || typeof text !== 'string') return '';

    // PRE-PROCESS: Strip soft line breaks copied verbatim from narrow-column PDFs.
    // PDFs often have line breaks mid-sentence (e.g., "She makes ice creams from fresh milk and the\nsame are available...")
    // These are NOT paragraph breaks — they're just PDF column wrapping artifacts.
    // Strategy: collapse any newline that is NOT followed by a blank line, a number+dot, a letter+paren, or a bullet
    // into a single space. This preserves real paragraph breaks and list items.
    text = text
        // Collapse mid-sentence line breaks: newline NOT preceded/followed by blank line
.replace(/([^\n])\n([^\n])/g, (match, before, after) => {
    if (/^(\d+[\.\)]\s|[A-Z]\)\s|\*\s|-\s|•\s|[A-Z]{2,})/.test(after)) return match;
    if (/:\s*$/.test(before)) return match;
    if (before === '|' || after === '|') return match;
    return before + ' ' + after;
});




let processedText = text
        // Collapse any run of 2+ backslashes down to exactly 1, BEFORE anything else.
        // Grader sometimes mismatches escaping, e.g. "\\(x = \frac{1}{2}\)" — double
        // backslash on the opening delimiter, single on the closing one. Normalizing
        // here prevents MathJax delimiter-mismatch failures downstream.
        .replace(/\\{2,}/g, '\\')
        // Unwrap math delimiters that contain rupee sign but no real LaTeX
        .replace(/\\\(\s*(₹[^)]*?)\s*\\\)/g, '$1')
        .replace(/\\\[\s*(₹[^]]*?)\s*\\\]/g, '$1')
        // Also handle escaped \₹ → ₹
        .replace(/\\₹/g, '₹');

// PRE-PROCESS: Fix bare LaTeX commands missing the leading backslash.
    // Grader sometimes outputs mismatched escaping, e.g. "\\(x = \frac{1}{2}\)"
    // (double backslash on the opening delimiter, single on the closing one).
    // This normalizes \\\(, \\\\frac, \\\), etc. all down to single-backslash LaTeX
    // before any other math processing runs.
    processedText = processedText.replace(/\\{2,}/g, '\\');

// PRE-PROCESS: Fix bare LaTeX commands missing the leading backslash.
    // Grader outputs e.g. "frac1U + frac1V" instead of "\frac1U + \frac1V".
    // Only add \ if NOT already preceded by a backslash.
// Fix bare LaTeX commands missing backslash — math-only tokens only, never English words
processedText = processedText.replace(
    /(?<!\\)\b(frac|sqrt|oint|prod|alpha|beta|gamma|delta|epsilon|theta|lambda|mu|nu|phi|psi|omega|sigma|rho|eta|xi|zeta|chi|kappa|iota|infty|partial|nabla|cdot|cdots|ldots|neq|leq|geq|approx|equiv|propto|notin|subset|supset|forall|exists|rightarrow|leftarrow|Rightarrow|Leftarrow|leftrightarrow|mapsto|vec|ddot|overline|underline|mathrm|mathbf|mathbb|mathcal)(?=[0-9{]|\b)/g,
    '\\$1'
);
    processedText = processedText.replace(/#/g, '\\#');
   const commonLatexRegex = /\\(frac|sqrt|int|sum|alpha|beta|gamma|delta|epsilon|theta|lambda|mu|nu|pi|phi|psi|omega|sigma|rho|eta|xi|zeta|chi|kappa|infty|partial|nabla|alpha|times|div|pm|mp|cdot|cdots|ldots|neq|leq|geq|le|ge|approx|equiv|sim|propto|in|notin|subset|supset|cup|cap|forall|exists|rightarrow|leftarrow|Rightarrow|Leftarrow|leftrightarrow|to|mapsto|vec|hat|bar|dot|ddot|tilde|overline|underline|text|mathrm|mathbf|mathbb|sin|cos|tan|cot|log|ln|exp|lim|max|min|\{|[_^])/g;
    const hasDelimiters = /\\\(|\\\[|\$\$|\$/.test(processedText);
    
    if (commonLatexRegex.test(processedText) && !hasDelimiters) {
        processedText = processedText.split('\n').map(line => {
            if (commonLatexRegex.test(line) && !/\\\(|\\\[|\$\$|\$/.test(line)) {
                return `\\( ${line.trim()} \\)`;
            }
            return line;
        }).join('\n');
    }
    
    // More resilient regex that handles varied backslash escaping from the OCR/JSON pipeline
const mathRegex = /(\\+\[[\s\S]*?\\+\])|(\\+\([\s\S]*?\\+\))|(\$\$[\s\S]*?\$\$)/g;
    
    const mathExpressions: string[] = [];
    let textWithPlaceholders = processedText.replace(mathRegex, (match) => {
        mathExpressions.push(match);
        return `%%MATH_PLACEHOLDER_${mathExpressions.length - 1}%%`;
    });

textWithPlaceholders = textWithPlaceholders.replace(/^(\s*)(\d+)\./gm, '$1$2\\.');

    let html = marked.parse(textWithPlaceholders, { breaks: true, gfm: true }) as string;

    html = html.replace(/%%MATH_PLACEHOLDER_(\d+)%%/g, (match, indexStr) => {
        const index = parseInt(indexStr, 10);
        let originalMatch = mathExpressions[index];
        if (!originalMatch) return '';

        // FIX: Ensure delimiters are single-slashed for MathJax compatibility
        originalMatch = originalMatch.replace(/^\\+\(/, '\\(')
                            .replace(/\\+\)$/, '\\)')
                            .replace(/^\\+\[/, '\\[')
                            .replace(/\\+\]$/, '\\]');

        // FIX: Escape raw HTML special chars before they're injected into the HTML string.
        // Math like "\(9<x<16\)" contains a literal "<" immediately followed by a letter,
        // which the browser's HTML parser reads as the start of a tag (e.g. "<x...>") once
        // this string is set via innerHTML — silently swallowing everything up to the next
        // ">" (which may be far downstream in unrelated markup) and corrupting the card.
        // Escaping here is transparent to MathJax, which reads the decoded text content.
        return originalMatch.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    });

    return html;
}
// --- END: REPLACEMENT FUNCTION ---
async function handleCopyToClipboard(textToCopy: string, btn: HTMLButtonElement) {
    if (!textToCopy) return;
    try {
        await navigator.clipboard.writeText(textToCopy);
        const originalText = btn.textContent;
        btn.textContent = 'Copied!';
        btn.disabled = true;
        setTimeout(() => {
            btn.textContent = originalText;
            btn.disabled = false;
        }, 2000);
    } catch (err) {
        console.error('Failed to copy text: ', err);
        showFeedbackMessage('Failed to copy to clipboard.', 'error');
    }
}

function generateInviteCode(length = 8): string {
    const chars = 'ABCDEFHJKLMNPQRSTUVWXYZ23456789'; // Omitted I, O, 0, 1 for clarity
    let result = '';
    for (let i = 0; i < length; i++) {
        result += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return result;
}


// -- Firebase Services --



function renderModelAnswerHtml(text, isMath) {
    if (!text) return '';
    const lines = text.split('\n').map(l => l.trim()).filter(Boolean);
    const isTable = lines.length >= 2 && lines.every(l => l.startsWith('|') && l.endsWith('|'));
    if (!isTable) return formatMathExpressions(text, isMath);

    const rows = lines
        .map(l => l.slice(1, -1).split('|').map(c => c.trim()))
        .filter(cells => !cells.every(c => /^-+$/.test(c)));

    const [header, ...body] = rows;
    const thead = `<tr>${header.map(c => `<th>${formatMathExpressions(c, isMath)}</th>`).join('')}</tr>`;
    const tbody = body.map(r => `<tr>${r.map(c => `<td>${formatMathExpressions(c, isMath)}</td>`).join('')}</tr>`).join('');
    return `<table class="model-answer-table" style="border-collapse:collapse;width:100%;"><thead>${thead}</thead><tbody>${tbody}</tbody></table>`;
}


async function updateAssessmentQuestionsInDb(assessmentId: string, updatedQuestions: AIQuestion[]) {
    if (!teacherProfile) return;
    try {
        const docRef = fbFirestore.collection('teachers').doc(teacherProfile.uid)
            .collection('assessmentHistory').doc(assessmentId);
        
// Do NOT recalculate totalMarks — use the existing value from Firestore.
        // Recalculating is unreliable with OR questions (both sides would be double-counted
        // or excluded). The teacher sets totalMarks when creating the paper; it stays fixed.
        await docRef.update({
            questions: sanitizeObjectForFirestore(updatedQuestions),
        });
        showFeedbackMessage("Question paper updated successfully!", "success");
    } catch (e) {
        console.error("Error updating QP:", e);
        showFeedbackMessage("Failed to save changes to database.", "error");
    }
}


/**
 * Publishes a single student's graded assessment report to a student-accessible collection.
 * @param studentUid The UID of the student receiving the report.
 * @param report The full AIFullAssessmentReport object to publish.
 * @param assessmentId The ID of the parent assessment document.
 * @param assessmentTitle The title of the assessment.
 */
async function publishAssessmentReport(studentUid: string, report: AIFullAssessmentReport, assessmentId: string, assessmentTitle: string): Promise<void> {
    if (!teacherProfile || !report.submissionDocId) {
        throw new Error("Cannot publish report: Missing required teacher or submission data.");
    }

    // HOMEWORK BRANCH
    if (assessmentId.startsWith('hw_grade_') || (report as any)._isHomeworkReport) {
        const hwSubmissionRef = fbFirestore.collection('completedHomeworkSubmissions').doc(report.submissionDocId);
        const studentAssessmentRef = fbFirestore.collection('studentAssessments').doc(studentUid)
            .collection('assessments').doc(report.submissionDocId);
        const reportForStudent = sanitizeObjectForFirestore({
            ...report,
            assessmentId,
            assessmentTitle,
            subject: currentAssessmentForReportView?.subject || '',
            className: currentAssessmentForReportView?.className || '',
            section: currentAssessmentForReportView?.section || '',
            gradingTimestamp: new Date().toISOString(),
            isHomework: true,
        });
        delete reportForStudent.published;
        const batch = fbFirestore.batch();
        batch.update(hwSubmissionRef, { published: true });
        batch.set(studentAssessmentRef, reportForStudent);
        await batch.commit();
        return;
    }

    // 1. Define the path to the original submission document in the teacher's private history.
    // For a SHARED (co-taught) report, the document may live under a different teacher's
    // UID/assessmentId than whoever is currently viewing it — resolve the real owner the
    // same way handleTeacherVerify does, instead of always assuming the viewing teacher owns it.
    const ownerUid = (report as any)._ownerTeacherUid || teacherProfile.uid;
    const ownerAssessmentId = (report as any)._ownerAssessmentId || assessmentId;
    const teacherSubmissionRef = fbFirestore.collection('teachers').doc(ownerUid)
        .collection('assessmentHistory').doc(ownerAssessmentId)
        .collection('submissions').doc(report.submissionDocId);

// 2. Define the path for the new, student-accessible document.
    // Use assessmentId_studentUid to match admin publish format and prevent duplicates.
    const studentDocId = `${assessmentId}_${studentUid}`;
    const studentAssessmentRef = fbFirestore.collection('studentAssessments').doc(studentUid)
        .collection('assessments').doc(studentDocId);

    // 3. Create a clean data object for the student, adding necessary context.
    const reportForStudent = {
        // Core report data
        ...report,
        // Add context from the parent assessment for the student's reference
        assessmentId: assessmentId,
        assessmentTitle: assessmentTitle,
        subject: currentAssessmentForReportView?.subject || 'N/A',
        className: currentAssessmentForReportView?.className || 'N/A',
        section: currentAssessmentForReportView?.section || 'N/A',
        gradingTimestamp: new Date().toISOString() // Add a timestamp for when it was published
    };
    
    // Remove teacher-specific internal fields before sending to student
    delete reportForStudent.published;

    // 4. Use a Firestore batch write to perform both operations atomically.
    const batch = fbFirestore.batch();
    
    // Operation A: Update the original report in the teacher's records to mark it as published.
    batch.update(teacherSubmissionRef, { published: true });
    
    // Operation B: Create the new, clean report in the student-facing collection.
    batch.set(studentAssessmentRef, sanitizeObjectForFirestore(reportForStudent));

    // 5. Commit the batch.
    await batch.commit();
}

async function unpublishAssessmentReport(studentUid: string, report: AIFullAssessmentReport, assessmentId: string): Promise<void> {
    if (!teacherProfile || !report.submissionDocId) {
        throw new Error("Cannot unpublish: Missing required data.");
    }

    const batch = fbFirestore.batch();

    // Mark unpublished in the submission doc — resolve the real owner the same way
    // publishAssessmentReport / handleTeacherVerify do, since a SHARED (co-taught)
    // report may live under a different teacher's UID/assessmentId than the viewer's.
    const ownerUid = (report as any)._ownerTeacherUid || teacherProfile.uid;
    const ownerAssessmentId = (report as any)._ownerAssessmentId || assessmentId;
    const teacherSubmissionRef = fbFirestore.collection('teachers').doc(ownerUid)
        .collection('assessmentHistory').doc(ownerAssessmentId)
        .collection('submissions').doc(report.submissionDocId);
    batch.update(teacherSubmissionRef, { published: false });

const studentDocId = `${assessmentId}_${studentUid}`;
    const studentAssessmentRef = fbFirestore.collection('studentAssessments').doc(studentUid)
        .collection('assessments').doc(studentDocId);
    batch.delete(studentAssessmentRef);

    await batch.commit();
}

window.handleUnpublishSingleReport = async (reportIndex: number) => {
    const report = assessmentReports[reportIndex];
    if (!confirm(`Unpublish report for ${report.studentName}?\n\nThe student will lose access until you publish again. No grading data will be lost.`)) return;

    toggleLoading(true, `Unpublishing for ${report.studentName}...`);
    try {
        await unpublishAssessmentReport(
            report.studentUid,
            report,
            currentAssessmentForReportView.assessmentId
        );
        report.published = false;
        renderAssessmentReportView();
        showFeedbackMessage(`Report for ${report.studentName} unpublished. Student can no longer see it.`, "info");
    } catch (error) {
        console.error("Failed to unpublish report:", error);
        showFeedbackMessage("Error unpublishing report.", "error");
    } finally {
        toggleLoading(false);
    }
};



