/**
 * Atomically deducts a specified number of credits from a class roster's remaining credits.
 * This function is safe from race conditions.
 * @param rosterId The ID of the class roster document in Firestore.
 * @param creditsToDeduct The number of credits to subtract.
 */
async function deductCreditsFromRoster(
    rosterId: string,
    creditsToDeduct: number,
    logEntry?: { type: 'exam' | 'assignment'; title: string; studentName: string; pages: number }
): Promise<void> {
    if (!rosterId || creditsToDeduct <= 0) {
        console.warn("Credit deduction skipped: Invalid rosterId or zero credits to deduct.");
        return;
    }

    const rosterRef = fbFirestore.collection('classRosters').doc(rosterId);

    // ── Step 1: Decrement credits (critical — must succeed) ──
    try {
        await rosterRef.update({
            remainingCredits: window.firebase.firestore.FieldValue.increment(-creditsToDeduct)
        });
        console.log(`[Credits] Successfully deducted ${creditsToDeduct} credits from roster ${rosterId}.`);
    } catch (error) {
        console.error(`[Credits] Failed to deduct credits for roster ${rosterId}:`, error);
        return; // Don't attempt log if deduction itself failed
    }

    // ── Step 2: Write credit log (non-critical — log failure must NOT affect deduction) ──
    if (logEntry) {
        try {
            await rosterRef.collection('creditLogs').add({
                type: logEntry.type,
                title: logEntry.title,
                studentName: logEntry.studentName,
                pages: logEntry.pages,
                creditsUsed: creditsToDeduct,
                timestamp: window.firebase.firestore.FieldValue.serverTimestamp()
            });
        } catch (logError) {
            // Log write failed (likely a Firestore rules issue on creditLogs subcollection).
            // Credits were already deducted above — this is safe to ignore.
            console.warn(`[Credits] Log write failed for roster ${rosterId} (credits still deducted):`, logError);
        }
    }
}


