/**
 * Uploads a File object to a specified path in Firebase Storage.
 * This is the missing helper function that makes the large file uploads work.
 * @param file The File object to upload (e.g., an image from an answer sheet).
 * @param path The desired path in Firebase Storage (e.g., 'assessmentSubmissions/teacher123/assessment456/submission789/page_1.jpg').
 * @returns A promise that resolves with the public download URL of the uploaded file.
 */
async function uploadFileToStorage(file: File, path: string): Promise<string> {
    if (!fbStorage) {
        throw new Error("Firebase Storage has not been initialized. Check Firebase config.");
    }
    
    // Create a reference to the location we want to upload to in Firebase Storage
    const storageRef = fbStorage.ref(path);
    
    // 'put(file)' is the core command that uploads the data
    const snapshot = await storageRef.put(file);
    
    // After the upload is complete, we get the public URL to store in our database
    const downloadURL = await snapshot.ref.getDownloadURL();
    
    return downloadURL;
}

