/**
 * Fetches the feature flags for a given school from Firestore.
 * @param schoolId The unique ID of the school.
 * @returns A promise that resolves to the FeatureFlags object.
 */
async function getSchoolFeatureFlags(schoolId: string): Promise<FeatureFlags> {
    // --- START: NEW DEBUGGING CODE ---
    console.log(`Attempting to fetch features for schoolId: "${schoolId}"`);
    // --- END: NEW DEBUGGING CODE ---

    if (!schoolId) {
        console.warn("Cannot fetch feature flags: schoolId is missing from teacher profile.");
        return {}; // Return empty flags if no ID is provided
    }
    try {
        const schoolDoc = await fbFirestore.collection('schools').doc(schoolId).get();
        if (schoolDoc.exists) {
            const schoolData = schoolDoc.data();
            const features = schoolData?.features || {};
            // --- START: NEW DEBUGGING CODE ---
            console.log("SUCCESS: Fetched feature flags:", features);
            // --- END: NEW DEBUGGING CODE ---
            return features;
        } else {
            console.warn(`School document with ID ${schoolId} not found.`);
            return {};
        }
    } catch (error) {
        console.error("Error fetching school feature flags:", error);
        // In case of error, default to empty flags (which means features will be enabled by default)
        return {};
    }
}

