function initializeFirebase(config: any) {
    if (window.firebase.apps.length === 0) window.firebase.initializeApp(config);
    fbAuth = window.firebase.auth();
    fbFirestore = window.firebase.firestore();
    fbFirestore.enablePersistence()
  .catch((err) => {
      if (err.code == 'failed-precondition') {
          // This can happen if multiple tabs are open. Persistence can only be
          // enabled in one tab at a time. This is a normal scenario.
          console.warn("Firestore persistence failed: multiple tabs open.");
      } else if (err.code == 'unimplemented') {
          // The browser does not support all features required for persistence.
          console.warn("Firestore persistence is not supported in this browser.");
      }
  });
    fbStorage = window.firebase.storage();
}
