async function getTeacherProfile(uid: string): Promise<TeacherProfile | null> {
    const teacherDocRef = fbFirestore.collection('teachers').doc(uid);
    const teacherDoc = await teacherDocRef.get();
    if (!teacherDoc.exists) return null;

    let profileData = teacherDoc.data() as any;

    // --- START: SELF-HEALING LOGIC FOR schoolId ---
    // If the schoolId is missing, we try to find it using the schoolName.
    if (!profileData.schoolId && profileData.schoolName) {
        console.warn(`Teacher profile for ${profileData.email} is missing a schoolId. Attempting to find it...`);
        try {
            // Query the 'schools' collection to find a document that matches the teacher's schoolName.
            const schoolsQuery = await fbFirestore.collection('schools')
                .where('schoolName', '==', profileData.schoolName)
                .limit(1)
                .get();
            
            if (!schoolsQuery.empty) {
                // We found a matching school.
                const schoolDoc = schoolsQuery.docs[0];
                const foundSchoolId = schoolDoc.id; // The document ID is the schoolId
                console.log(`SUCCESS: Found matching school ID: ${foundSchoolId}. Updating teacher profile.`);
                
                // Add the found ID to our profile data in memory.
                profileData.schoolId = foundSchoolId;

                // IMPORTANT: Save this back to the teacher's document so we don't
                // have to do this expensive query every single time they log in.
                await teacherDocRef.update({ schoolId: foundSchoolId });

            } else {
                console.error(`CRITICAL: Could not find a school named "${profileData.schoolName}" in the 'schools' collection. Feature permissions will not work for this teacher.`);
            }
        } catch (error) {
            console.error("Error during automatic schoolId lookup:", error);
        }
    }
    // --- END: SELF-HEALING LOGIC ---
    
    // Final check for the console log. This helps you confirm the right data is being used.
    console.log("Final teacher profile being used by the app:", profileData);

    // Handle legacy `boardName` field for backward compatibility
    return { ...profileData, board: profileData.board || profileData.boardName } as TeacherProfile;
}

async function autoPopulateChaptersForForm(containerId: string, loadingId: string, subject: string, className: string) {
    const loadingEl = document.getElementById(loadingId);
    if (loadingEl) loadingEl.style.display = 'block';

    await fetchAndCacheTopicsCSV(
        (topics) => {
            const board = teacherProfile?.board;
            const normalizedBoard = normalizeForComparison(board);
            const normalizedClass = normalizeForComparison(className);
            const normalizedSubject = normalizeForComparison(subject);

            const filteredChapters = [...new Set(topics
                .filter(t => 
                    normalizeForComparison(t.Board) === normalizedBoard && 
                    normalizeForComparison(t.Class) === normalizedClass && 
                    normalizeForComparison(t.Subject) === normalizedSubject
                )
                .map(t => t['Chapter Name'].trim())
            )].sort();

            renderChapterCheckboxes(containerId, filteredChapters);
            if (loadingEl) loadingEl.style.display = 'none';
        },
        () => { if (loadingEl) loadingEl.style.display = 'none'; }
    );
}



