async function registerTeacher(details: any): Promise<TeacherProfile> {
    const { name, email, password, schoolName, board, classes, subjects, phone } = details;
    const cred = await fbAuth.createUserWithEmailAndPassword(email, password);
    if (!cred.user) throw new Error("User creation failed.");
const profile: TeacherProfile = { uid: cred.user.uid, name, email, schoolName, schoolId: schoolName, board: board, classesTaught: classes, subjectsTaught: subjects, phone };
    await fbFirestore.collection('teachers').doc(cred.user.uid).set(profile);

    // If it's a new school, add it to our own DB
    if (details.isNewSchool) {
        await addSchoolToDatabase({ SchoolName: schoolName, Board: board });
    }
    return profile;
}

