async function addSchoolToDatabase(schoolData: SchoolData): Promise<void> {
    try {
        // Use the school name as the document ID to prevent duplicates
        const schoolDocRef = fbFirestore.collection('schools').doc(schoolData.SchoolName);
        await schoolDocRef.set(schoolData, { merge: true }); // Use merge to be non-destructive
    } catch (error) {
        console.error("Could not save new school to Firestore:", error);
        // Don't throw an error to the user, just log it. The registration can still succeed.
    }
}


