async function getAssignedHomeworks(uid: string, classFilter?: { className: string, section: string, subject: string, stream?: string }): Promise<Homework[]>{
    let query: firebase.firestore.Query = fbFirestore.collection('homeworks')
        .where('createdByTeacherUid', '==', uid);
        // The .orderBy() clause that caused the error has been removed from the query.

    const snap = await query.get();
    let homeworks = snap.docs.map(doc => {
        const data = doc.data() as any;
        // Standardize data model on the fly
        return {
            ...data,
            className: data.className || data.targetClass,
            section: data.section || data.targetSection,
            schoolName: data.schoolName || data.school,
            board: data.board || data.boardName,
        } as Homework;
    });

    // NEW: Perform the sorting here, inside the application code.
homeworks.sort((a, b) => {
        const timeA = a.creationTimestamp ? new Date(a.creationTimestamp).getTime() : 0;
        const timeB = b.creationTimestamp ? new Date(b.creationTimestamp).getTime() : 0;
        if (isNaN(timeA) || isNaN(timeB)) return 0;
        return timeB - timeA;
    });

    if (classFilter && classFilter.subject) {
        const filterClassName = classFilter.className?.trim().toLowerCase();
        const filterSection = classFilter.section?.trim().toLowerCase();
        const filterSubject = classFilter.subject?.trim().toLowerCase();
        
      homeworks = homeworks.filter(hw => {
            const hwClassName = (hw.className || "").trim().toLowerCase();
            const hwSection = (hw.section || "").trim().toLowerCase();
            const hwSubject = (hw.subject || "").trim().toLowerCase();

            const filterStream = (classFilter.stream || "").trim().toLowerCase();
            const hwStream = (hw.stream || "").trim().toLowerCase();

            return hwClassName === filterClassName &&
                   hwSection === filterSection && 
                   hwSubject === filterSubject &&
                   (!filterStream || hwStream === filterStream); // Added stream check
        });
    }
    return homeworks;
}

/**
 * Uploads a base64 encoded image string to Firebase Storage.
 * @param base64String The base64 string of the image.
 * @param path The desired path in Firebase Storage (e.g., 'homework-images/hw123/q1.jpg').
 * @returns A promise that resolves with the public download URL of the uploaded image.
 */
async function uploadBase64ToStorage(base64String: string, path: string): Promise<string> {
    if (!fbStorage) throw new Error("Firebase Storage is not initialized.");

    // Create a reference to the file location
    const storageRef = fbStorage.ref(path);

    // Upload the base64 string directly. 'data_url' tells Firebase how to handle it.
    const snapshot = await storageRef.putString(base64String, 'base64', {
        contentType: 'image/jpeg'
    });

    // Get the public URL for the file
    const downloadURL = await snapshot.ref.getDownloadURL();
    return downloadURL;
}

// --- API LOGGING INTERFACE ---
interface ApiUsageLog {
    teacherProfile: TeacherProfile;
    feature: string;
    model: string;
    units: {
        inputChars?: number;
        outputChars?: number;
        imagesProcessed?: number;
        imagesGenerated?: number;
    };
     // ADD THIS SECTION
    tokenUsage?: {
        promptTokens: number;
        candidatesTokens: number;
        totalTokens: number;
    };
    metadata?: any;
}

// --- API LOGGER FUNCTION ---
async function logApiUsage(logData: ApiUsageLog): Promise<void> {
    if (!fbFirestore || !logData.teacherProfile) {
        console.warn("Cost logging skipped: Firestore or teacher profile not available.");
        return;
    }

    const { teacherProfile, feature, model, units } = logData;
    const { inputChars = 0, outputChars = 0, imagesProcessed = 0, imagesGenerated = 0 } = units;

    let totalCost = 0;
    let breakdownString = "";
    
    const unitCostInr = {
        inputChars_per_1M: 0,
        outputChars_per_1M: 0,
        imageProcessed_per_unit: 0,
        imageGenerated_per_unit: 0
    };

    // Cost Calculation Logic (Gemini 2.5 Flash)
    if (model.includes('gemini-2.5-flash')) {
        unitCostInr.inputChars_per_1M = API_PRICING_INR.GEMINI_FLASH.INPUT_PER_1M_CHARS;
        unitCostInr.outputChars_per_1M = API_PRICING_INR.GEMINI_FLASH.OUTPUT_PER_1M_CHARS;
        unitCostInr.imageProcessed_per_unit = API_PRICING_INR.GEMINI_FLASH.IMAGE_INPUT_PER_UNIT;
        
        const costInput = (inputChars / 1000000) * unitCostInr.inputChars_per_1M;
        const costOutput = (outputChars / 1000000) * unitCostInr.outputChars_per_1M;
        const costImages = imagesProcessed * unitCostInr.imageProcessed_per_unit;
        
        totalCost += costInput + costOutput + costImages;
        
        breakdownString = `Reading(${inputChars} chars): ₹${costInput.toFixed(5)} | Writing(${outputChars} chars): ₹${costOutput.toFixed(5)} | Eyes(${imagesProcessed} imgs): ₹${costImages.toFixed(5)}`;
    }
    
    // Image Generation Models
    if (model.includes('gemini-2.5-flash-image')) {
        unitCostInr.imageGenerated_per_unit = API_PRICING_INR.GEMINI_FLASH_IMAGE.GENERATION_PER_UNIT;
        const costGen = imagesGenerated * unitCostInr.imageGenerated_per_unit;
        totalCost += costGen;
        breakdownString += ` | Generated(${imagesGenerated} imgs): ₹${costGen.toFixed(2)}`;
    }

    // Prepare Firestore Document
    const logDocument = {
        timestamp: window.firebase.firestore.FieldValue.serverTimestamp(),
        teacherUid: teacherProfile.uid,
        teacherName: teacherProfile.name,
        schoolId: teacherProfile.schoolId || 'N/A',
        schoolName: teacherProfile.schoolName,
        feature: feature,
        apiService: 'Gemini API',
        modelCalled: model,
        // SKU Categorization for Admin Dashboard
        skuCategory: model.includes('image') ? 'GenAI Image' : 'GenAI Text', 
        unitsConsumed: {
            inputChars,
            outputChars,
            imagesProcessed,
            imagesGenerated
        },
        // ADD THIS: Save the exact token counts
tokenUsage: logData.tokenUsage || { promptTokens: 0, candidatesTokens: 0, totalTokens: 0 },
    metadata: logData.metadata || null, 
    totalCostInr: Number(totalCost.toFixed(6)),
    costDetailedPrompt: breakdownString
    };

    try {
        fbFirestore.collection('apiUsageLogs').add(logDocument);
    } catch (error) {
        console.error("Failed to log API usage:", error);
    }
}


