// --- REPLACE THE OLD sanitizeCreatedAssessment FUNCTION WITH THIS ENTIRE BLOCK ---

function sanitizeCreatedAssessment(data: any): CreatedAssessment {
const assessmentTitle = String(data.assessmentTitle || data.title || 'Untitled Assessment');

    const questions: AIQuestion[] = (Array.isArray(data.questions) ? data.questions : [])
.map((q: any, index: number) => {
            if (typeof q !== 'object' || q === null) {
                return null;
            }
            // Use parseFloat to preserve decimals like 0.5 or 0.8
            const marks = parseFloat(String(q.marks));
            return {
                id: String(q.id || `q_${Date.now()}_${index}`),
                questionNumber: q.questionNumber ? String(q.questionNumber) : undefined,
                text: String(q.text || "Question text not found."),
                topic: String(q.topic || assessmentTitle),
                imagePrompt: q.imagePrompt ? String(q.imagePrompt) : null,
                imageBase64: q.imageBase64 ? String(q.imageBase64) : null,
                type: (q.type || 'Subjective') as QuestionType,
                options: Array.isArray(q.options) ? q.options.map(String) : undefined,
                answer: String(q.answer || "A model answer was not provided."),
                kept: q.kept !== false,
                marks: isNaN(marks) ? 5 : marks,
                checkingInstructions: String(q.checkingInstructions || ''), // THIS IS THE NEW LINE
topicAnchors: Array.isArray(q.topicAnchors) ? q.topicAnchors.map(String) : [],
rubric: q.rubric ? (
    typeof q.rubric === 'string' 
    ? { keywords: [], step_marking: q.rubric } // Handle flat string from DB
    : {
        keywords: Array.isArray(q.rubric.keywords) ? q.rubric.keywords.map(String) : [],
        step_marking: String(q.rubric.step_marking || '')
    }
) : { keywords: [], step_marking: '' },
            };
        })
        .filter((q): q is AIQuestion => q !== null);

    return {
        assessmentId: String(data.assessmentId || `assmt_${Date.now()}`),
        createdByTeacherUid: String(data.createdByTeacherUid || ''),
        teacherName: String(data.teacherName || ''),
        schoolName: String(data.schoolName || ''),
        board: String(data.board || ''),
subject: String(data.subject || ''),
        className: String(data.className || data.class || data.targetClass || ''),
        section: String(data.section || data.targetSection || ''),
        stream: data.stream ? String(data.stream) : undefined, // <-- ADD THIS LINE
        assessmentTitle: assessmentTitle,
        questions: questions,
        creationTimestamp: String(data.creationTimestamp || new Date().toISOString()),
        source: data.source || 'curriculum',
        totalMarks: Number(data.totalMarks) || 0,
        difficultyLevel: String(data.difficultyLevel || 'Medium'),
        checkingStrictness: String(data.checkingStrictness || 'Moderate'),
        selectedChapters: Array.isArray(data.selectedChapters) ? data.selectedChapters.map(String) : [],
        topics: Array.isArray(data.topics) ? data.topics.map(String) : [],
                // --- START: THESE ARE THE 3 NEW LINES TO ADD ---
        teacherActionableInsights: data.teacherActionableInsights || undefined,
        insightsLastUpdated: data.insightsLastUpdated || undefined,
        insightsGeneratedForReportCount: data.insightsGeneratedForReportCount || undefined,
        generalInstructions: data.generalInstructions || '',
        // --- END: NEW LINES ---
    };
}

