/**
 * Fetches all homework submissions related to a given list of homework IDs.
 * This is a more robust and performant way to get all submission data.
 * @param homeworkIds An array of homework IDs belonging to the teacher.
 * @returns A Promise resolving to an array of all relevant submissions.
 */
async function getAllSubmissionsForTeacher(homeworkIds: string[]): Promise<Submission[]> {
    if (homeworkIds.length === 0) {
        return []; // No need to query if there are no homeworks
    }

    const allSubmissions: Submission[] = [];

    // Firestore 'in' queries are limited to 30 items per batch.
    // We must break the homework IDs into smaller chunks.
    const idBatches: string[][] = [];
    for (let i = 0; i < homeworkIds.length; i += 30) {
        idBatches.push(homeworkIds.slice(i, i + 30));
    }

    // Create a query for each batch of IDs.
    const batchPromises = idBatches.map(batch => {
        if (batch.length > 0) {
// We add the createdByTeacherUid filter so Firestore rules can verify we own these submissions
return fbFirestore.collection('completedHomeworkSubmissions')
    .where('createdByTeacherUid', '==', teacherProfile!.uid) 
    .where('homeworkId', 'in', batch)
    .get();
        }
        return Promise.resolve(null);
    });
    
    // Execute all the batch queries in parallel for maximum efficiency.
    const snapshots = await Promise.all(batchPromises);

    // Process the results from all batches.
    for (const snapshot of snapshots) {
        if (snapshot) {
            for (const doc of snapshot.docs) {
                const data = doc.data() as any;
                // IMPORTANT: This includes robust mapping for older data models.
                const submission = {
                    ...data,
                    submissionId: doc.id,
                    className: data.className || data.class,
                    schoolName: data.schoolName || data.school,
                    boardName: data.boardName || data.board,
                } as Submission;
                allSubmissions.push(submission);
            }
        }
    }
    
    return allSubmissions;
}

