async function getCreatedAssessments(uid: string, classFilter?: { className: string, section: string, subject: string }): Promise<CreatedAssessment[]> {
    
    // Fetch all — no compound where() so no composite index needed
    const snapshot = await fbFirestore
        .collection('teachers').doc(uid)
        .collection('assessmentHistory')
        .get();

    const all = snapshot.docs.map(doc => {
        const sanitized = sanitizeCreatedAssessment(doc.data());
        sanitized.assessmentId = doc.id;
        return sanitized;
    });

// DEBUG — remove after fix
    console.log('ALL ASSESSMENTS RAW:', all.map(a => ({ 
        title: a.assessmentTitle, 
        className: a.className, 
        section: a.section, 
        subject: a.subject 
    })));
    console.log('FILTER LOOKING FOR:', classFilter);

let result = all;
    if (classFilter) {
        console.log('EXAM DATA:', all[0]?.className, all[0]?.section, all[0]?.subject);
        console.log('ROSTER DATA:', classFilter.className, classFilter.section, classFilter.subject);
        result = all.filter(a =>
            normalizeForComparison(a.className) === normalizeForComparison(classFilter.className) &&
            normalizeForComparison(a.section) === normalizeForComparison(classFilter.section) &&
            normalizeForComparison(a.subject) === normalizeForComparison(classFilter.subject)
        );
    }

    // Deduplicate by assessmentId
    const seen = new Set<string>();
    const deduped = result.filter(a => {
        if (seen.has(a.assessmentId)) return false;
        seen.add(a.assessmentId);
        return true;
    });

    deduped.sort((a, b) => new Date(b.creationTimestamp).getTime() - new Date(a.creationTimestamp).getTime());
    return deduped;
}
async function getAllStudentsFromSchool(schoolName: string): Promise<StudentProfile[]> {
    if (!schoolName) return [];
    try {
        const snapshot = await fbFirestore.collection('students')
            .where('school', '==', schoolName)
            .get();
        return snapshot.docs.map(doc => doc.data() as StudentProfile);
    } catch (error) {
        // If permissions are denied for the whole school directory, we log it and return empty
        // This prevents the entire dashboard from failing to load.
        console.warn("Access denied to school student directory. Syncing skipped.", error);
        return [];
    }
}

