/**
 * A robust function to fetch the full history of graded assessments, including all
 * student reports. This version is resilient to data changes and uses the correct
 * document IDs.
 * @param uid The teacher's UID.
 * @param classFilter An optional filter to narrow results to a specific class.
 * @returns A promise resolving to an array of StoredAssessment objects.
 */
async function getAssessmentHistory(uid: string, classFilter?: { className: string, section: string, subject: string, stream?: string }): Promise<StoredAssessment[]> {
    if (!uid) return [];

    // Step 1: Build the query for the main assessment documents.
    let query: firebase.firestore.Query = fbFirestore
        .collection('teachers').doc(uid)
        .collection('assessmentHistory');

    // Apply filters if provided, which makes the query much more efficient.
    if (classFilter) {
        query = query.where('className', '==', classFilter.className)
                     .where('section', '==', classFilter.section)
                     .where('subject', '==', classFilter.subject);
    }

    const createdAssessmentsSnapshot = await query.get();

    // Step 2: For each assessment, fetch its submissions subcollection.
    const submissionPromises = createdAssessmentsSnapshot.docs.map(async (assessmentDoc) => {
        const assessmentData = assessmentDoc.data() as CreatedAssessment;
        const submissionsSnapshot = await assessmentDoc.ref.collection('submissions').get();
        
        // If an assessment has no submissions, we correctly filter it out.
        if (submissionsSnapshot.empty) {
            return null;
        }

const reports = await Promise.all(submissionsSnapshot.docs.map(async doc => {
    const data = doc.data() as any;
    let questionWiseReport = data.questionWiseReport || [];
    try {
const detailDoc = await doc.ref.collection('detail').doc('report').get();
        if (detailDoc.exists) {
            questionWiseReport = (detailDoc.data() as any).questionWiseReport || [];
            if ((detailDoc.data() as any).fullOcrText) {
                data.fullOcrText = (detailDoc.data() as any).fullOcrText;
            }
        }
    } catch (e) {
        console.warn('[History] detail subcollection fetch failed', e);
    }
    return { ...data, questionWiseReport } as AIFullAssessmentReport & { gradingTimestamp?: any };
}));
        // --- START OF THE FIX ---

        // FIX #1: Find the LATEST grading timestamp among all reports.
        // This is robust and doesn't depend on the order or existence of any single report.
        let mostRecentTimestamp = assessmentData.creationTimestamp;
        if (reports.length > 0) {
            // We map over all timestamps and find the maximum (most recent) one.
      const timestamps = reports.map(r => {
    const d = r.gradingTimestamp;
    // Handle Firestore Timestamp objects
    if (d && typeof d === 'object' && 'seconds' in d) return d.seconds * 1000;
    // Fallback for strings or numeric timestamps
    const parsed = new Date(d || 0).getTime();
    return isFinite(parsed) ? parsed : 0;
});
            mostRecentTimestamp = new Date(Math.max(...timestamps)).toISOString();
        }
        
        // FIX #2: Always use the actual document ID as the definitive assessmentId.
        // This prevents data mismatches if the internal ID is stale.
        const storedAssessment: StoredAssessment = {
            assessmentId: assessmentDoc.id, // Use the real document ID
            teacherUid: uid,
            assessmentTitle: assessmentData.assessmentTitle,
            className: assessmentData.className,
            section: assessmentData.section,
            subject: assessmentData.subject,
            creationTimestamp: mostRecentTimestamp, // Use the robustly determined timestamp
            reports: reports,
        };
        
        // --- END OF THE FIX ---

        return storedAssessment;
    });

    const results = await Promise.all(submissionPromises);
    // Filter out any assessments that had no submissions.
// Filter by stream in memory to avoid needing a new Firestore composite index
const finalResults = results.filter(item => item !== null) as StoredAssessment[];
    
    // Update global cache if we fetched the whole history
if (!classFilter) {
        globalAssessmentHistoryCache = finalResults;
        // REMOVED: isTeacherDataPreloaded = true
        // Only preloadTeacherData() should set this flag.
        // Setting it here causes stale/empty caches to be treated as complete.
    }
    
    return finalResults;
}

