/**
 * Fetches all of a teacher's rosters and silently syncs them with the full
 * school student directory in the background. It updates pending students
 * and adds newly registered students who match the class details.
 * @param teacherId The UID of the logged-in teacher.
 * @param schoolName The name of the school to get the directory from.
 * @returns A Promise that resolves to an array of the latest, synced ClassRoster objects.
 */
async function syncAllRostersInBackground(teacherId: string, schoolName: string): Promise<ClassRoster[]> {
    // First, fetch the teacher's current rosters.
    const rostersSnapshot = await fbFirestore.collection('classRosters').where('teacherUid', '==', teacherId).get();
    const initialRosters = rostersSnapshot.docs.map(doc => {
        const data = doc.data() as any;
        // This ensures compatibility with older data structures
        return { 
            ...data, 
            id: doc.id, 
            className: data.className || data.targetClass, 
            section: data.section || data.targetSection, 
            students: data.students || [] 
        } as ClassRoster;
    });

    try {
        // Now, attempt the sync. Fetch the entire school directory just once for efficiency.
        const allSchoolStudents = await getAllStudentsFromSchool(schoolName);

        // If there's no directory to sync against, no point in continuing.
        if (allSchoolStudents.length === 0) {
            return initialRosters;
        }

        const directoryStudentsByEmail = new Map(allSchoolStudents.map(s => [s.email.toLowerCase(), s]));
        const updatePromises: Promise<void>[] = [];
        const finalSyncedRosters: ClassRoster[] = [];

        // Loop through each of the teacher's rosters to check for updates.
        for (const roster of initialRosters) {
            let rosterHasChanged = false;
            const rosterStudentsByEmail = new Map(roster.students.map(s => [s.email.toLowerCase(), s]));

// AFTER
roster.students.forEach(rosterStudent => {
    const directoryMatch = directoryStudentsByEmail.get(rosterStudent.email.toLowerCase());
    if (directoryMatch) {
        if (rosterStudent.status === 'pending') {
            rosterStudent.uid = directoryMatch.uid;
            rosterStudent.status = 'active';
            rosterHasChanged = true;
        }
        // Always fix blank name or missing rollNumber for all students
        if (!rosterStudent.name && directoryMatch.name) {
            rosterStudent.name = directoryMatch.name;
            rosterHasChanged = true;
        }
        if (!(rosterStudent as any).rollNumber && (directoryMatch as any).rollNumber) {
            (rosterStudent as any).rollNumber = (directoryMatch as any).rollNumber;
            rosterHasChanged = true;
        }
    }
});

// --- CLEANUP: Remove students who don't have this subject enrolled ---
            // subjectsEnrolled is a comma-separated string e.g. "English,Physics,Chemistry,Mathematics"
            const rosterSubjectClean = (roster.subject || "").trim().toLowerCase();
            const originalCount = roster.students.length;
            roster.students = roster.students.filter(rosterStudent => {
                const dirMatch = directoryStudentsByEmail.get(rosterStudent.email.toLowerCase());
                if (!dirMatch) return true; // not in directory → keep (manually added)
                const enrolled: string = (dirMatch as any).subjectsEnrolled || "";
                if (!enrolled) return true; // no subjects data → keep (safe)
                return enrolled.split(',').some(s => s.trim().toLowerCase() === rosterSubjectClean);
            });
            if (roster.students.length !== originalCount) {
                rosterHasChanged = true;
                console.log(`[RosterCleanup] ${roster.subject} ${roster.className}-${roster.section}: removed ${originalCount - roster.students.length} students not enrolled in this subject`);
            }

// --- START: STRICT STREAM MATCHING LOGIC ---
            // Normalize the roster's stream (treat null/undefined as empty string)
            const rosterStream = (roster.stream || "").trim().toLowerCase();

            // Sync Part 2: Add new students from the directory who match this class/section AND STREAM.
            const newStudentsToAdd = allSchoolStudents.filter(dirStudent => {
                const isInRoster = rosterStudentsByEmail.has(dirStudent.email.toLowerCase());
                
    const matchesClass = (dirStudent.studentClass || "").trim() === (roster.className || "").trim();
                const matchesSection = (dirStudent.studentSection || "").trim().toLowerCase() === (roster.section || "").trim().toLowerCase();
                
                const studentStream = (dirStudent.stream || "").trim().toLowerCase();
                const matchesStream = rosterStream === studentStream;

// Subject filter: only add students who have this subject enrolled
                // subjectsEnrolled is stored as a comma-separated string: "English,Physics,Chemistry,Mathematics"
                const rosterSubject = (roster.subject || "").trim().toLowerCase();
                // Subject filter: subjectsEnrolled is a comma-separated string
                const subjectsEnrolledRaw: string = (dirStudent as any).subjectsEnrolled || "";
                const matchesSubject = !subjectsEnrolledRaw ||
                    subjectsEnrolledRaw.split(',').some(s => s.trim().toLowerCase() === rosterSubjectClean);

                return !isInRoster && matchesClass && matchesSection && matchesStream && matchesSubject;
            });
            // --- END: STRICT STREAM MATCHING LOGIC ---

            if (newStudentsToAdd.length > 0) {
                newStudentsToAdd.forEach(student => {
roster.students.push({
    uid: student.uid,
    name: student.name,
    email: student.email,
    status: 'active',
    rollNumber: student.rollNumber || ''
});
                });
                rosterHasChanged = true;
            }
            
            // If this roster was modified, add a promise to save it back to the database.
            if (rosterHasChanged) {
                updatePromises.push(saveClassRoster(roster));
            }
            finalSyncedRosters.push(roster);
        }

        // Save all changed rosters back to Firestore in parallel without blocking the user.
        if (updatePromises.length > 0) {
            await Promise.all(updatePromises);
            console.log(`Automatic Sync: ${updatePromises.length} roster(s) were successfully updated.`);
        }
        
        return finalSyncedRosters;

    } catch (error) {
        console.error("Automatic roster sync failed silently in the background:", error);
        // IMPORTANT: If the sync fails for any reason (e.g., network error),
        // we return the original, unmodified rosters so the app doesn't crash.
        return initialRosters;
    }
}


// -- Gemini Services --
async function generateRemedialWorksheet(report: AIFullAssessmentReport, assessment: CreatedAssessment): Promise<PersonalizedWorksheet | null> {
    // Only send the specific topic strings where mistakes happened
    const weakTopics = (report.overallFeedback.areasForImprovement || [])
        .map(item => typeof item === 'object' ? item.text : item)
        .filter(text => text && text.length > 3 && !text.toLowerCase().includes("not found"));

    if (weakTopics.length === 0) return null;

const selectedChapters = assessment.selectedChapters && assessment.selectedChapters.length > 0 
    ? assessment.selectedChapters.join(', ') 
    : 'General Curriculum';

const prompt = `
    You are a Senior Curriculum Designer specializing in Competency-Based Education (NCF & NAS standards) for ${assessment.board}.
    
    **CURRICULUM CONTEXT:**
    - Board: ${assessment.board}
    - Class: ${assessment.className}
    - Subject: ${assessment.subject}
    - Chapter(s): ${selectedChapters}
    
    **TASK:**
    Generate exactly one HIGH-QUALITY Case Study Based Question for each of the following conceptual gap topics: 
    [${weakTopics.join(', ')}]

    **PEDAGOGICAL REQUIREMENTS for each 2-Mark Question:**
    1. **Case Stem (Mandatory):** Start with a 1-2 sentence real-world scenario or data set linked to the class curriculum.
    2. **Competency Focus:** Test application, analysis, or interpretation. DO NOT ask for direct definitions or simple formula recall.
    3. **Action Verbs:** Use verbs like: Analyze, Infer, Justify, Calculate (within the scenario context), or Predict.
    4. **Tone:** Professional, neutral, and curriculum-linked.

    **OUTPUT FORMAT:**
    Return a SINGLE JSON array of objects. Each object must contain:
    - "topic": The exact mistake topic string provided.
    - "caseStudy": The scenario paragraph (The Stem).
    - "question": The specific application task based on that case study.
    - "answer": Provide ONLY 2-3 short bullet pointers. NO full sentences. NO introductory filler.

    Format: Return JSON array of objects: {"topic", "caseStudy", "question", "answer"}.
    Strictly NO markdown, NO "Case Study #" labels.
`;
try {
    const response = await getAiInstance().models.generateContent({
        model: 'gemini-2.5-flash', 
        contents: prompt,
config: {
    responseMimeType: "application/json",
    responseSchema: {
        type: Type.ARRAY,
        items: {
            type: Type.OBJECT,
            properties: {
                topic: { type: Type.STRING },
                caseStudy: { type: Type.STRING },
                question: { type: Type.STRING },
                answer: { 
                    type: Type.STRING, 
                    description: "Pointers only. Ex: '- Identify X; - Apply Y; - Result Z.'" 
                }
            },
            required: ["topic", "caseStudy", "question", "answer"]
        }
    },
    temperature: 0.1, // Low temperature prevents hallucinations/wordiness
    thinkingConfig: { thinkingBudget: 0 } // Disables expensive thinking tokens for simple tasks
}
});

logApiUsage({
    teacherProfile,
    feature: 'Remedial Worksheet Generation',
    model: 'gemini-2.5-flash',
    units: { inputChars: prompt.length },
    metadata: {
        studentUid: report.studentUid,
        studentName: report.studentName,
        assessmentId: assessment.assessmentId,
        assessmentTitle: assessment.assessmentTitle,
        topicCount: weakTopics.length,
        weakTopics: weakTopics 
    },
    tokenUsage: {
        promptTokens: response.usageMetadata?.promptTokenCount || 0,
        candidatesTokens: response.usageMetadata?.candidatesTokenCount || 0,
        totalTokens: response.usageMetadata?.totalTokenCount || 0
    }
});
        const questions = JSON.parse(response.text.trim());
return {
            studentUid: report.studentUid,
            studentName: report.studentName,
            assessmentId: assessment.assessmentId,
            assessmentTitle: assessment.assessmentTitle, // <--- ADD THIS LINE
            subject: assessment.subject,
            className: assessment.className,
            board: assessment.board,
            questions: questions.map((q: any) => ({ ...q, marks: 2 })),
            sentAt: new Date().toISOString()
        };
    } catch (e) {
        console.error("Gemini 3 Generation Error", e);
        return null;
    }
}



