async function getSingleQuestionFromImages(
    questionNumberToFind: string,
    context: Partial<Homework | CreatedAssessment>,
    questionImageParts: Part[],
    solutionImageParts: Part[]
): Promise<AIQuestion> {
    
    const solutionInstruction = solutionImageParts.length > 0
        ? `You have been given solution key images. Find the answer for question "${questionNumberToFind}" in the solution key images and copy it VERBATIM. Do NOT summarize, shorten, or rephrase. Your goal is a 100% identical copy of what is written in the solution key for this question's answer.`
        : `You MUST generate a correct model "answer" for the question yourself. Keep it short and concise.`;

   // --- THIS IS THE NEW, REPLACEMENT PROMPT ---
// --- THIS IS THE NEW, REPLACEMENT PROMPT ---
const prompt = `
    You are a Math & Science OCR Specialist. Your task is to perform a targeted re-extraction of a specific question from the provided exam paper images.

    **MISSION:**
    Find **Question "${questionNumberToFind}"** and transcribe it with 100% fidelity, specifically focusing on mathematical notation and completeness.

    **STRICT MATH OCR RULES:**
    1.  **ALL MATH IS LATEX:** Every variable, number, equation, or symbol MUST be in LaTeX format.
        -   Example: "Calculate x" -> "Calculate \\( x \\)"
        -   Example: "integral of x^2" -> "\\( \\int x^2 dx \\)"
        -   Example: "5/2" -> "\\( \\frac{5}{2} \\)"
    2.  **NO SIMPLIFICATION:** Do not convert fractions to decimals or simplify expressions. Transcribe exactly what is printed.
    3.  **COMPLETE EXTRACTION:**
        -   Include ALL introductory text associated with this question.
        -   **Sub-parts:** If the question number covers multiple sub-parts (e.g., if you are looking for "3", extract 3(a), 3(b), etc.), you MUST include ALL of them in the "text" field.
        -   **Options:** If it is a Multiple Choice Question, include all options.
    4.  **DIAGRAMS:** If there is a diagram, write [DIAGRAM: detailed description] in the text.

    **NUMBER MATCHING:**
    -   Look for "${questionNumberToFind}" at the start of a block or line.
    -   **Resilience:** Accept variations like "Q${questionNumberToFind}", "(${questionNumberToFind})", "${questionNumberToFind}.", or Roman numerals if applicable.
    -   **Context:** If the number is ambiguous, use the surrounding sequence (e.g., finding it between ${parseInt(questionNumberToFind) - 1} and ${parseInt(questionNumberToFind) + 1}) to confirm.

    **FAILURE CONDITION:**
    If you absolutely cannot find this question after scanning every page, return \`{"text": "NOT_FOUND", ...}\`. However, you should try your hardest to find it based on context.

    **ANSWER SOURCE:** ${solutionInstruction}

    **CONTEXT:** Subject: ${context.subject || 'General'}, Class: ${context.className || 'N/A'}.
    ${LATEX_MATH_INSTRUCTIONS}

    **JSON SCHEMA & OUTPUT:**
    Your entire response MUST be a single, valid JSON object with the keys "text", "answer", "marks", "topic", "type", and "questionNumber". The "questionNumber" field in the output MUST be exactly "${questionNumberToFind}".
`;

    const responseSchema = {
        type: Type.OBJECT,
        properties: {
            text: { type: Type.STRING },
            answer: { type: Type.STRING },
            marks: { type: Type.NUMBER },
            topic: { type: Type.STRING },
            type: { type: Type.STRING },
            questionNumber: { type: Type.STRING }
        },
        required: ["text", "answer", "marks", "questionNumber"]
    };
    
    const allParts: Part[] = [...questionImageParts, ...solutionImageParts, { text: prompt }];

    const response = await getAiInstance().models.generateContent({
        model: 'gemini-2.5-flash',
        contents: { parts: allParts },
        config: { responseMimeType: "application/json", responseSchema }
    });

    const parsed = JSON.parse(response.text.trim());
    // Add the necessary local properties before returning
    return { ...parsed, id: `q_${Date.now()}`, kept: true };
}


/**
 * A highly-focused AI call to extract keywords from a feedback paragraph.
 * This acts as a failsafe if the main grading call fails to provide keywords.
 * @param feedbackText The paragraph of feedback explaining a score.
 * @returns A promise that resolves to an array of keyword strings.
 */
async function extractKeywordsFromFeedback(feedbackText: string): Promise<string[]> {
    if (!feedbackText) return ["Review Manually"];

    const prompt = `
        Analyze the following teacher's feedback text, which explains why a student lost marks on a question. Your ONLY task is to extract 1-3 concise keywords that summarize the core reason for the mark deduction.

        **Feedback Text:**
        "${feedbackText}"

        **CRITICAL INSTRUCTIONS:**
        - Your output MUST be a valid JSON array of strings.
        - Keywords should be short and specific (e.g., "Calculation Error", "Incomplete Definition", "Misunderstood the Question").
        - Do NOT provide a score, explanation, or any text outside the JSON array.

        **Example:**
        - Input: "The student correctly identified the formula but made a calculation error in the final step."
        - Output: ["Calculation Error"]
    `;
    
    try {
        const response = await getAiInstance().models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: { 
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.ARRAY,
                    items: { type: Type.STRING }
                }
            }
        });

        const keywords = JSON.parse(response.text.trim());
        return Array.isArray(keywords) && keywords.length > 0 ? keywords : ["Review Manually"];
    } catch (e) {
        console.error("Keyword extraction failsafe failed:", e);
        return ["AI Error"]; // Return a specific error keyword
    }
}


/**
 * Uses pdf.js to render each page of a PDF file into a separate, high-quality JPEG File object.
 * This is used to break down large PDFs into manageable chunks for the Gemini API.
 * @param pdfFile The PDF file to process.
 * @returns A Promise that resolves to an array of image File objects.
 */
async function processPdfToImageFiles(pdfFile: File): Promise<File[]> {
    const imageFiles: File[] = [];
    const fileURL = URL.createObjectURL(pdfFile);
    
    try {
        const pdf = await pdfjsLib.getDocument(fileURL).promise;
        const numPages = pdf.numPages;

        // Process each page sequentially
        for (let i = 1; i <= numPages; i++) {
            const page = await pdf.getPage(i);
            
            // Use a scale for high resolution. 1.5 gives good quality without being too large.
            const scale = 2.0; 
            const viewport = page.getViewport({ scale });

            const canvas = document.createElement('canvas');
            const context = canvas.getContext('2d');
            canvas.height = viewport.height;
            canvas.width = viewport.width;

            if (!context) {
                throw new Error('Could not get canvas context');
            }

            // Render the page onto the canvas
            const renderContext = {
                canvasContext: context,
                viewport: viewport
            };
            await page.render(renderContext).promise;


            // Convert the canvas content to a JPEG blob
            const blob = await new Promise<Blob | null>((resolve) => {
                canvas.toBlob(resolve, 'image/jpeg', 0.85); // 85% quality is a good balance
            });

            if (blob) {
                // Create a new File object from the blob
                const imageFile = new File([blob], `${pdfFile.name}_page_${i}.jpg`, {
                    type: 'image/jpeg'
                });
                imageFiles.push(imageFile);
            }
        }
    } catch (error) {
        console.error("Error processing PDF:", error);
        // If PDF processing fails, show an error to the user
        showFeedbackMessage(`Failed to read the PDF file: ${(error as Error).message}. Please ensure it's not corrupted.`, "error");
        // Return an empty array to stop further processing
        return [];
    } finally {
        URL.revokeObjectURL(fileURL);
    }

    return imageFiles;
}


async function getLocalConfidenceMap(file: File) {
    if (!window.Tesseract) return [];
    
    // Tesseract v5 Fix: createWorker takes NO arguments
  const worker = await (window as any).Tesseract.createWorker();
    
    try {
        // Must load and initialize explicitly in v5
        await worker.loadLanguage('eng');
        await worker.initialize('eng');
        
        const ret = await worker.recognize(file);
        
        // Return words where the local engine is < 60% sure
        const messyWords = ret.data.words
            .filter((w: any) => w.confidence < 60)
            .map((w: any) => w.text);
            
        await worker.terminate();
        return messyWords;
    } catch (e) {
        console.error("Local confidence scan failed", e);
        if (worker) await worker.terminate();
        return [];
    }
}

async function extractTextFromImages(files: File[], featureName: string = 'Question Extraction (OCR)', onBatchComplete?: (processedCount: number, totalCount: number) => void, ocrRagRules: string = ""): Promise<{ pageNum: number, text: string, rawText: string, anchors: any[] }[]> {
    
    // NOTE: We removed the pre-processing of all images here to save memory.
    
 // CRITICAL FIX: Process 1 page at a time. 
    // This ensures 100% attention to detail and accurate page tracking.
    // It prevents the "lazy reader" effect where AI skips middle pages in a batch.
    const BATCH_SIZE = 2;
   const pageResults: { pageNum: number, text: string, rawText: string, anchors: any[] }[] = [];


const prompt = `

${ocrRagRules} 
`;
    
// 4. Process in Batches (1 page at a time for accuracy)
    const ocrSystemPrompt = prompt; // ocrRagRules already injected via ${ocrRagRules} inside prompt template above
    for (let i = 0; i < files.length; i += BATCH_SIZE) {
const currentFiles = files.slice(i, i + BATCH_SIZE);
const pageRange = Array.from({length: currentFiles.length}, (_, idx) => i + idx + 1).join(', ');
const currentBatch = await Promise.all(currentFiles.map(fileToPart));

        // --- START OF RETRY LOOP FOR SINGLE PAGE ---
        let attempt = 0;
        let pageSuccess = false;

        while (attempt < 2 && !pageSuccess) {
            try {
                const ocrSchema = {
                    type: Type.OBJECT,
                    properties: {
                        text: { type: Type.STRING },
                        pageConfidence: { type: Type.NUMBER, description: "0-100 score" },
                        visionFlags: { type: Type.ARRAY, items: { type: Type.STRING } }
                    },
                    required: ["text", "pageConfidence"]
                };

                // "Hard Refresh" Instruction for second attempt
                const refreshModifier = attempt > 0 ? 
                    "\n\nCRITICAL: The previous attempt failed due to a repetition loop. RESET your state. DO NOT repeat characters. Extract ONLY handwriting concisely. Stop immediately when done." : "";

                const response = await geminiAPICallWithRetry({
                    model: 'gemini-2.5-flash', 
                    contents: { 
                        parts: [
                            ...currentBatch, 
                            { text: "Analyze these " + currentFiles.length + " images (Pages: " + pageRange + "). For EACH image, you MUST strictly prepend the transcription with [PAGE X] (where X is the actual page number) followed by the content for that specific page. Do not skip any pages. " + refreshModifier }
                        ] 
                    },
                    config: { 
                        responseMimeType: "application/json",
                        responseSchema: ocrSchema,
                        systemInstruction: ocrSystemPrompt + refreshModifier,
                        
                    }
                }, 120000);

                let rawResponseText = response.text || "";

                // --- 1. PRE-PARSE HALLUCINATION CHECK ---
const loopRegex = /(?!\+|-|=|\s|×|·)(.{4,})\1{10,}/;
                if (loopRegex.test(rawResponseText)) {
                    console.warn(`OCR: Loop detected on Pages ${pageRange}. Attempt ${attempt + 1}/2`);
                    throw new Error("REPETITION_LOOP"); // Triggers retry
                }

                // --- 2. ATTEMPT JSON PARSE ---
                let parsedOcr = extractJsonFromString(rawResponseText);
                
                // FIXED: Check existence before accessing properties
                if (!parsedOcr || !parsedOcr.text) {
                    throw new Error("INVALID_JSON_STRUCTURE");
                }

                // --- 3. SUCCESS: RUN ANCHOR & REGEX LOGIC ---
                let transcript = parsedOcr.text;


// Define a regex that splits the transcript by any variation of [PAGE X]
const pageSplitRegex = /(?:\[|\*\*|#)*PAGE\s*[:\-]*\s*(\d+)(?:\]|\*\*|#)*/gi;
const chunks = transcript.split(pageSplitRegex);
// Chunks array looks like: ["text before", "1", "page 1 text", "2", "page 2 text"...]

const anchors = [];
const matches = [...transcript.matchAll(/\[#P\s*:\s*([^,]+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\]/gi)];
matches.forEach(m => {
    anchors.push({
        qNum: m[1],
        pageIndex: i + (parseInt(m[2]) - 1), // Assuming m[2] is 1-based page in batch
        y: parseInt(m[3]),
        x: parseInt(m[4])
    });
});

currentFiles.forEach((_, idx) => {
    const actualPageNum = i + idx + 1;
    let pageContent = "";

// 1. Primary Search: Look for absolute page number (e.g., [PAGE 5])
let pageMarkerIndex = chunks.findIndex((val, index) => index % 2 === 1 && parseInt(val) === actualPageNum);

// 2. Secondary Search: Look for relative page number in the batch (e.g., [PAGE 1])
if (pageMarkerIndex === -1) {
    const relativePageNum = idx + 1;
    pageMarkerIndex = chunks.findIndex((val, index) => index % 2 === 1 && parseInt(val) === relativePageNum);
}

if (pageMarkerIndex !== -1) {
    pageContent = chunks[pageMarkerIndex + 1] || "";
} 
// 3. Fallback for the first page of a batch if no tags were used
else if (idx === 0 && chunks[0].trim().length > 10) {
    pageContent = chunks[0];
} 
// 4. SMART RECOVERY: If specific page text is missing but transcript is substantial
else {
    const rawLower = transcript.toLowerCase();
    // If the transcript contains the page number or is simply very long, 
    // it's safer to show the full text than to assume it's empty.
    if (rawLower.includes(`page ${actualPageNum}`) || transcript.length > 300) {
         pageContent = transcript; 
    } else {
         pageContent = `[EMPTY PAGE] No text detected for Page ${actualPageNum}.`;
    }
}

    const pageAnchors = anchors.filter(a => a.pageIndex === (i + idx));
    pageResults.push({ 
        pageNum: actualPageNum, 
        text: pageContent.trim(), 
        rawText: pageContent.trim(),        
        anchors: pageAnchors 
    });
});
                // --- 4. LOG USAGE ---
                if (teacherProfile && response.usageMetadata) {
                    logApiUsage({
                        teacherProfile,
                        feature: featureName,
                        model: 'gemini-2.5-flash',
                        units: { 
                            imagesProcessed: currentBatch.length,
                            inputChars: response.usageMetadata.promptTokenCount,
                            outputChars: response.usageMetadata.candidatesTokenCount
                        },
                        tokenUsage: {
                            promptTokens: response.usageMetadata.promptTokenCount,
                            candidatesTokens: response.usageMetadata.candidatesTokenCount,
                            totalTokens: response.usageMetadata.totalTokenCount
                        }
                    });
                }

                if (onBatchComplete) onBatchComplete(i + 1, files.length);
                pageSuccess = true; 

           } catch (e: any) {
                attempt++;
                const time = new Date().toLocaleTimeString();
                
                // CRITICAL RECOVERY: If a batch of 3 fails or loops once, 
                // immediately "Cut Off" and restart for those 3 pages individually.
                if (attempt >= 1) {
                    console.warn(`OCR Batch Error at Pages ${pageRange}. Transitioning to Individual Recovery Mode...`);
                    ragSystemLogs.push(`<span class="log-timestamp">[${time}]</span> 🔄 <strong>Batch Hallucination.</strong> Cutting off. Restarting Pages ${pageRange} one-by-one with fresh memory...`);
                    
                    // Process ONLY the pages in the failing batch individually
                    for (let subIdx = 0; subIdx < currentFiles.length; subIdx++) {
                        const singleFile = currentFiles[subIdx];
                        const actualPageNum = i + subIdx + 1;
                        
                        try {
                            // FRESH START: Create a brand new client instance to clear any hidden session state
                         throw new Error("Frontend recovery OCR disabled. Backend handles OCR.");
                            const recoveryAi = new GoogleGenAI({ apiKey: "" as string });
                            
                            // CONTEXTUAL RECOVERY PROMPT: Injects the full original system instructions 
                            // plus specific "Hard Reset" commands to stop repeating.
                            const recoveryUserMessage = `[PAGE ${actualPageNum}] 
                            CRITICAL RECOVERY: Extract handwriting for THIS SINGLE IMAGE ONLY. 
                            The previous attempt failed due to a repetition loop. 
                            Perform a hard reset. BE EXTREMELY CONCISE. DO NOT repeat characters. 
                            If text is illegible, write [ILLEGIBLE] once and stop.`;

                            const recoveryResponse = await recoveryAi.models.generateContent({
                                model: 'gemini-2.5-flash',
                                contents: { 
                                    parts: [
                                        await fileToPart(singleFile), 
                                        { text: recoveryUserMessage }
                                    ] 
                                },
                                config: { 
                                    responseMimeType: "application/json",
                                    // Use the same schema as the main call
                                    responseSchema: {
                                        type: Type.OBJECT,
                                        properties: {
                                            text: { type: Type.STRING },
                                            pageConfidence: { type: Type.NUMBER }
                                        },
                                        required: ["text", "pageConfidence"]
                                    },
                                    // RECOVERY PERSONA: Include original prompt + RAG rules + recovery constraints
                                    systemInstruction: ocrSystemPrompt + "\n\nSTRICT RECOVERY MODE: NO REPETITION. NO NOISE. ONE IMAGE ONLY.",
                                    temperature: 0.1, // Breaks deterministic loops by allowing slight creative variance
                                    maxOutputTokens: 4096,
                                    thinkingConfig: { thinkingBudget: 0 }
                                }
                            });

                            const parsed = extractJsonFromString(recoveryResponse.text);
                            if (!parsed || !parsed.text) throw new Error("Individual recovery parse failed");

                            // SUCCESS: Push the individual result to the master array
                            pageResults.push({ 
                                pageNum: actualPageNum, 
                                text: parsed.text.trim(), 
                                rawText: parsed.text.trim(),
                                anchors: [] // Individual recovery simplifies anchor logic to ensure transcription accuracy
                            });
                            console.log(`✅ Recovery Success: Page ${actualPageNum}`);
                        } catch (recoveryErr) {
                            // Final Failsafe: Mark the specific failing page
                            const errLabel = `[CRITICAL ERROR PAGE ${actualPageNum}]: Individual recovery failed.`;
                            pageResults.push({ pageNum: actualPageNum, text: errLabel, rawText: errLabel, anchors: [] });
                        }
                    }
                    
                    // Update overall progress bar
                    if (onBatchComplete) onBatchComplete(i + currentFiles.length, files.length);
                    pageSuccess = true; // Exit the while loop for this chunk
                } else {
                    // This block handles the rare case of a generic failure before the recovery triggers
                    ragSystemLogs.push(`<span class="log-timestamp">[${time}]</span> ⚠️ Retrying batch ${pageRange}...`);
                    await new Promise(r => setTimeout(r, 1000));
                }
            }
        }
        // --- END OF RETRY LOOP ---
    }

    return pageResults;
}


async function generateReportSummaryAndKeywords(studentName: string, questionWiseReport: AIQuestionReport[]) {
    // This function is now ZERO COST because it does not call Gemini.
    // It simply gathers the labels the grader already created.
    
    const areasForImprovement: any[] = [];
    
    questionWiseReport.forEach(qr => {
        if (qr.improvementArea && qr.improvementArea.length > 0) {
            qr.improvementArea.forEach(area => {
                // The grader already formatted these as "[Category] Detail (Q#)"
                areasForImprovement.push(area);
            });
        }
    });

    const overallFeedback = {
        summary: areasForImprovement.length > 0 
            ? `Performance indicates specific gaps in ${[...new Set(areasForImprovement.map(a => a.split(']')[0].replace('[','')))].join(', ')}.`
            : "Excellent performance with no significant errors identified.",
        strengths: [],
        areasForImprovement: areasForImprovement
    };

    const studentKeywords = areasForImprovement.map(area => `WEAKNESS: ${area}`);

    return { overallFeedback, studentKeywords };
}


