/**
 * Analyzes a student's answer text to determine the likelihood of it being AI-generated.
 * @param studentAnswer The full text of the student's answer.
 * @returns A promise that resolves to a percentage (0-100) indicating the likelihood of AI generation.
 */
async function detectAIGeneratedContent(studentAnswer: string): Promise<number> {
    if (!studentAnswer || studentAnswer.trim().length < 50) {
        return 0; // Not enough text to analyze
    }

    const prompt = `
        Analyze the following text, which is a student's homework answer. Your task is to determine the likelihood that this text was generated by an AI language model (like ChatGPT, Gemini, etc.) versus written by a human student.

        Consider factors like:
        - Overly perfect grammar and syntax.
        - Complex vocabulary and sentence structures unusual for the student's level.
        - Lack of common human errors or colloquialisms.
        - A generic, encyclopedic tone.

        Student's Answer:
        ---
        ${studentAnswer}
        ---

        Based on your analysis, provide a single integer representing the percentage likelihood that this content is AI-generated. The integer should be between 0 (definitely human-written) and 100 (definitely AI-generated).

        Your response MUST be a single, valid JSON object with one key: "ai_score".
    `;

    const responseSchema = {
        type: Type.OBJECT,
        properties: {
            ai_score: { type: Type.NUMBER, description: "An integer from 0 to 100 representing the AI-generated likelihood." }
        },
        required: ["ai_score"]
    };

    try {
        const response = await getAiInstance().models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: { 
    responseMimeType: "application/json", 
    responseSchema: responseSchema,
    temperature: 0,
    maxOutputTokens: 32, // Only returning a number
    thinkingConfig: { thinkingBudget: 0 }
}
        });

        // --- ADD THIS BLOCK FOR COST TRACKING ---
if (teacherProfile) {
    logApiUsage({
        teacherProfile,
        feature: 'AI Content Detection',
        model: 'gemini-2.5-flash',
        units: {
            inputChars: prompt.length,
            outputChars: response.text.length,
        }
    });
}
// --- END OF COST TRACKING BLOCK ---

        const result = JSON.parse(response.text.trim());
        const score = Math.max(0, Math.min(100, Math.round(result.ai_score || 0)));
        return score;
    } catch (e) {
        console.error("Failed to detect AI-generated content:", e);
        return -1; // Return -1 to indicate an error
    }
}

