async function cropImageForQuestion(questionIndex: number, originalFiles: File[]) {
    const question = temporaryHomeworkData.questions?.[questionIndex];
    if (!question?.imagePrompt || originalFiles.length === 0 || !fbStorage) {
        return; // No instruction, no image, or storage not ready
    }

    const card = document.getElementById(`review-q-${questionIndex}`);
    const imageContainer = card?.querySelector('.question-image-container');
    if (imageContainer) {
        imageContainer.innerHTML = `<div class="spinner-container"><div class="spinner-inline"></div> <p style="font-size: 0.8rem;">Cropping & Uploading...</p></div>`;
    }

    try {
        const imageParts: Part[] = await Promise.all(originalFiles.map(fileToPart));
        const cropPrompt = `From the provided image, perform a precise digital crop of the area described here: "${question.imagePrompt}".
        CRITICAL INSTRUCTIONS: CROP ONLY. DO NOT GENERATE. Your output must be the cropped image itself.`;

        const response = await getAiInstance().models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: { parts: [...imageParts, { text: cropPrompt }] },
            config: { responseModalities: [Modality.IMAGE] }
        });

        // --- ADD THIS BLOCK FOR COST TRACKING ---
if (teacherProfile) {
    logApiUsage({
        teacherProfile,
        feature: 'Image Cropping',
        model: 'gemini-2.5-flash-image',
        units: {
            inputChars: cropPrompt.length,
            imagesProcessed: imageParts.length,
            imagesGenerated: 1
        }
    });
}
// --- END OF COST TRACKING BLOCK ---
        
        let foundBase64: string | null = null;
        if (response.candidates?.[0]?.content?.parts) {
            for (const part of response.candidates[0].content.parts) {
                if (part.inlineData) {
                    foundBase64 = part.inlineData.data;
                    break;
                }
            }
        }

        if (foundBase64) {
            const homeworkId = temporaryHomeworkData.homeworkId || `temp_${Date.now()}`;
            const imagePath = `homework-images/${homeworkId}/${question.id}_cropped.jpg`;
            const imageUrl = await uploadBase64ToStorage(foundBase64, imagePath);
            question.imageUrl = imageUrl;
        } else {
            throw new Error("The AI response did not contain the expected image data.");
        }

    } catch (cropError) {
        console.error(`Could not crop/upload image for question ${questionIndex}:`, cropError);
        question.imageUrl = null; // Mark as failed
    } finally {
        // Always re-render to either show the cropped image or the error message
        displayAIQuestionsForReview();
    }
}


