async function generateStudentSubjectInsights(studentId: string, subject: string): Promise<StudentInsights> {
    if (!teacherProfile) throw new Error("Teacher not logged in.");

    const allHomeworksSnap = await fbFirestore.collection('homeworks')
        .where('createdByTeacherUid', '==', teacherProfile.uid)
        .get();
        
    const subjectHomeworks = allHomeworksSnap.docs
        .map(doc => doc.data() as Homework)
        .filter(hw => (hw.subject || "").trim().toLowerCase() === (subject || "").trim().toLowerCase());

    const subjectHomeworkIds = subjectHomeworks.map(hw => hw.homeworkId);

    if (subjectHomeworkIds.length === 0) {
        return { summary: "No homeworks have been assigned for this subject yet.", strengths: [], weaknesses: [] };
    }

    const relevantSubmissions: Submission[] = [];
    
    const idBatches: string[][] = [];
    for (let i = 0; i < subjectHomeworkIds.length; i += 30) {
        idBatches.push(subjectHomeworkIds.slice(i, i + 30));
    }

    for (const batch of idBatches) {
        if (batch.length > 0) {
            const submissionsSnap = await fbFirestore.collection('completedHomeworkSubmissions')
                .where('studentId', '==', studentId)
                .where('homeworkId', 'in', batch)
                .get();

            submissionsSnap.docs.forEach(doc => {
                const sub = doc.data() as Submission;
                if (sub.detailedReport) {
                    relevantSubmissions.push(sub);
                }
            });
        }
    }
    
    if (relevantSubmissions.length === 0) {
        return { summary: "This student has not submitted any homework with detailed feedback for this subject yet.", strengths: [], weaknesses: [] };
    }

    const compiledData = relevantSubmissions.map(sub => {
        if (!sub || !sub.detailedReport || !Array.isArray(sub.detailedReport.questionDetails)) {
            return null;
        }

        const details = sub.detailedReport.questionDetails.map(qd => {
            const feedback = qd.aiFeedback;
            if (!feedback || !feedback.strengths || !feedback.weaknesses) { 
                return null; 
            }
            return {
                question: qd.questionText,
                score: feedback.score,
                strengths: feedback.strengths,
                weaknesses: feedback.weaknesses,
                improvementTips: feedback.improvementTips
            };
        }).filter(Boolean);

        if (details.length === 0) {
            return null;
        }

        return {
            homeworkId: sub.homeworkId,
            score: sub.score,
            overallFeedback: sub.detailedReport?.overallFeedback,
            questionDetails: details
        };
    }).filter(Boolean);

    if (compiledData.length === 0) {
         return { summary: "While this student has submissions, none contain the detailed AI feedback required for generating insights.", strengths: [], weaknesses: [] };
    }

    const prompt = `As an expert educational analyst, review the following performance data for a student in the subject "${subject}". The data includes scores and AI feedback from multiple homework assignments. Synthesize all this information to provide a high-level overview of the student's progress and learning patterns.
${LATEX_MATH_INSTRUCTIONS} // <--- THIS IS THE NEW LINE TO ADD

Performance Data:
${JSON.stringify(compiledData, null, 2)}

Your Task:
Generate a report with a concise overall summary, a list of consistent strengths, and a list of recurring areas for improvement. Focus on patterns, not just single instances.

The response MUST be a valid JSON object following the specified schema. Do not include any text outside the JSON object.`;

    const responseSchema = {
        type: Type.OBJECT,
        properties: {
            summary: { type: Type.STRING, description: "A concise overall summary of the student's performance and progress in the subject." },
            strengths: { type: Type.ARRAY, items: { type: Type.STRING }, description: "A list of consistent strengths observed across multiple assignments." },
            weaknesses: { type: Type.ARRAY, items: { type: Type.STRING }, description: "A list of recurring weaknesses or areas for improvement." }
        },
        required: ["summary", "strengths", "weaknesses"]
    };

    const response = await getAiInstance().models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: { responseMimeType: "application/json", responseSchema }
    });

    // --- ADD THIS BLOCK FOR COST TRACKING ---
if (teacherProfile) {
    logApiUsage({
        teacherProfile,
        feature: 'Student Subject Insight Generation',
        model: 'gemini-2.5-flash',
        units: {
            inputChars: prompt.length,
            outputChars: response.text.length,
        }
    });
}
// --- END OF COST TRACKING BLOCK ---

    try {
        return JSON.parse(response.text.trim()) as StudentInsights;
    } catch (e) {
        console.error("Failed to parse student insights AI response:", response.text, e);
        throw new Error("AI returned an invalid report format for student insights.");
    }
}

