        temporaryAssessmentData.section = sectionSelect.value === 'Other' ? customSectionInput.value : sectionSelect.value;
        temporaryAssessmentData.selectedChapters = selectedChapters;
        temporaryAssessmentData.topics = Array.from(topicsSelect.selectedOptions).map(opt => opt.value);

