        const sectionEl = document.getElementById('as-book-section-select') as HTMLSelectElement;
        const customSectionEl = document.getElementById('as-book-section-custom-input') as HTMLInputElement;
        temporaryAssessmentData.section = sectionEl.value === 'Other' ? customSectionEl.value : sectionEl.value;

          const checkedBoxes = document.querySelectorAll('#as-book-chapters-list input[name="selected-chapters"]:checked');
        temporaryAssessmentData.selectedChapters = Array.from(checkedBoxes).map((cb: any) => cb.value);

