function parseAIResponse(responseText: string): AIFullAssessmentReport {
    try {
        // The Gemini API for JSON mode can sometimes include ```json ... ``` markers.
        const cleanedText = responseText.replace(/^```json/, '').replace(/```$/, '').trim();
        if (!cleanedText) {
             throw new Error("AI returned an empty response.");
        }
        return JSON.parse(cleanedText) as AIFullAssessmentReport;
    } catch (e) {
        console.error("Failed to parse AI assessment report as JSON:", responseText, e);
        const errorMessage = e instanceof Error ? e.message : String(e);
        throw new Error(`The AI returned an invalid report format. Parser error: ${errorMessage}`);
    }
}

async function extractQuestionsFromPaper(qpImages: Part[], title: string): Promise<AIQuestion[]> {
    // --- THIS PROMPT HAS BEEN UPDATED ---
    const prompt = `
        You are an expert OCR and data extraction AI. Your task is to analyze the provided question paper images and extract every question you can find.

        **Assessment Title for Context:** ${title}

        **CRITICAL RULE: PRESERVE ORIGINAL NUMBERING**
       - You MUST identify the full, original question number from the image, including any sub-parts (e.g., "1.", "Q2.", "3. (a)", "iii.").
- The "questionNumber" field in your JSON output MUST contain this full, verbatim number.
- The "text" field in your JSON output MUST contain ONLY the question content itself, WITHOUT the number.


        **Example:**
        - If the image shows "Question 3. (iii) Draw a ray diagram...", your output "text" field MUST be "3. (iii) Draw a ray diagram...".

        **Your Task & Output Format:**
        1.  For each question you find, extract its full text (including the original number, as instructed above).
        
        2.  **Extract Marks (CRITICAL):** You MUST find the marks allocated for each question. They are usually written on the right side of the question, often in brackets like "[3]" or "(5 Marks)". You MUST extract this number and place it in the "marks" field. If, and only if, no marks are visible, then infer a reasonable integer.
        
        3.  Provide a reasonable, concise model answer for each question.
        
              4.  **Determine Question Type:**
            - If valid options (A, B, C, D) are found, set "type": "MCQ".
            - If marks are 1, set "type": "VSA".
            - If marks are 2-3, set "type": "Subjective".
            - If marks are >= 5, set "type": "Long Answer".
        
        5.  Your response MUST be a valid JSON array where each object in the array represents a single question and strictly follows the provided schema.


        6. **Exact Numbering:** Extract the "questionNumber" exactly as printed (e.g., "4. (Q1)").
        7. **MCQs:**         
        - **TEXT FIELD:** Must include Question Stem + All Options (A, B, C, D) + "[Type: MCQ]" at the end.
        - **ANSWER FIELD:** Must include "Option X: [Text]".
8. **OR Questions:** If a question has an Alternative Question (OR), extract both as separate entries.
           - Both entries MUST use the SAME questionNumber (the printed number from the first block).
           - **CBSE-STYLE:** "OR" is printed centered on its own line. The block after OR has NO printed number — assign it the SAME number as the block above OR.
           - Set checkingInstructions for BOTH entries to: "Alternative Question (OR) with Question [X]. Grade first attempt only." where [X] is that shared questionNumber.
           - **ASYMMETRIC OR:** If one side has sub-parts and the other does not, extract all sub-parts normally and extract the other side as a single object — all share the same base questionNumber and all get the OR checkingInstructions.
        8b. **MCQ 2-Column Options:** CBSE options are in a 2×2 grid (a+b on row 1, c+d on row 2). Extract ALL FOUR as separate options. Never merge two options from the same row.        9. **Math:** Use LaTeX for all math expressions.
        10. **Marks:** Extract marks accurately.
        11. **RUBRIC:** 
        - Objective: Omit rubric.
        - Subjective: define step marking.
        Do not include any other text or markdown formatting. Begin processing now.
    `;

    // NOTE: direct client-side Gemini calls are disabled (getAiInstance() always throws —
    // see [SECURITY] guard above). This now goes through the same backend proxy
    // (extractAssessmentQuestions) already used by the exam question-extraction flow.
    // That endpoint has no responseSchema/JSON-mode support, so the strict-JSON instruction
    // below does the enforcement instead, same as the exam flow already relies on.
    const strictJsonInstruction = `\n\nCRITICAL: Output ONLY the raw JSON array described above. No markdown code fences, no explanatory text before or after the array.`;

    const imagesPayload = qpImages
        .filter((p: any) => p.inlineData)
        .map((p: any) => ({ mimeType: p.inlineData.mimeType, data: p.inlineData.data }));

    const backendResp = await fetch(EXTRACT_ASSESSMENT_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ images: imagesPayload, prompt: prompt + strictJsonInstruction })
    });
    if (!backendResp.ok) throw new Error(`Extraction backend error: ${backendResp.status}`);
    const rawText = (await backendResp.text()).replace(/```json|```/g, '').trim();

    // --- COST TRACKING (char-based estimate — backend proxy doesn't return usageMetadata) ---
if (teacherProfile) {
    logApiUsage({
        teacherProfile,
        feature: 'Assessment Question Extraction (Manual QP)',
        model: 'gemini-2.5-flash',
        units: {
            inputChars: prompt.length,
            outputChars: rawText.length,
            imagesProcessed: qpImages.length
        }
    });
}
// --- END OF COST TRACKING BLOCK ---

    try {
        const parsedQuestions = JSON.parse(rawText) as any[];
        return parsedQuestions.map((q, index) => ({
            ...q,
            id: `q_manual_${Date.now()}_${index}`
        }));
    } catch (e) {
        console.error("Failed to parse extracted questions from QP:", rawText, e);
        throw new Error("AI failed to extract questions from the question paper in a valid format.");
    }
}



