/**
 * A robust CSV parser that handles quoted fields containing commas and newlines.
 * @param csvText The raw CSV string.
 * @returns An array of arrays, representing rows and columns.
 */
function robustCsvParser(csvText: string): string[][] {
    const rows: string[][] = [];
    let currentRow: string[] = [];
    let currentField = '';
    let inQuotedField = false;

    if (!csvText) return rows;

    for (let i = 0; i < csvText.length; i++) {
        const char = csvText[i];

        if (inQuotedField) {
            if (char === '"') {
                // Check for escaped quote ("")
                if (i + 1 < csvText.length && csvText[i + 1] === '"') {
                    currentField += '"';
                    i++; // Skip the next quote
                } else {
                    inQuotedField = false;
                }
            } else {
                currentField += char;
            }
        } else {
            switch (char) {
                case ',':
                    currentRow.push(currentField);
                    currentField = '';
                    break;
                case '"':
                    inQuotedField = true;
                    break;
                case '\n':
                case '\r':
                    // Handle line endings (CRLF, LF)
                    if (char === '\r' && i + 1 < csvText.length && csvText[i + 1] === '\n') {
                        i++; // Skip LF in CRLF
                    }
                    currentRow.push(currentField);
                    rows.push(currentRow);
                    currentRow = [];
                    currentField = '';
                    break;
                default:
                    currentField += char;
                    break;
            }
        }
    }

    // Add the last field and row if the file doesn't end with a newline
    currentRow.push(currentField);
    if (currentRow.length > 0 || currentField) {
        rows.push(currentRow);
    }

    return rows;
}


async function fetchAndCacheSchoolsCSV(onSuccess: (schools: SchoolData[]) => void, onError: (message: string) => void) {
    if (allSchoolsFromCSV.length > 0) {
        onSuccess(allSchoolsFromCSV);
        return;
    }
    
    const allSchoolsMap = new Map<string, SchoolData>();

    // Fetch from CSV
    try {
        const csvResponse = await fetch(SCHOOLS_CSV_URL);
        if (csvResponse.ok) {
            const csvText = await csvResponse.text();
            const parsedRows = robustCsvParser(csvText);
            // Skip header row by starting at i = 1
            for(let i = 1; i < parsedRows.length; i++) {
                const row = parsedRows[i];
                if (row && row.length >= 2 && row[0] && row[1]) {
                    allSchoolsMap.set(row[0].trim().toLowerCase(), { SchoolName: row[0].trim(), Board: row[1].trim() });
                }
            }
        } else {
            console.warn(`Failed to fetch schools CSV: ${csvResponse.statusText}`);
        }
    } catch (csvError) {
        console.warn("Could not fetch schools from CSV source:", csvError);
    }

    // Fetch from Firestore
    try {
        const firestoreSchoolsSnap = await fbFirestore.collection('schools').get();
        firestoreSchoolsSnap.docs.forEach(doc => {
            const schoolData = doc.data() as SchoolData;
            if (schoolData.SchoolName && schoolData.Board) {
                // Firestore data overwrites CSV data in case of conflict
                allSchoolsMap.set(schoolData.SchoolName.trim().toLowerCase(), schoolData);
            }
        });
    } catch(firestoreError) {
        console.warn("Could not fetch schools from Firestore source:", firestoreError);
    }

    // Finalize
    if (allSchoolsMap.size > 0) {
        allSchoolsFromCSV = Array.from(allSchoolsMap.values());
        onSuccess(allSchoolsFromCSV);
    } else {
        // Only trigger error if both sources fail
        allSchoolsFromCSV = [{ SchoolName: "Default School (Error Loading List)", Board: "CBSE" }];
        onError("Could not load the live list of schools. Using a default list.");
        onSuccess(allSchoolsFromCSV);
    }
}
async function fetchAndCacheTopicsCSV(onSuccess: (topics: TopicData[]) => void, onError: (message: string) => void) {
    if (allTopicsFromCSV.length > 0) { onSuccess(allTopicsFromCSV); return; }
    try {
        const response = await fetch(TOPICS_CSV_URL);
        if (!response.ok) throw new Error(`Failed to fetch topics CSV: ${response.statusText}`);
        
        const csvText = await response.text();
        const parsedRows = robustCsvParser(csvText);

        if (parsedRows.length < 2) throw new Error("Topics CSV data is empty or invalid header.");
        
        const headers = parsedRows[0].map(h => h.trim());
        const requiredHeaders = ['Subject', 'Class', 'Board', 'Chapter Name', 'Subtopic Name', 'Subtopic Order'];
        const indices: { [key: string]: number } = {};
        
        requiredHeaders.forEach(header => {
            const index = headers.findIndex(h => h.toLowerCase() === header.toLowerCase());
            if (index === -1) {
                throw new Error(`Topics CSV is missing required column: ${header}`);
            }
            indices[header] = index;
        });
        
        ['ContentType', 'ContentName', 'ContentURL'].forEach(header => {
            indices[header] = headers.findIndex(h => h.toLowerCase() === header.toLowerCase());
        });

        const parsedTopics: TopicData[] = [];
        for (let i = 1; i < parsedRows.length; i++) {
            const values = parsedRows[i];
            const topicEntry: TopicData = {
                Subject: values[indices['Subject']]?.trim(),
                Class: values[indices['Class']]?.trim(),
                Board: values[indices['Board']]?.trim(),
                'Chapter Name': values[indices['Chapter Name']]?.trim(),
                'Subtopic Name': values[indices['Subtopic Name']]?.trim(),
                'Subtopic Order': values[indices['Subtopic Order']]?.trim(),
                ContentType: indices['ContentType'] > -1 ? values[indices['ContentType']]?.trim() : undefined,
                ContentName: indices['ContentName'] > -1 ? values[indices['ContentName']]?.trim() : undefined,
                ContentURL: indices['ContentURL'] > -1 ? values[indices['ContentURL']]?.trim() : undefined,
            };
            if (requiredHeaders.every(h => topicEntry[h as keyof TopicData])) {
                parsedTopics.push(topicEntry);
            }
        }
        allTopicsFromCSV = parsedTopics;
        onSuccess(allTopicsFromCSV);
    } catch (error) {
        console.warn("Failed to fetch live topics CSV, loading default data.", error);
        allTopicsFromCSV = [{ Subject: "Physics", Class: "8", Board: "CBSE", "Chapter Name": "Force and Pressure", "Subtopic Name": "Introduction to Force", "Subtopic Order": "1", ContentType: "Video", ContentName: "Intro to Force", ContentURL: "#" }, { Subject: "Maths", Class: "7", Board: "CBSE", "Chapter Name": "Integers", "Subtopic Name": "Properties of Addition and Subtraction", "Subtopic Order": "1" }];
        onError("Could not load live curriculum data. Using a default set.");
        onSuccess(allTopicsFromCSV);
    }
}

