window.handleUpdateScoreFromModal = (reportIndex: number, questionIndex: number) => {
    
    const report = assessmentReports[reportIndex];
    pushGradingUndo(report);
    if (!report) return;

    // 1. Find the MODAL input element and get its value
    const inputEl = document.getElementById(`modal-score-input-${reportIndex}-${questionIndex}`) as HTMLInputElement;
    const mainPageInputEl = document.getElementById(`score-input-${reportIndex}-${questionIndex}`) as HTMLInputElement;
    const maxScore = report.questionWiseReport[questionIndex].maxMarksForQuestion;
    let newValue = parseFloat(inputEl.value);

    // 2. Validate and clamp
    if (isNaN(newValue) || newValue < 0) newValue = 0;
    else if (newValue > maxScore) newValue = maxScore;
    inputEl.value = newValue.toFixed(1);
    if(mainPageInputEl) mainPageInputEl.value = newValue.toFixed(1); // Sync main page input

    // 3. Update local state
    report.questionWiseReport[questionIndex].marksAwarded = newValue;
    const newTotalScore = report.questionWiseReport.reduce((sum, qr) => sum + qr.marksAwarded, 0);
    report.overallScore = newTotalScore;
    const newPercentage = report.maximumMarks > 0 ? (newTotalScore / report.maximumMarks * 100) : 0;

    // 4. Update the UI *in the main page's card* so it's correct when the modal closes
    const mainPageTotalScoreEl = document.getElementById(`total-score-${reportIndex}`);
    if (mainPageTotalScoreEl) {
        let scoreClass = 'score-low';
        if (newPercentage > 70) scoreClass = 'score-high';
        else if (newPercentage > 40) scoreClass = 'score-medium';
        mainPageTotalScoreEl.innerHTML = `
            <strong>${newTotalScore.toFixed(1)} / ${report.maximumMarks}</strong>
            <span class="individual-score-percent ${scoreClass}">${newPercentage.toFixed(0)}%</span>
        `;
    }
    
    // 5. Also update the UI inside the modal
    const modalScoreEl = document.querySelector('#individual-report-stats .stat-card:nth-child(1) .stat-main-value') as HTMLParagraphElement;
    const modalPercentEl = document.querySelector('#individual-report-stats .stat-card:nth-child(2) .stat-main-value') as HTMLParagraphElement;
    const modalPercentCardEl = modalPercentEl?.parentElement as HTMLDivElement;
    if(modalScoreEl) modalScoreEl.textContent = `${newTotalScore.toFixed(1)} / ${report.maximumMarks}`;
    if(modalPercentEl) modalPercentEl.textContent = `${newPercentage.toFixed(0)}%`;
    if(modalPercentCardEl) {
        let scoreClass = 'score-low';
        if (newPercentage > 70) scoreClass = 'score-high';
        else if (newPercentage > 40) scoreClass = 'score-medium';
        modalPercentCardEl.className = `stat-card ${scoreClass}`;
    }
    
    // 6. Save changes to DB
    saveUpdatedAssessmentReport(report);
};




