/**
 * Main function to initiate the attendance taking process for a class.
 */
async function handleTakeAttendance() {
    if (!currentEditingRoster) {
        showFeedbackMessage("Could not load class data for attendance.", "error");
        return;
    }
    const roster = currentEditingRoster;

    // --- THIS IS THE FIX ---
    // This line closes the roster modal before opening the attendance modal.
    toggleModal('class-roster-modal', false);

    attendanceModalTitleEl.textContent = `Attendance for ${roster.subject} (Class ${roster.className} - ${roster.section})`;
    
    // Reset and initialize attendance data for all students in the roster
    currentAttendanceData.clear();
    roster.students.forEach(student => {
        currentAttendanceData.set(student.uid, 'present'); // Default everyone to present
    });

    renderAttendanceList(roster);
    toggleModal('attendance-modal', true);
}
window.handleTakeAttendance = handleTakeAttendance;


/**
 * Gathers attendance data from the modal and saves it to Firestore.
 */
async function handleSaveAttendance() {
    if (!currentEditingRoster || currentAttendanceData.size === 0) {
        showFeedbackMessage("No attendance data to save.", "error");
        return;
    }
    
    toggleLoading(true, "Saving attendance...");

    const roster = currentEditingRoster;
    const today = new Date();
    const dateString = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}-${String(today.getDate()).padStart(2, '0')}`;
    
    const attendanceRecord: AttendanceRecord = {
        id: `${roster.id}_${dateString}`,
        rosterId: roster.id,
        date: dateString,
        teacherUid: roster.teacherUid,
        className: roster.className,
        section: roster.section,
        subject: roster.subject,
        attendance: Object.fromEntries(currentAttendanceData),
    };

    try {
        await saveAttendanceRecord(attendanceRecord);
        toggleModal('attendance-modal', false);
        showFeedbackMessage("Attendance for today saved successfully!", "success");
    } catch (error) {
        console.error("Failed to save attendance:", error);
        showFeedbackMessage("An error occurred while saving attendance. Please try again.", "error");
    } finally {
        toggleLoading(false);
    }
}




/**
 * Applies the "frozen" UI state to features based on the globally stored featureFlags.
 */
function applyFeatureLocks() {
// A map connecting feature flag names from Firestore to the HTML elements in the app.
const featureMap: { [key in keyof FeatureFlags]: HTMLElement[] } = {
    // Homework Creation Buttons
    teacherHomeworkCreation_usingAI: [document.getElementById('create-hw-from-ai-btn')!],
    teacherHomeworkCreation_fromBook: [document.getElementById('create-hw-from-book-btn')!],
    teacherHomeworkCreation_myQuestions: [document.getElementById('create-hw-from-myq-btn')!],

    
    
teacherAssessmentCreation_usingAI: [
    document.getElementById('create-as-from-ai-btn')!,
    document.querySelector('.as-tab[data-tab="ai"]') as HTMLElement  // ← also lock the tab
],
teacherAssessmentCreation_fromBook: [
    document.getElementById('create-as-from-book-btn')!,
    document.querySelector('.as-tab[data-tab="book"]') as HTMLElement
],
    teacherAssessmentCreation_myQuestions: [document.getElementById('create-as-from-myq-btn')!],
    
    // The Master Grading Lock
    teacherAssessmentGrading: [
        document.getElementById('goto-assessment-checker-btn')!,
        ...Array.from(document.querySelectorAll<HTMLElement>('.grade-assessment-btn')),
        ...Array.from(document.querySelectorAll<HTMLElement>('.grading-action-btn'))
    ],

teacherAnalyticsHub: [document.getElementById('view-summary-analytics-btn')!],
studentPortfolioView: [...Array.from(document.querySelectorAll<HTMLElement>('button[onclick*="handleViewStudentPortfolio"]'))]
};

    // --- Personalized Worksheets Card Lock ---
    // Always visible, but locked with overlay when feature is OFF
    const worksheetCard = document.getElementById('class-page-remedial');
    if (worksheetCard) {
        // Clean up previous lock state
        worksheetCard.classList.remove('worksheet-card-locked');
        const existingOverlay = worksheetCard.querySelector('.worksheet-lock-overlay');
        if (existingOverlay) existingOverlay.remove();

        if (featureFlags['teacherPersonalizedWorksheets'] === false) {
            worksheetCard.classList.add('worksheet-card-locked');
            const overlay = document.createElement('div');
            overlay.className = 'worksheet-lock-overlay';
            overlay.innerHTML = `
                <div class="worksheet-lock-content">
                    <span class="worksheet-lock-icon">🔒</span>
                    <p class="worksheet-lock-text">Feature Locked</p>
                    <p class="worksheet-lock-subtext">Contact your institute admin to enable</p>
                </div>`;
            worksheetCard.appendChild(overlay);
        }
    }



    // Loop through each feature we can control
    for (const featureName in featureMap) {
        // The feature is considered OFF only if it is explicitly set to `false`.
        // If the flag is `true` or doesn't exist (undefined), the feature is ON by default.
        const isEnabled = featureFlags[featureName] !== false;
        const elements = featureMap[featureName as keyof FeatureFlags].filter(el => el); // Filter out any null elements

        elements.forEach(el => {
            // Clean up previous state first
            el.classList.remove('frozen-feature');
            const existingIcon = el.querySelector('.lock-icon-overlay');
            if (existingIcon) {
                existingIcon.remove();
            }

            // If the feature is disabled, apply the frozen styles
            if (!isEnabled) {
                el.classList.add('frozen-feature');
                // Add the lock icon overlay
                const lockIcon = document.createElement('span');
                lockIcon.className = 'lock-icon-overlay';
                lockIcon.textContent = '🔒';
                lockIcon.setAttribute('aria-label', 'Feature locked');
                el.appendChild(lockIcon);
            }
        });
    }
}

