function populateSubjectDropdownForHomeworkCreation(elements: HTMLSelectElement[]) {
    if (!teacherProfile || !teacherProfile.subjectsTaught) return;

    // Start with the subjects from the teacher's profile and use a Set to prevent duplicates.
    const subjects = new Set(teacherProfile.subjectsTaught);

    // This is the key fix: If we are creating homework/assessment for a specific class,
    // we ensure its subject is included in the dropdown list, even if it's not in the teacher's main profile.
    // This prevents the form from failing if the profile is slightly out of date.
    if (currentClassForHomeworkCreation && currentClassForHomeworkCreation.subject) {
        subjects.add(currentClassForHomeworkCreation.subject);
    }

    // Convert the Set back to an array and sort it for a clean, alphabetical display.
    const sortedSubjects = [...subjects].sort();

    // Generate the HTML for the dropdown options.
    const optionsHtml = '<option value="">-- Select Subject --</option>' + sortedSubjects.map(s => `<option value="${s}">${s}</option>`).join('');
    
    // Apply the new, corrected options to all the select elements passed to the function.
    elements.forEach(el => {
        if(el) el.innerHTML = optionsHtml;
    });
}

function populateClassDropdowns(elements: HTMLSelectElement[]) {
    if (!teacherProfile || !teacherProfile.classesTaught) return;
    const sortedClasses = [...teacherProfile.classesTaught].sort((a,b) => parseInt(a) - parseInt(b));
    const optionsHtml = '<option value="">-- Select Class --</option>' + sortedClasses.map(c => `<option value="${c}">Class ${c}</option>`).join('');
     elements.forEach(el => {
        if(el) el.innerHTML = optionsHtml;
    });
}

function populateSectionDropdowns(selectEl: HTMLSelectElement, customInputEl?: HTMLInputElement) {
    if (!selectEl) return;
    const sections = ['A', 'B', 'C', 'D'];
    selectEl.innerHTML = '<option value="">-- Select Section --</option>' +
        sections.map(s => `<option value="${s}">${s}</option>`).join('') +
        '<option value="Other">Other...</option>';

    if (customInputEl) {
        customInputEl.style.display = 'none';
        selectEl.addEventListener('change', () => {
            if (selectEl.value === 'Other') {
                customInputEl.style.display = 'block';
                customInputEl.value = '';
                customInputEl.focus();
            } else {
                customInputEl.style.display = 'none';
            }
        });
    }
}

function setupSchoolRegistration() {
    schoolRegisterLoadingMsgEl.style.display = 'block';
    teacherRegisterSchoolInputEl.disabled = true;

    const showSuggestions = (searchTerm: string) => {
        schoolSuggestionsContainerEl.innerHTML = '';
        if (!searchTerm) {
            schoolSuggestionsContainerEl.style.display = 'none';
            return;
        }

        const filteredSchools = allSchoolsFromCSV
            .filter(school => school.SchoolName.toLowerCase().includes(searchTerm.toLowerCase()))
            .slice(0, 10); // Limit to 10 suggestions for performance

        if (filteredSchools.length > 0) {
            filteredSchools.forEach(school => {
                const item = document.createElement('div');
                item.className = 'suggestion-item';
                item.innerHTML = `${school.SchoolName} <span class="board">(${school.Board})</span>`;
                item.addEventListener('click', () => {
                    teacherRegisterSchoolInputEl.value = school.SchoolName;
                    (teacherRegisterSchoolInputEl as HTMLInputElement).dataset.board = school.Board;
                    schoolSuggestionsContainerEl.style.display = 'none';
                });
                schoolSuggestionsContainerEl.appendChild(item);
            });
            schoolSuggestionsContainerEl.style.display = 'block';
        } else {
            schoolSuggestionsContainerEl.style.display = 'none';
        }
    };

    teacherRegisterSchoolInputEl.addEventListener('input', () => {
        showSuggestions(teacherRegisterSchoolInputEl.value);
        delete (teacherRegisterSchoolInputEl as HTMLInputElement).dataset.board;
    });

    document.addEventListener('click', (e) => {
        if (!teacherRegistrationSectionEl.contains(e.target as Node)) {
            schoolSuggestionsContainerEl.style.display = 'none';
        }
    });

    fetchAndCacheSchoolsCSV(
        (schools) => {
            allSchoolsFromCSV = schools.sort((a, b) => a.SchoolName.localeCompare(b.SchoolName));
            schoolRegisterLoadingMsgEl.style.display = 'none';
            teacherRegisterSchoolInputEl.disabled = false;
        },
        (errorMsg) => {
            showFeedbackMessage(errorMsg, 'info');
            schoolRegisterLoadingMsgEl.style.display = 'none';
            teacherRegisterSchoolInputEl.disabled = false;
        }
    );
}


