function prefillAndDisableHomeworkClassDetails(subjectEl: HTMLSelectElement, classEl: HTMLSelectElement, sectionEl: HTMLSelectElement, customSectionEl: HTMLInputElement) {
    if (currentClassForHomeworkCreation) {
        const { subject, className, section, stream } = currentClassForHomeworkCreation as any;

        subjectEl.value = subject;
        subjectEl.disabled = true;

        classEl.value = className;
        classEl.disabled = true;

        const standardSections = ['A', 'B', 'C', 'D'];
        if (standardSections.includes(section)) {
            sectionEl.value = section;
            customSectionEl.style.display = 'none';
        } else {
            sectionEl.value = 'Other';
            customSectionEl.value = section;
            customSectionEl.style.display = 'block';
            customSectionEl.disabled = true;
        }
        sectionEl.disabled = true;

        // Auto-show and pre-fill stream for Class 11/12
        const classNum = parseInt(String(className).replace(/\D/g, ''), 10);
        const isHighClass = classNum >= 11;
        // Try to find a stream field sibling: derive form prefix from subjectEl id
        const prefix = subjectEl.id.replace('-subject-select', '').replace('as-create', 'as');
        const streamGroup = document.getElementById(`${prefix}-stream-group`) || 
                            subjectEl.closest('form')?.querySelector('[id$="-stream-group"]') as HTMLElement | null;
        const streamSelect = streamGroup?.querySelector('select') as HTMLSelectElement | null;
        if (streamGroup) {
            streamGroup.style.display = isHighClass ? '' : 'none';
            if (streamSelect && stream) {
                streamSelect.value = stream;
                streamSelect.disabled = true;
            }
        }
    } else {
        subjectEl.disabled = false;
        classEl.disabled = false;
        sectionEl.disabled = false;
        customSectionEl.disabled = false;

        // Also enable/show stream based on class value when not prefilled
        const classNum = parseInt(String(classEl.value).replace(/\D/g, ''), 10);
        const prefix = subjectEl.id.replace('-subject-select', '').replace('as-create', 'as');
        const streamGroup = document.getElementById(`${prefix}-stream-group`) ||
                            subjectEl.closest('form')?.querySelector('[id$="-stream-group"]') as HTMLElement | null;
        if (streamGroup) streamGroup.style.display = isNaN(classNum) || classNum < 11 ? 'none' : '';
    }
}

