// --- REPLACE THE OLD prepareHomeworkCreationForm FUNCTION WITH THIS ENTIRE BLOCK ---

function prepareHomeworkCreationForm() {
    if (!teacherProfile) return;

    if (hwFormAbortController) {
        hwFormAbortController.abort();
    }
    hwFormAbortController = new AbortController();
    const signal = hwFormAbortController.signal;

    const setupAndPopulateForm = () => {
        hwCreateDueDateInputEl.value = '';
        hwCreateSectionCustomInputEl.value = '';
        hwCreateChaptersSelectEl.innerHTML = '<option value="">-- Select Subject, Class first --</option>';
        hwCreateChaptersSelectEl.disabled = true;
        hwCreateTopicsSelectEl.innerHTML = '<option value="">-- Select Chapter(s) first --</option>';
        hwCreateTopicsSelectEl.disabled = true;
        chaptersLoadingMessageEl.style.display = 'none';
        topicsLoadingMessageEl.style.display = 'none';
        
        hwCreateSchoolDisplayEl.textContent = teacherProfile!.schoolName;
        hwCreateBoardDisplayEl.textContent = teacherProfile!.board || 'Not Found. Please update in profile.';
        populateSubjectDropdownForHomeworkCreation([hwCreateSubjectSelectEl]);
        populateClassDropdowns([hwCreateClassSelectEl]);
        populateSectionDropdowns(hwCreateSectionSelectEl, hwCreateSectionCustomInputEl);
        
        prefillAndDisableHomeworkClassDetails(hwCreateSubjectSelectEl, hwCreateClassSelectEl, hwCreateSectionSelectEl, hwCreateSectionCustomInputEl);

        const updateChapters = () => {
            const subject = hwCreateSubjectSelectEl.value;
            const studentClass = hwCreateClassSelectEl.value;
            const board = teacherProfile!.board;

            if (!subject || !studentClass || !board) {
                hwCreateChaptersSelectEl.innerHTML = '<option value="">-- Select Subject & Class first --</option>';
                hwCreateChaptersSelectEl.disabled = true;
                return;
            }

            hwCreateChaptersSelectEl.disabled = true;
            chaptersLoadingMessageEl.style.display = 'block';
            fetchAndCacheTopicsCSV(
                (topics) => {
                    // --- THIS IS THE FIX: Normalizing all data before comparison ---
                    const normalizedBoard = normalizeForComparison(board);
                    const normalizedClass = normalizeForComparison(studentClass);
                    const normalizedSubject = normalizeForComparison(subject);

                    const filteredChapters = [...new Set(topics
                        .filter(t => 
                            normalizeForComparison(t.Board) === normalizedBoard && 
                            normalizeForComparison(t.Class) === normalizedClass && 
                            normalizeForComparison(t.Subject) === normalizedSubject
                        )
                        .map(t => t['Chapter Name'].trim())
                    )].sort();
                    // --- END OF FIX ---

                    if (filteredChapters.length > 0) {
                        hwCreateChaptersSelectEl.innerHTML = filteredChapters.map(ch => `<option value="${ch}">${ch}</option>`).join('');
                    } else {
                        hwCreateChaptersSelectEl.innerHTML = '<option value="">No chapters found for this selection</option>';
                    }
                    hwCreateChaptersSelectEl.disabled = false;
                    chaptersLoadingMessageEl.style.display = 'none';
                    updateTopicsForSelectedChapters();
                },
                (errorMsg) => {
                    chaptersLoadingMessageEl.textContent = 'Error loading chapters.';
                    showFeedbackMessage(errorMsg, 'info');
                }
            );
        };

        const updateTopicsForSelectedChapters = () => {
            const selectedChapters = Array.from(hwCreateChaptersSelectEl.selectedOptions).map(opt => opt.value);
            const subject = hwCreateSubjectSelectEl.value;
            const studentClass = hwCreateClassSelectEl.value;
            const board = teacherProfile!.board;

            if (selectedChapters.length === 0 || !subject || !studentClass || !board) {
                hwCreateTopicsSelectEl.innerHTML = '<option value="">-- Select Chapter(s) first --</option>';
                hwCreateTopicsSelectEl.disabled = true;
                return;
            }

            hwCreateTopicsSelectEl.disabled = true;
            topicsLoadingMessageEl.style.display = 'block';
            
            // --- THIS IS THE FIX: Normalizing all data before comparison ---
            const normalizedBoard = normalizeForComparison(board);
            const normalizedClass = normalizeForComparison(studentClass);
            const normalizedSubject = normalizeForComparison(subject);

            const topicNames = allTopicsFromCSV
                .filter(t =>
                    normalizeForComparison(t.Board) === normalizedBoard &&
                    normalizeForComparison(t.Subject) === normalizedSubject &&
                    normalizeForComparison(t.Class) === normalizedClass &&
                    selectedChapters.includes(t['Chapter Name'])
                )
                .map(t => t['Subtopic Name'].trim());
            // --- END OF FIX ---
            
            const uniqueTopics = [...new Set(topicNames)].sort();
            
            if (uniqueTopics.length > 0) {
                hwCreateTopicsSelectEl.innerHTML = uniqueTopics.map(topic => `<option value="${topic}" selected>${topic}</option>`).join('');
            } else {
                hwCreateTopicsSelectEl.innerHTML = '<option value="">No topics found for this selection</option>';
            }
            hwCreateTopicsSelectEl.disabled = false;
            topicsLoadingMessageEl.style.display = 'none';
        };
        
        if (hwCreateSubjectSelectEl.value && hwCreateClassSelectEl.value) {
            updateChapters();
        }

        hwCreateSubjectSelectEl.addEventListener('change', updateChapters, { signal });
        hwCreateClassSelectEl.addEventListener('change', updateChapters, { signal });
        hwCreateChaptersSelectEl.addEventListener('change', updateTopicsForSelectedChapters, { signal });

        if (isCopyingHomework && temporaryHomeworkData.source === 'curriculum') {
            hwCreateSubjectSelectEl.value = temporaryHomeworkData.subject || '';
            hwCreateClassSelectEl.value = temporaryHomeworkData.className || '';
            hwCreateSectionSelectEl.value = temporaryHomeworkData.section || '';
            hwCreateQuestionTypeSelectEl.value = temporaryHomeworkData.questionType || 'Subjective';
            hwCreateNumQuestionsSelectEl.value = temporaryHomeworkData.questions?.length.toString() || '5';
            hwCreateDifficultySelectEl.value = temporaryHomeworkData.difficultyLevel || 'Medium';
            hwCreateCheckingStrictnessSelectEl.value = temporaryHomeworkData.checkingStrictness || 'Medium';
            
            updateChapters();
            setTimeout(() => {
                if (temporaryHomeworkData.selectedChapters) {
                    Array.from(hwCreateChaptersSelectEl.options).forEach(opt => {
                        if (temporaryHomeworkData.selectedChapters!.includes(opt.value)) {
                            opt.selected = true;
                        }
                    });
                    hwCreateChaptersSelectEl.dispatchEvent(new Event('change'));
                }
            }, 1000); 
            isCopyingHomework = false;
        }
    };

    if (!teacherProfile.board && teacherProfile.schoolName) {
        toggleLoading(true, "Looking up your school's curriculum board...");
        fetchAndCacheSchoolsCSV(
            (schools) => {
                const schoolData = schools.find(s => 
                    s.SchoolName.trim().toLowerCase() === teacherProfile!.schoolName.trim().toLowerCase()
                );
                if (schoolData && schoolData.Board) {
                    teacherProfile!.board = schoolData.Board;
                    showFeedbackMessage(`Found and applied your school's board: ${schoolData.Board}`, "success");
                } else {
                    showFeedbackMessage("Could not automatically find your school's board. Please set it in your profile to access curriculum features.", "info");
                }
                toggleLoading(false);
                setupAndPopulateForm();
            },
            (errorMsg) => {
                showFeedbackMessage(`Error fetching school list: ${errorMsg}`, "error");
                toggleLoading(false);
                setupAndPopulateForm();
            }
        );
    } else {
        setupAndPopulateForm();
    }
}

