function handleCopyHomework(homework: Homework) {
    isCopyingHomework = true;
    const copiedQuestions = JSON.parse(JSON.stringify(homework.questions));
    temporaryHomeworkData = { ...homework, questions: copiedQuestions };
    delete temporaryHomeworkData.homeworkId;
    delete temporaryHomeworkData.creationTimestamp;

    showFeedbackMessage("Copied homework details. Please review and generate new questions, or save as is.", 'info');
    
    currentClassForHomeworkCreation = {
        id: '', teacherUid: '', students: [],
        subject: homework.subject,
        className: homework.className,
        section: homework.section,
        schoolName: homework.schoolName,
        board: homework.board
    };

    window.switchHomeworkTab('myq');
}

function displayStudentListInModal(title: string, submittedStudents: {name: string | undefined, id: string}[], allAssignedStudents?: RosterStudent[]) {
    studentListModalTitleEl.textContent = title;

    if (!allAssignedStudents || allAssignedStudents.length === 0) {
         const submittedHtml = submittedStudents.length > 0 ? submittedStudents
            .map(s => `<li class="submitted">${s.name || 'Unknown Student'}</li>`)
            .join('') : '<p>None</p>';

        studentListModalContentEl.innerHTML = `
            <div class="student-list-columns">
                <div class="student-list-column">
                    <h4>Submitted (${submittedStudents.length})</h4>
                    <p class="description">Full class roster could not be loaded to show pending students.</p>
                    <ul class="student-status-list">${submittedHtml}</ul>
                </div>
            </div>`;
    } else {
        const uniqueAssignedStudents = [...new Map(allAssignedStudents.map(student => [student.uid, student])).values()];
        
        const submittedStudentIds = new Set(submittedStudents.map(s => s.id));

        const submittedHtml = uniqueAssignedStudents
            .filter(s => submittedStudentIds.has(s.uid))
            .map(s => `<li class="submitted">${s.name}</li>`)
            .join('');
        
        const submittedCount = uniqueAssignedStudents.filter(s => submittedStudentIds.has(s.uid)).length;

        const pendingHtml = uniqueAssignedStudents
            .filter(s => !submittedStudentIds.has(s.uid))
            .map(s => `<li class="pending">${s.name}</li>`)
            .join('');

        const pendingCount = uniqueAssignedStudents.length - submittedCount;

        studentListModalContentEl.innerHTML = `
            <div class="student-list-columns">
                <div class="student-list-column">
                    <h4>Submitted (${submittedCount})</h4>
                    <ul class="student-status-list">${submittedHtml || '<p>None</p>'}</ul>
                </div>
                <div class="student-list-column">
                    <h4>Pending (${pendingCount})</h4>
                    <ul class="student-status-list">${pendingHtml || '<p>None</p>'}</ul>
                </div>
            </div>
        `;
    }
    toggleModal('student-list-modal', true);
}

// AFTER
async function renderRosterInModal(roster: ClassRoster) {
    currentEditingRoster = roster;
    classRosterModalTitleEl.innerHTML = `Roster: ${roster.subject} (Class ${roster.className} - ${roster.section})`;
    
    if (!teacherProfile) {
        showFeedbackMessage("Cannot load roster actions because teacher profile is not available.", "error");
        return;
    }

    const uniqueStudents = [...new Map(roster.students.map(item => [item.email, item])).values()];
    rosterStudentCountEl.textContent = uniqueStudents.length.toString();

    // Enrich from school directory to get name + rollNumber for students with blank names
    const hasBlankNames = uniqueStudents.some(s => !s.name);
    let directoryMap = new Map<string, any>();
    if (hasBlankNames && teacherProfile.schoolName) {
        try {
            const dirSnap = await fbFirestore.collection('students')
                .where('school', '==', teacherProfile.schoolName).get();
            dirSnap.docs.forEach(doc => {
                const d = doc.data();
                if (d.uid) directoryMap.set(d.uid, d);
                if (d.email) directoryMap.set(d.email.toLowerCase(), d);
            });
        } catch(e) { /* permissions may block — proceed without */ }
    }

    const studentListHtml = uniqueStudents.length > 0 ?
        uniqueStudents
        .map(student => {
            // Enrich with directory data if name is blank
            const dir = directoryMap.get(student.uid) || directoryMap.get((student.email || '').toLowerCase());
            const displayName = student.name || dir?.name || student.email || student.uid;
            const rollNumber = (student as any).rollNumber || dir?.rollNumber || '';
            return { ...student, displayName, rollNumber };
        })
        .sort((a, b) => {
            // Sort by roll number numerically if available, else by name
            const rA = parseInt(a.rollNumber) || 0;
            const rB = parseInt(b.rollNumber) || 0;
            if (rA && rB) return rA - rB;
            return a.displayName.localeCompare(b.displayName);
        })
        .map(student => {
            const status = student.status || 'active';
            return `
                <li class="roster-student-item">
                    <span class="roster-student-info">
                        <span class="name">${student.displayName}</span>
                        ${student.rollNumber ? `<span style="font-size:0.75rem;color:#94a3b8;margin-left:6px;">#${student.rollNumber}</span>` : ''}
                    </span>
                    <div class="roster-student-actions">
                        <span class="status-chip ${status}">${status}</span>
                    </div>
                </li>
            `
        }).join('') : '<li>No students in this class yet.</li>';

    rosterStudentListContainerEl.innerHTML = `<ul class="roster-student-list">${studentListHtml}</ul>`;
    
    toggleModal('class-roster-modal', true);
    
    applyFeatureLocks();
}

async function handleGenerateAssessmentFromMyQ(event: Event) {
    event.preventDefault();
    if (!teacherProfile) return;

    if (uploadedQuestionImages.length === 0) {
        showFeedbackMessage("Please upload at least one question paper image.", "error");
        return;
    }

    const form = document.getElementById('as-myq-form') as HTMLFormElement;
    const sectionSelectEl = form.querySelector('#as-myq-section-select') as HTMLSelectElement;
    const solutionFiles = Array.from(asMyQSolutionInputEl.files || []);
    
    temporaryAssessmentData = {
        createdByTeacherUid: teacherProfile.uid,
        teacherName: teacherProfile.name,
        schoolName: teacherProfile.schoolName,
        board: currentClassForHomeworkCreation?.board || teacherProfile.board,

        assessmentTitle: (form.querySelector('#as-myq-title-input') as HTMLInputElement).value,
        subject: (form.querySelector('#as-myq-subject-select') as HTMLSelectElement).value,
        className: (form.querySelector('#as-myq-class-select') as HTMLSelectElement).value,
        section: sectionSelectEl.value === 'Other' 
            ? (form.querySelector('#as-myq-section-custom') as HTMLInputElement).value 
            : sectionSelectEl.value,
        checkingStrictness: (form.querySelector('#as-myq-checking-strictness-select') as HTMLSelectElement).value,
source: 'question_images',
        hasSections: (form.querySelector('input[name="as-paper-structure"]:checked') as HTMLInputElement)?.value === 'sectioned',
        totalMarks: parseInt((form.querySelector('.as-myq-total-marks') as HTMLInputElement).value, 10),
        questions: [],
    };
    
    displayAssessmentReviewSummary();
    updateUIVisibility('teacher_assessment_ai_review');
    const container = document.getElementById('assessment-ai-questions-preview-container') as HTMLDivElement;
    container.innerHTML = `<div class="spinner-container"><div class="spinner-small"></div> <p>AI is extracting questions from your images...</p></div>`;

    try {
        await streamExtractAssessmentQuestionsFromImages(temporaryAssessmentData, uploadedQuestionImages, solutionFiles, async (newQuestion) => {
            if (temporaryAssessmentData.questions?.length === 0) {
                container.innerHTML = ''; 
            }
            temporaryAssessmentData.questions?.push(newQuestion);
            // ADD THIS NEW LINE:
const newQuestionIndex = temporaryAssessmentData.questions.length - 1;
             await appendAndRenderAssessmentQuestionCard(newQuestion, newQuestionIndex, container);
            // NOTE: The image cropping call has been intentionally removed as requested.
        });
    } catch (error) {
        console.error("Error extracting assessment from images:", error);
        container.innerHTML = `<p class="error-text">Failed to extract questions. Please try again.</p>`;
        showFeedbackMessage("An AI error occurred during question extraction.", "error");
    }
}


async function handleViewRoster(rosterId: string) {
    if (!rosterId || rosterId.includes('undefined') || rosterId.includes('null')) {
        showFeedbackMessage("Invalid class identifier. The class may have incomplete details (e.g., missing section or subject).", 'error');
        return;
    }
    toggleLoading(true, "Loading roster...");
    try {
        const roster = await getClassRoster(rosterId);
        if (roster) {
            await renderRosterInModal(roster);
        } else {
            showFeedbackMessage("Could not find the class roster.", 'error');
        }
    } catch (error) {
        console.error(`Error fetching roster ${rosterId}:`, error);
        showFeedbackMessage("An error occurred while loading the roster details.", 'error');
    } finally {
        toggleLoading(false);
    }
}
window.handleViewRoster = handleViewRoster;

