// VIEW UPLOADED PAGES MODAL — shows thumbnails + filenames of pre-uploaded sheets
// ─────────────────────────────────────────────────────────────────────────────
window.handleViewUploadedPages = (studentUid: string, studentName: string) => {
    const data = studentPreUploadedData.get(studentUid);
    if (!data || data.urls.length === 0) return;

    // Build or reuse modal
    let modal = document.getElementById('uploaded-pages-preview-modal');
    if (!modal) {
        modal = document.createElement('div');
        modal.id = 'uploaded-pages-preview-modal';
        modal.style.cssText = `
            position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,0.75);
            display:flex;align-items:center;justify-content:center;padding:16px;
        `;
        modal.addEventListener('click', (e) => {
            if (e.target === modal) modal!.style.display = 'none';
        });
        document.body.appendChild(modal);
    }

    const thumbsHtml = data.urls.map((url, i) => {
        // Extract readable filename from the storage path
        const path = data.paths[i] || '';
        const rawName = path.split('/').pop() || `page_${i + 1}`;
        // Strip the timestamp prefix (e.g. "1716543210000_") if present
        const displayName = rawName.replace(/^\d{10,}_/, '');
        return `
            <div style="display:flex;flex-direction:column;align-items:center;gap:6px;cursor:pointer;"
                 onclick="window.open('${url}','_blank')">
                <img src="${url}" alt="Page ${i+1}"
                     style="width:140px;height:180px;object-fit:cover;border-radius:8px;
                            border:2px solid #e8e8e8;box-shadow:0 2px 8px rgba(0,0,0,0.15);
                            transition:transform 0.15s;"
                     onmouseover="this.style.transform='scale(1.04)'"
                     onmouseout="this.style.transform='scale(1)'"
                     onerror="this.src='data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 width=%22140%22 height=%22180%22><rect width=%22140%22 height=%22180%22 fill=%22%23f0f0f0%22/><text x=%2250%25%22 y=%2250%25%22 dominant-baseline=%22middle%22 text-anchor=%22middle%22 font-size=%2212%22 fill=%22%23999%22>No preview</text></svg>'" />
                <div style="text-align:center;max-width:140px;">
                    <div style="font-size:0.7rem;font-weight:600;color:#1d1d1f;">Page ${i+1}</div>
                    <div style="font-size:0.65rem;color:#666;word-break:break-all;line-height:1.3;">${displayName}</div>
                </div>
            </div>`;
    }).join('');

    modal.innerHTML = `
        <div style="background:#fff;border-radius:16px;max-width:860px;width:100%;
                    max-height:90vh;overflow-y:auto;box-shadow:0 20px 60px rgba(0,0,0,0.3);">
            <div style="padding:20px 24px;border-bottom:1px solid #f0f0f0;
                        display:flex;align-items:center;justify-content:space-between;
                        position:sticky;top:0;background:#fff;z-index:1;border-radius:16px 16px 0 0;">
                <div>
                    <h3 style="margin:0;font-size:1.05rem;color:#1d1d1f;">☁️ Uploaded Pages — ${studentName}</h3>
                    <p style="margin:4px 0 0;font-size:0.8rem;color:#666;">${data.urls.length} page(s) stored in cloud • Click any page to open full size</p>
                </div>
                <button onclick="document.getElementById('uploaded-pages-preview-modal').style.display='none'"
                        style="background:none;border:none;font-size:1.4rem;cursor:pointer;color:#666;
                               width:32px;height:32px;display:flex;align-items:center;justify-content:center;
                               border-radius:50%;transition:background 0.15s;"
                        onmouseover="this.style.background='#f5f5f5'"
                        onmouseout="this.style.background='none'">✕</button>
            </div>
            <div style="padding:24px;display:flex;flex-wrap:wrap;gap:16px;justify-content:flex-start;">
                ${thumbsHtml}
            </div>
        </div>`;

    modal.style.display = 'flex';
};

