window.handleScheduleBatchGrade = (studentUids: string[]) => {
    if (!currentAssessmentToGrade || !teacherProfile) {
        showFeedbackMessage("No assessment selected.", "error");
        return;
    }

    // Only students who have pre-uploaded files
    const eligibleUids = studentUids.filter(uid => studentPreUploadedData.has(uid));
    if (eligibleUids.length === 0) {
        showFeedbackMessage("No students have uploaded files yet. Upload answer sheets first.", "error");
        return;
    }

    // Build or reuse modal
    let modal = document.getElementById('batch-schedule-modal');
    if (!modal) {
        modal = document.createElement('div');
        modal.id = 'batch-schedule-modal';
        modal.style.cssText = `position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,0.7);
            display:flex;align-items:center;justify-content:center;padding:16px;`;
        modal.addEventListener('click', (e) => { if (e.target === modal) modal!.style.display = 'none'; });
        document.body.appendChild(modal);
    }

    const notUploaded = studentUids.length - eligibleUids.length;
    const warningHtml = notUploaded > 0
        ? `<div style="background:#fff8e7;border:1px solid #f59e0b;border-radius:8px;padding:10px 14px;font-size:0.8rem;color:#92400e;margin-bottom:16px;">
               ⚠️ ${notUploaded} student(s) skipped — no files uploaded yet.
           </div>` : '';

    modal.innerHTML = `
        <div style="background:#fff;border-radius:16px;max-width:440px;width:100%;
                    box-shadow:0 20px 60px rgba(0,0,0,0.3);overflow:hidden;">
            <div style="background:linear-gradient(135deg,#1a1a2e,#16213e);padding:20px 24px;">
                <h3 style="margin:0;color:#fff;font-size:1.1rem;">🌙 Batch Grade Tonight</h3>
                <p style="margin:6px 0 0;color:rgba(255,255,255,0.7);font-size:0.82rem;">
                    Grades ${eligibleUids.length} student(s) automatically while you sleep
                </p>
            </div>
            <div style="padding:20px 24px;">
                ${warningHtml}
                <div style="margin-bottom:16px;">
                    <label style="font-size:0.85rem;font-weight:600;color:#1d1d1f;display:block;margin-bottom:8px;">
                        ⏰ Start grading at (IST):
                    </label>
                    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;" id="batch-timeslot-grid">
                        ${[
                            { label: '11:00 PM', hour: 23 },
                            { label: '12:00 AM', hour: 0 },
                            { label: '1:00 AM',  hour: 1 },
                            { label: '2:00 AM',  hour: 2 },
                        ].map((slot, i) => `
                            <button class="batch-slot-btn ${i === 1 ? 'selected' : ''}"
                                    data-hour="${slot.hour}"
                                    onclick="document.querySelectorAll('.batch-slot-btn').forEach(b=>b.classList.remove('selected'));this.classList.add('selected');"
                                    style="padding:12px;border-radius:10px;font-size:0.9rem;font-weight:600;cursor:pointer;
                                           border:2px solid ${i === 1 ? '#6366f1' : '#e5e7eb'};
                                           background:${i === 1 ? '#eef2ff' : '#fff'};
                                           color:${i === 1 ? '#4338ca' : '#374151'};
                                           transition:all 0.15s;">
                                ${slot.label}
                            </button>`).join('')}
                    </div>
                </div>
                <div style="background:#f0fdf4;border:1px solid #86efac;border-radius:8px;padding:10px 14px;
                            font-size:0.78rem;color:#166534;margin-bottom:20px;">
                    ✅ 60-second gap between each student &nbsp;|&nbsp; 
                    Same grading quality as single student &nbsp;|&nbsp; 
                    Reports ready by morning
                </div>
                <div style="display:flex;gap:10px;">
                    <button onclick="document.getElementById('batch-schedule-modal').style.display='none'"
                            style="flex:1;padding:12px;border-radius:10px;border:1px solid #e5e7eb;
                                   background:#fff;cursor:pointer;font-size:0.9rem;color:#374151;">
                        Cancel
                    </button>
                    <button id="batch-confirm-btn"
                            style="flex:2;padding:12px;border-radius:10px;border:none;
                                   background:linear-gradient(135deg,#6366f1,#4338ca);color:#fff;
                                   font-size:0.9rem;font-weight:700;cursor:pointer;">
                        🌙 Schedule Batch Grade
                    </button>
                </div>
            </div>
        </div>`;

    modal.style.display = 'flex';

    // Confirm button handler
    document.getElementById('batch-confirm-btn')?.addEventListener('click', async () => {
        const selectedBtn = document.querySelector('.batch-slot-btn.selected') as HTMLButtonElement;
        const scheduledHour = selectedBtn ? parseInt(selectedBtn.dataset.hour!) : 0;

        const confirmBtn = document.getElementById('batch-confirm-btn') as HTMLButtonElement;
        confirmBtn.disabled = true;
        confirmBtn.textContent = '⏳ Scheduling...';

        try {
            const studentsPayload = eligibleUids.map(uid => {
                const pre = studentPreUploadedData.get(uid)!;
                const student = currentAssessmentRoster.find(s => s.uid === uid);
                return {
                    studentUid: uid,
                    studentName: student?.name || uid,
                    filePaths: pre.paths,
                    answerSheetImageUrls: pre.urls,
                    strictness: assessmentStudentStrictness.get(uid) || 'Moderate',
                };
            });

            const assessmentData = {
                totalMarks: currentAssessmentToGrade!.totalMarks,
                subject: currentAssessmentToGrade!.subject,
                questions: currentAssessmentToGrade!.questions.map(q => ({
                    questionNumber: q.questionNumber,
                    text: q.text,
                    answer: q.answer,
                    marks: q.marks,
                    type: q.type,
                    rubric: q.rubric || null,
                    ragContext: q.ragContext || '',
                    topicAnchors: Array.isArray(q.topicAnchors) ? [...q.topicAnchors] : [],
                    checkingInstructions: q.checkingInstructions || '',
                })),
            };

            const hourLabels: Record<number, string> = { 23: '11:00 PM', 0: '12:00 AM', 1: '1:00 AM', 2: '2:00 AM' };

            await fbFirestore.collection('batchGradingJobs').add({
teacherUid: capturedAssessment.createdByTeacherUid || teacherProfile!.uid,
                assessmentId: currentAssessmentToGrade!.assessmentId,
                assessmentTitle: currentAssessmentToGrade!.assessmentTitle || currentAssessmentToGrade!.assessmentId,
                students: studentsPayload,
                assessmentData: assessmentData,
                scheduledHour: scheduledHour,
                scheduledLabel: hourLabels[scheduledHour] || `${scheduledHour}:00`,
                status: 'SCHEDULED',
                processedCount: 0,
                totalCount: studentsPayload.length,
                createdAt: window.firebase.firestore.FieldValue.serverTimestamp(),
            });

            modal!.style.display = 'none';
            showFeedbackMessage(
                `🌙 Batch grade scheduled for ${hourLabels[scheduledHour]} IST — ${studentsPayload.length} students will be graded automatically.`,
                "success",
                true
            );

            // Update UI: show scheduled badge for each student
            eligibleUids.forEach(uid => {
                const actionContainer = document.getElementById(`grading-actions-${uid}`);
                if (actionContainer) {
                    actionContainer.innerHTML = `
                        <div style="display:flex;flex-direction:column;gap:4px;align-items:center;">
                            <span style="color:#6366f1;font-size:0.75rem;font-weight:600;">
                                🌙 Scheduled ${hourLabels[scheduledHour]}
                            </span>
                            <span style="color:#9ca3af;font-size:0.7rem;">Auto-grading tonight</span>
                        </div>`;
                }
            });

        } catch (err) {
            console.error('[BatchGrade] Failed to schedule:', err);
            showFeedbackMessage("Failed to schedule batch grade. Please try again.", "error");
            confirmBtn.disabled = false;
            confirmBtn.textContent = '🌙 Schedule Batch Grade';
        }
    });
};


