window.handleRemoveStudentFromRoster = async (studentUid: string) => {
    if (!currentEditingRoster) return;
    if (!confirm("Are you sure you want to remove this student from the roster?")) return;
    
    const studentIndex = currentEditingRoster.students.findIndex(s => s.uid === studentUid);
    if (studentIndex === -1) return;

    const studentToRemove = currentEditingRoster.students[studentIndex];
    currentEditingRoster.students.splice(studentIndex, 1);
    await renderRosterInModal(currentEditingRoster); // Optimistic UI update
    
    toggleLoading(true, "Updating roster...");
    try {
        await saveClassRoster(currentEditingRoster);
    } catch (error) {
        console.error("Error removing student:", error);
        showFeedbackMessage("Failed to remove student. Please try again.", 'error');
        currentEditingRoster.students.splice(studentIndex, 0, studentToRemove);
        await renderRosterInModal(currentEditingRoster);
    } finally {
        toggleLoading(false);
    }
}
// Individual Generator
window.handleGenerateSingleWorksheet = async (reportIndex: number) => {
    const report = assessmentReports[reportIndex];
    if (!report || !currentAssessmentForReportView) return;

    toggleLoading(true, `Generating Worksheet for ${report.studentName}...`);
    try {
        const worksheet = await generateRemedialWorksheet(report, currentAssessmentForReportView);
        if (worksheet) {
            const docId = `${report.studentUid}_${currentAssessmentForReportView.assessmentId}`;
            await fbFirestore.collection('studentWorksheets').doc(docId).set(sanitizeObjectForFirestore(worksheet));
            showFeedbackMessage(`Worksheet created for ${report.studentName}!`, "success");
            if (currentStage === 'teacher_remedial_progress') {
    renderRemedialProgressPage(currentAssessmentForReportView.assessmentId);
}
        }
    } finally { toggleLoading(false); }
};

// Batch Generator (All Students)
window.handleSendPersonalizedWorksheets = async () => {
    if (!currentAssessmentForReportView || assessmentReports.length === 0) return;
    if (!confirm(`Create personalized worksheets for all ${assessmentReports.length} students?`)) return;

    toggleLoading(true, "Batch Processing Worksheets...");
    let count = 0;
    try {
        for (const report of assessmentReports) {
            const worksheet = await generateRemedialWorksheet(report, currentAssessmentForReportView);
            if (worksheet) {
                const docId = `${report.studentUid}_${currentAssessmentForReportView.assessmentId}`;
                await fbFirestore.collection('studentWorksheets').doc(docId).set(sanitizeObjectForFirestore(worksheet));
                count++;
            }
        }
        showFeedbackMessage(`Created ${count} worksheets!`, "success");
    } finally { toggleLoading(false); }
};







