window.handleSaveReferenceEdit = async (event: Event, index: number) => {
    const btn = event.target as HTMLElement;
    const card = btn.closest('.qp-reference-item') as HTMLElement;
    if (!currentAssessmentToGrade || !currentAssessmentToGrade.questions || !card) return;
    
    // Pull values specifically from the card that was clicked
    const qNum = (card.querySelector('.edit-q-num') as HTMLInputElement).value;
    const qText = (card.querySelector('.edit-q-text') as HTMLTextAreaElement).value;
    const qAns = (card.querySelector('.edit-q-ans') as HTMLTextAreaElement).value;
    const qMarks = parseFloat((card.querySelector('.edit-q-marks') as HTMLInputElement).value);
    const qInst = (card.querySelector('.edit-q-inst') as HTMLTextAreaElement).value;

    const question = currentAssessmentToGrade.questions[index];
question.questionNumber = qNum;
    question.text = qText;
    question.answer = qAns;
    question.marks = qMarks;
    question.checkingInstructions = qInst;

    // Save options if MCQ/AR
    if (question.type === 'MCQ' || question.type === 'Assertion-Reason') {
        const opts = [0,1,2,3].map(idx => {
            const inp = card.querySelector(`.edit-q-option-${idx}`) as HTMLInputElement;
            return inp ? inp.value.trim() : (question.options?.[idx] || '');
        });
        question.options = opts;
    }

    // Handle optional rubric fields if present
    const kwInput = card.querySelector('.edit-q-keywords') as HTMLInputElement;
    const stepInput = card.querySelector('.edit-q-steps') as HTMLTextAreaElement;
    if (kwInput || stepInput) {
        if (!question.rubric) question.rubric = { keywords: [], step_marking: '' };
        if (kwInput) question.rubric.keywords = kwInput.value.split(',').map(s => s.trim()).filter(s => s);
        if (stepInput) question.rubric.step_marking = stepInput.value;
    }
const anchorsInput = card.querySelector('.anchors-edit-input') as HTMLInputElement;
if (anchorsInput) {
    question.topicAnchors = anchorsInput.value.split(',').map(s => s.trim()).filter(s => s);

        // Save MCQ/AR options if present
        if (question.type === 'MCQ' || question.type === 'Assertion-Reason') {
            const opts = [0,1,2,3].map(idx => {
                const inp = card.querySelector(`.mcq-option-input-${idx}`) as HTMLInputElement;
                return inp ? inp.value.trim() : (question.options?.[idx] || '');
            });
            if (opts.some(o => o)) question.options = opts;
        }
}

    toggleLoading(true, "Saving changes...");
    try {
        await updateAssessmentQuestionsInDb(currentAssessmentToGrade.assessmentId, currentAssessmentToGrade.questions);
        
        // 1. Refresh background view
        renderQuestionPaperForGradingReference(currentAssessmentToGrade);
        
        // 2. Sync changes back to the modal if it's open
        const modalContent = document.getElementById('full-qp-modal-content');
        if (modalContent && document.getElementById('view-full-qp-modal')?.style.display === 'flex') {
            const freshHtml = document.getElementById('grading-mode-qp-display')?.innerHTML;
            if (freshHtml) modalContent.innerHTML = freshHtml;
        }

        showFeedbackMessage("Updated successfully!", "success");
    } catch (e) {
        showFeedbackMessage("Failed to save.", "error");
    } finally {
        toggleLoading(false);
    }
};

function recomputeOverallFeedbackFromEdits(report: AIFullAssessmentReport) {
    if (!report.questionWiseReport || report.questionWiseReport.length === 0) return;

    const areasForImprovement: string[] = [];
    const strengths: string[] = [];

    report.questionWiseReport.forEach(qr => {
        const max = qr.maxMarksForQuestion || 0;
        const got = qr.marksAwarded || 0;
        const pct = max > 0 ? (got / max) * 100 : 100;
        const topic = qr.topic || qr.questionNumber || 'General';
        const feedback = (qr.finalFeedback || '').toLowerCase();

        // Skip unattempted / not detected
        if (feedback.includes('not attempted') || feedback.includes('not detected') || feedback.includes('no text found')) return;

        if (pct < 50 && max > 0) {
            // Weak — goes to areasForImprovement
            const tag = `[${topic}] Score: ${got}/${max} — ${qr.finalFeedback || 'Needs improvement'}`;
            if (!areasForImprovement.some(a => a.includes(topic))) {
                areasForImprovement.push(tag);
            }
        } else if (pct >= 80 && max > 0) {
            // Strong
            if (!strengths.some(s => s.includes(topic))) {
                strengths.push(topic);
            }
        }
    });

    // Patch the report in-memory
    if (!report.overallFeedback) {
        report.overallFeedback = { summary: '', strengths: [], areasForImprovement: [] };
    }
    report.overallFeedback.areasForImprovement = areasForImprovement;
    report.overallFeedback.strengths = strengths;

    // Rebuild summary
    const pct = report.maximumMarks > 0 ? Math.round((report.overallScore / report.maximumMarks) * 100) : 0;
    report.overallFeedback.summary = `${report.studentName} scored ${report.overallScore}/${report.maximumMarks} (${pct}%). `
        + (areasForImprovement.length > 0
            ? `Areas needing attention: ${[...new Set(areasForImprovement.map(a => a.split(']')[0].replace('[', '')))].join(', ')}.`
            : 'Strong overall performance.');
}

