async function writeAuditLog(action: {
    actionType: 'marks_changed' | 'marker_added' | 'marker_removed' | 'marker_edited' | 'page_changed' | 'verified' | 'published';
    studentUid: string;
    studentName: string;
    studentRollNumber?: string;
    questionNumber?: string;
    oldValue?: string;
    newValue?: string;
}) {
    if (!teacherProfile) return;
    try {
        await fbFirestore.collection('auditLogs').add({
            teacherUid: teacherProfile.uid,
            teacherName: teacherProfile.name,
            schoolName: teacherProfile.schoolName,
            assessmentTitle: currentAssessmentForReportView?.assessmentTitle || '',
            className: currentAssessmentForReportView?.className || '',
            section: currentAssessmentForReportView?.section || '',
            subject: currentAssessmentForReportView?.subject || '',
            studentUid: action.studentUid,
            studentName: action.studentName,
            studentRollNumber: action.studentRollNumber || null,
            actionType: action.actionType,
            questionNumber: action.questionNumber || null,
            oldValue: action.oldValue || null,
            newValue: action.newValue || null,
            timestamp: firebase.firestore.FieldValue.serverTimestamp(),
        });
    } catch (e) {
        console.warn('[AuditLog] Failed to write:', e);
    }
}


async function saveUpdatedAssessmentReport(report: AIFullAssessmentReport) {
    // Determine context from either report view or grading view
    const assessmentContext = currentAssessmentForReportView || currentAssessmentToGrade;

    if (!teacherProfile || !assessmentContext || !report.submissionDocId) {
        console.error("Missing context to save report update", { teacherProfile, assessmentContext, report });
        showFeedbackMessage("Error: Could not save score. Missing session data.", "error");
        return;
    }
    
    try {
const ownerUid = (report as any)._ownerTeacherUid || (assessmentContext as any).createdByTeacherUid || teacherProfile.uid;
        console.log('[DEBUG saveScore]', { ownerUid, assessmentId: assessmentContext.assessmentId, submissionDocId: report.submissionDocId, teacherProfileUid: teacherProfile.uid });
const ownerAssessmentId = (report as any)._ownerAssessmentId || assessmentContext.assessmentId;
const isHomeworkReport = ownerAssessmentId.startsWith('hw_grade_');

const docRef = isHomeworkReport
    ? fbFirestore.collection('completedHomeworkSubmissions').doc(report.submissionDocId)
    : fbFirestore
        .collection('teachers').doc(ownerUid)
        .collection('assessmentHistory').doc(ownerAssessmentId)
        .collection('submissions').doc(report.submissionDocId);

        // We only need to update the fields that changed.
// Recompute weakness/strength data from current marks — zero cost, no AI call
        recomputeOverallFeedbackFromEdits(report);

// Slim fields go to main doc
await docRef.update(sanitizeObjectForFirestore({
    overallScore: report.overallScore,
    overallFeedback: report.overallFeedback,
}));

// questionWiseReport goes to subcollection (exam only; homework stores inline)
if (!isHomeworkReport) {
    await docRef.collection('detail').doc('report').set(
        sanitizeObjectForFirestore({
            questionWiseReport: report.questionWiseReport.map(qr => ({ ...qr }))
        }),
        { merge: true }
    );
} else {
    await docRef.update(sanitizeObjectForFirestore({
        'detailedReport.questionWiseReport': report.questionWiseReport.map(qr => ({ ...qr })),
        'detailedReport.overallScore': report.overallScore,
        'detailedReport.overallFeedback': report.overallFeedback,
        score: report.overallScore,
    }));
}
// SYNC FIX: Trigger UI refreshes for both Standard and Fullscreen modes
const reportIndex = assessmentReports.findIndex(r => r.studentUid === report.studentUid);
if (reportIndex !== -1) {
    // This refreshes markers and scores in whichever view is active
    renderReportPageUI(report, reportIndex);
}

// Refresh the background summary table
renderAssessmentReportView(); 

showFeedbackMessage(`${report.studentName}'s report updated successfully!`, "success");

    } catch (error) {
        console.error("Failed to save updated score to Firestore:", error);
        showFeedbackMessage("Failed to save the score to the database.", "error");
    }
}

window.handleUpdateScore = (reportIndex: number, questionIndex: number) => {
    const report = assessmentReports[reportIndex];
    if (!report) return;

    // 1. Find the input element and get its value
    const inputEl = document.getElementById(`score-input-${reportIndex}-${questionIndex}`) as HTMLInputElement;
    const maxScore = report.questionWiseReport[questionIndex].maxMarksForQuestion;
    let newValue = parseFloat(inputEl.value);

    // 2. Validate and clamp the new value
    if (isNaN(newValue) || newValue < 0) {
        newValue = 0;
    } else if (newValue > maxScore) {
        newValue = maxScore;
    }
    inputEl.value = newValue.toFixed(1); // Update input in case it was clamped/formatted

    // 3. Update the score in our local state
    report.questionWiseReport[questionIndex].marksAwarded = newValue;

    // 4. Recalculate the student's total score
    const newTotalScore = report.questionWiseReport.reduce((sum, qr) => sum + qr.marksAwarded, 0);
    report.overallScore = newTotalScore;

    // 5. Update the UI for the total score in the card header
    const totalScoreEl = document.getElementById(`total-score-${reportIndex}`);
    if (totalScoreEl) {
        const newPercentage = report.maximumMarks > 0 ? (newTotalScore / report.maximumMarks * 100) : 0;
        let scoreClass = 'score-low';
        if (newPercentage > 70) scoreClass = 'score-high';
        else if (newPercentage > 40) scoreClass = 'score-medium';
        
        totalScoreEl.innerHTML = `
            <strong>${newTotalScore.toFixed(1)} / ${report.maximumMarks}</strong>
            <span class="individual-score-percent ${scoreClass}">${newPercentage.toFixed(0)}%</span>
        `;
        // Add a temporary highlight to show the change
        totalScoreEl.classList.add('updated');
        setTimeout(() => totalScoreEl.classList.remove('updated'), 1500);
    }

    // 6. Re-render the class-wide analytics to reflect the change
    renderAssessmentReportSummary(); 
    renderStudentPerformanceScatterPlot();

    // 7. Save the changes to the database
    saveUpdatedAssessmentReport(report);
};

// PASTE THIS ENTIRE NEW FUNCTION
window.handleUpdateFeedback = (reportIndex: number, questionIndex: number) => {
    const report = assessmentReports[reportIndex];
    if (!report || !report.questionWiseReport) return;

    // 1. Find the textarea element and get its value
    const textareaEl = document.getElementById(`feedback-input-${reportIndex}-${questionIndex}`) as HTMLTextAreaElement;
    if (!textareaEl) return;
    const newFeedback = textareaEl.value;

    // 2. Update the feedback in our local state
    const questionReport = report.questionWiseReport[questionIndex];
    if (questionReport) {
        questionReport.finalFeedback = newFeedback;
    }
    
    // 3. Save the changes to the database
    // This reuses the existing save function, which is efficient.
    saveUpdatedAssessmentReport(report);
};

