window.handleViewStudentInsights = async (studentId: string, subject: string, studentName: string) => {
    studentInsightsModalTitleEl.textContent = `AI Insights for ${studentName} (${subject})`;
    studentInsightsModalContentEl.innerHTML = `<div class="spinner-container"><div class="spinner-small"></div> <p>Generating insights based on past homework...</p></div>`;
    toggleModal('student-insights-modal', true);

    try {
        const insights = await generateStudentSubjectInsights(studentId, subject);

        const summaryHtml = formatMathExpressions(insights.summary);
        const strengthsHtml = insights.strengths.map(s => `<li>${formatMathExpressions(s)}</li>`).join('') || '<li>No specific strengths identified.</li>';
        const weaknessesHtml = insights.weaknesses.map(w => `<li>${formatMathExpressions(w)}</li>`).join('') || '<li>No specific areas for improvement identified.</li>';
        
        const finalHtml = `
            <div class="insight-item"><h4>📝 Overall Summary</h4><p>${summaryHtml}</p></div>
            <div class="insight-item strengths"><h4>💪 Strengths</h4><ul>${strengthsHtml}</ul></div>
            <div class="insight-item weaknesses"><h4>📉 Areas for Improvement</h4><ul>${weaknessesHtml}</ul></div>
        `;

    studentInsightsModalContentEl.innerHTML = finalHtml;
await typesetMathInContainer(studentInsightsModalContentEl);

    } catch (error) {
        console.error("Error generating student insights:", error);
        const errorMessage = (error instanceof Error) ? error.message : "An unknown error occurred.";
        studentInsightsModalContentEl.innerHTML = `<p class="error-text">Could not generate insights. Error: ${errorMessage}</p>`;
    }
};


window.handleViewLightReport = async (studentUid: string, assessmentId: string) => {
    if (!teacherProfile) return;

    // Show loading modal — reuse any existing full-screen modal or create one
    const modalOverlay = document.createElement('div');
    modalOverlay.id = 'light-report-modal-overlay';
    modalOverlay.style.cssText = `
        position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.6);
        z-index:9999;display:flex;flex-direction:column;overflow:hidden;
    `;

    modalOverlay.innerHTML = `
        <div style="background:#f0f4f9;flex:1;overflow-y:auto;position:relative;">
            <div style="position:sticky;top:0;z-index:10;background:#1a2235;color:white;
                        display:flex;align-items:center;justify-content:space-between;
                        padding:12px 20px;box-shadow:0 2px 12px rgba(0,0,0,0.3);">
                <div style="display:flex;align-items:center;gap:12px;">
                    <span style="font-weight:800;font-size:1rem;">⚡ Light Diagnostic Report</span>
                    <span style="font-size:0.75rem;opacity:0.6;" id="light-report-student-label">Loading...</span>
                </div>
                <div style="display:flex;gap:10px;">
                    <button id="light-report-download-btn"
                        style="padding:8px 16px;background:#1d72e8;color:white;border:none;border-radius:8px;
                               font-weight:700;cursor:pointer;font-size:0.8rem;">
                        📥 Download PDF
                    </button>
                    <button id="light-report-delete-btn"
                        style="padding:8px 16px;background:rgba(239,68,68,0.15);color:#ef4444;border:1px solid rgba(239,68,68,0.3);border-radius:8px;
                               font-weight:700;cursor:pointer;font-size:0.8rem;">
                        🗑 Delete Report
                    </button>
                    <button id="light-report-close-btn"
                        style="padding:8px 16px;background:rgba(255,255,255,0.15);color:white;
                               border:1px solid rgba(255,255,255,0.3);border-radius:8px;cursor:pointer;font-size:0.8rem;">
                        ✕ Close
                    </button>
                    
                </div>
            </div>
            <div id="light-report-content" style="padding:0;">
                <div style="display:flex;align-items:center;justify-content:center;height:60vh;">
                    <div class="spinner-small"></div>
                    <p style="margin-left:12px;color:#555;">Loading diagnostic report...</p>
                </div>
            </div>
        </div>
    `;

    document.body.appendChild(modalOverlay);

    try {
        const doc = await fbFirestore
            .collection('teachers').doc(teacherProfile!.uid)
            .collection('assessmentHistory').doc(assessmentId)
            .collection('lightSubmissions').doc(studentUid)
            .get({ source: 'server' });

        if (!doc.exists) throw new Error('Report not found.');
        const data = doc.data() as any;

        // The backend stores the rendered HTML in data.diagnosticHtml
        const reportHtml = data.diagnosticHtml || '<p>Report HTML not available.</p>';
        const studentName = data.studentName || 'Student';

        const labelEl = document.getElementById('light-report-student-label');
        if (labelEl) labelEl.textContent = studentName;

        const contentEl = document.getElementById('light-report-content');
        if (contentEl) {
            // Inject the HTML into an iframe for CSS isolation
            const iframe = document.createElement('iframe');
            iframe.style.cssText = 'width:100%;border:none;min-height:100vh;';
            iframe.setAttribute('sandbox', 'allow-same-origin allow-scripts');
            contentEl.innerHTML = '';
            contentEl.appendChild(iframe);

            // Write report HTML into iframe
            iframe.onload = () => {
                // Make all text nodes contenteditable for inline editing
                try {
                    const iDoc = iframe.contentDocument!;
                    // Add contenteditable to all text-containing elements
                    iDoc.querySelectorAll('p, h1, h2, h3, h4, span, td, li, div.weakness-item, div.action-text').forEach(el => {
                        (el as HTMLElement).contentEditable = 'true';
                        (el as HTMLElement).style.outline = 'none';
                    });
                } catch(e) {}
            };

            const iDoc = iframe.contentDocument || iframe.contentWindow?.document;
            if (iDoc) {
                iDoc.open();
                iDoc.write(reportHtml);
                iDoc.close();
                // Auto-resize iframe to content
                iframe.style.height = Math.max(iDoc.body.scrollHeight, 800) + 'px';
            }
        }

        // PDF Download
        const dlBtn = document.getElementById('light-report-download-btn');
        if (dlBtn) {
            dlBtn.addEventListener('click', () => {
                const printHtml = reportHtml.replace('</body>', `
<script>
  window.onload = function() { setTimeout(function() { window.print(); }, 800); };
<\/script>
</body>`);
                const blob = new Blob([printHtml], { type: 'text/html' });
                const blobUrl = URL.createObjectURL(blob);
                const printWin = window.open(blobUrl, '_blank');
                if (!printWin) alert('Please allow popups for this site to download the PDF.');
                setTimeout(() => URL.revokeObjectURL(blobUrl), 60000);
            });
        }

        // Delete Report
  // Delete Report — no page reload; restore Light Grade button in-place
        const delBtn = document.getElementById('light-report-delete-btn');
        if (delBtn) {
            delBtn.addEventListener('click', async () => {
                if (!confirm(`Delete the light report for ${studentName}? This cannot be undone. You can re-run light grading after.`)) return;
                try {
                    await fbFirestore
                        .collection('teachers').doc(teacherProfile!.uid)
                        .collection('assessmentHistory').doc(assessmentId)
                        .collection('lightSubmissions').doc(studentUid)
                        .delete();
                    // Close modal without reloading
                    document.getElementById('light-report-modal-overlay')?.remove();
                    // Restore the Light Grade button in the student's action container
                    const actionContainer = document.getElementById(`grading-actions-${studentUid}`);
                    if (actionContainer) {
                        actionContainer.innerHTML = `
                            <button id="light-grade-btn-${studentUid}" class="button-secondary grading-action-btn grade-light-btn"
                                title="Weakness analysis only — fast & cheap">
                                ⚡ Light Grade
                            </button>`;
                        const newBtn = actionContainer.querySelector(`#light-grade-btn-${studentUid}`) as HTMLButtonElement;
                        if (newBtn) {
                            newBtn.addEventListener('click', (e) => {
                                e.stopPropagation();
                                handleLightGradeIndividualStudent(studentUid);
                            });
                        }
                    }
                } catch(e) {
                    alert('Failed to delete: ' + (e as Error).message);
                }
            });
        }
        // Close button — just remove modal, do NOT navigate
        const closeBtn = document.getElementById('light-report-close-btn');
        if (closeBtn) {
            closeBtn.addEventListener('click', () => {
                document.getElementById('light-report-modal-overlay')?.remove();
            });
        }

    } catch (error) {
        const contentEl = document.getElementById('light-report-content');
        if (contentEl) contentEl.innerHTML = `<p style="padding:40px;color:#cf1322;">❌ Could not load report: ${(error as Error).message}</p>`;
    }
};

