function addStudentAnswerField() {
    const studentId = `student-upload-${Date.now()}`;
    const newStudentUpload: StudentAssessmentUpload = { id: studentId, studentName: '', rollNumber: '', answerSheetFiles: [] };
    studentAssessmentUploads.push(newStudentUpload);

    const container = document.createElement('div');
    container.className = 'student-answer-upload-group';
    container.id = studentId;

    container.innerHTML = `
        <div class="student-info-inputs">
            <input type="text" class="student-name-input" placeholder="Student Name" required>
            <input type="text" class="student-roll-input" placeholder="Roll Number (Optional)">
        </div>
        <div class="answer-sheet-upload">
            <label for="file-${studentId}">Answer Sheet(s):</label>
            <input type="file" id="file-${studentId}" class="student-answer-file-input" multiple accept="image/*,application/pdf">
            <div class="file-preview-list"></div>
        </div>
        <button type="button" class="remove-student-btn">&times; Remove Student</button>
    `;

    container.querySelector('.remove-student-btn')?.addEventListener('click', () => {
        const index = studentAssessmentUploads.findIndex(s => s.id === studentId);
        if (index > -1) {
            studentAssessmentUploads.splice(index, 1);
            container.remove();
        }
    });

    const nameInput = container.querySelector('.student-name-input') as HTMLInputElement;
    nameInput.addEventListener('change', () => {
        const student = studentAssessmentUploads.find(s => s.id === studentId);
        if(student) student.studentName = nameInput.value;
    });

    const rollInput = container.querySelector('.student-roll-input') as HTMLInputElement;
    rollInput.addEventListener('change', () => {
        const student = studentAssessmentUploads.find(s => s.id === studentId);
        if(student) student.rollNumber = rollInput.value;
    });

    const fileInput = container.querySelector('.student-answer-file-input') as HTMLInputElement;
    fileInput.addEventListener('change', () => {
        const student = studentAssessmentUploads.find(s => s.id === studentId);
        const previewList = container.querySelector('.file-preview-list')!;
        if (student && fileInput.files) {
            student.answerSheetFiles = Array.from(fileInput.files);
            previewList.innerHTML = student.answerSheetFiles.map(f => `<span class="file-chip">${f.name}</span>`).join('');
        }
    });

    studentAnswersUploadContainerEl.appendChild(container);
}

// PASTE THIS ENTIRE NEW FUNCTION

/**
 * Renders the file previews for a specific student, including remove buttons.
 * This function also updates the upload button's text to improve user experience.
 * @param studentUid The unique ID of the student.
 * @param previewArea The HTML element where file chips should be rendered.
 * @param listItem The parent <li> element for the student's roster item.
 */
function renderStudentFilePreviews(studentUid: string, previewArea: HTMLElement, listItem: HTMLElement) {
const displayFiles = localStudentFiles.get(studentUid) || [];

previewArea.innerHTML = displayFiles.map((file, index) => `
    <span class="file-chip" 
          onclick="window.previewProcessedFile('${studentUid}', ${index})" 
          style="cursor:pointer;" 
          title="Click to verify AI-enhanced view">
        ${file.name}
        <button type="button" class="remove-file-btn" data-index="${index}" onclick="event.stopPropagation();">&times;</button>
    </span>
`).join('');

      const gradeBtn = document.getElementById(`grade-btn-${studentUid}`) as HTMLButtonElement;
    if (gradeBtn) {
        gradeBtn.disabled = displayFiles.length === 0;
    }

    const uploadLabel = listItem.querySelector('label.button-secondary') as HTMLLabelElement;

    if (displayFiles.length > 0) {
        listItem.classList.add('files-uploaded');
        if (uploadLabel) {
            uploadLabel.innerHTML = `<span class="icon">➕</span> Add More Files`;
        }
    } else {
        listItem.classList.remove('files-uploaded');
        if (uploadLabel) {
            uploadLabel.innerHTML = `<span class="icon">📄</span> Upload Answer Sheet`;
        }
    }

// Re-attach listeners for the delete buttons inside the chips
previewArea.querySelectorAll('.remove-file-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const indexToRemove = parseInt((e.target as HTMLButtonElement).dataset.index!, 10);
        
        // 1. Remove from local files (The Source of Truth for grading/previews)
        const localFiles = localStudentFiles.get(studentUid) || [];
        localFiles.splice(indexToRemove, 1);
        if (localFiles.length === 0) {
            localStudentFiles.delete(studentUid);
        } else {
            localStudentFiles.set(studentUid, localFiles);
        }

        // 2. Synchronize assessmentStudentFiles (storage paths) if they exist
        const storagePaths = assessmentStudentFiles.get(studentUid) || [];
        if (storagePaths.length > indexToRemove) {
            storagePaths.splice(indexToRemove, 1);
            if (storagePaths.length === 0) {
                assessmentStudentFiles.delete(studentUid);
            } else {
                assessmentStudentFiles.set(studentUid, storagePaths);
            }
        }

        // 3. Refresh the UI
        renderStudentFilePreviews(studentUid, previewArea, listItem);
    });
});
}


