// --- REPLACE the entire old 'runGradingPipelineForStudent' function with this ---
async function runGradingPipelineForStudent(
    student: RosterStudent,
    files: File[],
    structuredQuestions: AIQuestion[],
    strictness: string,
    onProgressUpdate: (step: string, status: string, data?: any) => void
): Promise<{ report: AIFullAssessmentReport, processedFiles: File[] }> { // <-- MODIFIED RETURN TYPE



// STEP 1: Process Images locally in PARALLEL (PDF to JPG, image compression)
onProgressUpdate('process-images', 'in-progress');

// Create an array of promises. Each promise represents one file being processed.
// This allows the browser to work on multiple images at the same time.
const processingPromises = files.map(file => {
    if (file.type === 'application/pdf') {
        return processPdfToImageFiles(file);
    } else if (file.type.startsWith('image/')) {
        return processImageFile(file);
    }
    return Promise.resolve(file); // Return non-image files as is.
});

// Promise.all waits for ALL the individual image processing tasks to complete.
const nestedFiles = await Promise.all(processingPromises);

// The final, crucial step: .flat() takes the results (which might be in groups, like
// pages from a PDF) and combines them into a single, ordered array.
// This array maintains the original upload order, ensuring the AI reads it sequentially.
const processedFiles: File[] = nestedFiles.flat();

    if (files.length > 0 && processedFiles.length === 0) {
        throw new Error("File processing failed. Could not extract pages from PDF.");
    }
    onProgressUpdate('process-images', 'done');

     onProgressUpdate('read-answers', 'in-progress', { currentPage: 0, totalPages: processedFiles.length }); 

// --- START: NEW RAG OCR FILTERING ---
const subjectForRag = currentAssessmentToGrade?.subject || "General";
const cachedRagRules = await ragService.fetchRulesForSubject(subjectForRag);

// 1. For OCR (Vision), we want ALL rules marked 'OCR' for this subject/global.
// We DO NOT use semantic search here because vision instructions rarely match assessment titles.
const ocrTargetRules = cachedRagRules.filter(rule => {
    const isOCR = rule.targetStep === 'OCR';
    const isGlobal = normalizeForComparison(rule.subject) === 'global';
    const isSubjectMatch = normalizeForComparison(rule.subject) === normalizeForComparison(subjectForRag);
    return isOCR && (isGlobal || isSubjectMatch);
});

const ocrRulesString = ocrTargetRules
    .map(r => `- VISION RULE: ${r.correctionRule}`)
    .join('\n');

// 2. IMMEDIATE LOGGING & INSPECTOR SYNC
const timeOCR = new Date().toLocaleTimeString();
if (ocrTargetRules.length > 0) {
    ragSystemLogs.push(`<span class="log-timestamp">[${timeOCR}]</span> 👁️ <strong>Step 2 (OCR Phase) Rules Injected into Vision Prompt:</strong><br><pre style="font-size:0.75rem; color:#f1c40f; background:#1e1e1e; padding:8px; border-radius:4px;">${ocrRulesString}</pre>`);
} else {
    ragSystemLogs.push(`<span class="log-timestamp">[${timeOCR}]</span> ℹ️ Step 2 (OCR Phase): No vision rules found for this subject.`);
}

// 3. Pass the rules to the OCR function (This line usually exists, ensure ocrRulesString is the last parameter)
activeRagRules = ocrTargetRules; // Update global state for Inspector
const pagesResult = await extractTextFromImages(processedFiles, 'Assessment Checker OCR', (p, t) => {
    onProgressUpdate('read-answers', 'in-progress', { currentPage: p, totalPages: t });
}, ocrRulesString);
const pages = pagesResult;
const uploadedCount = processedFiles.length;
const detectedCount = pages.length;

// CRITICAL VALIDATION: Ensure the AI actually "read" every image
if (detectedCount !== uploadedCount) {
    throw new Error(`STABILITY ALERT: AI skipped pages. Uploaded: ${uploadedCount}, Read: ${detectedCount}. Grading stopped to save credits. Please check your internet.`);
}

// CRITICAL VALIDATION: Ensure no page returned an OCR error
const erroredPage = pages.find(p => p.text.includes("[ERROR READING PAGE"));
if (erroredPage) {
    throw new Error(`OCR FAILURE: ${erroredPage.text}. Please check image quality and retry.`);
}

const fullOcrText = pagesResult.map(p => `[START_PAGE_${p.pageNum}]\n${p.rawText || p.text}\n[END_PAGE_${p.pageNum}]`).join('\n\n');

// 3. Store in Global State for Inspector
activeRagRules = cachedRagRules; 

// 4. Log Success
const time2 = new Date().toLocaleTimeString();
ragSystemLogs.push(`<span class="log-timestamp">[${time2}]</span> ✅ Successfully loaded <strong>${cachedRagRules.length}</strong> rules into browser memory.`);
ragSystemLogs.push(`<span class="log-timestamp">[${time2}]</span> ℹ️ Ready for vector similarity search.`);

console.log(`✅ RAG: Loaded ${cachedRagRules.length} rules into memory.`);
// ---------------------------

// STEP 3: Grade questions one-by-one from the extracted text to prevent timeouts.
onProgressUpdate('grade-questions', 'in-progress');

// Identify the file: index.tsx
// Locate function: runGradingPipelineForStudent
// Replace the 'questionDataForAI' mapping block with this:

const questionDataForAI = structuredQuestions.map((q, index) => {
    const questionNumber = q.questionNumber || (q.text.match(/^([Qq]uestion\s)?[\d\w\.\(\)]+/) || [`${index + 1}`])[0].trim();
    
    const explicitTypeTag = q.type ? ` [Type: ${q.type}]` : '';


    return {
        questionNumber: questionNumber,
        questionText: q.text + explicitTypeTag,
        questionType: q.type,
        topic: (q.topic && q.topic.length > 5) ? q.topic : (q.text.substring(0, 40) + "..."),
        modelAnswer: q.answer,// Use the sanitized answer
        maxMarks: q.marks || 5,
        checkingInstructions: (q.checkingInstructions || '') + 
    (q.questionNumber ? ` [Link to Q: ${q.questionNumber}]` : '') + 
    (q.checkingInstructions?.includes("OR") ? " [CONFLICT WARNING: This is a choice question. Check for duplicate numbers and grade only one!]" : ""),
    rubric: q.rubric || { keywords: [], step_marking: "Grade based on model answer." },
        ragContext: q.ragContext || '',
        options: q.options || [],
        type: q.type || 'Subjective'
    };
});


// Define complexity weights to balance token usage and accuracy
// Goal: 20 MCQs (1pt each) OR 5 Long Answers (3-7pts each)
const MAX_BATCH_WEIGHT = 18; 
const questionBatches: any[][] = [];
let currentBatch: any[] = [];
let currentWeight = 0;

for (const q of questionDataForAI) {
    let weight = 1; // Default for 1-mark questions (MCQs/VSA)
    
    // Assign weights based on marks to control batch density:
    // Marks >= 3: Weight 4 (Ensures exactly 5 questions per batch: 20 / 4 = 5)
    // Marks == 2: Weight 2 (Ensures 10 questions per batch: 20 / 2 = 10)
    // Marks < 2:  Weight 1 (Ensures 20 questions per batch: 20 / 1 = 20)
    
    if (q.maxMarks >= 5) weight = 2;
    else if (q.maxMarks >= 2) weight = 1;
    
    // Start a new batch if adding this question exceeds the weight limit
    if (currentWeight + weight > MAX_BATCH_WEIGHT && currentBatch.length > 0) {
        questionBatches.push(currentBatch);
        currentBatch = [];
        currentWeight = 0;
    }
    
    currentBatch.push(q);
    currentWeight += weight;
}

// Push the final remaining batch
if (currentBatch.length > 0) {
    questionBatches.push(currentBatch);
}
const subject = currentAssessmentToGrade?.subject || '';
let questionsGraded = 0;

const questionWiseReport: AIQuestionReport[] = [];
let batchesProcessed = 0;

const masterAnchors = pages.flatMap(p => p.anchors || []);

let questionsGradedSoFar = 0; // Tracks cumulative progress for UI

// map question numbers to their detected start pages
const questionStartPages = new Map<string, number>();
masterAnchors.forEach(a => {
    const cleanNum = normalizeForComparison(a.qNum);
    if (!questionStartPages.has(cleanNum)) {
        questionStartPages.set(cleanNum, a.pageIndex + 1); // 1-based
    }
});

// Identify the start page for every question in the paper's defined structure
const sortedQuestionNumbers = structuredQuestions.map(q => normalizeForComparison(q.questionNumber));

for (const batch of questionBatches) {
    batchesProcessed++;

// Find the absolute earliest page any question in this batch starts on
let batchStartPage = 1;
const batchQuestions = batch.map(q => normalizeForComparison(q.questionNumber));
const firstQStart = questionStartPages.get(batchQuestions[0]);
if (firstQStart) batchStartPage = firstQStart;

// Find the start of the question that follows this batch to determine the "cutoff"
let batchEndPage = pagesResult.length; 
const lastQInBatchNum = batchQuestions[batchQuestions.length - 1];
const lastQIndex = sortedQuestionNumbers.indexOf(lastQInBatchNum);

if (lastQIndex !== -1 && lastQIndex < sortedQuestionNumbers.length - 1) {
    const nextQuestionNum = sortedQuestionNumbers[lastQIndex + 1];
    const nextStartPage = questionStartPages.get(nextQuestionNum);
    // FIX: Ensure we include the page where the NEXT question starts 
    // so the AI sees the [Q:NEXT] tag and knows exactly where to stop grading.
    if (nextStartPage) {
        batchEndPage = nextStartPage; 
    }
}

// Extract only the pages in this window
const batchOcrText = pagesResult
    .filter(p => p.pageNum >= batchStartPage && p.pageNum <= batchEndPage)
    .map(p => `[PAGE ${p.pageNum}]\n${p.rawText || p.text}`)
    .join('\n\n');

console.log(`Batch Slicing: Q${batchQuestions[0]} to Q${batchQuestions[batchQuestions.length-1]} | Range: Pg ${batchStartPage}-${batchEndPage}`);

    
// Update UI using cumulative count
onProgressUpdate('grade-questions', 'in-progress', { 
    currentQuestion: questionsGradedSoFar + 1, 
    totalQuestions: questionDataForAI.length 
});



const uniqueRulesMap = new Map<string, any>(); 

// 1. Only auto-include GLOBAL rules to keep base tokens low. 
// Subject-specific rules will be pulled in dynamically via semantic search below.
cachedRagRules.forEach(rule => {
    const isGradingStep = rule.targetStep === 'Grading' || !rule.targetStep;
    const isGlobal = normalizeForComparison(rule.subject) === 'global';
    if (isGradingStep && isGlobal) {
        uniqueRulesMap.set(rule.correctionRule, { rule, score: 1.0 });
    }
});

// 2. SEARCH ONCE PER UNIQUE TEXT: Deduplicate question texts in this batch 
// to avoid redundant embedding API calls and duplicate rule processing.
const uniqueTextsInBatch = [...new Set(batch.map(q => q.questionText))];

for (const text of uniqueTextsInBatch) {
    const matches = await ragService.findMatchingRules(text, cachedRagRules);
    matches.forEach(m => {
        // Only add if it's a grading rule and not already in our map
        if (m.rule.targetStep === 'Grading' || !m.rule.targetStep) {
            const key = m.rule.correctionRule; 
            if (!uniqueRulesMap.has(key)) {
                uniqueRulesMap.set(key, m);
            }
        }
    });
}

// 3. HARD CAP: If the map is too large, keep only top 12 rules by score.
// This prevents "Token Overflow" when a teacher has hundreds of rules.
if (uniqueRulesMap.size > 12) {
    const sortedRules = Array.from(uniqueRulesMap.values())
        .sort((a, b) => (b.score || 0) - (a.score || 0))
        .slice(0, 12);
    uniqueRulesMap.clear();
    sortedRules.forEach(m => uniqueRulesMap.set(m.rule.correctionRule, m));
}
    let combinedRagInstructions = "";
if (uniqueRulesMap.size > 0) {
    const timeGrading = new Date().toLocaleTimeString();
    const batchRulesText = Array.from(uniqueRulesMap.values())
        .map(m => `- RULE: ${m.rule.correctionRule}`)
        .join('\n');

    // Create the detailed log entry
    ragSystemLogs.push(`<span class="log-timestamp">[${timeGrading}]</span> 🎯 <strong>Step 3 (Grading Phase) Rules Injected into Batch ${batchesProcessed}:</strong><br><pre style="font-size:0.75rem; color:#3498db; background:#1e1e1e; padding:8px; border-radius:4px;">${batchRulesText}</pre>`);
combinedRagInstructions = `\n**CORRECTION RULES:**\n` +
    Array.from(uniqueRulesMap.values()).map((m, i) => {
        // Use a much more compact format
        return `R${i + 1}: ${m.rule.correctionRule}`;
    }).join('\n');
        ragSystemLogs.push(`<span class="log-timestamp">[${new Date().toLocaleTimeString()}]</span> ⚡ <strong>Batch ${batchesProcessed} RAG Context (${uniqueRulesMap.size} rules)</strong>`);
    }

    // --- CALL GRADER ---
   try {
    activeRagRules = Array.from(uniqueRulesMap.values()).map(m => m.rule); // Set state to Grading rules
        const batchResult = await gradeQuestionBatchFromOcrText(batchOcrText, batch, strictness, subject, combinedRagInstructions);
        questionWiseReport.push(...batchResult);
    } catch (error) {
        console.error(`Batch ${batchesProcessed} failed:`, error);
        // Fallback for this specific batch
        const fallback = batch.map(q => ({
            questionNumber: q.questionNumber,
            marksAwarded: 0,
            maxMarksForQuestion: q.maxMarks,
            finalFeedback: `AI grading failed for this batch: ${(error as Error).message}`,
            improvementArea: ["Manual Review Required"],
            stepWiseEvaluation: [],
            topic: q.topic,
            questionText: q.questionText,
        }));
        questionWiseReport.push(...fallback);
    }

    // Small breathing room for the API
    await new Promise(resolve => setTimeout(resolve, 600)); 
    questionsGradedSoFar += batch.length;
}



let overallFeedback = { 
    summary: "", 
    strengths: [], 
    areasForImprovement: [] 
};
let studentKeywords: string[] = [];

if (featureFlags.teacherAssessmentGrading_improvementAreas !== false) {
    onProgressUpdate('generate-summary', 'in-progress');
    const result = await generateReportSummaryAndKeywords(student.name, questionWiseReport);
    overallFeedback = result.overallFeedback;
    studentKeywords = result.studentKeywords;
    onProgressUpdate('generate-summary', 'done');
}

// STEP 5: Calculate final scores
const overallScore = questionWiseReport.reduce((sum, qr) => sum + qr.marksAwarded, 0);
const maximumMarks = (currentAssessmentToGrade.totalMarks && currentAssessmentToGrade.totalMarks > 0)
    ? currentAssessmentToGrade.totalMarks
    : 0;


// --- START: Manual Code Insertion (Place inside runGradingPipelineForStudent) ---

// 1. Sort all found anchors by page and vertical position (Existing line)
const sortedAnchors = [...masterAnchors].sort((a, b) => {
    if (a.pageIndex !== b.pageIndex) return a.pageIndex - b.pageIndex;
    return a.y - b.y;
});

// --- NEW "ANCHOR TRUTH" LOGIC START ---
// This forces the page number to match reality based on where the OCR *actually* found the question number.
questionWiseReport.forEach((qr) => {
    if (!qr.questionNumber) return;

    // Helper to clean number (e.g. "Q.19" -> "19")
    const cleanTarget = normalizeForComparison(qr.questionNumber);

    // Look for the specific anchor tag detected during the visual scan (Step 2)
 // Use findLast to get the coordinate at the end of the answer rather than the start of the question label
const visualAnchor = masterAnchors.find(a => normalizeForComparison(a.qNum) === cleanTarget);
    const originalQ = structuredQuestions.find(sq => normalizeForComparison(sq.questionNumber) === cleanTarget);

if (visualAnchor) {
    qr.answerPageIndex = visualAnchor.pageIndex;
    (qr as any)._usesVisualAnchor = true; 
    
    qr.stepWiseEvaluation.forEach(step => {
        // step.pageIndex is 1-based from AI (raw value, not yet converted).
        // visualAnchor.pageIndex is 0-based (loop index i).
        // Only overwrite if the AI gave an invalid value.
        const pageIdx = step.pageIndex;
        if (typeof pageIdx !== 'number' || isNaN(pageIdx) || pageIdx < 1) {
            step.pageIndex = visualAnchor.pageIndex + 1; // store 1-based
        }
        // If valid (>=1), trust the AI's 1-based value as-is.
        
        const hasValidAiCoords = step.stepPoint && Array.isArray(step.stepPoint) && step.stepPoint[0] > 0;
        if (!hasValidAiCoords && !step.stepPoint) {
            // ONLY apply anchor fallback if the AI provided NO coordinates at all
            step.stepPoint = [visualAnchor.y, 920];
        }
    });
}
});
// --- NEW "ANCHOR TRUTH" LOGIC END ---

questionWiseReport.forEach((qr) => {
    // 1. Robust check for unattempted questions
    const feedbackLower = String(qr.finalFeedback || "").toLowerCase();
const isNotDetected = feedbackLower.includes("question not detected") ||
        feedbackLower === "not attempted" ||
        feedbackLower.includes("not attempted") ||
        feedbackLower.includes("no text found") ||
        feedbackLower.includes("alternative choice") ||
        feedbackLower.includes("answer not found in ocr") ||
        feedbackLower.includes("answer not mapped");

    if (isNotDetected) {
        qr.stepWiseEvaluation = []; // Strip all markers
        qr.marksAwarded = 0;
        qr.finalFeedback = "Question not detected";
        return; 
    }

    // ── MISSING STEP POSITIONING ─────────────────────────────────────────────
    // Steps where student wrote nothing get placed as a horizontal row at the
    // bottom of the written answer zone. They render as ⚠️ markers.
    // Steps for fully-unanswered questions (handled above) are already stripped.
    const isMissingStep = (step: AIStepEvaluation) => {
        const c = (step.comment || '').toLowerCase();
        return step.marks === 0 && (
            c.includes('missing') ||
            c.includes('no answer provided') ||
            c.includes('not provided') ||
            c.includes('not written') ||
            c.includes('not mentioned')
        );
    };

    const missingSteps = qr.stepWiseEvaluation.filter(isMissingStep);
    const writtenSteps = qr.stepWiseEvaluation.filter(s => !isMissingStep(s));

    if (missingSteps.length > 0) {
        // Place missing markers stacked vertically below the last written step on the page
        const anchorPage = (qr as any)._usesVisualAnchor
            ? qr.answerPageIndex + 1
            : (writtenSteps[0]?.pageIndex || 1);
        const writtenOnPage = writtenSteps.filter(s => s.pageIndex === anchorPage);
        const maxWrittenY = writtenOnPage.length > 0
            ? Math.max(...writtenOnPage.map(s => s.stepPoint?.[0] || 0))
            : 0;
        // Start just below last written step; stack each missing marker 60 units below previous
        const MISSING_Y_START = maxWrittenY > 0 ? Math.min(maxWrittenY + 60, 880) : 780;
        const MISSING_X = 600; // center-right column
        const MISSING_Y_STEP = 60;
        missingSteps.forEach((step, i) => {
            step.pageIndex = anchorPage;
            step.stepPoint = [MISSING_Y_START + i * MISSING_Y_STEP, MISSING_X];
            (step as any).isMissing = true;
        });
        qr.stepWiseEvaluation = [...writtenSteps, ...missingSteps];
    }
    // ── END MISSING STEP POSITIONING ─────────────────────────────────────────

qr.stepWiseEvaluation.forEach((step) => {
        // Consistent conversion: AI returns 1-based string, we store 0-based.
        // We only subtract if the value is > 0 and hasn't been processed yet.

if (!step.stepPoint || !Array.isArray(step.stepPoint) || step.stepPoint.length !== 2) {
    // Only default if data is actually null/undefined. 
    // If data exists but is malformed, we try to cast it to numbers first.
    if (step.stepPoint && step.stepPoint.length >= 2) {
        step.stepPoint = [Number(step.stepPoint[0]), Number(step.stepPoint[1])];
    } else {
        // Use 500 (middle) so it's obvious data was missing, rather than stacking at top.
        step.stepPoint = [500, 920]; 
    }
}
    });

    // Sync the main report page index to the first step's page
   if (!(qr as any)._usesVisualAnchor) {
// When no visual anchor AND no step markers, fall back to last page (visible & editable).
    // answerPageIndex is 0-based; stepWiseEvaluation[0].pageIndex is 1-based.
    if (qr.stepWiseEvaluation.length > 0) {
const rawPI = qr.stepWiseEvaluation[0].pageIndex;
const safePI = (typeof rawPI === 'number' && rawPI >= 1) ? rawPI : 1;
qr.answerPageIndex = Math.max(0, safePI - 1); // 1-based → 0-based, never negative
//         } else {
        // No steps found → place on last page so it's visible and editable
        const lastPg = (pagesResult.length || 1) - 1;
        qr.answerPageIndex = lastPg;
    }
}
});


// 1. Define the full text string as a local variable FIRST
const fullOcrTextString = pages.map(p => `[START_PAGE_${p.pageNum}]\n${p.text}\n[END_PAGE_${p.pageNum}]`).join('\n');

// 2. Assemble the complete report object
const finalReport: AIFullAssessmentReport = {
    studentName: student.name,
    studentUid: student.uid,
    rollNumber: (student as any).rollNumber || '',
    overallScore: overallScore,
    maximumMarks: maximumMarks,
    overallFeedback: overallFeedback,
    studentKeywords: studentKeywords,
    fullOcrText: fullOcrTextString, // Use the variable here
    questionWiseReport: questionWiseReport.map(qr => {
        // Now fullOcrTextString is safely accessible in this scope
        const snippet = getOcrTextForPage(fullOcrTextString, (qr.answerPageIndex || 0) + 1);
        return {
            ...qr,
            studentOcrAnswer: snippet.substring(0, 3000)

        };
    }),
};
    

    
    
    // NEW: Return both the report and the files to be uploaded.
    return { report: finalReport, processedFiles: processedFiles };
}


window.forceLoadRosterStream = async (rosterId: string) => {
    // This function is triggered when the user manually selects a stream for an old assessment
    toggleLoading(true, "Switching stream...");
    try {
        const roster = await getClassRoster(rosterId);
        if (roster && currentAssessmentToGrade) {
            // 1. Update the current assessment object in memory so it remembers the choice
if (currentAssessmentToGrade) {
    currentAssessmentToGrade = { ...currentAssessmentToGrade, stream: roster.stream };
}
            currentGradingRosterId = roster.id; // store actual roster doc ID
            // 2. Reload the roster logic with the specific stream now set
            loadRosterForAssessmentChecker(currentAssessmentToGrade);
        }
    } catch (e) {
        console.error("Error switching stream", e);
        showFeedbackMessage("Failed to switch stream.", "error");
    } finally {
        toggleLoading(false);
    }
};
// PASTE THESE THREE NEW FUNCTIONS

async function loadRosterForAssessmentChecker(assessmentDetails: { className: string, section: string, subject: string, stream?: string }) {
    if (!teacherProfile) return;
    const { className, section, subject } = assessmentDetails;
    const rosterContainer = document.getElementById('assessment-student-roster-container') as HTMLDivElement;

    currentAssessmentRoster = [];
    assessmentStudentFiles.clear();
    studentPreUploadedData.clear();
    (assessmentStudentFiles as any).__preloadedUrls = {}; 
    rosterContainer.innerHTML = `<div class="spinner-container"><div class="spinner-small"></div> <p>Loading roster...</p></div>`;
    
    try {
        const allRostersSnap = await fbFirestore.collection('classRosters').where('teacherUid', '==', teacherProfile.uid).get();
        const allRosters = allRostersSnap.docs.map(doc => ({ ...doc.data(), id: doc.id } as ClassRoster));

        // Find matches for the class/section/subject
        const candidateRosters = allRosters.filter(r => 
            normalizeForComparison(r.className) === normalizeForComparison(className) &&
            normalizeForComparison(r.section) === normalizeForComparison(section) &&
            normalizeForComparison(r.subject) === normalizeForComparison(subject)
        );

        let roster: ClassRoster | undefined;

        // 1. Precise Match by Stream
        if (assessmentDetails.stream) {
            const targetStream = normalizeForComparison(assessmentDetails.stream);
            roster = candidateRosters.find(r => normalizeForComparison(r.stream) === targetStream);
        }

        // 2. Fallback: If only one exists, use it
        if (!roster && candidateRosters.length === 1) {
            roster = candidateRosters[0];
            if (currentAssessmentToGrade) {
    currentAssessmentToGrade = { ...currentAssessmentToGrade, stream: roster.stream };
}
        }

        // 3. Ambiguity: Show selection buttons
        if (!roster && candidateRosters.length > 1) {
            rosterContainer.innerHTML = `
                <div class="info-box warning">
                    <h4>⚠️ Select Class Stream</h4>
                    <p>Multiple streams found. Select one to load students:</p>
                    <div style="display:flex; gap:10px; flex-wrap:wrap; margin-top:10px;">
                        ${candidateRosters.map(r => `
                            <button type="button" class="button-primary small-button" onclick="window.forceLoadRosterStream('${r.id}')">
                                ${r.stream || 'General'} (${r.students.length} Students)
                            </button>
                        `).join('')}
                    </div>
                </div>`;
            return;
        }

        if (roster && roster.students.length > 0) {
currentAssessmentRoster = roster.students.sort((a, b) => a.name.localeCompare(b.name));
            currentGradingRosterId = roster.id; // ← store actual Firestore doc ID for credit deduction
            // Load any pre-uploaded files from Firestore so refreshing doesn't lose upload state
            if (currentAssessmentToGrade?.assessmentId) {
                studentPreUploadedData.clear();
await loadPreUploadedStudentData(currentAssessmentToGrade.assessmentId);
renderRosterForAssessmentChecker(currentAssessmentRoster);
            } else {
                renderRosterForAssessmentChecker(currentAssessmentRoster);
            }
            // AUTO-LOAD: If grading homework, pre-attach submitted answer sheets
            if ((window as any)._isGradingHomework && (window as any)._homeworkSubmissionUrls) {
                autoAttachHomeworkSubmissions(currentAssessmentRoster);
            }
        } else {
            rosterContainer.innerHTML = `<p class="info-box warning">No students found in the roster for this stream.</p>`;
        }
    } catch (error) {
        console.error("Error loading roster:", error);
        rosterContainer.innerHTML = `<p class="info-box error">Could not load roster.</p>`;
    }
}

function handleMasterStrictnessChange() {
    const masterStrictnessSelectEl = document.getElementById('master-strictness-select') as HTMLSelectElement;
    const masterValue = masterStrictnessSelectEl.value as 'Moderate' | 'Lenient' | 'Strict';
    if (!masterValue || !currentAssessmentRoster) return;

    // Loop through every student currently in the roster for this assessment
    currentAssessmentRoster.forEach(student => {
        // 1. Update our internal state map with the new value
        assessmentStudentStrictness.set(student.uid, masterValue);

        // 2. Find the individual dropdown for this student in the UI
        const studentSelectEl = document.getElementById(`strictness-select-${student.uid}`) as HTMLSelectElement;
        if (studentSelectEl) {
            // 3. Set its value to match the master control
            studentSelectEl.value = masterValue;
        }
    });
}

window.handleGradeAllStudents = function() {
    if (!currentAssessmentToGrade) {
        showFeedbackMessage("No assessment loaded.", "error");
        return;
    }

    // Collect only students who have files pre-uploaded and not already graded/in-queue
    const eligibleUids: string[] = [];
    if (currentAssessmentRoster) {
        currentAssessmentRoster.forEach(student => {
            const isDone = assessmentReports.some(r => r.studentUid === student.uid);
            const inQueue = gradingQueue.includes(student.uid);
            const hasFiles = studentPreUploadedData.has(student.uid);
            if (!isDone && !inQueue && hasFiles) {
                eligibleUids.push(student.uid);
            }
        });
    }

    if (eligibleUids.length === 0) {
        showFeedbackMessage("No students ready to grade. Upload files first.", "info");
        return;
    }

    // Grade first one immediately, rest go into queue — sequential, full resources per student
    handleGradeIndividualStudent(eligibleUids[0]);
    for (let i = 1; i < eligibleUids.length; i++) {
        if (!gradingQueue.includes(eligibleUids[i])) {
            gradingQueue.push(eligibleUids[i]);
        }
    }

    updateGradingPIP();
    showFeedbackMessage(`${eligibleUids.length} student(s) queued. Grading one at a time.`, "success");
};


