/**
 * When teacher is grading a homework, auto-fetch student submitted answer URLs,
 * convert to File objects, and enable Grade button.
 */
async function autoAttachHomeworkSubmissions(students: RosterStudent[]) {
    const submissionMap: Record<string, any> = (window as any)._homeworkSubmissionUrls || {};
    const rosterContainer = document.getElementById('assessment-student-roster-container');
    if (!rosterContainer) return;

    for (const student of students) {
        const subData = submissionMap[student.uid] || submissionMap[student.email];
        if (!subData || !subData.urls?.length) continue;

        const actionContainer = rosterContainer.querySelector(`#grading-actions-${student.uid}`) as HTMLElement;
        const previewArea = rosterContainer.querySelector(`#preview-for-${student.uid}`) as HTMLElement;
        if (!actionContainer) continue;

        actionContainer.innerHTML = `<span class="status pending">⏳ Loading...</span>`;

        try {
            // Store URLs directly as a special "url-reference" file to bypass CORS fetch issues.
            // handleGradeIndividualStudent will detect these and skip re-upload.
            const urlRefFiles: File[] = subData.urls.map((url: string, i: number) => {
                const blob = new Blob([url], { type: 'text/plain' });
                const f = new File([blob], `_url_ref_page_${i + 1}.txt`, { type: 'text/plain' });
                (f as any)._downloadUrl = url; // attach the real URL
                return f;
            });

            localStudentFiles.set(student.uid, urlRefFiles);
            // Also pre-populate assessmentStudentFiles with the resolved paths/URLs
            // so the grading pipeline can skip upload
            (assessmentStudentFiles as any).__preloadedUrls = (assessmentStudentFiles as any).__preloadedUrls || {};
            (assessmentStudentFiles as any).__preloadedUrls[student.uid] = subData.urls;

           
if (previewArea) {
    const studentUidForPreview = student.uid;
    const urlsForPreview = subData.urls;
    previewArea.innerHTML = `
        <div style="display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin-top:6px;">
            ${urlsForPreview.map((url: string, i: number) => `
                <button
                    onclick="window._openHomeworkImageViewer('${studentUidForPreview}', ${i})"
                    style="display:inline-flex;align-items:center;gap:4px;background:#f0f4ff;border:1px solid #c7d4f7;border-radius:20px;padding:3px 10px;font-size:0.72rem;font-weight:600;color:#4361ee;cursor:pointer;transition:all 0.15s;"
                    onmouseover="this.style.background='#4361ee';this.style.color='white'"
                    onmouseout="this.style.background='#f0f4ff';this.style.color='#4361ee'"
                >
                    <span style="font-size:0.8rem;">🖼️</span> ${i + 1}
                </button>
            `).join('')}
            <span style="font-size:0.7rem;color:#aaa;margin-left:2px;">${urlsForPreview.length} page${urlsForPreview.length > 1 ? 's' : ''}</span>
        </div>`;

    // Store URLs on window for the viewer
// Store storage PATHS (not URLs) so viewer can get fresh download URLs on demand
(window as any)._homeworkPreviewUrls = (window as any)._homeworkPreviewUrls || {};
(window as any)._homeworkPreviewUrls[studentUidForPreview] = urlsForPreview.map((url: string) => {
    try {
        const pathMatch = new URL(url).pathname.match(/\/o\/([^?]+)/);
        return pathMatch ? decodeURIComponent(pathMatch[1]) : url; // store path, fallback to URL
    } catch { return url; }
});
}

            const isLocked = featureFlags.teacherAssessmentGrading === false;
            const lockClass = isLocked ? 'frozen-feature' : '';
            const lockIcon = isLocked ? '<span class="lock-icon-overlay">🔒</span>' : '';
            actionContainer.innerHTML = `<button id="grade-btn-${student.uid}" class="button-primary grading-action-btn ${lockClass}">Grade${lockIcon}</button>`;
            const btn = actionContainer.querySelector('button');
            btn?.addEventListener('click', (e) => { e.preventDefault(); handleGradeIndividualStudent(student.uid); });
        } catch (err) {
            console.error(`[HomeworkGrade] Failed for ${student.name}:`, err);
            actionContainer.innerHTML = `<span style="color:red;font-size:0.8rem;">⚠️ Load failed. Upload manually.</span>`;
        }
    }
}

// ── updateStudentRowWithReport ────────────────────────────────────────────────
// Called after polling confirms grading is complete.
// Stores the report in assessmentReports array and swaps the row's Grade button
// to a ✅ View Report button, also enabling the class-level "View Full Report" footer.
function updateStudentRowWithReport(studentUid: string, report: AIFullAssessmentReport) {
    // 1. Store report in the assessmentReports array (upsert by studentUid)
    const existingIdx = assessmentReports.findIndex(r => r.studentUid === studentUid);
    if (existingIdx !== -1) {
        assessmentReports[existingIdx] = report;
    } else {
        assessmentReports.push(report);
    }

    // 2. Swap the action button in the roster row
    const actionContainer = document.getElementById(`grading-actions-${studentUid}`);
    if (actionContainer) {
        actionContainer.innerHTML = `<button id="view-report-btn-${studentUid}" type="button"
            class="button-primary accent-positive-btn grading-action-btn"
            onclick="window.handleViewSingleStudentReport('${studentUid}')">✅ View Report</button>`;
    }

// 3. Enable the "View Full Class Report" footer button if present
    const fullReportBtn = document.getElementById('view-full-class-report-btn') as HTMLButtonElement | null;
    if (fullReportBtn) {
        fullReportBtn.disabled = false;
        fullReportBtn.classList.remove('disabled');
    }
    // 4. Show the footer so the button is actually visible
    if (assessmentCheckerFooterEl) assessmentCheckerFooterEl.style.display = 'flex';

    console.log(`[Grading] Row updated for ${studentUid} — report stored, View Report button shown.`);
}

async function processGradingQueue() {
    updateGradingPIP();
    if (isGradingBusy || gradingQueue.length === 0) return;

    // CLAIM LOCK IMMEDIATELY — before any await — prevents race where a manual
    // click during checkEnvironmentHealth() slips past the busy check.
    isGradingBusy = true;
    updateGradingPIP();

    // 1. Connection Health Check
    const health = await checkEnvironmentHealth();
    if (!health.healthy) {
        console.warn("Grading Queue Paused: Poor environment health.");
        const pip = document.getElementById('grading-pip-widget');
        if (pip) {
            pip.classList.add('network-paused');
            const label = pip.querySelector('.pip-status-label');
            if (label) label.textContent = `Paused: ${health.reason}`;
        }
        // Release lock and retry in 5 seconds
        isGradingBusy = false;
        updateGradingPIP();
        setTimeout(processGradingQueue, 5000);
        return;
    }

    const nextStudentUid = gradingQueue.shift();
    if (nextStudentUid) {
        // 2. Mandatory Memory/Network Buffer Clearance (8 second delay)
        await new Promise(r => setTimeout(r, 8000));
        
        await handleGradeIndividualStudent(nextStudentUid, true);
    } else {
        // Queue emptied between check and shift — release lock
        isGradingBusy = false;
        updateGradingPIP();
    }
}




