async function handleLightGradeIndividualStudent(studentUid: string) {
    const actionContainer = document.getElementById(`grading-actions-${studentUid}`) as HTMLDivElement;
    if (!actionContainer) return;

    if (isGradingBusy) {
        showFeedbackMessage("Please wait for current grading to finish.", "info");
        return;
    }

    const student = currentAssessmentRoster.find(s => s.uid === studentUid);
    if (!student || !currentAssessmentToGrade) return;

    const capturedAssessment = currentAssessmentToGrade;
    (capturedAssessment as any).answerLanguage = (document.getElementById('master-language-select') as HTMLSelectElement)?.value || '';

    isGradingBusy = true;
    currentGradingStudentName = student.name;
    updateGradingPIP();

    actionContainer.innerHTML = `
    <div class="grading-progress-container">
        <div class="progress-bar-minimal"><div id="lbar-${studentUid}" class="progress-fill" style="background:linear-gradient(90deg,#667eea,#764ba2);"></div></div>
        <ul class="progress-steps-list-v2">
            <li id="lstep-0-${studentUid}" class="step-item-v2">
                <span class="step-icon-dot"></span> <span>Uploading Sheets...</span> <span class="step-status-tag">PENDING</span>
            </li>
            <li id="lstep-1-${studentUid}" class="step-item-v2">
                <span class="step-icon-dot"></span> <span>Reading Handwriting (OCR)...</span> <span class="step-status-tag">PENDING</span>
            </li>
            <li id="lstep-2-${studentUid}" class="step-item-v2">
                <span class="step-icon-dot"></span> <span>Mapping Weaknesses...</span> <span class="step-status-tag">PENDING</span>
            </li>
        </ul>
    </div>`;

    try {
        // ── Step 0: Upload files (reuse exact same logic as full grader) ──
        const step0El = document.getElementById(`lstep-0-${studentUid}`);
        const barEl = document.getElementById(`lbar-${studentUid}`);
        if (step0El) { step0El.className = "step-item-v2 in-progress"; (step0El.querySelector('.step-status-tag') as HTMLElement).textContent = "UPLOADING..."; }

        const rawFiles = localStudentFiles.get(studentUid) || [];
        const preUploaded = studentPreUploadedData.get(studentUid);

        let answerSheetImageUrls: string[];
        let filePaths: string[] = [];
        let expandedFiles: File[] = [];

        if (preUploaded && preUploaded.urls.length > 0) {
            answerSheetImageUrls = preUploaded.urls;
            filePaths = preUploaded.paths;
            assessmentStudentFiles.set(studentUid, filePaths);
            if (step0El) { step0El.className = "step-item-v2 done"; (step0El.querySelector('.step-status-tag') as HTMLElement).textContent = "ALREADY UPLOADED ✅"; if (barEl) barEl.style.width = "20%"; }
        } else {
            const expandedFilesPromises = rawFiles.map(async (file) => {
                if (file.type === 'application/pdf') return await processPdfToImageFiles(file);
                return [file];
            });
            const nested = await Promise.all(expandedFilesPromises);
            expandedFiles = nested.flat();

            const uploadPromises = expandedFiles.map((file) =>
                uploadToTempStorage(file, studentUid, file.name.includes('_page_'), capturedAssessment.assessmentId)
            );
            filePaths = await Promise.all(uploadPromises);
            const storagePromises = filePaths.map(path => fbStorage.ref(path).getDownloadURL());
            answerSheetImageUrls = await Promise.all(storagePromises);

            if (step0El) { step0El.className = "step-item-v2 done"; (step0El.querySelector('.step-status-tag') as HTMLElement).textContent = "DONE"; if (barEl) barEl.style.width = "20%"; }
            assessmentStudentFiles.set(studentUid, filePaths);
        }

        if (step0El) step0El.className = "step-item-v2 done";

        // ── Step 1+2: Submit to lightGradingQueue ──
        const step1El = document.getElementById(`lstep-1-${studentUid}`);
        if (step1El) { step1El.className = "step-item-v2 in-progress"; (step1El.querySelector('.step-status-tag') as HTMLElement).textContent = "PROCESSING..."; if (barEl) barEl.style.width = "40%"; }

        const lightTicket = {
   teacherUid: capturedAssessment.createdByTeacherUid || teacherProfile!.uid,
            studentUid,
            studentName: student.name,
            assessmentId: capturedAssessment.assessmentId,
            assessmentTitle: capturedAssessment.assessmentTitle || '',
            subject: capturedAssessment.subject,
            className: capturedAssessment.className || '',
            board: (capturedAssessment as any).board || 'CBSE',
            checkingStrictness: capturedAssessment.checkingStrictness || 'Moderate',
            totalMarks: capturedAssessment.totalMarks,
            answerSheetImageUrls,
            filePaths: filePaths || [],
            questions: capturedAssessment.questions.map(q => ({
                questionNumber: q.questionNumber,
                text: q.text,
                answer: q.answer,
                marks: q.marks,
                type: q.type,
                topic: (q as any).topic || '',
                topicAnchors: Array.isArray(q.topicAnchors) ? [...q.topicAnchors] : [],
                options: (q as any).options || null,
                rubric: (q as any).rubric || null,
                checkingInstructions: (q as any).checkingInstructions || '',
            })),
            status: 'PENDING',
            createdAt: window.firebase.firestore.FieldValue.serverTimestamp()
        };

        const ticketRef = await fbFirestore.collection('lightGradingQueue').add(lightTicket);

        // ── Credit deduction (same as full grading) ──
        if (expandedFiles.length > 0 && currentGradingRosterId && teacherProfile) {
            deductCreditsFromRoster(currentGradingRosterId, Math.ceil(expandedFiles.length * 0.1), {
                type: 'exam',
                title: `[LIGHT] ${capturedAssessment.assessmentTitle || 'Exam'}`,
                studentName: student.name,
                pages: expandedFiles.length
            });
        }

        // ── Poll for completion ──
        const MAX_ATTEMPTS = 90;
        for (let attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
            await new Promise(r => setTimeout(r, 5000));
            
            let snap: any;
            try { snap = await ticketRef.get(); } catch (e) { continue; }

            if (!snap.exists) {
                // Backend deleted doc = success
                if (step1El) { step1El.className = "step-item-v2 done"; (step1El.querySelector('.step-status-tag') as HTMLElement).textContent = "DONE"; }
                const step2El = document.getElementById(`lstep-2-${studentUid}`);
                if (step2El) { step2El.className = "step-item-v2 done"; (step2El.querySelector('.step-status-tag') as HTMLElement).textContent = "DONE"; }
                if (barEl) barEl.style.width = "100%";

                // Fetch the light report
                const lightReportDoc = await fbFirestore
                    .collection('teachers').doc(teacherProfile!.uid)
                    .collection('assessmentHistory').doc(capturedAssessment.assessmentId)
                    .collection('lightSubmissions').doc(studentUid)
                    .get();

                isGradingBusy = false;
                currentGradingStudentName = null;
                updateGradingPIP();
                processGradingQueue();

                if (lightReportDoc.exists) {
                    const lightData = lightReportDoc.data() as any;
                    // Show the ⚡ View Light Report button
                    actionContainer.innerHTML = `
                        <button class="button-primary accent-positive-btn grading-action-btn"
                           onclick="event.preventDefault(); event.stopPropagation(); window.handleViewLightReport('${studentUid}', '${capturedAssessment.assessmentId}')">

                            ⚡ View Light Report
                        </button>`;
                } else {
                    actionContainer.innerHTML = `<span style="color:#cf1322;font-size:0.8rem;">⚠️ Light report not found</span>`;
                }
                return;
            }

            const data = snap.data();
            if (!data) continue;

            const step2El = document.getElementById(`lstep-2-${studentUid}`);
            if (data.currentStep >= 2 && step1El) { step1El.className = "step-item-v2 done"; (step1El.querySelector('.step-status-tag') as HTMLElement).textContent = "DONE"; if (barEl) barEl.style.width = "70%"; }
            if (data.currentStep >= 2 && step2El) { step2El.className = "step-item-v2 in-progress"; (step2El.querySelector('.step-status-tag') as HTMLElement).textContent = data.statusDetails || "IN PROGRESS"; }

            if (data.status === 'ERROR') {
                actionContainer.innerHTML = `
                    <div class="grading-status-container error">
                        <span class="status error" title="${data.statusDetails || ''}">❌ Light Grade Failed</span>
                        <button onclick="handleLightGradeIndividualStudent('${studentUid}')" class="button-secondary extra-small-button">Retry</button>
                    </div>`;
                isGradingBusy = false;
                currentGradingStudentName = null;
                updateGradingPIP();
                processGradingQueue();
                return;
            }
        }

        throw new Error('Light grading timed out.');

    } catch (error) {
        isGradingBusy = false;
        currentGradingStudentName = null;
        updateGradingPIP();
        processGradingQueue();
        actionContainer.innerHTML = `
            <div class="grading-status-container error">
                <span class="status error">❌ Light Grade Failed</span>
                <button onclick="handleLightGradeIndividualStudent('${studentUid}')" class="button-secondary extra-small-button">Retry</button>
            </div>`;
    }
}

window.previewProcessedFile = (studentUid: string, index: number) => {
    const files = localStudentFiles.get(studentUid);
    if (!files || !files[index]) return;
    
    // Create a temporary URL for the actual File object stored in memory
    const url = URL.createObjectURL(files[index]);
    currentViewerImageUrls = [url];
    currentViewerIndex = 0;
    updateImageViewerContent();
    toggleModal('image-viewer-modal', true);
    
    // Clean up memory after modal closes (optional but good practice)
    const modal = document.getElementById('image-viewer-modal');
    const observer = new MutationObserver(() => {
        if (modal?.style.display === 'none') {
            URL.revokeObjectURL(url);
            observer.disconnect();
        }
    });
    if (modal) observer.observe(modal, { attributes: true, attributeFilter: ['style'] });
};



