// --- INSTRUCTION: REPLACE THE ENTIRE OLD renderQuestionAnalyticsMatrix FUNCTION WITH THIS ---

function renderQuestionAnalyticsMatrix() {
    const container = document.getElementById('analytics-matrix-container');
    const card = document.getElementById('question-analytics-matrix-card');
    if (!container || !card) return;

    if (!currentAssessmentForReportView || !currentAssessmentForReportView.questions || assessmentReports.length === 0) {
        card.style.display = 'none';
        return;
    }
card.style.display = 'none';
    return;

    // --- START: Manual Code Change ---

    // --- START: Manual Code Change ---
const validReports = assessmentReports.filter(r => r.questionWiseReport && r.questionWiseReport.length > 0);
const totalStudentsWhoTookTest = validReports.length;
// --- END: Manual Code Change ---
    const questions = currentAssessmentForReportView.questions;

    // --- START OF THE DATA FIX ---
    // The core problem was that we were trying to match graded questions using an unreliable
    // number parsing method. This new logic is much more robust and accounts for all question types.
    const questionStats = questions.map((definedQuestion, index) => {
        // We now have two potential identifiers for a question:
        // 1. Its original number from an uploaded paper (e.g., "3. (a)")
        const ocrQuestionNumber = definedQuestion.questionNumber;
        // 2. Its simple position in the list (e.g., the 1st question, the 2nd question)
        const sequentialQuestionNumber = (index + 1).toString();

// --- START: Manual Code Change ---
const reportsWithThisQuestion = validReports
    .map(r => r.questionWiseReport.find(gradedQuestionReport => {
        // Add this guard clause
        if (!gradedQuestionReport) return false;
        // Trim all values before comparing to prevent whitespace errors
        const gradedQNum = String(gradedQuestionReport.questionNumber || '').trim();
        const ocrQNum = ocrQuestionNumber?.trim();
        const sequentialQNum = sequentialQuestionNumber?.trim();
        
        return gradedQNum === ocrQNum || gradedQNum === sequentialQNum;
    }))
    .filter((report): report is AIQuestionReport => !!report);
// --- END: Manual Code Change ---
        
        const attemptCount = reportsWithThisQuestion.length;
        const attemptRate = totalStudentsWhoTookTest > 0 ? (attemptCount / totalStudentsWhoTookTest) * 100 : 0;
        
        const totalScoreAwarded = reportsWithThisQuestion.reduce((sum, qr) => sum + qr.marksAwarded, 0);
        const totalMaxScore = reportsWithThisQuestion.reduce((sum, qr) => sum + qr.maxMarksForQuestion, 0);
        const averageScorePercent = totalMaxScore > 0 ? (totalScoreAwarded / totalMaxScore) * 100 : 0;

        return {
            questionNumber: index + 1, // Use a simple number for the box label
            text: definedQuestion.text,
            attemptRate,
            averageScorePercent
        };
    });
    // --- END OF THE DATA FIX ---

    const matrixCells: (typeof questionStats)[] = Array(9).fill(0).map(() => []);

    questionStats.forEach(q => {
        let xPos = 0;
        if (q.attemptRate > 70) xPos = 2;
        else if (q.attemptRate >= 40) xPos = 1;

        let yPos = 0;
        if (q.averageScorePercent < 40) yPos = 2;
        else if (q.averageScorePercent <= 75) yPos = 1;

        const cellIndex = yPos * 3 + xPos;
        if (cellIndex >= 0 && cellIndex < 9) {
            matrixCells[cellIndex].push(q);
        }
    });

    // --- START OF THE UI FIX ---
    // The axis labels below have been simplified by removing the percentage text in brackets.
    const matrixHtml = `
        <div class="analytics-matrix-wrapper">
            <div class="matrix-y-axis">
                <span>Above Average</span>
                <span>Average</span>
                <span>Below Average</span>
            </div>
            <div class="analytics-matrix-grid">
                ${matrixCells.map(cellQuestions => {
                    let sizeClass = '';
                    if (cellQuestions.length > 20) sizeClass = 'size-tiny';
                    else if (cellQuestions.length > 10) sizeClass = 'size-small';

                    return `
                        <div class="matrix-cell">
                            ${cellQuestions.map(q => {
                                let colorClass = 'q-box-red';
                                if (q.averageScorePercent > 75) colorClass = 'q-box-green';
                                else if (q.averageScorePercent >= 40) colorClass = 'q-box-yellow';
                                const tooltipText = `Q${q.questionNumber}: ${q.text.replace(/"/g, '&quot;')}\\nAttempt Rate: ${q.attemptRate.toFixed(0)}%\\nAvg Score: ${q.averageScorePercent.toFixed(0)}%`;
                                
                                return `<div class="matrix-question-box ${colorClass} ${sizeClass}" title="${tooltipText}">
                                    ${q.questionNumber}
                                </div>`;
                            }).join('')}
                        </div>
                    `;
                }).join('')}
            </div>
            <div class="matrix-x-axis">
                <span>Least Attended</span>
                <span>Moderately Attended</span>
                <span>Most Attended</span>
            </div>
        </div>
    `;
    container.innerHTML = matrixHtml;
    // --- END OF THE UI FIX ---
}


