/**
 * A robust and efficient function to fetch all performance data for a specific student
 * within the context of a single class and subject.
 * @param studentUid The UID of the student.
 * @param classInfo An object containing className, section, and subject.
 * @returns A promise that resolves to an object containing lists of homeworks and assessments.
 */
async function fetchStudentProfileData(studentUid: string, classInfo: { className: string, section: string, subject: string }) {
    if (!teacherProfile) throw new Error("Authentication error: Teacher profile not found.");
    
    // --- PART 1: FETCH HOMEWORK SUBMISSIONS (NEW ROBUST LOGIC) ---
    // Step 1: Find all homework assignments that were created for this specific class.
    const classHomeworks = await getAssignedHomeworks(teacherProfile.uid, classInfo);
    const classHomeworkIds = classHomeworks.map(hw => hw.homeworkId);

    let homeworks: Submission[] = [];

    // Step 2: If there are homeworks for this class, fetch the student's submissions for them.
    if (classHomeworkIds.length > 0) {
        // Firestore 'in' queries are limited to 30 items. We must batch the requests for performance.
        const idBatches: string[][] = [];
        for (let i = 0; i < classHomeworkIds.length; i += 30) {
            idBatches.push(classHomeworkIds.slice(i, i + 30));
        }

        const batchPromises = idBatches.map(batch => {
            if (batch.length > 0) {
                return fbFirestore.collection('completedHomeworkSubmissions')
                    .where('studentId', '==', studentUid)
                    .where('homeworkId', 'in', batch)
                    .get();
            }
            return Promise.resolve(null);
        });

        const snapshots = await Promise.all(batchPromises);

        for (const snapshot of snapshots) {
            if (snapshot) {
                for (const doc of snapshot.docs) {
                    // This includes mapping for older data models (e.g., 'class' vs 'className') to ensure consistency.
                    const data = doc.data() as any;
                    homeworks.push({
                        ...data,
                        submissionId: doc.id,
                        className: data.className || data.class,
                    } as Submission);
                }
            }
        }
    }
    // At this point, `homeworks` correctly contains all submissions by this student for this specific class.
    
    // --- PART 2: FETCH ASSESSMENT SUBMISSIONS (This part remains the same) ---
    const studentAssessments: (AIFullAssessmentReport & { assessmentTitle: string, creationTimestamp: string })[] = [];
    
    const assessmentsForClassQuery = fbFirestore.collection('teachers').doc(teacherProfile.uid).collection('assessmentHistory')
        .where('className', '==', classInfo.className)
        .where('section', '==', classInfo.section)
        .where('subject', '==', classInfo.subject);

    const assessmentsForClassSnap = await assessmentsForClassQuery.get();

    // Now, for each relevant assessment, we check if this specific student has a submission.
    const submissionPromises = assessmentsForClassSnap.docs.map(async (doc) => {
        const assessmentData = doc.data() as CreatedAssessment;
        if (!assessmentData) return;

        const submissionSnap = await doc.ref.collection('submissions').where('studentUid', '==', studentUid).limit(1).get();
        
        if (!submissionSnap.empty) {
            const report = submissionSnap.docs[0].data() as AIFullAssessmentReport;
            if (!report) return;

            const creationTimestamp = (report as any).gradingTimestamp || assessmentData.creationTimestamp || new Date().toISOString();
            
            studentAssessments.push({ 
                ...report, 
                assessmentTitle: assessmentData.assessmentTitle || "Untitled Assessment",
                creationTimestamp: creationTimestamp
            });
        }
    });

    await Promise.all(submissionPromises);

    // --- PART 3: FINALIZE AND RETURN DATA ---
    homeworks.sort((a, b) => new Date(b.submissionTimestamp).getTime() - new Date(a.submissionTimestamp).getTime());
    studentAssessments.sort((a, b) => new Date(b.creationTimestamp).getTime() - new Date(a.creationTimestamp).getTime());

    return { homeworks, assessments: studentAssessments };
}


