/**
 * Calls Gemini to generate a high-level "Know Your Student" summary for the teacher,
 * now with specific class context.
 */
async function generateKnowYourStudentSummary(studentName: string, data: { homeworks: Submission[], assessments: any[] }, classInfo: { className: string, section: string, subject: string }) {
    // Compile a more concise data summary to send to the AI, focusing on patterns.
    const compiledData = {
        homeworkPerformance: data.homeworks.map(hw => ({
            score: hw.score,
            overallFeedback: hw.detailedReport?.overallFeedback
        })).slice(0, 10), // Limit to the 10 most recent homeworks to manage token count
        assessmentPerformance: data.assessments.map(as => ({
            title: as.assessmentTitle,
            scorePercentage: as.maximumMarks > 0 ? (as.overallScore / as.maximumMarks * 100) : 0,
            overallFeedback: as.overallFeedback
        })).slice(0, 10) // Limit to the 10 most recent assessments
    };

    const prompt = `
        You are an expert educational psychologist AI. Your task is to analyze a student's performance history for a specific subject and generate a powerful, concise "Know Your Student" summary for their teacher.

        **Student's Name:** ${studentName}
        **Subject Context:** ${classInfo.subject} (Class ${classInfo.className} - ${classInfo.section})

        **Performance Data (for this subject only):**
        ${JSON.stringify(compiledData, null, 2)}

        **Your CRITICAL Task & Output Format:**
        1.  **Synthesize All Data:** Review all performance data. Identify recurring patterns, academic traits, and learning habits based ONLY on the provided context.
        2.  **Generate a High-Level Summary:** Write a concise (2-3 sentences) overall summary of the student's abilities and progress in this specific subject. **You MUST bold the most important keywords** in this summary using Markdown's double asterisks (e.g., "shows **strong conceptual understanding** but struggles with **time management**.").
        3.  **Identify Strengths & Weaknesses as Keywords:**
            - Provide a list of 2-4 high-level, pattern-based strengths. Each strength MUST be a short keyword or 2-3 word phrase.
            - Provide a list of 2-4 actionable, pattern-based areas for improvement. Each weakness MUST be a short keyword or 2-3 word phrase.
        4.  **Final Output:** Your response MUST be a single, valid JSON object that adheres to the provided schema. Do not add any extra text or markdown formatting.
    `;

    const responseSchema = {
        type: Type.OBJECT,
        properties: {
            summary: { type: Type.STRING, description: "A concise overall summary with key phrases bolded using Markdown." },
            strengths: { type: Type.ARRAY, items: { type: Type.STRING }, description: "A list of 2-4 short keywords/phrases for strengths." },
            weaknesses: { type: Type.ARRAY, items: { type: Type.STRING }, description: "A list of 2-4 short keywords/phrases for weaknesses." }
        },
        required: ["summary", "strengths", "weaknesses"]
    };

    try {
        const response = await getAiInstance().models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: { 
    responseMimeType: "application/json", 
    responseSchema: responseSchema,
    temperature: 0,
    maxOutputTokens: 400, // High-level summary only
    thinkingConfig: { thinkingBudget: 0 }
}
        });

// --- ADD THIS BLOCK FOR COST TRACKING ---
if (teacherProfile) {
    logApiUsage({
        teacherProfile,
        feature: 'Know Your Student Summary Generation',
        model: 'gemini-2.5-flash',
        units: {
            inputChars: prompt.length,
            outputChars: response.text.length,
        }
    });
}
// --- END OF COST TRACKING BLOCK ---

        return JSON.parse(response.text.trim());
    } catch (e) {
        console.error("Failed to generate AI 'Know Your Student' summary:", e);
        // Provide a safe fallback object in case of an AI error
        return {
            summary: "The AI was unable to generate a summary for this student at this time. Please check their individual work below for performance details.",
            strengths: ["Manual Review Needed"],
            weaknesses: ["AI Generation Failed"]
        };
    }
}

