async function setupKnowYourStudentPage() {
    if (!currentStudentForPortfolio || !currentClassForPortfolio) {
        console.error("Profile Error: Missing student or class context.");
        updateUIVisibility('teacher_dashboard'); // Go back if context is lost
        return;
    }

    const student = currentStudentForPortfolio;
    const classInfo = currentClassForPortfolio;
    const headingEl = document.getElementById('student-profile-heading') as HTMLHeadingElement;
    const summaryContainerEl = document.getElementById('student-profile-ai-summary') as HTMLDivElement;
    const assessmentListEl = document.getElementById('profile-assessment-list') as HTMLDivElement;
    const homeworkListEl = document.getElementById('profile-homework-list') as HTMLDivElement;
    
    // --- Setup Tabs ---
    const assessmentTabBtn = document.getElementById('profile-assessment-tab') as HTMLButtonElement;
    const homeworkTabBtn = document.getElementById('profile-homework-tab') as HTMLButtonElement;
    const assessmentPanel = document.getElementById('profile-assessment-panel') as HTMLDivElement;
    const homeworkPanel = document.getElementById('profile-homework-panel') as HTMLDivElement;

    assessmentTabBtn.onclick = () => {
        assessmentTabBtn.classList.add('active');
        homeworkTabBtn.classList.remove('active');
        assessmentPanel.style.display = 'block';
        homeworkPanel.style.display = 'none';
    };
    homeworkTabBtn.onclick = () => {
        assessmentTabBtn.classList.remove('active');
        homeworkTabBtn.classList.add('active');
        assessmentPanel.style.display = 'none';
        homeworkPanel.style.display = 'block';
    };

    // --- Initial UI State (Loading Spinners) ---
    headingEl.textContent = `Know Your Student: ${student.name}`;
    summaryContainerEl.innerHTML = `<div class="spinner-container"><div class="spinner-small"></div><p>AI is analyzing student performance...</p></div>`;
    assessmentListEl.innerHTML = `<div class="spinner-container"><div class="spinner-small"></div><p>Loading assessment history...</p></div>`;
    homeworkListEl.innerHTML = `<div class="spinner-container"><div class="spinner-small"></div><p>Loading homework history...</p></div>`;

    try {
        // --- 1. Fetch all performance data ---
        const profileData = await fetchStudentProfileData(student.uid, classInfo);
        
        // --- 2. Generate AI Summary (with specific class context) ---
        generateKnowYourStudentSummary(student.name, profileData, classInfo).then(aiSummary => {
            const summaryHtml = formatMathExpressions(aiSummary.summary).replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
            summaryContainerEl.innerHTML = `
                <p class="summary-text">${summaryHtml}</p>
                <div class="traits-grid">
                    <div class="trait-card strengths">
                        <h5>💪 Strengths</h5>
                        <ul>${aiSummary.strengths.map((s:string) => `<li>${s}</li>`).join('')}</ul>
                    </div>
                    <div class="trait-card weaknesses">
                        <h5>📉 Areas for Improvement</h5>
                        <ul>${aiSummary.weaknesses.map((w:string) => `<li>${w}</li>`).join('')}</ul>
                    </div>
                </div>
            `;
        });
        
        // --- 3. Render Assessment List & Chart ---
        if (profileData.assessments.length > 0) {
            assessmentListEl.innerHTML = profileData.assessments.map(as => {
                const percentage = as.maximumMarks > 0 ? (as.overallScore / as.maximumMarks * 100) : 0;
                return `
                    <div class="profile-item-card">
                        <h4>${as.assessmentTitle}</h4>
                        <p class="profile-item-date">Graded on: ${new Date(as.creationTimestamp).toLocaleDateString()}</p>
                        <div class="profile-item-score">Score: ${as.overallScore.toFixed(1)} / ${as.maximumMarks} (${percentage.toFixed(0)}%)</div>
                        <div class="profile-feedback">
                            <p><strong>Feedback:</strong> ${as.overallFeedback.summary}</p>
                        </div>
                    </div>
                `;
            }).join('');
            
            const assessmentChartCanvas = document.getElementById('profile-assessment-chart-canvas') as HTMLCanvasElement;
            const assessmentChartCtx = assessmentChartCanvas.getContext('2d');
            if (assessmentChartCtx) {
                // CHART FIX: Destroy the old chart instance if it exists
                if (knowYourStudentAssessmentChart) {
                    knowYourStudentAssessmentChart.destroy();
                }
                const chartData = [...profileData.assessments].reverse();
                // CHART FIX: Store the new chart instance in our global variable
                knowYourStudentAssessmentChart = new window.Chart(assessmentChartCtx, {
                    type: 'line',
                    data: {
                        labels: chartData.map(a => a.assessmentTitle.slice(0, 15) + '...'),
                        datasets: [{
                            label: 'Score (%)',
                            data: chartData.map(a => a.maximumMarks > 0 ? (a.overallScore / a.maximumMarks * 100) : 0),
                            borderColor: 'rgba(155, 89, 182, 1)',
                            backgroundColor: 'rgba(155, 89, 182, 0.1)',
                            fill: true, tension: 0.1
                        }]
                    },
                    options: { responsive: true, maintainAspectRatio: false, scales: { y: { beginAtZero: true, max: 100 } } }
                });
            }

        } else {
            assessmentListEl.innerHTML = `<p class="info-text">No assessments have been graded for this student in this class yet.</p>`;
        }
        
        // --- 4. Render Homework List & Chart ---
        if (profileData.homeworks.length > 0) {
            homeworkListEl.innerHTML = profileData.homeworks.map(hw => {
                const homeworkDef = allAssignedHomeworks.find(h => h.homeworkId === hw.homeworkId);
                const title = homeworkDef ? getHomeworkTitle(homeworkDef) : 'Homework';
                const overallFeedback = typeof hw.detailedReport?.overallFeedback === 'object' ? hw.detailedReport.overallFeedback.summary : hw.detailedReport?.overallFeedback;
                return `
                     <div class="profile-item-card">
                        <h4>${title}</h4>
                        <p class="profile-item-date">Submitted on: ${new Date(hw.submissionTimestamp).toLocaleDateString()}</p>
                        <div class="profile-item-score">Score: ${hw.score}%</div>
                        <div class="profile-feedback">
                            <p><strong>Feedback:</strong> ${overallFeedback || 'No summary feedback available.'}</p>
                        </div>
                    </div>
                `;
            }).join('');

            const homeworkChartCanvas = document.getElementById('profile-homework-chart-canvas') as HTMLCanvasElement;
            const homeworkChartCtx = homeworkChartCanvas.getContext('2d');
            if (homeworkChartCtx) {
                 // CHART FIX: Destroy the old chart instance if it exists
                 if (knowYourStudentHomeworkChart) {
                    knowYourStudentHomeworkChart.destroy();
                 }
                 const chartData = [...profileData.homeworks].reverse();
                 // CHART FIX: Store the new chart instance in our global variable
                 knowYourStudentHomeworkChart = new window.Chart(homeworkChartCtx, {
                    type: 'bar',
                    data: {
                        labels: chartData.map((hw, i) => `HW ${i+1}`),
                        datasets: [{
                            label: 'Score (%)',
                            data: chartData.map(hw => hw.score),
                            backgroundColor: 'rgba(52, 152, 219, 0.7)',
                            borderColor: 'rgba(52, 152, 219, 1)',
                            borderWidth: 1, borderRadius: 5,
                        }]
                    },
                    options: { responsive: true, maintainAspectRatio: false, scales: { y: { beginAtZero: true, max: 100 } } }
                });
            }

        } else {
            homeworkListEl.innerHTML = `<p class="info-text">No homework has been submitted by this student in this class yet.</p>`;
        }

    } catch (error) {
        console.error("Failed to load 'Know Your Student' page:", error);
        
        const errorMessage = (error instanceof Error) ? error.message : String(error);
        const firestoreLinkMatch = errorMessage.match(/(https?:\/\/[^\s]+)/);
        let errorHtml = '';

        if (firestoreLinkMatch && firestoreLinkMatch[0].includes('console.firebase.google.com')) {
            const link = firestoreLinkMatch[0];
            errorHtml = `
                <div class="info-box error" style="text-align: left;">
                    <h4>Database Index Required</h4>
                    <p>To show a student's full history, a specific database index is needed. This is a one-time setup.</p>
                    <p>Please click the button below. A new tab will open in your Firebase console with the index details pre-filled. Just click "Save" in that tab, wait a few minutes for the index to build, and then refresh this page.</p>
                    <a href="${link}" target="_blank" class="button-primary icon-btn" style="margin-top: 10px;"><span class="icon">🔗</span> Create Missing Index</a>
                </div>
            `;
        } else {
            errorHtml = `
                <div class="info-box error">
                    <h4>An Error Occurred</h4>
                    <p>Could not load the student's profile data. Please check the browser console for more details and try again.</p>
                    <p class="description" style="font-size: 0.8rem;">Error: ${errorMessage}</p>
                </div>
            `;
        }
        summaryContainerEl.innerHTML = '';
        assessmentListEl.innerHTML = errorHtml;
        homeworkListEl.innerHTML = '';
    }
}


