/**
 * Filters and sorts the master list of homeworks based on UI controls, then renders them.
 */
function renderFilteredAndSortedHomeworks() {
    if (!assignedHomeworksListContainerEl) return;
    
    const searchTerm = homeworkSearchInputEl.value.toLowerCase();
    const sortOrder = homeworkSortSelectEl.value;

    // 1. Filter by search term
    const filteredHomeworks = allAssignedHomeworks.filter(hw => {
        const topic = hw.customTopic || hw.selectedChapters?.join(', ') || '';
        return topic.toLowerCase().includes(searchTerm);
    });

    // 2. Sort the filtered results
    filteredHomeworks.sort((a, b) => {
        const dateA = new Date(a.creationTimestamp).getTime();
        const dateB = new Date(b.creationTimestamp).getTime();
        return sortOrder === 'newest' ? dateB - dateA : dateA - dateB;
    });

    // 3. Render the final list
    assignedHomeworksListContainerEl.innerHTML = '';
    if (filteredHomeworks.length === 0) {
        noAssignedHomeworksMessageEl.style.display = 'block';
        noAssignedHomeworksMessageEl.innerHTML = `<p>No homeworks match your search criteria.</p>`;
    } else {
        noAssignedHomeworksMessageEl.style.display = 'none';
        filteredHomeworks.forEach(renderHomeworkCard);
    }
}

