async function handleViewGradedReports(assessment: CreatedAssessment) {
    assessmentReports = [];
currentAssessmentForReportView = null;
currentAssessmentToGrade = null;
currentAssessmentRoster = [];
    if (!assessment || !assessment.assessmentId) {
    showFeedbackMessage("Cannot view reports because the assessment has an invalid or missing ID.", "error", true);
    toggleLoading(false);
    return;
}
    if (!teacherProfile) return;
    toggleLoading(true, "Loading saved reports...");

    try {
        // --- ADD THIS ENTIRE "if" BLOCK ---
        if (!assessment || !assessment.assessmentId) {
            throw new Error("Cannot view reports because the assessment has an invalid or missing ID.");
        }
// Step 1: Fetch all saved submission reports.
        // Try current teacher's subcollection first, then check shared class teachers.
        let resolvedTeacherUid = assessment.createdByTeacherUid || teacherProfile.uid;
        let resolvedAssessmentId = assessment.assessmentId;
        let submissionsSnapshot = await fbFirestore
            .collection('teachers').doc(resolvedTeacherUid)
            .collection('assessmentHistory').doc(assessment.assessmentId)
            .collection('submissions')
            .get();
        if (submissionsSnapshot.empty) {
            try {
 const sharedRostersSnap = await fbFirestore.collection('classRosters')
    .where('className', '==', assessment.className)
    .where('section', '==', assessment.section)
    .where('subject', '==', assessment.subject)
    .where('schoolName', '==', teacherProfile.schoolName)
    .get();

                const otherTeacherUids = sharedRostersSnap.docs
                    .map(doc => doc.data().teacherUid as string)
                    .filter(tUid => tUid !== teacherProfile.uid);

for (const otherUid of otherTeacherUids) {
                    // Find matching assessment by title+class+section+subject
                    // (NOT by assessmentId — each teacher has their own doc ID)
                    const otherAssessSnap = await fbFirestore
                        .collection('teachers').doc(otherUid)
                        .collection('assessmentHistory')
                        .where('className', '==', assessment.className)
                        .where('section', '==', assessment.section)
                        .where('subject', '==', assessment.subject)
                        .where('assessmentTitle', '==', assessment.assessmentTitle)
                        .limit(1)
                        .get();

                    if (otherAssessSnap.empty) continue;

                    const otherAssessId = otherAssessSnap.docs[0].id;
                    const otherSnap = await fbFirestore
                        .collection('teachers').doc(otherUid)
                        .collection('assessmentHistory').doc(otherAssessId)
                        .collection('submissions')
                        .get();
if (!otherSnap.empty) {
                        submissionsSnapshot = otherSnap;
                        resolvedTeacherUid = otherUid;
                        resolvedAssessmentId = otherAssessId;
                        break;
                    }
                }
            } catch (e) {
                console.warn("Could not check shared teacher submissions:", e);
            }
        }

        if (submissionsSnapshot.empty) {
            showFeedbackMessage("No graded reports found for this assessment. Use the 'Grade Assessment' option to start.", "info");
            toggleLoading(false);
            return;
        }

        // --- STEP A: Map the raw database documents into a reports array first ---
const reports = await Promise.all(submissionsSnapshot.docs.map(async doc => {
    const data = doc.data() as any;
    let questionWiseReport = data.questionWiseReport || [];
    try {
const detailDoc = await doc.ref.collection('detail').doc('report').get();
        if (detailDoc.exists) {
            const detailData = (detailDoc.data() as any);
            questionWiseReport = detailData.questionWiseReport || [];
            if (detailData.fullOcrText) data.fullOcrText = detailData.fullOcrText;
        }
    } catch (e) {
        console.warn('[ReportView] detail subcollection fetch failed', e);
    }
return {
        ...data,
        questionWiseReport,
        submissionDocId: doc.id,
        _ownerTeacherUid: resolvedTeacherUid,
        _ownerAssessmentId: resolvedAssessmentId,
        gradingTimestamp: data.gradingTimestamp || data.creationTimestamp || new Date(0).toISOString()
    } as AIFullAssessmentReport & { gradingTimestamp: string };
}));
        // --- STEP B: Deduplicate (Keep only the LATEST report for each student) ---
// Replace the existing uniqueReportsMap.set loop with this:
const uniqueReportsMap = new Map<string, AIFullAssessmentReport & { gradingTimestamp: any }>();

reports.forEach(report => {
    const sId = report.studentUid;
    const existing = uniqueReportsMap.get(sId);

    // Helper to get raw milliseconds from string or Firestore Timestamp
    const getMs = (val: any) => {
        if (val && typeof val === 'object' && 'seconds' in val) return val.seconds * 1000;
        const p = new Date(val || 0).getTime();
        return isFinite(p) ? p : 0;
    };

    const currentMs = getMs(report.gradingTimestamp);
    const existingMs = existing ? getMs(existing.gradingTimestamp) : -1;

    // If no report exists for this student, or this one is newer, update the map
    if (!existing || currentMs > existingMs) {
        uniqueReportsMap.set(sId, report);
    }
});
        const deduplicatedReports = Array.from(uniqueReportsMap.values());



        // Step 4: Fetch the class roster using the correct Stream-Aware ID
       // Determine the stream context. If the assessment has one, use it.
// Otherwise, if we are currently viewing a class page, inherit its stream.
let effectiveStream = assessment.stream;
if (!effectiveStream && currentClassForView && 
    normalizeForComparison(currentClassForView.className) === normalizeForComparison(assessment.className) &&
    normalizeForComparison(currentClassForView.section) === normalizeForComparison(assessment.section) &&
    normalizeForComparison(currentClassForView.subject) === normalizeForComparison(assessment.subject)) {
    effectiveStream = currentClassForView.stream;
}

const rosterId = generateRosterId(teacherProfile.uid, assessment.className, assessment.section, assessment.subject, effectiveStream);
const roster = await getClassRoster(rosterId);

        // Create a lookup set for students in the CURRENT class roster
const rosterUids = new Set(roster ? roster.students.map(s => s.uid) : []);
const targetStream = normalizeForComparison(assessment.stream);
const finalFilteredReports = deduplicatedReports.filter(r => {
    const reportStream = normalizeForComparison((r as any).stream);
    const targetStream = normalizeForComparison(assessment.stream);
    
    // If both have streams, they must match. 
    // If one is missing (legacy), we show it to be safe.
    if (reportStream && targetStream) {
        return reportStream === targetStream;
    }
    return true; 
});
// Step 5: Set global state
        assessmentReports = finalFilteredReports;

        currentAssessmentToGrade = assessment;
        currentAssessmentRoster = roster ? roster.students : [];

        // Populate the expected-co-teacher cache before rendering, so verification
        // chips can show a "not yet verified" chip for a teacher who is expected but
        // has never clicked verify (see ensureExpectedVerifiersCached / expectedVerifiersCache).
        await ensureExpectedVerifiersCached(assessment.className, assessment.section, assessment.subject, teacherProfile.schoolName);

        updateUIVisibility('teacher_assessment_report_view');

    } catch (error) {
        console.error("Error loading graded reports:", error);
        showFeedbackMessage("Could not load the saved reports for this assessment.", "error");
    } finally {
        toggleLoading(false);
    }
}

async function setupAnalyticsHub() {
    if (!teacherProfile) return;
    analyticsContentAreaEl.style.display = 'none'; // Hide content until filters are applied

    try {
        const rostersSnapshot = await fbFirestore.collection('classRosters').where('teacherUid', '==', teacherProfile.uid).get();
        const rosters = rostersSnapshot.docs.map(doc => doc.data() as ClassRoster);

        const classes = [...new Set(rosters.map(r => r.className))].sort((a, b) => parseInt(a) - parseInt(b));
        const sections = [...new Set(rosters.map(r => r.section))].sort();
        const subjects = [...new Set(rosters.map(r => r.subject))].sort();

        analyticsClassSelectEl.innerHTML = '<option value="">All Classes</option>' + classes.map(c => `<option value="${c}">Class ${c}</option>`).join('');
        analyticsSectionSelectEl.innerHTML = '<option value="">All Sections</option>' + sections.map(s => `<option value="${s}">${s}</option>`).join('');
        analyticsSubjectSelectEl.innerHTML = '<option value="">All Subjects</option>' + subjects.map(s => `<option value="${s}">${s}</option>`).join('');

    } catch (error) {
        console.error("Error populating analytics filters:", error);
        showFeedbackMessage("Could not load class filters for analytics.", "error");
    }
}
async function handleLoadAnalytics() {
    if (!teacherProfile) return;

    toggleLoading(true, "Fetching performance data...");
    analyticsContentAreaEl.style.display = 'none'; // Hide until ready

    const className = analyticsClassSelectEl.value;
    const section = analyticsSectionSelectEl.value;
    const subject = analyticsSubjectSelectEl.value;

    if (!className || !section || !subject) {
        showFeedbackMessage("Please select a class, section, and subject.", "error");
        toggleLoading(false);
        return;
    }

    try {
        // --- 1. FETCH ALL RAW DATA for the selected class ---
        const rosterId = `${teacherProfile.uid}_${className}_${section}_${subject}`;
        const roster = await getClassRoster(rosterId);
        const studentsInClass = roster ? roster.students : [];
// 1. Get the stream value safely
        const streamEl = document.getElementById('analytics-stream-select') as HTMLSelectElement;
        const selectedStream = streamEl ? streamEl.value : (roster?.stream || "");

        // 2. Pass the stream to the filter
        const relevantHomeworks = await getAssignedHomeworks(teacherProfile.uid, { 
            className, 
            section, 
            subject,
            stream: selectedStream 
        });
        const homeworkIds = relevantHomeworks.map(hw => hw.homeworkId);
        let allSubmissions: Submission[] = [];
        // Batch fetch submissions for performance
        if (homeworkIds.length > 0) {
            const idBatches: string[][] = [];
            for (let i = 0; i < homeworkIds.length; i += 30) {
                idBatches.push(homeworkIds.slice(i, i + 30));
            }
            const submissionPromises = idBatches.map(batch => fbFirestore.collection('completedHomeworkSubmissions').where('homeworkId', 'in', batch).get());
            const submissionSnapshots = await Promise.all(submissionPromises);
            submissionSnapshots.forEach(snapshot => {
                snapshot.docs.forEach(doc => allSubmissions.push(doc.data() as Submission));
            });
        }
        
        const assessmentsSnapshot = await fbFirestore.collection('teachers').doc(teacherProfile.uid).collection('assessmentHistory')
            .where('className', '==', className)
            .where('section', '==', section)
            .where('subject', '==', subject)
            .get();
        const allAssessmentItems = assessmentsSnapshot.docs.map(doc => doc.data() as AssessmentHistoryItem);

        // --- 2. PROCESS AND STORE DATA ---
        // Group assessment items by batch
        const groupedAssessments = new Map<string, StoredAssessment>();
        for (const item of allAssessmentItems) {
            if (!groupedAssessments.has(item.assessmentBatchId)) {
                groupedAssessments.set(item.assessmentBatchId, {
                    assessmentId: item.assessmentBatchId, teacherUid: item.teacherUid, assessmentTitle: item.assessmentTitle,
                    className: item.className, section: item.section, subject: item.subject,
                    creationTimestamp: item.gradingTimestamp, reports: []
                });
            }
            groupedAssessments.get(item.assessmentBatchId)!.reports.push(item.report);
        }

        // Store all fetched & processed data in our global state
currentAnalyticsData = {
    classInfo: { className, section, subject },
    students: studentsInClass,
    homeworks: {
        allHomeworks: relevantHomeworks,
        allSubmissions: allSubmissions,
        questionWisePerformance: new Map(), // Add this
        studentPerformance: new Map(),      // Add this
        overallStudentScores: new Map(),    // Add this
    },
    assessments: {
        allAssessments: Array.from(groupedAssessments.values()),
        questionWisePerformance: new Map(), // Add this
        overallStudentScores: new Map(),    // Add this
    }
};
        
        // --- 3. POPULATE UI & RENDER DEFAULT VIEW ---
        populateAnalyticsSelectors();
        switchAnalyticsMainView('class'); // Default to class view
        analyticsContentAreaEl.style.display = 'block';

    } catch (error) {
        console.error("Error loading analytics data:", error);
        showFeedbackMessage("An error occurred while preparing the analytics data.", "error");
    } finally {
        toggleLoading(false);
    }
}

