//
// PASTE THIS ENTIRE CORRECTED FUNCTION IN PLACE OF THE OLD ONE
//
async function processAndCacheHomeworkAnalytics() {
    if (homeworkAnalyticsData) {
        return homeworkAnalyticsData; // Use cached data if available
    }
    if (!teacherProfile || allAssignedHomeworks.length === 0) {
        return null;
    }

    toggleLoading(true, "Analyzing all homework data...");

    try {
        const homeworksById = new Map(allAssignedHomeworks.map(hw => [hw.homeworkId, hw]));
        const homeworkIds = allAssignedHomeworks.map(hw => hw.homeworkId);
        const allSubmissions = await getAllSubmissionsForTeacher(homeworkIds);
        
        // --- START OF THE NEW, CORRECTED LOGIC ---
        // This is a crucial change. Instead of overwriting the 'score' property,
        // we will store the calculated percentage in a new property, preserving the original raw score.
        allSubmissions.forEach((sub: any) => {
            const homework = homeworksById.get(sub.homeworkId);
            if (homework && typeof homework.totalMarks === 'number' && homework.totalMarks > 0 && typeof sub.score === 'number') {
                const rawScore = sub.score;
                sub.percentageScore = (rawScore / homework.totalMarks) * 100;
            } else if (sub.detailedReport?.questionDetails?.length > 0) {
                // Fallback for older homeworks: try to calculate from the detailed report
                const totalScore = sub.detailedReport.questionDetails.reduce((sum: number, qd: QuestionDetail) => sum + (qd.aiFeedback?.score || 0), 0);
                const totalMaxScore = sub.detailedReport.questionDetails.reduce((sum: number, qd: QuestionDetail) => sum + (qd.aiFeedback?.maxScore || 10), 0);
                if (totalMaxScore > 0) {
                    sub.percentageScore = (totalScore / totalMaxScore) * 100;
                } else {
                    sub.percentageScore = 0;
                }
            } else {
                sub.percentageScore = 0; // Cannot determine percentage
            }
        });
        // --- END OF THE NEW, CORRECTED LOGIC ---
        
        const submissionsByHwId = new Map<string, Submission[]>();
        for (const sub of allSubmissions) {
            if (!submissionsByHwId.has(sub.homeworkId)) {
                submissionsByHwId.set(sub.homeworkId, []);
            }
            submissionsByHwId.get(sub.homeworkId)!.push(sub);
        }

        const uniqueRosterIds = [...new Set(allAssignedHomeworks.map(hw => `${teacherProfile.uid}_${hw.className}_${hw.section}_${hw.subject}`))];
        const rosterPromises = uniqueRosterIds.map(id => getClassRoster(id));
        const rosters = (await Promise.all(rosterPromises)).filter((r): r is ClassRoster => r !== null);
        const rostersById = new Map(rosters.map(r => [r.id, r]));
        
        const allStudents = new Map<string, RosterStudent>();
        rosters.forEach(r => r.students.forEach(s => allStudents.set(s.uid, s)));

        // --- CALCULATIONS ---
        const participationData: any[] = [];
        const avgScorePerHwData: any[] = [];
        allAssignedHomeworks.forEach(hw => {
            const rosterId = `${teacherProfile.uid}_${hw.className}_${hw.section}_${hw.subject}`;
            const roster = rostersById.get(rosterId);
            const submissions = submissionsByHwId.get(hw.homeworkId) || [];
            
            const totalStudentsInClass = roster ? roster.students.length : 0;
            const participationRate = totalStudentsInClass > 0 ? (submissions.length / totalStudentsInClass) * 100 : 0;
            
            participationData.push({ homework: hw, rate: participationRate, roster: roster, submissions: submissions });

            if (submissions.length > 0) {
                // Use the new 'percentageScore' for calculations
                const totalPercentage = submissions.reduce((sum, s) => sum + ((s as any).percentageScore || 0), 0);
                const avgScore = totalPercentage / submissions.length;
                
                const chartTitle = homeworkDisplayAbbrMap.get(hw.homeworkId) || hw.homeworkId.slice(0, 4);
                avgScorePerHwData.push({ title: chartTitle, score: avgScore });
            }
        });

        // Process student performance data
        const studentPerformance: { name: string; avgScore: number }[] = [];
        const submissionsByStudentId = new Map<string, Submission[]>();
        allSubmissions.forEach(sub => {
            if (!submissionsByStudentId.has(sub.studentId)) {
                submissionsByStudentId.set(sub.studentId, []);
            }
            submissionsByStudentId.get(sub.studentId)!.push(sub);
        });
        submissionsByStudentId.forEach((subs, studentId) => {
            const studentInfo = allStudents.get(studentId);
            if (studentInfo) {
                const totalPercentage = subs.reduce((sum, s) => sum + ((s as any).percentageScore || 0), 0);
                const avgScore = totalPercentage / subs.length;
                studentPerformance.push({ name: studentInfo.name, avgScore });
            }
        });

        // Process top-level stats
        const totalParticipation = participationData.reduce((sum, data) => sum + data.rate, 0);
        const overallAvgParticipation = participationData.length > 0 ? totalParticipation / participationData.length : 0;
        const totalAvgScore = avgScorePerHwData.reduce((sum, data) => sum + data.score, 0);
        const overallAvgScore = avgScorePerHwData.length > 0 ? totalAvgScore / avgScorePerHwData.length : 0;

        homeworkAnalyticsData = {
            overallAvgParticipation,
            overallAvgScore,
            participationData: participationData.sort((a,b) => new Date(b.homework.creationTimestamp).getTime() - new Date(a.homework.creationTimestamp).getTime()),
            avgScorePerHwData: avgScorePerHwData,
            studentPerformance: studentPerformance.sort((a, b) => b.avgScore - a.avgScore),
        };
        const participationMap = new Map<string, any>();
        participationData.forEach(data => {
            participationMap.set(data.homework.homeworkId, data);
        });
        homeworkParticipationMap = participationMap;
        return homeworkAnalyticsData;
    } catch (error) {
        console.error("Error processing homework analytics:", error);
        showFeedbackMessage("Could not process homework analytics data.", "error");
        return null;
    } finally {
        toggleLoading(false);
    }
}

