// PASTE THIS ENTIRE CORRECTED FUNCTION IN PLACE OF THE OLD ONE
//
/**
 * Processes all assessment and report data to generate aggregated analytics.
 */
async function processAndCacheAssessmentAnalytics(classFilter?: { className: string, section: string, subject: string }) {
    if (assessmentAnalyticsData) {
        return assessmentAnalyticsData;
    }
    if (!teacherProfile) return null;

    toggleLoading(true, "Analyzing all assessment data...");
    try {
        const allGradedAssessments = await getAssessmentHistory(teacherProfile.uid, classFilter);
        if (allGradedAssessments.length === 0) return null;

        const uniqueRosterIds = [...new Set(allGradedAssessments.map(as => `${teacherProfile.uid}_${as.className}_${as.section}_${as.subject}`))];
        const rosterPromises = uniqueRosterIds.map(id => getClassRoster(id));
        const rosters = (await Promise.all(rosterPromises)).filter((r): r is ClassRoster => r !== null);
        const rostersById = new Map(rosters.map(r => [r.id, r]));
        
        const allStudents = new Map<string, RosterStudent>();
        rosters.forEach(r => r.students.forEach(s => allStudents.set(s.uid, s)));

        // --- CALCULATIONS ---
        const participationData: any[] = []; // This will store the rate for EACH assessment
        const avgScorePerAssessmentData: any[] = [];
        const submissionsByStudentId = new Map<string, AIFullAssessmentReport[]>();

        allGradedAssessments.forEach(assessment => {
           const rosterId = generateRosterId(teacherProfile.uid, assessment.className, assessment.section, assessment.subject, assessment.stream);
            const roster = rostersById.get(rosterId);
            const totalStudentsInClass = roster ? roster.students.length : 0;
            
            // --- START OF THE FIX ---
            // STEP A: Calculate the participation rate for THIS SPECIFIC assessment.
            let participationRate = totalStudentsInClass > 0 ? (assessment.reports.length / totalStudentsInClass) * 100 : 0;
            
            // This is a safety check. Sometimes, a student might be removed from a roster
            // after submitting, which can make the participation rate > 100%. This line
            // ensures the rate for any single assessment is capped at a realistic 100%.
            participationRate = Math.min(participationRate, 100);

            // STEP B: Store the correctly calculated rate for this one assessment.
            participationData.push({ rate: participationRate });
            // --- END OF THE FIX ---

            if (assessment.reports.length > 0) {
                const totalScore = assessment.reports.reduce((sum, r) => sum + r.overallScore, 0);
                const totalMaxScore = assessment.reports.reduce((sum, r) => sum + r.maximumMarks, 0);
                const avgScore = totalMaxScore > 0 ? (totalScore / totalMaxScore) * 100 : 0;
                avgScorePerAssessmentData.push({ title: assessment.assessmentTitle, score: avgScore });
            }

assessment.reports.forEach(report => {
    const studentUid = report.studentUid || (roster?.students.find(s => s.name === report.studentName)?.uid);
    
    // VALIDATION: Only include this report if the student is actually in the roster 
    // we loaded for this specific stream. This solves the "shared assessment" problem.
    const isStudentInRoster = roster?.students.some(s => s.uid === studentUid);

    if (studentUid && isStudentInRoster) {
                    if (!submissionsByStudentId.has(studentUid)) {
                        submissionsByStudentId.set(studentUid, []);
                    }
                    submissionsByStudentId.get(studentUid)!.push(report);
                }
            });
        });

        const studentPerformance: { name: string; avgScore: number }[] = [];
        submissionsByStudentId.forEach((reports, studentUid) => {
            const studentInfo = allStudents.get(studentUid);
            if (studentInfo) {
                const totalScore = reports.reduce((sum, r) => sum + r.overallScore, 0);
                const totalMaxScore = reports.reduce((sum, r) => sum + r.maximumMarks, 0);
                const avgScore = totalMaxScore > 0 ? (totalScore / totalMaxScore) * 100 : 0;
                studentPerformance.push({ name: studentInfo.name, avgScore });
            }
        });

        // --- START OF THE FIX ---
        // STEP C: Now, calculate the final average by taking the average of all the
        // individual assessment participation rates we stored earlier.
        const totalParticipation = participationData.reduce((sum, data) => sum + data.rate, 0);
        const overallAvgParticipation = participationData.length > 0 ? totalParticipation / participationData.length : 0;
        // --- END OF THE FIX ---
        
        const totalAvgScore = avgScorePerAssessmentData.reduce((sum, data) => sum + data.score, 0);
        const overallAvgScore = avgScorePerAssessmentData.length > 0 ? totalAvgScore / avgScorePerAssessmentData.length : 0;

        assessmentAnalyticsData = {
            overallAvgParticipation,
            overallAvgScore,
            avgScorePerAssessmentData: avgScorePerAssessmentData.sort((a,b) => a.title.localeCompare(b.title)),
            studentPerformance: studentPerformance.sort((a, b) => b.avgScore - a.avgScore),
        };
        
        return assessmentAnalyticsData;
    } catch (error) {
        console.error("Error processing assessment analytics:", error);
        showFeedbackMessage("Could not process assessment analytics data.", "error");
        return null;
    } finally {
        toggleLoading(false);
    }
}

