// --- PASTE THIS ENTIRE NEW FUNCTION ---

/**
 * A robust helper function to get a display-friendly title for any homework object.
 * It intelligently checks for custom topics, chapters, or specific topics,
 * and provides a clean, truncated ID as a final fallback.
 * @param hw The homework object.
 * @returns A user-friendly string for the homework's title.
 */
function getHomeworkTitle(hw: Homework): string {
    // Priority 1: A custom topic, usually from image-based homework.
    if (hw.customTopic && hw.customTopic.trim() !== '') {
        return hw.customTopic;
    }
    // Priority 2: A list of selected chapters.
    if (Array.isArray(hw.selectedChapters) && hw.selectedChapters.length > 0) {
        return hw.selectedChapters.join(', ');
    }
    // Priority 3: A list of specific topics (might be more detailed).
    if (Array.isArray(hw.topics) && hw.topics.length > 0) {
        return hw.topics.join(', ');
    }
    // Fallback: If no other title is available, return the ID but truncated for brevity.
    return hw.homeworkId.slice(0, 15) + '...';
}



