function displayResultsSummaryStats() {
  const uniqueSubmissions = Array.from(
    new Map(currentSubmissionsForResults.map(s => [s.studentId, s])).values()
);
const submittedCount = uniqueSubmissions.length;

    // --- FIX 1: Correctly calculate total students and prevent misleading fallbacks ---
    const totalStudents = currentRosterForResults?.students.length || 0;
let participation: string = totalStudents > 0
    ? ((submittedCount / totalStudents) * 100).toFixed(1)
    : String(submittedCount);
let participationSubText = totalStudents > 0
    ? `(${submittedCount}/${totalStudents})`
    : `${submittedCount} Submitted`;
    // --- END OF FIX 1 ---

    const scores: number[] = currentSubmissionsForResults.map(sub => {
        const homework = currentHomeworkForResults;
        if (!homework) return 0;

        if (sub.detailedReport?.questionDetails?.length > 0) {
            const totalScore = sub.detailedReport.questionDetails.reduce((sum, qd) => sum + (qd.aiFeedback?.score || 0), 0);
            const totalMaxScore = sub.detailedReport.questionDetails.reduce((sum, qd) => sum + (qd.aiFeedback?.maxScore || 10), 0);
            return totalMaxScore > 0 ? (totalScore / totalMaxScore) * 100 : 0;
        }
        if (typeof homework.totalMarks === 'number' && homework.totalMarks > 0 && typeof sub.score === 'number') {
            return (sub.score / homework.totalMarks) * 100;
        }
        if (typeof sub.score === 'number') {
            return sub.score;
        }
        return 0;
    });

    const averageScore = scores.length > 0 ? (scores.reduce((a, b) => a + b, 0) / scores.length).toFixed(1) : 'N/A';
    const highestScore = scores.length > 0 ? Math.max(...scores).toFixed(1) : 'N/A';
    const lowestScore = scores.length > 0 ? Math.min(...scores).toFixed(1) : 'N/A';

    // --- FIX 2: Updated HTML structure to fix icon placement ---
    resultsSummaryStatsContainerEl.innerHTML = `
        <div class="stat-card" id="participation-stat-card" style="cursor:pointer; background:linear-gradient(135deg,#667eea,#764ba2); color:white; border:none;" title="Click to see who submitted">
            <p class="stat-label" style="color:rgba(255,255,255,0.8);">👥 Participation</p>
           <p class="stat-main-value" style="color:white; font-size:2rem; font-weight:800;">${participation}${totalStudents > 0 ? '%' : ''}</p>
            <p class="stat-sub-text" style="color:rgba(255,255,255,0.7);">${participationSubText}</p>
        </div>
        <div class="stat-card" style="background:linear-gradient(135deg,#11998e,#38ef7d); color:white; border:none;">
            <p class="stat-label" style="color:rgba(255,255,255,0.8);">🎯 Average Score</p>
            <p class="stat-main-value" style="color:white; font-size:2rem; font-weight:800;">${averageScore !== 'N/A' ? averageScore + '%' : 'N/A'}</p>
        </div>
        <div class="stat-card" style="background:linear-gradient(135deg,#f7971e,#ffd200); color:white; border:none;">
            <p class="stat-label" style="color:rgba(255,255,255,0.8);">🏆 Highest Score</p>
            <p class="stat-main-value" style="color:white; font-size:2rem; font-weight:800;">${highestScore !== 'N/A' ? highestScore + '%' : 'N/A'}</p>
        </div>
        <div class="stat-card" style="background:linear-gradient(135deg,#eb3349,#f45c43); color:white; border:none;">
            <p class="stat-label" style="color:rgba(255,255,255,0.8);">📉 Lowest Score</p>
            <p class="stat-main-value" style="color:white; font-size:2rem; font-weight:800;">${lowestScore !== 'N/A' ? lowestScore + '%' : 'N/A'}</p>
        </div>
    `;
    // --- END OF FIX 2 ---

    resultsSummaryStatsContainerEl.querySelector('#participation-stat-card')?.addEventListener('click', () => {
        const submittedStudents = currentSubmissionsForResults.map(s => ({ name: s.studentName, id: s.studentId }));
        displayStudentListInModal('Submission Status', submittedStudents, currentRosterForResults?.students);
    });
}
// PASTE THIS ENTIRE NEW PLUGIN OBJECT
const centerTextPlugin = {
  id: 'centerText',
  afterDraw: (chart: any) => {
    if (chart.config.type === 'doughnut') {
      const ctx = chart.ctx;
      const { width, height } = chart;
      const total = chart.data.datasets[0].data.reduce((a: number, b: number) => a + b, 0);

      ctx.save();
      ctx.font = 'bold 2.5rem ' + window.Chart.defaults.font.family;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = 'var(--text-primary)';
      const text = `${total}`;
      const textX = width / 2;
      const textY = height / 2;
      ctx.fillText(text, textX, textY - 10);
      
      ctx.font = '1rem ' + window.Chart.defaults.font.family;
      ctx.fillStyle = 'var(--text-secondary)';
      const subText = 'Students';
      ctx.fillText(subText, textX, textY + 20);
      
      ctx.restore();
    }
  }
};


// Copy and paste this entire corrected function
function displayScoreDistributionChart() {
    if (scoreChartInstance) {
        scoreChartInstance.destroy();
    }

    if (currentSubmissionsForResults.length === 0) {
        resultsScoreDistributionContainerEl.innerHTML = '<p class="info-text">No submissions with scores available to display a chart.</p>';
        return;
    }

    resultsScoreDistributionContainerEl.innerHTML = `<canvas id="results-score-chart"></canvas>`;
    const newChartCanvas = document.getElementById('results-score-chart') as HTMLCanvasElement;

    const scoreData = currentSubmissionsForResults.map(s => s.score);

    const labels = ["Below 40% (Needs Attention)", "41-70% (Developing)", "Above 70% (Proficient)"];
    const bins = [0, 0, 0];
    
    scoreData.forEach(percentage => {
        if (percentage <= 40) bins[0]++;
        else if (percentage <= 70) bins[1]++;
        else bins[2]++;
    });

    // Define vibrant, distinct colors for the pie chart slices.
    const sliceColors = ['#e74c3c', '#f1c40f', '#2ecc71'];
    const hoverSliceColors = ['#c0392b', '#d4ac0d', '#27ae60'];

    const ctx = newChartCanvas.getContext('2d');
    if (!ctx) return;

    // Register our custom plugin to be used with this chart instance.
    window.Chart.register(centerTextPlugin);

    scoreChartInstance = new window.Chart(ctx, {
        type: 'doughnut', // Changed from 'bar' to 'doughnut'
        data: {
            labels: labels,
            datasets: [{
                label: '# of Students',
                data: bins,
                backgroundColor: sliceColors,
                hoverBackgroundColor: hoverSliceColors,
                borderColor: '#ffffff', // Adds a clean border between slices
                borderWidth: 4,
                hoverOffset: 15 // Makes the selected slice pop out
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            cutout: '60%', // This creates the "doughnut" hole
            plugins: {
                legend: {
                    position: 'right', // Moves legend to the side for a cleaner look
                    labels: {
                        boxWidth: 20,
                        padding: 20,
                        font: {
                            size: 14
                        }
                    }
                },
                tooltip: {
                    callbacks: {
                        label: function(context: any) {
                            let label = context.label || '';
                            if (label) {
                                label += ': ';
                            }
                            const value = context.parsed;
                            const total = context.dataset.data.reduce((a: number, b: number) => a + b, 0);
                            const percentage = total > 0 ? (value / total * 100).toFixed(1) : 0;
                            label += `${value} student(s) (${percentage}%)`;
                            return label;
                        }
                    }
                }
            }
        }
    });
}

function preSummarizeClassPerformance(submissions: Submission[], homework: Homework): object {
    if (!submissions || submissions.length === 0) return {};

    let totalScoreSum = 0;
    const topicWeaknesses: Record<string, number> = {};
    const questionPerformance: Record<string, { totalScore: number; totalMaxScore: number; count: number; text: string }> = {};

    for (const sub of submissions) {
        if (!sub.detailedReport?.questionDetails) continue;
        totalScoreSum += sub.score;

        for (const qd of sub.detailedReport.questionDetails) {
            const topic = qd.questionTopic || 'General';
            const feedback = qd.aiFeedback;
            if (!feedback) continue;

            const maxScore = feedback.maxScore || 10;
            const score = feedback.score || 0;
            
            if (!questionPerformance[qd.questionId]) {
                questionPerformance[qd.questionId] = { totalScore: 0, totalMaxScore: 0, count: 0, text: qd.questionText };
            }
            questionPerformance[qd.questionId].totalScore += score;
            questionPerformance[qd.questionId].totalMaxScore += maxScore;
            questionPerformance[qd.questionId].count++;

            if (score < maxScore * 0.5) {
                topicWeaknesses[topic] = (topicWeaknesses[topic] || 0) + 1;
            }
        }
    }

    const averageClassScore = submissions.length > 0 ? (totalScoreSum / submissions.length).toFixed(1) : "N/A";

    const topWeaknesses = Object.entries(topicWeaknesses)
        .sort(([, countA], [, countB]) => countB - countA)
        .slice(0, 3)
        .map(([topic, count]) => ({ topic, count }));

    const lowestScoringQuestions = Object.values(questionPerformance)
        .map(q => ({
            text: q.text,
            averagePercentage: q.totalMaxScore > 0 ? (q.totalScore / q.totalMaxScore) * 100 : 0
        }))
        .sort((a, b) => a.averagePercentage - b.averagePercentage)
        .slice(0, 3)
        .map(q => q.text);

    return {
        homeworkContext: {
            subject: homework.subject,
            topic: homework.customTopic || homework.selectedChapters?.join(', ') || 'N/A',
            submissionCount: submissions.length,
        },
        performanceSummary: {
            averageClassScore: `${averageClassScore}%`,
            topicsStudentsStruggledWith: topWeaknesses,
            lowestScoringQuestions: lowestScoringQuestions,
        }
    };
}

async function displayClassAISummary(forceRefresh = false) {
    resultsClassAISummaryCardEl.style.display = 'block';
    const targetEl = document.getElementById('ai-summary-content-target') as HTMLDivElement;
    const timestampEl = document.getElementById('summary-timestamp') as HTMLSpanElement;

    if (!currentHomeworkForResults) {
        targetEl.innerHTML = `<p class="error-text">Could not generate summary because homework data is missing.</p>`;
        return;
    }

    const detailedSubmissions = currentSubmissionsForResults.filter(s => s.detailedReport?.questionDetails?.length > 0);
    if (detailedSubmissions.length < 1) {
        resultsClassAISummaryCardEl.style.display = 'none';
        return;
    }

    if (currentHomeworkForResults.aiClassSummary && !forceRefresh) {
        targetEl.innerHTML = currentHomeworkForResults.aiClassSummary;
        if (currentHomeworkForResults.summaryLastUpdated) {
            timestampEl.textContent = `Last generated: ${new Date(currentHomeworkForResults.summaryLastUpdated).toLocaleString()}`;
        }
        return;
    }

    targetEl.innerHTML = `<div class="spinner-container"><div class="spinner-small"></div> <p>Generating new class insights...</p></div>`;

    try {
        const summaryData = preSummarizeClassPerformance(detailedSubmissions, currentHomeworkForResults);

        const prompt = `
            You are an expert educational analyst AI. Your task is to provide deep, actionable insights to a teacher based on a class's performance on a homework assignment.

            **CRITICAL TASK: GRANULAR TOPIC ANALYSIS & QUANTIFICATION**
            1.  **Go Deeper:** Analyze the provided performance data to identify specific academic concepts or skills.
            2.  **Calculate Percentages:** For every concept you identify:
                -   **Weakness:** Calculate the percentage of students who struggled with it.
                -   **Strength:** Calculate the percentage of students who mastered it.
            3.  **Mandatory Sorting:** Your final 'strengths' and 'weaknesses' arrays MUST be sorted in descending order by percentage.
            4.  ${LATEX_MATH_INSTRUCTIONS}

            **YOUR TASK & OUTPUT FORMAT:**
            Based on your analysis, provide a report as a single, valid JSON object that strictly adheres to the schema below.

**JSON Schema to Follow:**
    {
      "overallPerformance": "A brief summary of performance trends in Markdown.",
      "categoryAnalysis": {
        "Conceptual": [{ "topic": "keyword", "percentage": 0 }],
        "Applicational": [{ "topic": "keyword", "percentage": 0 }],
        "Analytical": [{ "topic": "keyword", "percentage": 0 }],
        "Calculation": [{ "topic": "keyword", "percentage": 0 }]
      },
      "remedialActionPlan": "A highly detailed list of actionable steps in Markdown. Wrap academic topics in @@topic@@ markers."
    }

            **Data for Your Analysis:**
            ${JSON.stringify(summaryData, null, 2)}
        `;

        const responseSchema = {
            type: Type.OBJECT,
            properties: {
                overallPerformance: { type: Type.STRING },
                strengths: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { topic: { type: Type.STRING }, percentage: { type: Type.NUMBER } } } },
                weaknesses: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { topic: { type: Type.STRING }, percentage: { type: Type.NUMBER } } } },
                remedialActionPlan: { type: Type.STRING }
            },
            required: ["overallPerformance", "strengths", "weaknesses", "remedialActionPlan"]
        };

        const response = await getAiInstance().models.generateContent({
            model: 'gemini-2.5-flash',
            contents: prompt,
            config: { 
    responseMimeType: "application/json", 
    responseSchema: responseSchema,
    temperature: 0,
    maxOutputTokens: 800, // Summaries should be concise
    thinkingConfig: { thinkingBudget: 0 }
}
        });

        const aiReport = JSON.parse(response.text.trim());

       // FIX: formatMathExpressions already handles marked.parse. Double parsing breaks math.
const overallHtml = formatMathExpressions(aiReport.overallPerformance);

const rawRemedial = aiReport.remedialActionPlan || "";
const processedRemedialPlan = rawRemedial.replace(/@@topic@@(.*?)@@topic@@/g, '<span class="remedial-topic-pill">$1</span>');
const remedialHtml = formatMathExpressions(processedRemedialPlan);

// Generate the table for Strengths and Weaknesses
        const tableHtml = `
            <div class="strengths-weaknesses-table">
                <div class="sw-column">
                    <h4>💪 Class Strengths</h4>
                    <div class="pills-container">
                        ${aiReport.strengths?.map((s: any) => `
                            <div class="topic-pill strength">
                                <span class="topic-name">${s.topic}</span>
                                <span class="topic-percentage">${Number(s.percentage).toFixed(0)}% mastery</span>
                            </div>
                        `).join('') || '<p class="description">No major strengths identified yet.</p>'}
                    </div>
                </div>
                <div class="sw-column">
                    <h4>📉 Areas for Improvement</h4>
                    <div class="pills-container">
                        ${aiReport.weaknesses?.map((w: any) => `
                            <div class="topic-pill weakness">
                                <span class="topic-name">${w.topic}</span>
                                <span class="topic-percentage">${Number(w.percentage).toFixed(0)}% affected</span>
                            </div>
                        `).join('') || '<p class="description">No major weaknesses identified.</p>'}
                    </div>
                </div>
            </div>
        `;

const finalHtml = `
    <h3>Overall Class Performance</h3>
    <div>${overallHtml}</div>
    ${tableHtml}
    <h3>💡 Remedial Action Plan</h3>
    <div>${remedialHtml}</div>
`;

targetEl.innerHTML = finalHtml;

        const now = new Date().toISOString();
        await fbFirestore.collection('homeworks').doc(currentHomeworkForResults.homeworkId).update({
            aiClassSummary: finalHtml,
            summaryLastUpdated: now
        });

        currentHomeworkForResults.aiClassSummary = finalHtml;
        currentHomeworkForResults.summaryLastUpdated = now;
        timestampEl.textContent = `Last generated: ${new Date(now).toLocaleString()}`;
        await typesetMathInContainer(targetEl);

    } catch (error) {
        console.error("Error generating/streaming class AI summary:", error);
        targetEl.innerHTML = `<p class="error-text"><strong>Could not generate AI summary.</strong> The AI service may be temporarily unavailable.</p>`;
    }
}

