/**
 * Opens the Assessment Checker UI pre-loaded with student submissions for a homework.
 * Teacher can then grade each student's submitted answer sheets.
 */
async function handleGradeHomeworkSubmissions(homework: Homework) {
    if (!teacherProfile) return;
    if (!homework || !homework.homeworkId) {
        showFeedbackMessage("Invalid homework selected.", "error");
        return;
    }

    toggleLoading(true, "Loading student submissions...");

    try {
        // Fetch pending submissions from Firestore
        const snap = await fbFirestore.collection('completedHomeworkSubmissions')
            .where('homeworkId', '==', homework.homeworkId)
            .where('createdByTeacherUid', '==', teacherProfile.uid)
            .get();

        // Build a fake CreatedAssessment object so we can reuse the assessment checker
        const fakeAssessment: CreatedAssessment = {
            assessmentId: `hw_grade_${homework.homeworkId}`,
            assessmentTitle: `HW: ${homework.customTopic || homework.selectedChapters?.join(', ') || homework.subject}`,
            createdByTeacherUid: homework.createdByTeacherUid,
            teacherName: homework.teacherName || '',
            schoolName: homework.schoolName || '',
            board: homework.board || '',
            subject: homework.subject,
            className: homework.className || homework.targetClass || '',
            section: homework.section || homework.targetSection || '',
            questions: (homework.questions || []) as any,
            creationTimestamp: homework.creationTimestamp,
            source: 'question_images',
            totalMarks: homework.totalMarks || 0,
            difficultyLevel: homework.difficultyLevel,
            checkingStrictness: homework.checkingStrictness,
        };

        // Pre-load student answer sheets from Firestore submissions
        (window as any)._homeworkSubmissionUrls = {};
        
        // Helper to resolve a value that might be a storage path or already a URL
        const resolveToDownloadUrl = async (val: string): Promise<string> => {
            if (val.startsWith('https://')) return val; // already a download URL
            // It's a storage path — resolve via getDownloadURL
            return fbStorage.ref(val).getDownloadURL();
        };

        for (const doc of snap.docs) {
            const data = doc.data() as any;
            const key = data.studentUid || data.studentId || data.studentEmail;
            const rawUrls: string[] = data.answerSheetImageUrls || data.imageUrls || data.submittedAnswerImagesBase64 || [];
            
            if (key && rawUrls.length) {
                try {
                    // Resolve all paths/URLs to actual download URLs
                    const resolvedUrls = await Promise.all(rawUrls.map(resolveToDownloadUrl));
const entry = {
    urls: resolvedUrls,
    studentName: data.studentName,
    submissionDocId: doc.id,
    studentUid: data.studentUid || data.studentId || key,
};
if (data.studentUid) (window as any)._homeworkSubmissionUrls[data.studentUid] = entry;
if (data.studentId)  (window as any)._homeworkSubmissionUrls[data.studentId]  = entry;
if (data.studentEmail) (window as any)._homeworkSubmissionUrls[data.studentEmail] = entry;
if (!data.studentUid && !data.studentId && !data.studentEmail) {
    (window as any)._homeworkSubmissionUrls[key] = entry; // fallback
}
                } catch (resolveErr) {
                    console.warn(`[HomeworkGrade] Could not resolve URLs for ${key}:`, resolveErr);
                    // Still store raw URLs as fallback
                    (window as any)._homeworkSubmissionUrls[key] = {
                        urls: rawUrls,
      studentName: data.studentName,
    submissionDocId: doc.id,
    studentUid: key,
                    };
                }
            }
        }

        if (snap.empty) {
            showFeedbackMessage("No student submissions found for this homework yet.", "info", true);
            toggleLoading(false);
            return;
        }

        // Navigate to assessment checker with this homework context
        currentAssessmentToGrade = fakeAssessment;
        (window as any)._isGradingHomework = true;
        (window as any)._currentGradingHomework = homework;
        assessmentReports = [];
        localStudentFiles.clear();
        assessmentStudentFiles.clear();
    studentPreUploadedData.clear();
        assessmentStudentStrictness.clear();

        toggleLoading(false);
        updateUIVisibility('teacher_assessment_checker');

    } catch (err) {
        toggleLoading(false);
        showFeedbackMessage(`Error loading submissions: ${(err as Error).message}`, "error", true);
    }
}

// The student app's self-grading writes a DIFFERENT report shape than the exam grader:
// detailedReport.questionDetails[] with {questionText, marksAwarded, maxMarks, aiFeedback:{...}}
// instead of the exam-style questionWiseReport[] with {questionNumber, finalFeedback,
// stepWiseEvaluation, ...} that the shared report viewer (teacher_assessment_individual_report)
// actually reads. Reading detailedReport.questionWiseReport directly (as the old code did)
// always returned [] since that field never existed on homework submissions — this adapter
// converts the real shape into the one the viewer expects, matched against the homework's own
// questions[] (by id) to recover fields the submission itself doesn't carry, like questionNumber.
function mapHomeworkQuestionDetailToAIQuestionReport(qd: any, hq: AIQuestion | undefined): AIQuestionReport {
    const fb = qd.aiFeedback || {};
    return {
        questionNumber: hq?.questionNumber || qd.questionNumber || String(qd.questionId || ''),
        type: hq?.type || undefined,
        marksAwarded: typeof qd.marksAwarded === 'number' ? qd.marksAwarded : (fb.score ?? 0),
        maxMarksForQuestion: qd.maxMarks ?? hq?.marks ?? 0,
        stepWiseEvaluation: Array.isArray(fb.stepWiseEvaluation) ? fb.stepWiseEvaluation.map((s: any) => ({
            stepDescription: s.stepDescription || s.description || s.comment || '',
            marks: s.marks ?? 0,
            comment: s.comment || '',
            pageIndex: s.pageIndex,
            stepPoint: s.stepPoint,
        })) : [],
        finalFeedback: fb.scoreReasoning || '',
        feedbackStrengths: Array.isArray(fb.strengths) ? fb.strengths : [],
        feedbackGaps: Array.isArray(fb.weaknesses) ? fb.weaknesses : [],
        feedbackSuggestion: fb.improvementTips || '',
        modelAnswer: fb.fullCorrectAnswer || hq?.answer || '',
        topic: qd.questionTopic || hq?.topic || '',
        questionText: qd.questionText || hq?.text || '',
        studentOcrAnswer: qd.studentAnswerText || undefined,
        requiresReview: !!fb.requiresReview,
    };
}

function mapHomeworkDetailedReportToQuestionWiseReport(detailedReport: any, hwQuestions: AIQuestion[]): AIQuestionReport[] {
    const details = detailedReport?.questionDetails;
    if (!Array.isArray(details)) return [];
    const questionsById = new Map(hwQuestions.map(q => [q.id, q]));
    return details.map((qd: any) => mapHomeworkQuestionDetailToAIQuestionReport(qd, questionsById.get(qd.questionId)));
}

async function handleViewHomeworkReport(submissionDocId: string) {
    if (!teacherProfile || !currentHomeworkForResults) return;
    toggleLoading(true, "Loading report...");

    try {
        // Fetched via the backend (admin privileges), not a direct client-side Firestore read —
        // studentGradingResults (where the real per-question images live) is scoped to the
        // owning student, so a teacher's own client-side read of it is blocked by security rules.
        const backendResp = await fetch(GET_HOMEWORK_SUBMISSION_REPORT_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ submissionDocId, teacherUid: teacherProfile.uid })
        });

        if (!backendResp.ok) {
            showFeedbackMessage("Report not found.", "error");
            toggleLoading(false);
            return;
        }

        const { submission: data, gradingResult: gradingResultData } = await backendResp.json();

const rawUrls: string[] = data.answerSheetImageUrls
    || data.imageUrls
    || data.submittedAnswerImageUrls
    || data.studentAnswerImageUrls
    || [];

// Store storage PATHS (not URLs) — paths never expire, URLs do
// Extract path from Firebase URL if it's already a URL
const storagePaths: string[] = rawUrls.map((val: string) => {
    if (!val) return '';
    if (val.startsWith('data:') || val.length > 500) return val; // base64, keep as-is
    if (val.startsWith('https://firebasestorage.googleapis.com')) {
        try {
            const pathMatch = new URL(val).pathname.match(/\/o\/([^?]+)/);
            return pathMatch ? decodeURIComponent(pathMatch[1]) : val;
        } catch { return val; }
    }
    return val; // already a path
});

// Get fresh download URLs RIGHT NOW (not cached)
const resolvedUrls: string[] = await Promise.all(storagePaths.map(async (val: string) => {
    if (!val) return '';
    if (val.startsWith('data:') || val.length > 500) return val;
    if (val.startsWith('https://')) return val; // non-Firebase URL, use as-is
    try { return await fbStorage.ref(val).getDownloadURL(); } catch { return val; }
}));

        const hw = currentHomeworkForResults!;

        // The summary doc (completedHomeworkSubmissions) never carries the full per-question
        // report — objective (MCQ) questions are in data.objectiveReport here, but subjective
        // ones (with real answer images, one per question — perQuestionMode) live in a SEPARATE
        // document: studentGradingResults/{gradingJobId}, already in the exact AIQuestionReport
        // shape the exam report viewer expects (this is the same backend grading output exams
        // use). The backend call above already fetched and returned both; fall back to the
        // best-effort detailedReport adapter only for older submissions with no gradingJobId.
        let questionWiseReport: AIQuestionReport[];
        if (gradingResultData && Array.isArray(gradingResultData.questionWiseReport)) {
            questionWiseReport = [
                ...(Array.isArray(data.objectiveReport) ? data.objectiveReport : []),
                ...gradingResultData.questionWiseReport,
            ];
        } else {
            questionWiseReport = mapHomeworkDetailedReportToQuestionWiseReport(data.detailedReport, hw.questions || []);
        }

        // Build report object in same shape as exam reports
       const report: AIFullAssessmentReport = {
            ...(data.detailedReport || {}),
            studentName: data.studentName || '',
            studentUid: data.studentUid || data.studentId || '',
            overallScore: data.score ?? data.detailedReport?.overallScore ?? 0,
           maximumMarks: hw.totalMarks ?? data.maximumMarks ?? data.detailedReport?.maximumMarks ?? 0,
            questionWiseReport,
            answerSheetImageUrls: resolvedUrls.filter(Boolean),
            submissionDocId,
            gradingTimestamp: data.gradedAt || data.detailedReport?.gradingTimestamp || '',
            subject: hw.subject,
            published: data.published ?? false,
            teacherVerified: data.teacherVerified ?? false,
            teacherVerifications: data.teacherVerifications ?? {},
        };

        // Build assessment context so all exam report functions work
        const fakeAssessment: CreatedAssessment = {
            assessmentId: `hw_grade_${hw.homeworkId}`,
            assessmentTitle: `HW: ${hw.customTopic || hw.selectedChapters?.join(', ') || hw.subject}`,
            createdByTeacherUid: hw.createdByTeacherUid,
            teacherName: hw.teacherName || '',
            schoolName: hw.schoolName || '',
            board: hw.board || '',
            subject: hw.subject,
            className: hw.className || (hw as any).targetClass || '',
            section: hw.section || (hw as any).targetSection || '',
            questions: (hw.questions || []) as any,
            creationTimestamp: hw.creationTimestamp,
            source: 'question_images',
            totalMarks: hw.totalMarks || 0,
            difficultyLevel: hw.difficultyLevel,
            checkingStrictness: hw.checkingStrictness,
        };

        // Set global state — exactly like the exam path does
(report as any)._isHomeworkReport = true;
(report as any)._homeworkGradingMode = hw.gradingMode;
assessmentReports = [report];
currentAssessmentToGrade = fakeAssessment;
currentAssessmentForReportView = fakeAssessment;
currentAssessmentRoster = [];

        toggleLoading(false);

        // Navigate to the full exam-style individual report view
        updateUIVisibility('teacher_assessment_individual_report', { studentUid: report.studentUid });

    } catch (err) {
        toggleLoading(false);
        showFeedbackMessage(`Error loading report: ${(err as Error).message}`, "error");
    }
}

