function prepareImageBasedHomeworkForm(type: 'book' | 'myq') {
    if (!teacherProfile) return;

    const isBook = type === 'book';
    const formSection = isBook ? teacherHomeworkCreationBookImagesSectionEl : teacherHomeworkCreationQuestionImagesSectionEl;
    const dueDateEl = formSection.querySelector('input[type="date"]') as HTMLInputElement;
    const subjectEl = formSection.querySelector<HTMLSelectElement>('.hw-subject-select')!;
    const classEl = formSection.querySelector<HTMLSelectElement>('.hw-class-select')!;
    const sectionEl = formSection.querySelector<HTMLSelectElement>('.hw-section-select')!;
    const customSectionEl = formSection.querySelector<HTMLInputElement>('.hw-section-custom')!;
    const topicEl = formSection.querySelector<HTMLInputElement>('.hw-topic-input')!;
    const checkingStrictnessEl = formSection.querySelector<HTMLSelectElement>('.hw-strictness-select')!;
    const imagePreviewAreaEl = isBook 
        ? formSection.querySelector<HTMLDivElement>('.image-preview-area')!
        : document.getElementById('hw-myq-image-preview-area') as HTMLDivElement;
    const imageUploads = isBook ? uploadedBookPageImages : uploadedQuestionImages;

    // Reset common fields
    dueDateEl.value = '';
    topicEl.value = '';
    imageUploads.length = 0;
    if (imagePreviewAreaEl) imagePreviewAreaEl.innerHTML = '<p class="image-preview-placeholder">No images uploaded yet.</p>';
    const fileInput = isBook 
        ? formSection.querySelector('input[type="file"]') as HTMLInputElement
        : document.getElementById('hw-myq-image-upload-input') as HTMLInputElement;
    if (fileInput) fileInput.value = '';

    topicEl.required = false;

    // Populate dropdowns
    populateSubjectDropdownForHomeworkCreation([subjectEl]);
    populateClassDropdowns([classEl]);
    populateSectionDropdowns(sectionEl, customSectionEl);
    
    prefillAndDisableHomeworkClassDetails(subjectEl, classEl, sectionEl, customSectionEl);

    // Pre-fill if copying
    if (isCopyingHomework && temporaryHomeworkData.source === (isBook ? 'book_images' : 'question_images')) {
        subjectEl.value = temporaryHomeworkData.subject || '';
        classEl.value = temporaryHomeworkData.className || '';
        sectionEl.value = temporaryHomeworkData.section || '';
        topicEl.value = temporaryHomeworkData.customTopic || '';
        if (isBook) {
            const questionTypeEl = formSection.querySelector<HTMLSelectElement>('.hw-qtype-select')!;
            const numQuestionsEl = formSection.querySelector<HTMLInputElement>('.hw-num-q-select');
            const difficultyEl = formSection.querySelector<HTMLSelectElement>('.hw-difficulty-select')!;
            questionTypeEl.value = temporaryHomeworkData.questionType || 'Subjective';
            if (numQuestionsEl && temporaryHomeworkData.numberOfQuestions) numQuestionsEl.value = temporaryHomeworkData.numberOfQuestions.toString();
            difficultyEl.value = temporaryHomeworkData.difficultyLevel || 'Medium';
        }
        checkingStrictnessEl.value = temporaryHomeworkData.checkingStrictness || 'Medium';
        isCopyingHomework = false;
    }
}

