// Renders a homework/"My Questions" review card using the same createQuestionCardHtml()
// builder the Exams flow uses (see appendAndRenderAssessmentQuestionCard), so MCQ options,
// the model answer, the rubric/step-marking, and OCR/topic-anchor tags all render the same
// way for Assignments as they do for Exams. Previously this function built its own separate,
// incomplete HTML (no rubric section at all, and a `.split('<div class="question-text">')[0]`
// expression that always evaluated to an empty string, so MCQ options never rendered).
async function appendAndRenderQuestionCard(q: AIQuestion, index: number, container: HTMLElement, imageFiles: File[]) {
    const isKept = q.kept !== false;

    const questionCard = document.createElement('div');
    questionCard.className = `ai-question-review-card ${isKept ? 'kept' : ''}`;
    questionCard.id = `review-q-${index}`;
    questionCard.innerHTML = createQuestionCardHtml(q, index, 'homework');

    container.appendChild(questionCard);
    await typesetMathInContainer(questionCard);

    if (q.imagePrompt && temporaryHomeworkData.source === 'book_images') {
        cropImageForQuestion(index, imageFiles);
    }
}


async function displayAIQuestionsForReview() {
    const container = aiQuestionsPreviewContainerEl;
    container.innerHTML = ''; // It's safe to clear here, as it's a one-time render
// This is the CORRECTED line
if (!temporaryHomeworkData.questions || temporaryHomeworkData.questions.length === 0) {
    return;
}
    
    const imageFiles = temporaryHomeworkData.source === 'book_images' ? uploadedBookPageImages : [];

    for (const [index, q] of temporaryHomeworkData.questions.entries()) {
        // We don't await here because we can render all math at the end
        appendAndRenderQuestionCard(q, index, container, imageFiles);
    }
    // A final call to render math on the entire container can be done here if needed,
    // but the append function already handles it individually.
}

