window.handleSingleGenChapterChange = () => {
    const chapterSelect = document.getElementById('single-gen-chapter') as HTMLSelectElement;
    const topicSelect = document.getElementById('single-gen-topics') as HTMLSelectElement;
    const selectedChapter = chapterSelect.value;
    const currentSubject = chapterSelect.dataset.subject;
    const currentClass = chapterSelect.dataset.className;

    topicSelect.innerHTML = ''; 

    if (!selectedChapter || !currentSubject || !teacherProfile) {
        topicSelect.innerHTML = '<option value="" disabled>-- Select Chapter First --</option>';
        return;
    }

    const normalizedSubject = normalizeForComparison(currentSubject);
    const normalizedClass = normalizeForComparison(currentClass);
    const normalizedBoard = normalizeForComparison(teacherProfile.board); // <--- Added Board Normalization

    // Filter topics by Subject, Chapter, Class AND Board
    const relevantTopics = allTopicsFromCSV.filter(t => 
        normalizeForComparison(t.Subject) === normalizedSubject &&
        t['Chapter Name'].trim() === selectedChapter &&
        (!normalizedClass || normalizeForComparison(t.Class) === normalizedClass) &&
        (!normalizedBoard || normalizeForComparison(t.Board) === normalizedBoard) // <--- Added Board Filter
    ).map(t => t['Subtopic Name'].trim());

    const uniqueTopics = [...new Set(relevantTopics)].sort();

    if (uniqueTopics.length > 0) {
        topicSelect.innerHTML = uniqueTopics.map(t => `<option value="${t}">${t}</option>`).join('');
    } else {
        topicSelect.innerHTML = '<option value="" disabled>No topics found</option>';
    }
};

window.cancelQuestionEdit = (index: number) => {
     const card = document.getElementById(`review-q-${index}`);
    if (card) {
        (card.querySelector('.question-view-mode') as HTMLElement).style.display = 'block';
        (card.querySelector('.question-edit-mode') as HTMLElement).style.display = 'none';
        
        const questionTextarea = card.querySelector('.question-edit-textarea') as HTMLTextAreaElement;
        const answerTextarea = card.querySelector('.answer-edit-textarea') as HTMLTextAreaElement;
        const marksInput = card.querySelector('.marks-edit-input') as HTMLInputElement;
        // --- THIS IS THE NEW LINE ---
        const instructionsTextarea = card.querySelector('.instructions-edit-textarea') as HTMLTextAreaElement;

        if (temporaryHomeworkData.questions) {
            const originalQuestion = temporaryHomeworkData.questions[index];
            questionTextarea.value = originalQuestion.text;
            if (answerTextarea) {
                 answerTextarea.value = originalQuestion.answer || '';
            }
            if (marksInput) {
                marksInput.value = (originalQuestion.marks || 5).toString();
            }
            // --- THIS IS THE NEW LINE ---
            if (instructionsTextarea) {
                instructionsTextarea.value = originalQuestion.checkingInstructions || '';
            }

              // --- ADD THIS BLOCK ---
            const rubricKeywordsInput = card.querySelector('.rubric-keywords-edit-input') as HTMLInputElement;
            const rubricStepsInput = card.querySelector('.rubric-steps-edit-input') as HTMLTextAreaElement;
            
            if (originalQuestion.rubric) {
                if (rubricKeywordsInput) rubricKeywordsInput.value = originalQuestion.rubric.keywords.join(', ');
                if (rubricStepsInput) rubricStepsInput.value = originalQuestion.rubric.step_marking;
            } else {
                if (rubricKeywordsInput) rubricKeywordsInput.value = '';
                if (rubricStepsInput) rubricStepsInput.value = '';
            }
            // ---------------------
        }
    }
};

