async function handleDownloadAllReports() {
    if (!assessmentReports || assessmentReports.length === 0) {
        showFeedbackMessage("No graded reports found. Please grade students first.", "error");
        return;
    }

    const btn = document.getElementById('download-all-reports-btn') as HTMLButtonElement | null;
    if (btn) { btn.disabled = true; btn.textContent = '⏳ Preparing…'; }

    const loadScript = (src: string): Promise<void> => new Promise((resolve, reject) => {
        if (document.querySelector(`script[src="${src}"]`)) { resolve(); return; }
        const s = document.createElement('script');
        s.src = src; s.onload = () => resolve(); s.onerror = () => reject();
        document.head.appendChild(s);
    });

    try {
        await loadScript('https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js');
        await loadScript('https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js');
    } catch {
        showFeedbackMessage("Could not load PDF libraries.", "error");
        if (btn) { btn.disabled = false; btn.textContent = '📦 Download All PDFs'; }
        return;
    }

    const JSZip = (window as any).JSZip;
    const html2canvas = (window as any).html2canvas;
    const { jsPDF } = (window as any).jspdf;

    if (!JSZip || !html2canvas || !jsPDF) {
        showFeedbackMessage("Required libraries not available.", "error");
        if (btn) { btn.disabled = false; btn.textContent = '📦 Download All PDFs'; }
        return;
    }

// Offscreen render container — placed off-screen LEFT so browser computes full layout
    const offscreen = document.createElement('div');
    offscreen.style.cssText = `
        position: fixed; top: 0; left: -9999px;
        width: 794px; background: #ffffff;
        pointer-events: none; z-index: -1;
    `;
    offscreen.classList.add('pdf-render-context');
    document.body.appendChild(offscreen);

    const zip = new JSZip();
    const reportTitle = currentAssessmentToGrade?.assessmentTitle || currentAssessmentTitle || 'Assessment';
    const className = currentAssessmentToGrade?.className || 'Class';
    const section = currentAssessmentToGrade?.section || '';
    const subject = currentAssessmentToGrade?.subject || 'Subject';
    const classLabel = section ? `${className}-${section}` : className;

    isBatchDownloading = true;
    let successCount = 0;

    for (let i = 0; i < assessmentReports.length; i++) {
        const report = assessmentReports[i];
        if (btn) btn.textContent = `⏳ ${i + 1}/${assessmentReports.length} — ${report.studentName}`;

        try {
            // Get the fully built HTML from individual report function
            const reportHtml = await handleDownloadIndividualReport(i) as unknown as string;
            if (!reportHtml) continue;

            // Render into offscreen div
            offscreen.innerHTML = reportHtml;
            await typesetMathInContainer(offscreen);

            // Wait for images
            const imgs = Array.from(offscreen.querySelectorAll('img')) as HTMLImageElement[];
            await Promise.all(imgs.map(img => {
                if (img.complete && img.naturalWidth > 0) return Promise.resolve();
                return new Promise<void>(res => { img.onload = () => res(); img.onerror = () => res(); });
            }));
            await new Promise(r => setTimeout(r, 800));

            // Find page-break divs — each top-level child of the report wrapper is one "page"
            const wrapper = offscreen.querySelector('div') as HTMLElement;
            const pageEls = wrapper ? Array.from(wrapper.children) as HTMLElement[] : [offscreen];
            
// Match @page { size: 200mm 200mm } used in individual print
            const PAGE_MM = 200;
            const pdfDoc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: [PAGE_MM, PAGE_MM] });
            const pageW = pdfDoc.internal.pageSize.getWidth();   // 200
            const pageH = pdfDoc.internal.pageSize.getHeight();  // 200
// Match offscreen container width exactly so absolute-positioned OSM markers render correctly
            const RENDER_PX = 794;
            let isFirstPage = true;

// Capture each page element individually — offscreen is always fully laid out
            for (const pageEl of pageEls) {
                if (!pageEl.innerHTML?.trim()) continue;

                pageEl.style.width = `${RENDER_PX}px`;
                pageEl.style.pageBreakBefore = 'unset';
                pageEl.style.pageBreakAfter = 'unset';

                // Two rAF ticks to ensure browser has reflowed
                await new Promise(r => requestAnimationFrame(r));
                await new Promise(r => requestAnimationFrame(r));

const canvas = await html2canvas(pageEl as HTMLElement, {
                    scale: 3,
                    useCORS: true,
                    allowTaint: true,
                    backgroundColor: '#ffffff',
                    logging: false,
                    windowWidth: RENDER_PX,
                    imageTimeout: 15000,
                });

                if (canvas.width === 0 || canvas.height === 0) continue;

const imgData = canvas.toDataURL('image/png');
                const imgH = pageW * (canvas.height / canvas.width);

                if (!isFirstPage) pdfDoc.addPage();
                isFirstPage = false;

                let yOffset = 0;
                while (yOffset < imgH) {
                    if (yOffset > 0) pdfDoc.addPage();
                    pdfDoc.addImage(imgData, 'JPEG', 0, -yOffset, pageW, imgH);
                    yOffset += pageH;
                }
            }

            if (isFirstPage) continue; // nothing was added

const pdfBlob = pdfDoc.output('arraybuffer');
            const fileName = `${sanitizeForFilename(report.studentName)}_${sanitizeForFilename(reportTitle)}_${sanitizeForFilename(classLabel)}_${sanitizeForFilename(subject)}.pdf`;
            zip.file(fileName, pdfBlob);
            successCount++;
            // Free memory
            offscreen.innerHTML = '';
            await new Promise(r => setTimeout(r, 100));

        } catch (err) {
            console.warn(`Failed PDF for ${report.studentName}:`, err);
        }
    }

    isBatchDownloading = false;
    document.body.removeChild(offscreen);

    if (successCount === 0) {
        showFeedbackMessage("No PDFs could be generated.", "error");
        if (btn) { btn.disabled = false; btn.textContent = '📦 Download All PDFs'; }
        return;
    }

    if (btn) btn.textContent = '⏳ Zipping…';

    try {
const zipBlob = await zip.generateAsync({ type: 'blob', compression: 'DEFLATE', compressionOptions: { level: 6 } });
        const url = URL.createObjectURL(zipBlob);
        const a = document.createElement('a');
        a.href = url; a.download = `${sanitizeForFilename(reportTitle)}_All_Reports.zip`;
        document.body.appendChild(a); a.click(); document.body.removeChild(a);
        setTimeout(() => URL.revokeObjectURL(url), 5000);
        showFeedbackMessage(`✅ Downloaded ${successCount} PDF(s) in ZIP!`, "success");
    } catch {
        showFeedbackMessage("Failed to create ZIP file.", "error");
    }

    if (btn) { btn.disabled = false; btn.textContent = '📦 Download All PDFs'; }
}

window.handleDownloadAllReports = handleDownloadAllReports;

/**
 * Compares the graded reports against the class roster to show who was graded and who was absent.
 * Displays this list in a modal.
 */
function handleShowGradingStatus() {
    if (currentAssessmentRoster.length === 0) {
        showFeedbackMessage("The class roster could not be loaded to show student status.", "info");
        return;
    }

    const gradedStudentUids = new Set(assessmentReports.map(r => r.studentUid));
    const allStudents = [...currentAssessmentRoster].sort((a,b) => a.name.localeCompare(b.name));

    const studentListHtml = allStudents.map(student => {
        if (gradedStudentUids.has(student.uid)) {
            return `<li class="graded">${student.name}</li>`;
        } else {
            return `<li class="absent">${student.name}</li>`;
        }
    }).join('');

    studentListModalTitleEl.textContent = "Grading Status";
    studentListModalContentEl.innerHTML = `
        <div class="student-list-column">
            <h4>All Students (${allStudents.length})</h4>
            <ul class="student-status-list">${studentListHtml}</ul>
        </div>
    `;
    toggleModal('student-list-modal', true);
}

