function renderStudentPerformanceScatterPlot() {
    if (assessmentScatterChartInstance) {
        assessmentScatterChartInstance.destroy();
    }

    if (!currentAssessmentToGrade || !currentAssessmentToGrade.questions || currentAssessmentToGrade.questions.length === 0) {
        return;
    }
    const totalQuestions = currentAssessmentToGrade.questions.length;
    
    const scatterData = assessmentReports.map(report => {
        const scorePercentage = report.maximumMarks > 0 ? (report.overallScore / report.maximumMarks) * 100 : 0;
        const attemptPercentage = totalQuestions > 0 ? (report.questionWiseReport.length / totalQuestions) * 100 : 0;
        
        let pointColor = 'rgba(231, 76, 60, 0.8)'; // Red (Low)
        if (scorePercentage > 70) {
            pointColor = 'rgba(46, 204, 113, 0.8)'; // Green (High)
        } else if (scorePercentage > 40) {
            pointColor = 'rgba(243, 156, 18, 0.8)'; // Yellow (Medium)
        }
        
        return {
            x: attemptPercentage,
            y: scorePercentage,
            studentName: report.studentName,
            pointColor: pointColor
        };
    });

    const ctx = assessmentScatterPlotChartEl.getContext('2d');
    if (!ctx) return;
    
    assessmentScatterChartInstance = new window.Chart(ctx, {
        type: 'scatter',
        data: {
            datasets: [{
                label: 'Student Performance',
                data: scatterData,
                backgroundColor: scatterData.map(d => d.pointColor),
                pointRadius: 8,
                pointHoverRadius: 12
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            scales: {
                x: {
                    title: { display: true, text: 'Attempt Rate (%)', font: { size: 14, family: 'Poppins' } },
                    min: 0, 
                    max: 105 
                },
                y: {
                    title: { display: true, text: 'Score (%)', font: { size: 14, family: 'Poppins' } },
                    min: 0, 
                    max: 105
                }
            },
            plugins: {
                legend: { display: false },
                tooltip: {
                    callbacks: {
                        label: function(context) {
                            const dataPoint: any = context.dataset.data[context.dataIndex];
                            return `${dataPoint.studentName}: (${dataPoint.x.toFixed(0)}% attempted, ${dataPoint.y.toFixed(0)}% score)`;
                        }
                    },
                    bodyFont: { size: 13, family: 'Poppins' },
                    titleFont: { size: 14, family: 'Poppins' }
                }
            }
        }
    });
}

function toggleFlash() {
    if (!currentCameraStream) return;
    const track = currentCameraStream.getVideoTracks()[0];
    const capabilities = track.getCapabilities() as any;
    if (capabilities.torch) {
        isFlashOn = !isFlashOn;
       (track as any).applyConstraints({ advanced: [{ torch: isFlashOn }] });
        document.getElementById('flash-text')!.textContent = isFlashOn ? "Flash On" : "Flash Off";
    }
}
