(window as any)._openHomeworkImageViewer = async (studentUid: string, startIndex: number) => {
    const storedPaths: string[] = (window as any)._homeworkPreviewUrls?.[studentUid] || [];
    if (!storedPaths.length) return;

    // Show loading spinner immediately
    document.getElementById('hw-image-viewer-overlay')?.remove();
    const overlay = document.createElement('div');
    overlay.id = 'hw-image-viewer-overlay';
    overlay.style.cssText = `position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,0.85);display:flex;align-items:center;justify-content:center;`;
    overlay.innerHTML = `<div style="color:white;font-size:1rem;">⏳ Loading images...</div>`;
    document.body.appendChild(overlay);

    // Get fresh download URLs NOW (not at load time)
    let freshUrls: string[];
    try {
        freshUrls = await Promise.all(storedPaths.map(async (pathOrUrl: string) => {
            try {
                // If it's a storage path (not a full URL), get fresh download URL
                if (!pathOrUrl.startsWith('https://')) {
                    return await fbStorage.ref(pathOrUrl).getDownloadURL();
                }
                // It's a URL — extract path and refresh
                const pathMatch = new URL(pathOrUrl).pathname.match(/\/o\/([^?]+)/);
                if (pathMatch) {
                    return await fbStorage.ref(decodeURIComponent(pathMatch[1])).getDownloadURL();
                }
                return pathOrUrl;
            } catch (e) {
                console.warn('[Preview] URL refresh failed for:', pathOrUrl, e);
                return pathOrUrl;
            }
        }));
    } catch (e) {
        overlay.innerHTML = `<div style="color:red;">Failed to load images. Please try again.</div>`;
        return;
    }

    let current = startIndex;

    const render = () => {
        overlay.innerHTML = `
            <div style="position:relative;max-width:90vw;max-height:85vh;display:flex;flex-direction:column;align-items:center;gap:12px;">
                <button onclick="document.getElementById('hw-image-viewer-overlay').remove()"
                    style="position:absolute;top:-40px;right:0;background:none;border:none;color:white;font-size:1.6rem;cursor:pointer;line-height:1;">✕</button>
                <div style="color:#ccc;font-size:0.78rem;font-weight:600;letter-spacing:0.05em;">
                    PAGE ${current + 1} OF ${freshUrls.length}
                </div>
                <img src="${freshUrls[current]}"
                    style="max-width:88vw;max-height:75vh;border-radius:12px;object-fit:contain;box-shadow:0 8px 40px rgba(0,0,0,0.6);"
                    onerror="this.alt='Could not load image';this.style.background='#333';this.style.padding='40px';"
                />
                <div style="display:flex;gap:16px;align-items:center;">
                    <button onclick="window._hwViewerNav(-1)"
                        ${current === 0 ? 'disabled' : ''}
                        style="background:${current === 0 ? '#333' : '#4361ee'};color:white;border:none;border-radius:50%;width:40px;height:40px;font-size:1.2rem;cursor:${current === 0 ? 'not-allowed' : 'pointer'};">‹</button>
                    <span style="color:#ccc;font-size:0.82rem;">${current + 1} / ${freshUrls.length}</span>
                    <button onclick="window._hwViewerNav(1)"
                        ${current === freshUrls.length - 1 ? 'disabled' : ''}
                        style="background:${current === freshUrls.length - 1 ? '#333' : '#4361ee'};color:white;border:none;border-radius:50%;width:40px;height:40px;font-size:1.2rem;cursor:${current === freshUrls.length - 1 ? 'not-allowed' : 'pointer'};">›</button>
                </div>
            </div>`;
    };

    (window as any)._hwViewerNav = (delta: number) => {
        current = Math.max(0, Math.min(freshUrls.length - 1, current + delta));
        render();
    };

    render();
};

window.setFsTool = (tool: 'pencil' | 'eraser' | 'tick' | 'cross', pageIdx: number, reportIdx: number) => {
    // If the same tool is clicked, toggle it off.
    activeFsTool = activeFsTool === tool ? null : tool;
    (window as any).activeFsTool = activeFsTool;
    
    // For markers, we need to ensure we have an editing context
    if (activeFsTool === 'tick' || activeFsTool === 'cross') {
        const report = assessmentReports[reportIdx];
        // Ensure we are in an "editing" state for markers

        // Initialize temp steps if not already there
        if (!tempOsmSteps || tempOsmSteps.length === 0) {
            tempOsmSteps = JSON.parse(JSON.stringify(report.questionWiseReport[0]?.stepWiseEvaluation || []));
        }
    } else {
        // Keep markers visible but disable drop logic context if switching to pencil/eraser
        isOsmEditing = false;
    }
    renderReportPageUI(assessmentReports[reportIdx], reportIdx);
};

window.startScribble = (e: MouseEvent, pageIdx: number) => {
    if (activeFsTool !== 'pencil') return;
    isScribbling = true;
    const svg = document.getElementById(`fs-svg-${pageIdx}`) as unknown as SVGSVGElement;
    const rect = svg.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 1000;
    const y = ((e.clientY - rect.top) / rect.height) * 1000;
    
    currentPathData = `M ${x} ${y}`;
    currentPath = document.createElementNS("http://www.w3.org/2000/svg", "path");
    currentPath.setAttribute("d", currentPathData);
   currentPath.setAttribute("stroke", "#2ecc71");
    currentPath.setAttribute("stroke-width", "2");
    currentPath.setAttribute("fill", "none");
    svg.appendChild(currentPath);
};

window.drawScribble = (e: MouseEvent, pageIdx: number) => {
    if (!isScribbling || !currentPath) return;
    const svg = document.getElementById(`fs-svg-${pageIdx}`) as unknown as SVGSVGElement;
    const rect = svg.getBoundingClientRect();
    const x = ((e.clientX - rect.left) / rect.width) * 1000;
    const y = ((e.clientY - rect.top) / rect.height) * 1000;
    
    currentPathData += ` L ${x} ${y}`;
    currentPath.setAttribute("d", currentPathData);
};

window.endScribble = (pageIdx: number, reportIdx: number) => {
    if (!isScribbling) return;
    isScribbling = false;
    const report = assessmentReports[reportIdx];
    if (!report.pencilAnnotations) report.pencilAnnotations = {};
    if (!report.pencilAnnotations[pageIdx]) report.pencilAnnotations[pageIdx] = [];
    
    report.pencilAnnotations[pageIdx].push(currentPathData);
    currentPath = null;
    saveUpdatedAssessmentReport(report);
};

window.clearPencil = (pageIdx: number, reportIdx: number) => {
    if (!confirm("Clear all pencil marks on this page?")) return;
    const report = assessmentReports[reportIdx];
    if (report.pencilAnnotations) delete report.pencilAnnotations[pageIdx];
    renderReportPageUI(report, reportIdx);
    saveUpdatedAssessmentReport(report);
};


window.removeScribble = (reportIndex: number, pageIdx: number, pathIdx: number) => {
    const report = assessmentReports[reportIndex];
    if (report.pencilAnnotations && report.pencilAnnotations[pageIdx]) {
        report.pencilAnnotations[pageIdx].splice(pathIdx, 1);
        renderReportPageUI(report, reportIndex);
        saveUpdatedAssessmentReport(report);
    }
};

