function renderAssessmentReportSummary() {
    // Compute OR-loser-corrected scores for all reports
    const _ctxSumm = currentAssessmentForReportView || currentAssessmentToGrade;
const correctedScoreOf = (r: AIFullAssessmentReport) => {
        const losers = computeOrLoserQNums(r.questionWiseReport || [], _ctxSumm?.questions);
        const active = (r.questionWiseReport || []).filter((qr: any) => !losers.has(qr.questionNumber));
        return {
            score: active.reduce((s: number, qr: any) => s + (qr.marksAwarded || 0), 0),
            max: r.maximumMarks || active.reduce((s: number, qr: any) => s + (qr.maxMarksForQuestion || 0), 0),
        };
    };
    const correctedScores = assessmentReports.map(correctedScoreOf);
    const totalScores = correctedScores.map(c => c.score);
    const totalMaxMarks = correctedScores.map(c => c.max);
    const averageScore = totalScores.length > 0 ? totalScores.reduce((a, b) => a + b, 0) / totalScores.length : 0;
    const averageMaxMarks = totalMaxMarks.length > 0 ? totalMaxMarks.reduce((a, b) => a + b, 0) / totalMaxMarks.length : 0;
    const averagePercentage = averageMaxMarks > 0 ? (averageScore / averageMaxMarks * 100) : 0;

    const percentages = correctedScores.map(c => c.max > 0 ? (c.score / c.max) * 100 : 0);
    const labels = ["0–20", "21–40", "41–60", "61–80", "81–100"];
    const bins = [0, 0, 0, 0, 0];
    percentages.forEach(p => {
        if (p <= 20) bins[0]++; else if (p <= 40) bins[1]++; else if (p <= 60) bins[2]++; else if (p <= 80) bins[3]++; else bins[4]++;
    });
    const barColors = ['#ef4444', '#f97316', '#eab308', '#22c55e', '#16a34a'];
    const maxBin = Math.max(...bins, 1);

    // Quick stats in slim header
    const headerStats = document.getElementById('ar-header-quick-stats');
    if (headerStats) {
        headerStats.innerHTML = `
            <div class="ar-quick-stat"><div class="ar-quick-stat-val">${assessmentReports.length}</div><div class="ar-quick-stat-label">Graded</div></div>
            <div class="ar-quick-stat"><div class="ar-quick-stat-val">${averagePercentage.toFixed(0)}%</div><div class="ar-quick-stat-label">Avg Score</div></div>
            <div class="ar-quick-stat"><div class="ar-quick-stat-val">${averageScore.toFixed(1)}/${averageMaxMarks.toFixed(0)}</div><div class="ar-quick-stat-label">Marks</div></div>
        `;
    }

    // Score distribution custom bars
    const distContainer = document.getElementById('ar-dist-bars-container');
    if (distContainer) {
        distContainer.innerHTML = labels.map((lbl, i) => {
            const heightPct = Math.round((bins[i] / maxBin) * 100);
            return `
                <div class="ar-dist-bar-wrap">
                    <div class="ar-dist-bar-count">${bins[i]}</div>
                    <div class="ar-dist-bar" style="height:${Math.max(heightPct, 4)}%;background:${barColors[i]};"></div>
                    <div class="ar-dist-bar-label">${lbl}</div>
                </div>`;
        }).join('');
    }

    // Top / Needs Help lists
// Top / Needs Help lists
const studentLabel = (r: AIFullAssessmentReport) => {
    const clean = (v: any) => (v && String(v).trim() && !['n/a','student','unknown'].includes(String(v).trim().toLowerCase())) ? String(v).trim() : '';
    const name = clean(r.studentName);
    const roll = clean(r.rollNumber);
    if (name) return name;
    if (roll) return `#${roll}`;
    return 'Student';
};
const sorted = [...assessmentReports].sort((a, b) => {
        const cA = correctedScoreOf(a); const pA = cA.max > 0 ? cA.score / cA.max : 0;
        const cB = correctedScoreOf(b); const pB = cB.max > 0 ? cB.score / cB.max : 0;
        return pB - pA;
    });
    const topList = document.getElementById('ar-top-performers-list');
    const helpList = document.getElementById('ar-needs-help-list');
    const top5 = sorted.slice(0, 5);
    const bot5 = sorted.slice(-5).reverse();
const _ctxPerf = currentAssessmentForReportView || currentAssessmentToGrade;
    const correctedPct = (r: AIFullAssessmentReport) => {
        const losers = computeOrLoserQNums(r.questionWiseReport || [], _ctxPerf?.questions);
        const active = (r.questionWiseReport || []).filter((qr: any) => !losers.has(qr.questionNumber));
        const sc = active.reduce((s: number, qr: any) => s + (qr.marksAwarded || 0), 0);
        const mx = active.reduce((s: number, qr: any) => s + (qr.maxMarksForQuestion || 0), 0);
        return mx > 0 ? (sc / mx * 100).toFixed(0) : '0';
    };
    if (topList) topList.innerHTML = top5.map(r => {
        const pct = correctedPct(r);
return `<div class="ar-perf-item top"><span>${studentLabel(r)}</span><span class="ar-perf-item-score">${pct}%</span></div>`;
    }).join('') || '<div style="color:#aaa;font-size:0.8rem;">No data</div>';
    if (helpList) helpList.innerHTML = bot5.map(r => {
        const pct = correctedPct(r);
return `<div class="ar-perf-item help"><span>${studentLabel(r)}</span><span class="ar-perf-item-score">${pct}%</span></div>`;
    }).join('') || '<div style="color:#aaa;font-size:0.8rem;">No data</div>';
}


window.handleDeleteStudentReport = async (reportIndex: number) => {
    const report = assessmentReports[reportIndex];
    if (!report || !teacherProfile || !currentAssessmentForReportView) return;

    const confirmMessage = `Are you sure you want to delete the report for ${report.studentName}? \n\nThis will permanently remove the score and feedback from the database. This action cannot be undone.`;
    
    if (!confirm(confirmMessage)) return;

    toggleLoading(true, "Deleting report...");

    try {
        // 1. Delete from Firestore
        if (report.submissionDocId) {
            await fbFirestore
                .collection('teachers').doc(teacherProfile.uid)
                .collection('assessmentHistory').doc(currentAssessmentForReportView.assessmentId)
                .collection('submissions').doc(report.submissionDocId)
                .delete();
        } else {
            console.warn("Report missing submissionDocId, removing from local view only.");
        }

        // 2. Remove from local array
        assessmentReports.splice(reportIndex, 1);

        // 3. Re-render the view to update table and summary stats
        renderAssessmentReportView();
        
        showFeedbackMessage(`Report for ${report.studentName} deleted successfully.`, "success");

    } catch (error) {
        console.error("Error deleting report:", error);
        showFeedbackMessage("Failed to delete the report from the database.", "error");
    } finally {
        toggleLoading(false);
    }
};

