const toggleSymbol = isCorrect ? '✓' : (isMissing ? '!' : '✗');
const toggleColor = isCorrect ? '#16a34a' : (isMissing ? '#d97706' : '#dc2626');
const isMcqType = ['MCQ','True/False','Fill in the Blanks','Assertion-Reason','AR'].includes(originalQ?.type || '');
const rowMinHeight = isCorrect ? '22px' : (isMcqType ? '22px' : '60px');
const safeComment = isMcqType ? '' : (step.comment || '').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fLabel = 'F' + (globalIdx + 1);
