return '<div style="position:relative; display:flex; align-items:flex-start; background:' + bg + '; border:1px solid ' + border + '30; border-left:3px solid ' + border + '; border-radius:4px; padding:1px 1px; min-height:' + rowMinHeight + ';">'
    + '<div style="display:flex;flex-direction:column;align-items:center;gap:1px;margin:2px 3px 2px 2px;flex-shrink:0;">'
