+ '<textarea id="' + noteId + '-edit" style="display:none; width:100%; font-size:' + (isCorrect ? '0.75rem' : '0.82rem') + '; border:1px solid #ccc; border-radius:3px; background:white; resize:vertical; color:#1a1a1a; line-height:1.3; min-height:' + rowMinHeight + '; outline:none; font-family:monospace; padding:2px 4px; box-sizing:border-box;"'
+ ' onblur="window.osmNoteEndEdit(\'' + noteId + '\', ' + reportIndex + ', ' + originalIndex + ', ' + globalIdx + ', this.value)">'
+ safeComment + '</textarea>'
