<select class="styled-select" 
      style="width:48px; padding:1px 5px; font-size:0.68rem; height:20px; background:#6b7280; color:white; border:none; border-radius:4px; font-weight:600; cursor:pointer; flex-shrink:0;"

      onchange="window.handleManualPageChange(${reportIndex}, ${originalIndex}, this.value)">
${(report.answerSheetImageUrls || []).map((_, pIdx) => `<option value="${pIdx}" ${pIdx === qr.answerPageIndex ? 'selected' : ''}> ${pIdx + 1}</option>`).join('')}
  </select>
