const jumpAction = (isExtra) ? "" : `onclick=\"window.jumpToGradingCard('${qr.questionNumber}', ${qr.answerPageIndex || 0}, '${report.studentUid}')\"`;
                            
const globalQIdx = report.questionWiseReport.indexOf(qr);
