let osmPointerDragStepIdx: number | null = null;

window.handleOsmPointerDown = (event: PointerEvent, stepIdx: number) => {
    event.preventDefault();
    event.stopPropagation();
    osmPointerDragStepIdx = stepIdx;
    document.addEventListener('pointermove', window.handleOsmPointerMove);
    document.addEventListener('pointerup', window.handleOsmPointerUp);
};

window.handleOsmPointerMove = (event: PointerEvent) => {
    if (osmPointerDragStepIdx === null || !osmEditingContext) return;
    const step = tempOsmSteps[osmPointerDragStepIdx];
    if (!step) return;

    const isFS = document.getElementById('fullscreen-grading-modal')?.style.display === 'flex';
    const overlayId = isFS ? `fs-osm-overlay-layer-${step.pageIndex}` : 'osm-overlay-layer';
    const overlay = document.getElementById(overlayId);
    const wrapper = overlay?.closest('.osm-inner-wrapper') || overlay?.parentElement?.querySelector('.osm-inner-wrapper');
    const targetImg = (wrapper?.querySelector('img') as HTMLImageElement | null)
        || document.getElementById('current-report-image') as HTMLImageElement | null;
    if (!targetImg) return;

    const rect = targetImg.getBoundingClientRect();
    const x = Math.max(0, Math.min(1000, ((event.clientX - rect.left) / rect.width) * 1000));
    const y = Math.max(0, Math.min(1000, ((event.clientY - rect.top) / rect.height) * 1000));

    step.stepPoint = [y, x];
    renderEditableAnnotations(step.pageIndex);
};

window.handleOsmPointerUp = (event: PointerEvent) => {
    osmPointerDragStepIdx = null;
    document.removeEventListener('pointermove', window.handleOsmPointerMove);
    document.removeEventListener('pointerup', window.handleOsmPointerUp);
};

window.renderEditableAnnotations = renderEditableAnnotations;
/**
 * Adds a new marker to the temporary list.
 * If we're in edit mode, adds to tempOsmSteps. Otherwise, adds directly to the report.
 */
function handleOsmAddMarker(isCorrect: boolean, explicitPageIdx?: number) {
    const reportIndex = (window as any).currentOsmReportIndex;
    if (reportIndex === undefined) {
        showFeedbackMessage("No report loaded. Please open a student report first.", "error");
        return;
    }
    
    const report = assessmentReports[reportIndex];
    if (!report) {
        showFeedbackMessage("Report not found.", "error");
        return;
    }

    // If we're in edit mode, use the tempOsmSteps buffer
    if (isOsmEditing && osmEditingContext) {
        const questionReport = report.questionWiseReport[osmEditingContext.questionIndex];
        const targetPage = explicitPageIdx !== undefined ? explicitPageIdx : (questionReport.answerPageIndex || 0);

        const newStep: AIStepEvaluation = {
            stepDescription: 'Manual Marker',
            comment: isCorrect ? 'Correct' : 'Incorrect',
            marks: isCorrect ? 1 : 0,
            pageIndex: targetPage,
            stepPoint: [100, 100] // Default center-top
        };
        tempOsmSteps.push(newStep);
        renderEditableAnnotations(targetPage);
        return;
    }

    // --- NEW: Direct add mode (no edit mode required) ---
    // Find the question that corresponds to the current page or the first question
    const currentPage = (window as any).currentReportPageIdx || 0;
    
    // Find a question that has markers on this page, or use the first question
    let targetQIdx = report.questionWiseReport.findIndex(qr => {
        const fb = (qr.finalFeedback || '').toLowerCase();

        return (qr.answerPageIndex === currentPage) || 
               (qr.stepWiseEvaluation || []).some(s => (s as any).pageIndex - 1 === currentPage);
    });
    
    // If no question found on this page, use the first question that has markers
    if (targetQIdx === -1) {
        targetQIdx = report.questionWiseReport.findIndex(qr => {
            const fb = (qr.finalFeedback || '').toLowerCase();
return true;
        });
    }
    
    // If still no question, use the first question
    if (targetQIdx === -1) targetQIdx = 0;
    
    const qr = report.questionWiseReport[targetQIdx];
    if (!qr) {
        showFeedbackMessage("No valid question found to add a marker.", "error");
        return;
    }

    // Push the grading undo state
    pushGradingUndo(report);

    // Create the new step
    const newStep: AIStepEvaluation = {
        stepDescription: 'Manual Marker',
        comment: isCorrect ? 'Correct' : 'Incorrect',
        marks: isCorrect ? (qr.maxMarksForQuestion || 1) : 0,
        pageIndex: currentPage + 1, // 1-based for storage
        stepPoint: [500, 920] // Default position (middle of page, right side)
    };

    // Add to the question's stepWiseEvaluation
    if (!qr.stepWiseEvaluation) qr.stepWiseEvaluation = [];
    qr.stepWiseEvaluation.push(newStep);

    // Recalculate total score
    report.overallScore = report.questionWiseReport.reduce((sum, q) => sum + q.marksAwarded, 0);

    // Save and re-render
    saveUpdatedAssessmentReport(report);
    renderReportPageUI(report, reportIndex);
    renderAssessmentReportView();
    
    showFeedbackMessage(`Added ${isCorrect ? '✓ correct' : '✗ incorrect'} marker to Q${qr.questionNumber}`, "success");
}
window.handleOsmAddMarker = handleOsmAddMarker;

(window as any).isOsmEditing = false; // will be kept in sync

/**
 * Removes a marker from the temporary list.
 */
function handleOsmRemoveMarker(stepIndex: number) {
    if (!tempOsmSteps[stepIndex]) return; // Safety check
    
    // Store the page index before we remove the item from the array
    const pageIdx = tempOsmSteps[stepIndex].pageIndex;
    
    tempOsmSteps.splice(stepIndex, 1);
    
    // Re-render the specific page to reflect the removal
    renderEditableAnnotations(pageIdx);
}


