// NEW — cycles: correct → incorrect → missing → correct
window.handleOsmToggleMarkerType = (reportIndex: number, questionIndex: number, stepIndex: number) => {
    const report = assessmentReports[reportIndex];
    if (!report) return;
    const step = report.questionWiseReport[questionIndex]?.stepWiseEvaluation?.[stepIndex];
    if (!step) return;
    window.pushGradingUndo(JSON.parse(JSON.stringify(report)));
    const commentLower = (step.comment || '').toLowerCase();
    const isMissing = !!(step as any).isMissing;
    const isCorrect = !isMissing && (step.marks > 0 || commentLower.includes('correct'));

    const isIncorrect = !isMissing && !isCorrect;

    if (isCorrect) {
        // correct → incorrect
        step.marks = 0;
        (step as any).isMissing = false;
        if (!step.comment || commentLower === 'correct') step.comment = 'Incorrect';
    } else if (isIncorrect) {
        // incorrect → missing
        step.marks = 0;
        (step as any).isMissing = true;
        if (!step.comment || commentLower === 'incorrect') step.comment = 'Missing';
    } else {
        // missing → correct
        const qr = report.questionWiseReport[questionIndex];
        step.marks = qr?.maxMarksForQuestion || 1;
        (step as any).isMissing = false;
        if (!step.comment || commentLower === 'missing') step.comment = 'Correct';
    }
    const rIdx = assessmentReports.indexOf(report);
    renderReportPageUI(report, rIdx !== -1 ? rIdx : reportIndex);
};

