/**
 * Refreshes the score summary table UI after a mark update.
 */
function refreshScoreSummaryTable(reportIndex: number) {
    const report = assessmentReports[reportIndex];
    if (!report) return;

    const container = document.getElementById('score-summary-container');
    if (!container) return;

   const _ctx2 = currentAssessmentForReportView || currentAssessmentToGrade;
    const _orLosers2 = computeOrLoserQNums(report.questionWiseReport, _ctx2?.questions);
    const allQuestions = report.questionWiseReport.filter((qr: any) => !_orLosers2.has(qr.questionNumber));
const hasSections = !!(currentAssessmentForReportView?.hasSections);

    const getSectionLetter = (qNum: string): string => {
        const m = String(qNum).match(/^([A-Z])(?=\d)/);
        return m ? m[1] : '';
    };

const buildRow = (qr: any): string => {
        const feedback = qr.finalFeedback || "";
        const isExtra = feedback.toLowerCase().includes("already attempted");
        const isUndetected = isUnattemptedFb(feedback);
        let displayScore = qr.marksAwarded.toFixed(1);
        let colorClass = "";
if (isExtra) {
            displayScore = "-";
            colorClass = "score-extra";
} else {
            const pct = qr.maxMarksForQuestion > 0 ? (qr.marksAwarded / qr.maxMarksForQuestion) * 100 : 0;
            colorClass = pct > 70 ? "score-high" : pct > 40 ? "score-medium" : "score-low";
        }
const jumpAction = isExtra ? "" : `onclick="window.jumpToGradingCard('${qr.questionNumber}', ${qr.answerPageIndex || 0}, '${report.studentUid}')"`;
const globalQIdx = allQuestions.indexOf(qr);
        const totalPages = (report.answerSheetImageUrls || []).length || 1;
        const currentPage = qr.answerPageIndex ?? 0;
        const pageOptions = Array.from({length: totalPages}, (_, pi) =>
            `<option value="${pi}" ${currentPage===pi?'selected':''}> ${pi+1}</option>`
        ).join('');
        return `<tr>
            <td class="${(isExtra || isUndetected) ? "" : "q-jump-link"}" ${jumpAction}>
                ${qr.questionNumber}
                ${qr.requiresReview ? `<span class="caution-flag-mini">⚠️</span>` : ''}
            </td>
            <td style="padding:2px 3px;">
                <select style="font-size:0.50rem;padding:0.5px 2px;border:1px solid #ddd;border-radius:2px;width:40px;cursor:pointer;background:#fafafa;"
                    onchange="window.handleManualPageChange(${reportIndex}, ${globalQIdx}, this.value)"
                    onclick="event.stopPropagation()">
                    ${pageOptions}
                </select>
            </td>
            <td>${qr.maxMarksForQuestion}</td>
            <td class="obtained-cell ${colorClass}">${displayScore}</td>
        </tr>`;
    };

    let html = '';

    if (hasSections) {
        const sectionMap: Map<string, any[]> = new Map();
        for (const qr of allQuestions) {
            const sec = getSectionLetter(String(qr.questionNumber)) || '?';
            if (!sectionMap.has(sec)) sectionMap.set(sec, []);
            sectionMap.get(sec)!.push(qr);
        }
        for (const [sec, qs] of sectionMap.entries()) {
for (let i = 0; i < qs.length; i += 5) {
                const chunk = qs.slice(i, i + 5);
                const isFirstChunk = i === 0;
                html += `<table class="score-summary-column-table">
                    <thead>
${isFirstChunk ? `<tr><th colspan="4" style="background:#3949ab;color:#fff;font-size:0.6rem;letter-spacing:1px;text-transform:uppercase;padding:4px 8px;text-align:left;">Section ${sec}</th></tr>` : ''}
<tr><th style="width:90px;">Q.No</th><th style="width:100px;"></th><th>Max</th><th>Score</th></tr>       
             </thead>
                    <tbody>${chunk.map(buildRow).join('')}</tbody>
                </table>`;
            }
        }
    } else {
        const reportChunks: any[][] = [];
for (let i = 0; i < allQuestions.length; i += 5) {
        reportChunks.push(allQuestions.slice(i, i + 5));
        }
        html = reportChunks.map(chunk => `
            <table class="score-summary-column-table">
<thead><tr><th style="width:90px;">Q.No</th><th style="width:100px;"></th><th>Max</th><th>Score</th></tr></thead>
                <tbody>${chunk.map(buildRow).join('')}</tbody>
            </table>
        `).join('');
    }

    container.innerHTML = html;
}


