window.handleUpdateScoreFromModal = (reportIndex: number, questionIndex: number) => {
    const report = assessmentReports[reportIndex];
    if (!report) return;

    pushGradingUndo(report);

    const isFS = document.getElementById('fullscreen-grading-modal')?.style.display === 'flex';
    const prefix = isFS ? 'fs-' : '';

    const inputEl = document.getElementById(`${prefix}modal-score-input-${reportIndex}-${questionIndex}`) as HTMLInputElement;
    const maxScore = report.questionWiseReport[questionIndex].maxMarksForQuestion;
    let newValue = parseFloat(inputEl.value);

    if (isNaN(newValue) || newValue < 0) newValue = 0;
    else if (newValue > maxScore) newValue = maxScore;
    
    inputEl.value = newValue.toFixed(1);

    // Update Input Styling
    const questionPercentage = maxScore > 0 ? (newValue / maxScore) * 100 : 0;
    let newScoreClass = 'score-low';
    if (questionPercentage > 70) newScoreClass = 'score-high';
    else if (questionPercentage > 40) newScoreClass = 'score-medium';
    
    inputEl.className = `editable-score-input fs-score-input-compact ${newScoreClass}`;

    const feedbackBox = document.getElementById(`modal-feedback-input-${reportIndex}-${questionIndex}`);
    if (feedbackBox) feedbackBox.className = newScoreClass;

// Update Data + AUDIT
    const _auditOldMarks = report.questionWiseReport[questionIndex].marksAwarded;
    report.questionWiseReport[questionIndex].marksAwarded = newValue;
    if (_auditOldMarks !== newValue) {
        writeAuditLog({
            actionType: 'marks_changed',
            studentUid: report.studentUid,
            studentName: (report as any).studentName || report.studentUid,
            questionNumber: report.questionWiseReport[questionIndex].questionNumber,
            oldValue: String(_auditOldMarks),
            newValue: String(newValue),
        });
    }
    if (report.questionWiseReport[questionIndex].stepWiseEvaluation?.length > 0) {
        report.questionWiseReport[questionIndex].stepWiseEvaluation[0].marks = newValue;
    }

    const newTotalScore = report.questionWiseReport.reduce((sum, qr) => sum + qr.marksAwarded, 0);
    report.overallScore = newTotalScore;
    const newPercentage = report.maximumMarks > 0 ? (newTotalScore / report.maximumMarks * 100) : 0;

    // --- NEW: Refresh UI Elements ---
    
    // 1. Update Header/Footer Stats
    const statsContainer = document.getElementById('individual-report-stats');
    if (statsContainer) {
        const modalScoreEl = statsContainer.querySelector('.stat-card:nth-child(1) .stat-main-value');
        const modalPercentEl = statsContainer.querySelector('.stat-card:nth-child(2) .stat-main-value');
        const modalPercentCardEl = statsContainer.querySelector('.stat-card:nth-child(2)');

        if(modalScoreEl) modalScoreEl.textContent = `${newTotalScore.toFixed(1)} / ${report.maximumMarks}`;
        if(modalPercentEl) modalPercentEl.textContent = `${newPercentage.toFixed(0)}%`;
        if(modalPercentCardEl) {
             let pctClass = newPercentage > 70 ? 'score-high' : newPercentage > 40 ? 'score-medium' : 'score-low';
             modalPercentCardEl.className = `stat-card ${pctClass}`;
        }
    }

    // 2. Refresh the Summary Table
    refreshScoreSummaryTable(reportIndex);
    
    // 3. Save to DB
    saveUpdatedAssessmentReport(report);
};
