window.handleRegradeSinglePage = async (reportIndex: number, pageIndex: number) => {
    const report = assessmentReports[reportIndex];
    if (!report) return;

    if (!confirm(`Are you sure you want to re-run OCR and Grading for Page ${pageIndex + 1}? This will replace existing feedback for questions on this page.`)) {
        return;
    }

    // Reuse the existing recheck logic but force it to target exactly this one page
    // handleExecuteRecheck takes (studentUid, targetPageNumbers [1-based])
    try {
        // Show a localized loading state in the transcript box if possible, 
        // otherwise use the global toggle
        toggleLoading(true, `Re-scanning Page ${pageIndex + 1}...`);
        
        // This function (already in your codebase) handles the proxy fetch, 
        // OCR, and targeted regrading of questions mapped to this page.
        await handleExecuteRecheck(report.studentUid, [pageIndex + 1]);
        
        // The handleExecuteRecheck function ends by calling renderAssessmentReportView() 
        // and renderIndividualStudentReportInModal(). We need to ensure Fullscreen stays open.
        // Re-render the Fullscreen UI to show the new data
        renderReportPageUI(assessmentReports[reportIndex], reportIndex);
        
        showFeedbackMessage(`Page ${pageIndex + 1} updated successfully.`, "success");
    } catch (error) {
        console.error("Single page regrade failed:", error);
        showFeedbackMessage("Failed to recheck page. Please try again.", "error");
    } finally {
        toggleLoading(false);
    }
};


window.handleDownloadStudentImages = async (studentUid: string) => {
    const report = assessmentReports.find(r => r.studentUid === studentUid);
    if (!report || !report.answerSheetImageUrls || report.answerSheetImageUrls.length === 0) {
        showFeedbackMessage("No images available to download.", "error");
        return;
    }

    toggleLoading(true, "Creating ZIP archive...");
    try {
        const zip = new (window as any).JSZip();
        const folder = zip.folder(`${sanitizeForFilename(report.studentName)}_Answers`);

for (let i = 0; i < report.answerSheetImageUrls.length; i++) {
    const url = report.answerSheetImageUrls[i];
    
    // Fetch via your existing backend proxy to bypass CORS
    const proxyResponse = await fetch(BACKEND_OCR_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: 'fetch_image', url: url })
    });
    
    if (!proxyResponse.ok) throw new Error("Proxy fetch failed");
    
    const data = await proxyResponse.json();
    // Convert returned base64 back to a Blob for the ZIP
    const byteCharacters = atob(data.base64);
    const byteNumbers = new Array(byteCharacters.length);
    for (let j = 0; j < byteCharacters.length; j++) {
        byteNumbers[j] = byteCharacters.charCodeAt(j);
    }
    const byteArray = new Uint8Array(byteNumbers);
    const blob = new Blob([byteArray], { type: data.mimeType || 'image/jpeg' });
    
    const extension = (data.mimeType || 'image/jpeg').split('/')[1] || 'jpg';
    folder.file(`Page_${i + 1}.${extension}`, blob);
}

        const content = await zip.generateAsync({ type: "blob" });
        (window as any).saveAs(content, `${sanitizeForFilename(report.studentName)}_Answers.zip`);
        showFeedbackMessage("ZIP file downloaded successfully!", "success");
    } catch (e) {
        console.error("ZIP Error:", e);
        showFeedbackMessage("Failed to create ZIP file.", "error");
    } finally {
        toggleLoading(false);
    }
};


window.handleOpenRecheckModal = (studentUid: string) => {
    recheckTargetUid = studentUid;
    recheckTargetMode = 'all';
    window.handleRecheckType('all');
    (document.getElementById('recheck-pages-input') as HTMLInputElement).value = '';
    toggleModal('recheck-options-modal', true);
};

window.handleRecheckType = (mode: 'all' | 'specific') => {
    recheckTargetMode = mode;
    const allBtn = document.getElementById('btn-recheck-all');
    const specBtn = document.getElementById('btn-recheck-specific');
    const inputCont = document.getElementById('specific-pages-input-container');

    if (mode === 'all') {
        allBtn?.classList.add('active');
        specBtn?.classList.remove('active');
        if (inputCont) inputCont.style.display = 'none';
    } else {
        allBtn?.classList.remove('active');
        specBtn?.classList.add('active');
        if (inputCont) inputCont.style.display = 'block';
    }
};

window.toggleFeedbackEdit = (reportIndex, questionIndex, isEditing) => {
    const isFS = document.getElementById('fullscreen-grading-modal')?.style.display === 'flex';
    const prefix = isFS ? 'fs-' : '';
    const viewEl = document.getElementById(`${prefix}feedback-view-${reportIndex}-${questionIndex}`);
    const editEl = document.getElementById(`${prefix}feedback-edit-${reportIndex}-${questionIndex}`);
    const textarea = editEl?.querySelector('textarea');
    
    if (viewEl && editEl && textarea) {
        if (isEditing) {
            // Before showing the edit view, ensure the textarea has the latest raw value from state
            const report = assessmentReports[reportIndex];
            if (report) {
                textarea.value = report.questionWiseReport[questionIndex].finalFeedback;
            }
            viewEl.style.display = 'none';
            editEl.style.display = 'block';
            textarea.focus();
        } else {
            // Cancel was clicked, so just switch back
            viewEl.style.display = 'block';
            editEl.style.display = 'none';
        }
    }
};

window.saveFeedbackEdit = async (reportIndex, questionIndex) => {
    const isFS = document.getElementById('fullscreen-grading-modal')?.style.display === 'flex';
    const prefix = isFS ? 'fs-' : '';
    const report = assessmentReports[reportIndex];
    const viewEl = document.getElementById(`${prefix}feedback-view-${reportIndex}-${questionIndex}`);
    const editEl = document.getElementById(`${prefix}feedback-edit-${reportIndex}-${questionIndex}`);
    const staticContentEl = viewEl?.querySelector('.static-feedback-content');
    const textarea = editEl?.querySelector('textarea');

    if (!report || !viewEl || !editEl || !staticContentEl || !textarea) return;

    // 1. Get new feedback and update local state
    const newFeedback = textarea.value;
    report.questionWiseReport[questionIndex].finalFeedback = newFeedback;

    // 2. Save to DB (reuses existing function)
    saveUpdatedAssessmentReport(report);

    // 3. Update the static view with the newly formatted content
    staticContentEl.innerHTML = formatMathExpressions(newFeedback);
    
    // 4. Important: Re-run MathJax on the updated element
    await typesetMathInContainer(staticContentEl as HTMLElement);

    // 5. Switch back to view mode
    viewEl.style.display = 'block';
    editEl.style.display = 'none';
};



