async function handleTeacherRegistration(event: Event) {
    event.preventDefault();
    clearFeedbackMessage();

    const name = teacherRegisterNameInputEl.value;
    const email = teacherRegisterEmailInputEl.value;
    const password = teacherRegisterPasswordInputEl.value;
    const phone = teacherRegisterPhoneInputEl.value;
    const classes = Array.from(teacherRegisterClassesSelectEl.selectedOptions).map(opt => opt.value);
    const subjects = Array.from(teacherRegisterSubjectsSelectEl.selectedOptions).map(opt => opt.value);
    let schoolName = teacherRegisterSchoolInputEl.value.trim();
    let board = (teacherRegisterSchoolInputEl as HTMLInputElement).dataset.board || '';
    let isNewSchool = false;

    if (!name || !email || !password || !schoolName || classes.length === 0 || subjects.length === 0 || !phone) {
        showFeedbackMessage("Please fill out all required fields marked with an asterisk (*).", "error");
        return;
    }



    toggleLoading(true, "Registering...");

    // Handle case where user types a new school not from suggestions
    if (teacherRegisterOtherSchoolContainerEl.style.display === 'block') {
        schoolName = teacherRegisterSchoolOtherInputEl.value.trim();
        board = teacherRegisterBoardOtherInputEl.value.trim();
        isNewSchool = true;
    } else if (!board && schoolName) {
        const foundSchool = allSchoolsFromCSV.find(s => s.SchoolName.toLowerCase() === schoolName.toLowerCase());
        if (foundSchool) {
            board = foundSchool.Board;
        } else {
            showFeedbackMessage("School not found in our list. Please use the 'School not listed?' option to add it with its board.", 'error');
            toggleLoading(false);
            return;
        }
    }
    
    if (!board) {
        showFeedbackMessage("Your selected school is missing a board. Please select a school from the list or add a new one.", "error");
        toggleLoading(false);
        return;
    }

    try {
        const profile = await registerTeacher({ name, email, password, schoolName, board, classes, subjects, isNewSchool, phone });
        teacherProfile = profile;
        updateTeacherHeader(profile);
        updateUIVisibility('teacher_dashboard');
    } catch (error: any) {
        console.error("Registration error:", error);
        showFeedbackMessage(error.message || "Registration failed. Please try again.", "error");
    } finally {
        toggleLoading(false);
    }
}

