async function handleTeacherLogin(event: Event) {
    event.preventDefault();
    toggleLoading(true, "Logging in...");
    
    // Hide the specific login error message on a new attempt
    loginErrorMessageEl.style.display = 'none';
    loginErrorMessageEl.textContent = '';
    clearFeedbackMessage(); // Also clear any global messages

    const email = teacherLoginEmailInputEl.value;
    const password = teacherLoginPasswordInputEl.value;

    try {
        await fbAuth.signInWithEmailAndPassword(email, password);
        // On success, onAuthStateChanged will handle navigation.
    } catch (error: any) {
        console.error("Login error:", error.code); 
        
        let message = "Login failed. Please check your email and password and try again.";

        switch (error.code) {
            case 'auth/invalid-credential':
            case 'auth/user-not-found':
            case 'auth/wrong-password':
                message = "Invalid credentials. Please check your email and password.";
                break;
            case 'auth/invalid-email':
                message = "The email address format is not valid.";
                break;
            case 'auth/user-disabled':
                message = "This user account has been disabled by an administrator.";
                break;
        }
        
        // Show the error message in the specific div below the password field
        loginErrorMessageEl.textContent = message;
        loginErrorMessageEl.style.display = 'block';

        toggleLoading(false); 
    }
}

async function handleForgotPassword(event: Event) {
    event.preventDefault();
    
    // 1. Get the email directly from the login form's input field.
    const email = teacherLoginEmailInputEl.value.trim();

    // 2. Check if the email field is empty.
    if (!email) {
        showFeedbackMessage("Please enter your email address in the field above before clicking 'Forgot Password'.", "info");
        teacherLoginEmailInputEl.focus(); // Guide the user to the email field
        return;
    }

    // 3. Proceed with sending the reset link.
    toggleLoading(true, "Sending reset link...");
    try {
        await fbAuth.sendPasswordResetEmail(email);
        showFeedbackMessage(`Password reset email sent to ${email}. Please check your inbox.`, "success");
    } catch (error: any) {
        console.error("Forgot password error:", error);
        
        let message = "Failed to send reset link. Please try again.";
        if (error.code === 'auth/user-not-found' || error.code === 'auth/invalid-email') {
            message = "No account found with that email address.";
        }
        showFeedbackMessage(message, "error");

    } finally {
        toggleLoading(false);
    }
}


