async function handleCreateNewClassBatch(event: Event) {
    event.preventDefault();
    if (!teacherProfile) return;
    toggleLoading(true, "Creating class...");

    const className = createClassBatchClassSelectEl.value;
    const subject = createClassBatchSubjectSelectEl.value;
    let section = createClassBatchSectionSelectEl.value;
    if (section === 'Other') {
        section = createClassBatchSectionCustomInputEl.value.trim();
    }

    if (!className || !subject || !section) {
        showFeedbackMessage("Please select a class, subject, and section.", "error");
        toggleLoading(false);
        return;
    }

   const rosterId = generateRosterId(teacherProfile.uid, className, section, subject, section === 'Other' ? undefined : (document.getElementById('create-class-batch-stream-select') as HTMLSelectElement)?.value);

    try {
        const existingRosterDoc = await fbFirestore.collection('classRosters').doc(rosterId).get();
        if (existingRosterDoc.exists) {
            showFeedbackMessage(`A class for ${subject} (Class ${className} - ${section}) already exists.`, "error");
            toggleLoading(false);
            return;
        }

        const newRoster: ClassRoster = {
            id: rosterId,
            teacherUid: teacherProfile.uid,
            className: className,
            section: section,
            subject: subject,
            schoolName: teacherProfile.schoolName,
            board: currentClassForHomeworkCreation?.board || teacherProfile.board,
            students: [],
            inviteCode: generateInviteCode()
        };

        // Save the critical roster data first
        await saveClassRoster(newRoster);
        
        // --- UI updates now happen immediately after successful roster creation ---
        toggleModal('create-class-batch-modal', false);
        const allHomeworks = await getAssignedHomeworks(teacherProfile.uid); // Fetch latest homeworks
        renderClassSidebar(allTeacherRosters);
renderClassCard(newRoster);
        showFeedbackMessage("Class created successfully!", "success");
        
        // --- Handle non-critical tasks in the background ---
        const newInvite: ClassInvite = {
            rosterId: newRoster.id,
            teacherName: teacherProfile.name,
            teacherUid: teacherProfile.uid,
            schoolName: newRoster.schoolName,
            board: newRoster.board,
            className: newRoster.className,
            section: newRoster.section,
            subject: newRoster.subject
        };

        // Save the invite, but don't block the user or show an error if it fails
        saveClassInvite(newInvite, newRoster.inviteCode!).catch(inviteError => {
            console.warn("Class was created, but failed to save the invite code:", inviteError);
        });

    } catch (error) {
        console.error("Error creating new class:", error);
        showFeedbackMessage("Failed to create the new class. Please check your database connection and try again.", "error");
    } finally {
        toggleLoading(false);
    }
}

async function generateImageForQuestion(index: number) {
    if (!temporaryHomeworkData.questions || !temporaryHomeworkData.questions[index] || !fbStorage) return;

    const question = temporaryHomeworkData.questions[index];
    if (!question.imagePrompt) return;

    try {
        // --- THIS IS THE NEW API CALL ---
        const response = await getAiInstance().models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: {
                parts: [{ text: question.imagePrompt }],
            },
            config: {
                responseModalities: [Modality.IMAGE],
            },
        });

        // --- THIS IS THE NEW COST TRACKING BLOCK ---
        if (teacherProfile) {
            logApiUsage({
                teacherProfile,
                feature: 'Homework Image Generation',
                model: 'gemini-2.5-flash-image', // Updated model name
                units: {
                    inputChars: question.imagePrompt.length,
                    imagesGenerated: 1
                }
            });
        }

        // --- THIS IS THE NEW RESPONSE PARSING LOGIC ---
        let foundBase64: string | null = null;
        if (response.candidates?.[0]?.content?.parts) {
            for (const part of response.candidates[0].content.parts) {
                if (part.inlineData && part.inlineData.mimeType.startsWith('image/')) {
                    foundBase64 = part.inlineData.data;
                    break;
                }
            }
        }

        if (foundBase64) {
            const homeworkId = temporaryHomeworkData.homeworkId || `temp_${Date.now()}`;
            const imagePath = `homework-images/${homeworkId}/${question.id}.jpg`;
            
            const imageUrl = await uploadBase64ToStorage(foundBase64, imagePath);
            
            question.imageUrl = imageUrl;
            
            displayAIQuestionsForReview();
        } else {
            throw new Error("No image data returned from AI.");
        }
    } catch (imgError) {
        console.warn(`Could not generate image for question ${index}`, imgError);
        const card = document.getElementById(`review-q-${index}`);
        const imageContainer = card?.querySelector('.question-image-container');
        if(imageContainer) {
            imageContainer.innerHTML = `<p class="error-text" style="font-size:0.8rem;">Image failed to generate.</p>`;
        }
        question.imageUrl = null; 
        displayAIQuestionsForReview();
    }
}

// --- PASTE THIS ENTIRE CORRECTED FUNCTION IN PLACE OF THE OLD ONE ---

async function startQuestionGenerationStream(
    keptQuestions: AIQuestion[] = [], 
    regenerationOptions?: { 
        count: number; 
        questionType: QuestionType; 
        difficultyLevel: string;
        bloomLevel?: number;
        bloomName?: string;
        cognitiveTarget?: string;
    }
) {
    const { source } = temporaryHomeworkData;
    let imageFiles: File[] = [];
    if (source === 'book_images') imageFiles = uploadedBookPageImages;
    if (source === 'question_images') imageFiles = uploadedQuestionImages;

    let solutionFiles: File[] = [];
    if (source === 'question_images' && hwMyQSolutionInputEl) {
        solutionFiles = Array.from(hwMyQSolutionInputEl.files || []);
    }

    temporaryHomeworkData.questions = [...keptQuestions];
    updateUIVisibility('teacher_homework_ai_review');
    displayAIQuestionsForReview(); // Show kept questions immediately
    displayHomeworkReviewSummary();

    const numToGenerate = regenerationOptions ? regenerationOptions.count : (temporaryHomeworkData.numberOfQuestions || 0) - keptQuestions.length;

    let spinnerText: string;
    if (source === 'question_images') {
        spinnerText = "AI is extracting questions from your images...";
    } else {
        spinnerText = `AI is generating ${numToGenerate} new question${numToGenerate !== 1 ? 's' : ''}...`;
    }

    const spinnerHtml = `<div id="regeneration-spinner" class="spinner-container"><div class="spinner-small"></div> <p>${spinnerText}</p></div>`;

    if (temporaryHomeworkData.questions.length > 0) {
        aiQuestionsPreviewContainerEl.insertAdjacentHTML('beforeend', spinnerHtml);
    } else {
        aiQuestionsPreviewContainerEl.innerHTML = spinnerHtml.replace('id="regeneration-spinner"', '');
    }
const generationConfig = {
        ...temporaryHomeworkData,
        ...(regenerationOptions && {
            numberOfQuestions: regenerationOptions.count,
            questionType: regenerationOptions.questionType,
            questionTypes: [regenerationOptions.questionType], // <--- FIX: Ensure array exists for prompt
            difficultyLevel: regenerationOptions.difficultyLevel,
            bloomLevel: regenerationOptions.bloomLevel,
            bloomName: regenerationOptions.bloomName,
            cognitiveTarget: regenerationOptions.cognitiveTarget
        })
    };


    // --- CORRECTED STRUCTURE: CALLBACKS DEFINED SEPARATELY ---

    const onQuestionGenerated = async (newQuestion: AIQuestion) => { // Make it async
    document.getElementById('regeneration-spinner')?.remove();
    if (temporaryHomeworkData.questions?.length === 0) {
        aiQuestionsPreviewContainerEl.innerHTML = '';
    }

    if (!newQuestion.questionNumber) {
    newQuestion.questionNumber = (temporaryHomeworkData.questions.length + 1).toString();
}

    temporaryHomeworkData.questions?.push(newQuestion);
    const newQuestionIndex = temporaryHomeworkData.questions!.length - 1;

    // Call our new, efficient function instead of the old one
    await appendAndRenderQuestionCard(newQuestion, newQuestionIndex, aiQuestionsPreviewContainerEl, imageFiles);

    displayHomeworkReviewSummary(); // Update the summary count
};

    // This callback handles what to do AFTER the entire stream is finished.
    const onGenerationComplete = () => {
        document.getElementById('regeneration-spinner')?.remove();
        if (temporaryHomeworkData.questions?.length === keptQuestions.length) {
            const messageEl = document.createElement('p');
            messageEl.className = 'info-text';
            messageEl.textContent = 'The AI did not generate any new questions. Please try adjusting your criteria or rephrasing the topic.';
            aiQuestionsPreviewContainerEl.appendChild(messageEl);
        }
        displayHomeworkReviewSummary();
    };

    // --- CORRECTED STRUCTURE: TRY/CATCH BLOCK AT THE MAIN LEVEL ---

    try {
        if (source !== 'question_images' && numToGenerate <= 0) {
            onGenerationComplete();
            return;
        }

        switch (source) {
            case 'curriculum':
                await streamGenerateQuestionsFromTopics(generationConfig, onQuestionGenerated);
                break;
            case 'book_images':
                await streamGenerateQuestionsFromBookImages(generationConfig, imageFiles, onQuestionGenerated);
                break;
            case 'question_images':
                await streamExtractQuestionsFromImages(generationConfig, imageFiles, solutionFiles, onQuestionGenerated);
                break;
        }
        // Once the `await` above is done, the stream is complete.
        onGenerationComplete();

    } catch (error: any) {
        console.error(`Error during question generation from ${source}:`, error);
        const errorMessage = `Failed to generate questions. ${error.message}`;
        showFeedbackMessage(errorMessage, 'error', true);
        aiQuestionsPreviewContainerEl.innerHTML = `<p class="error-text">${errorMessage}</p>`;
    }
}


