async function handleRegenerateQuestions() {
    if (!temporaryHomeworkData) return;
    
    // Setup modal with current homework settings
    const keptQuestionsCount = temporaryHomeworkData.questions?.filter(q => q.kept).length || 0;
    const currentTotal = temporaryHomeworkData.numberOfQuestions || 5;
    const defaultNew = Math.max(1, 5 - keptQuestionsCount);

    regenNumQuestionsSelectEl.value = defaultNew.toString();
    regenQuestionTypeSelectEl.value = temporaryHomeworkData.questionType || 'Subjective';
    regenDifficultySelectEl.value = temporaryHomeworkData.difficultyLevel || 'Medium';

    toggleModal('regeneration-options-modal', true);
}


function handleFileSelection(inputEl: HTMLInputElement, previewAreaEl: HTMLDivElement, fileArray: File[]) {
    if (!inputEl.files) return;
    const files = Array.from(inputEl.files);
    
    const validImageFiles = files.filter(file => ALLOWED_IMAGE_TYPES.includes(file.type));
    if(validImageFiles.length !== files.length) {
        showFeedbackMessage(`Some files were not valid image types (${ALLOWED_IMAGE_TYPES.join(', ')}). Only valid images were added.`, 'info');
    }

    if (fileArray.length + validImageFiles.length > MAX_IMAGE_UPLOADS) {
        showFeedbackMessage(`You can only upload a maximum of ${MAX_IMAGE_UPLOADS} files.`, 'error');
        validImageFiles.splice(MAX_IMAGE_UPLOADS - fileArray.length); // trim excess
    }

    fileArray.push(...validImageFiles);
    renderImagePreviews(previewAreaEl, fileArray);
}

function renderImagePreviews(previewAreaEl: HTMLDivElement, fileArray: File[]) {
    if (fileArray.length === 0) {
        previewAreaEl.innerHTML = `<p class="image-preview-placeholder">No images uploaded yet.</p>`;
        return;
    }
    previewAreaEl.innerHTML = ''; // Clear existing previews
    fileArray.forEach((file, index) => {
        const previewContainer = document.createElement('div');
        const isPdf = file.type === 'application/pdf';

        if (isPdf) {
            // Show a clean filename chip for PDFs (can't display PDF as <img>)
            previewContainer.className = 'image-preview-item image-preview-pdf';
            previewContainer.style.cssText = 'display:flex;align-items:center;gap:8px;background:#f0f4ff;border:1px solid #c7d2fe;border-radius:10px;padding:10px 14px;font-size:0.8rem;font-weight:600;color:#3730a3;max-width:100%;overflow:hidden;';
            previewContainer.innerHTML = `
                <span style="font-size:1.4rem;flex-shrink:0;">📄</span>
                <span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${file.name}">${file.name}</span>
                <span style="font-size:0.7rem;color:#94a3b8;flex-shrink:0;">${(file.size / 1024 / 1024).toFixed(1)} MB</span>`;
        } else {
            // Show image thumbnail
            previewContainer.className = 'image-preview-item';
            const img = document.createElement('img');
            img.src = URL.createObjectURL(file);
            img.onload = () => URL.revokeObjectURL(img.src);
            previewContainer.appendChild(img);
        }

        const removeBtn = document.createElement('button');
        removeBtn.className = 'remove-image-btn';
        removeBtn.innerHTML = '&times;';
        removeBtn.onclick = () => {
            fileArray.splice(index, 1);
            renderImagePreviews(previewAreaEl, fileArray);
        };

        previewContainer.appendChild(removeBtn);
        previewAreaEl.appendChild(previewContainer);
    });
}


