function sortCorners(pts: number[]) {
    // 1. Convert flat array to point objects
    const points = [
        { x: pts[0], y: pts[1] },
        { x: pts[2], y: pts[3] },
        { x: pts[4], y: pts[5] },
        { x: pts[6], y: pts[7] }
    ];

    // 2. Calculate Centroid
    const cx = (points[0].x + points[1].x + points[2].x + points[3].x) / 4;
    const cy = (points[0].y + points[1].y + points[2].y + points[3].y) / 4;

    // 3. Sort by angle to ensure consistent clockwise/counter-clockwise order
    points.sort((a, b) => {
        return Math.atan2(a.y - cy, a.x - cx) - Math.atan2(b.y - cy, b.x - cx);
    });

    // 4. Rotate array so Top-Left is first (point with min x+y usually)
    // This prevents the "twisted crop" bug
    let tlIndex = 0;
    let minSum = Infinity;
    for (let i = 0; i < 4; i++) {
        const sum = points[i].x + points[i].y;
        if (sum < minSum) {
            minSum = sum;
            tlIndex = i;
        }
    }
    const sorted = [...points.slice(tlIndex), ...points.slice(0, tlIndex)];

    return [sorted[0].x, sorted[0].y, sorted[1].x, sorted[1].y, sorted[2].x, sorted[2].y, sorted[3].x, sorted[3].y];
}
