function scanDocumentLoop() {
    if (!currentCameraStream || !isCVLoaded) return;

    const now = Date.now();
    // Only run the heavy OpenCV processing every 200ms (10 frames per sec) to save mobile CPU
    if (now - lastScanTimestamp < 200) {
        scannerAnimationFrame = requestAnimationFrame(scanDocumentLoop);
        return;
    }
    lastScanTimestamp = now;

    const video = cameraStreamEl;
    const canvas = document.getElementById('scanner-overlay') as HTMLCanvasElement;
    const ctx = canvas.getContext('2d');

    if (!video || video.videoWidth === 0 || video.videoHeight === 0 || !ctx) {
        scannerAnimationFrame = requestAnimationFrame(scanDocumentLoop);
        return;
    }

    // Initialize the persistent canvas once
    if (!persistentScanCanvas) {
        persistentScanCanvas = document.createElement('canvas');
        persistentScanCtx = persistentScanCanvas.getContext('2d', { alpha: false });
    }

    const processingWidth = 480;
    const scale = video.videoWidth / processingWidth;
    const processingHeight = video.videoHeight / scale;

    persistentScanCanvas.width = processingWidth;
    persistentScanCanvas.height = processingHeight;
    persistentScanCtx!.drawImage(video, 0, 0, processingWidth, processingHeight);

    // ... (rest of the drawing logic below remains same)

    const tempCanvas = document.createElement('canvas');
    tempCanvas.width = processingWidth;
    tempCanvas.height = processingHeight;
    const tempCtx = tempCanvas.getContext('2d');
    if (!tempCtx) return;

    tempCtx.drawImage(video, 0, 0, processingWidth, processingHeight);

    let src: any = null, dst: any = null, contours: any = null, hierarchy: any = null;
    let gray: any = null, M: any = null;

try {
        // --- CHANGE: Force documentContour to null to disable warping ---
        documentContour = null;

        // 1. Clear Canvas for drawing
canvas.width = canvas.clientWidth;
canvas.height = canvas.clientHeight;
ctx.clearRect(0, 0, canvas.width, canvas.height);
        // 2. Auto Capture Logic (Time-based only)
        if (isAutoCapturing) {
             const statusEl = document.getElementById('camera-overlay-status');
             const now = Date.now();
             const timeElapsed = now - lastAutoCaptureTime;
             const cycleTime = 8000; // 8 seconds
             
             if (timeElapsed >= cycleTime) {
                 // Visual Flash Effect
                 ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
                 ctx.fillRect(0, 0, canvas.width, canvas.height);
                 
                 // Trigger Capture (Will use center crop because documentContour is null)
                 takePhoto(); 
                 lastAutoCaptureTime = now;
                 if (statusEl) statusEl.textContent = "Captured!";
             } else {
                 // Update Countdown Display
                 const secondsLeft = Math.ceil((cycleTime - timeElapsed) / 1000);
                 if (statusEl) statusEl.textContent = `Scanning in ${secondsLeft}...`;
             }
        }

       const videoRatio = video.videoWidth / video.videoHeight;
const canvasRatio = canvas.width / canvas.height;
let actualW, actualH, offsetX, offsetY;

if (videoRatio > canvasRatio) {
    actualW = canvas.width;
    actualH = canvas.width / videoRatio;
    offsetX = 0;
    offsetY = (canvas.height - actualH) / 2;
} else {
    actualH = canvas.height;
    actualW = canvas.height * videoRatio;
    offsetY = 0;
    offsetX = (canvas.width - actualW) / 2;
}

ctx.strokeStyle = 'rgba(255, 255, 255, 0.9)';
ctx.lineWidth = 3;
// Draw the frame exactly covering the video feed area
ctx.strokeRect(offsetX, offsetY, actualW, actualH);

    } catch (err) {
        // Prevent crashing loop on CV error
        console.error(err);
    } finally {
        // Clean up OpenCV objects to prevent memory leaks
        if (src) src.delete();
        if (dst) dst.delete();
        if (gray) gray.delete();
        if (M) M.delete();
        if (contours) contours.delete();
        if (hierarchy) hierarchy.delete();
    }

    scannerAnimationFrame = requestAnimationFrame(scanDocumentLoop);
}

