function takePhoto(forcedContourPoints?: number[]) {
    if (navigator.vibrate) navigator.vibrate(50); // Haptic feedback
    if (!cameraStreamEl) return;

    // Visual feedback for the button
    const btn = document.getElementById('snap-photo-btn');
    if(btn) { 
        btn.style.transform = 'scale(0.9)';
        setTimeout(() => btn.style.transform = 'scale(1)', 100);
    }

    const activeRetakeIndex = retakeIndex;
    const targetIndex = (activeRetakeIndex !== null && activeRetakeIndex < capturedImagesInModal.length) 
        ? activeRetakeIndex 
        : capturedImagesInModal.length;
    
    const pageNum = activeRetakeIndex !== null ? activeRetakeIndex + 1 : (captureCounter);
    const filename = `Page_${pageNum}.jpg`;

    if (activeRetakeIndex === null) {
        captureCounter++;
    }
    retakeIndex = null; 

    const video = cameraStreamEl;
    const canvas = document.createElement('canvas');
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    ctx.drawImage(video, 0, 0);

    // 1. INSTANT UI FEEDBACK: Create a quick blob for the thumbnail
    canvas.toBlob((rawBlob) => {
        if (!rawBlob) return;
        const rawFile = new File([rawBlob], filename, { type: 'image/jpeg' });
        capturedImagesInModal[targetIndex] = rawFile;
        updateCameraScrollPreviews(); // The thumbnail appears immediately now

        // 2. BACKGROUND PROCESSING: Run OpenCV enhancement without freezing the UI
        setTimeout(async () => {
            if (!window.cv || !isCVLoaded) return;
            try {
                let src = window.cv.imread(canvas);
                let dst = new window.cv.Mat();
                src.copyTo(dst); // Simple copy since we disabled warping

                // Fast Enhancement
                let hsv = new window.cv.Mat();
                window.cv.cvtColor(dst, hsv, window.cv.COLOR_RGB2HSV);
                let hsvChannels = new window.cv.MatVector();
                window.cv.split(hsv, hsvChannels);
                let sChan = hsvChannels.get(1);
                sChan.convertTo(sChan, -1, 1.2, 5); 
                hsvChannels.set(1, sChan);
                window.cv.merge(hsvChannels, hsv);
                window.cv.cvtColor(hsv, dst, window.cv.COLOR_HSV2RGB);

                const finalCanvas = document.createElement('canvas');
                window.cv.imshow(finalCanvas, dst);

                // Export at lower quality (0.7) for speed
                finalCanvas.toBlob((eBlob) => {
                    if (eBlob) {
                        const enhancedFile = new File([eBlob], filename, { type: 'image/jpeg' });
                        capturedImagesInModal[targetIndex] = enhancedFile;
                        // Silently update the thumbnail in background
                    }
                }, 'image/jpeg', 0.70);

                src.delete(); dst.delete(); hsv.delete(); hsvChannels.delete(); sChan.delete();
            } catch (e) { console.error("Filter failed", e); }
        }, 10); // Small delay allows UI to render the first thumbnail instantly

    }, 'image/jpeg', 0.5); // Fast, low-quality initial capture for the preview
}

async function handlePrintHomework() {
    if (!temporaryHomeworkData.questions) {
        showFeedbackMessage("No questions to print.", "info");
        return;
    }

    const questionsToPrint = temporaryHomeworkData.questions.filter(q => q.kept);
    if (questionsToPrint.length === 0) {
        showFeedbackMessage("No questions have been kept to print.", "info");
        return;
    }

    const { subject, className, section, customTopic, selectedChapters, source } = temporaryHomeworkData;
    const topicDisplay = customTopic || (Array.isArray(selectedChapters) ? selectedChapters.join(', ') : 'General');
    const totalMarks = questionsToPrint.reduce((sum, q) => sum + (q.marks || 0), 0);

    const printHtml = generateModernQuestionPaperHtml(
        `Homework: ${topicDisplay}`,
        {
            schoolName: teacherProfile?.schoolName || 'Your School',
            subject: subject!,
            className: className!,
            section: section!
        },
        totalMarks,
        questionsToPrint,
        { printType: 'questions', source }
    );

    printableContentEl.innerHTML = printHtml;
    await typesetMathInContainer(printableContentEl);
    
    setTimeout(() => {
        window.print();
    }, 250);
}

