async function updateCopyModalSections() {
    const selectedClass = copyAsClassSelectEl.value;
    const selectedSubject = copyAsSubjectSelectEl.value;

    copyAsSectionContainerEl.innerHTML = '';

    if (!selectedClass || !selectedSubject) {
        copyAsSectionContainerEl.innerHTML = '<p class="description">Please select Class and Subject first.</p>';
        return;
    }

    if (!teacherProfile || !teacherProfile.schoolName) {
        copyAsSectionContainerEl.innerHTML = '<p class="error-text">School information missing. Cannot fetch sections.</p>';
        return;
    }

    // Show loading state
    copyAsSectionContainerEl.innerHTML = '<div class="spinner-small"></div>';

    try {
        // Query Firestore for ALL rosters in this school matching the criteria
        const snapshot = await fbFirestore.collection('classRosters')
            .where('schoolName', '==', teacherProfile.schoolName)
            .where('className', '==', selectedClass)
            .where('subject', '==', selectedSubject)
            .get();

        if (snapshot.empty) {
            copyAsSectionContainerEl.innerHTML = '<p class="description">No active sections found for this subject/class in the school.</p>';
            return;
        }
const rosterOptions = new Map<string, { section: string, teacherUid: string, teacherName: string }>();

snapshot.docs.forEach(doc => {
    const data = doc.data();
    const sec = data.section || data.targetSection;
    const tUid = data.teacherUid;
    const tName = data.teacherName || data.teacherEmail || 'Unknown Teacher';
    
    if (sec && tUid) {
        const key = `${tUid}::${sec}`;
        if (!rosterOptions.has(key)) {
            rosterOptions.set(key, { section: sec, teacherUid: tUid, teacherName: tName });
        }
    }
});

const sortedOptions = Array.from(rosterOptions.values()).sort((a, b) => 
    a.section.localeCompare(b.section) || a.teacherName.localeCompare(b.teacherName)
);

        copyAsSectionContainerEl.innerHTML = ''; // Clear spinner

        if (sortedOptions.length === 0) {
            copyAsSectionContainerEl.innerHTML = '<p class="description">No valid sections found.</p>';
            return;
        }

        // Render Checkboxes
        sortedOptions.forEach(opt => {
            const wrapper = document.createElement('div');
            wrapper.className = 'checkbox-group';
            wrapper.style.marginBottom = '5px';
            
            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.name = 'copy-section';
            // IMPORTANT: We store BOTH the owner UID and the section name in the value
            checkbox.value = `${opt.teacherUid}::${opt.section}`;
            checkbox.id = `copy-section-${opt.teacherUid}-${opt.section}`;
            
            const label = document.createElement('label');
            label.htmlFor = checkbox.id;
            
            // If the section belongs to another teacher, maybe indicate it? 
            // For now, we just show the section name to keep it clean.
         label.textContent = `Section ${opt.section} — ${opt.teacherName}`;
            
            wrapper.appendChild(checkbox);
            wrapper.appendChild(label);
            copyAsSectionContainerEl.appendChild(wrapper);
        });

    } catch (error) {
        console.error("Error fetching school sections:", error);
        copyAsSectionContainerEl.innerHTML = '<p class="error-text">Failed to load sections.</p>';
    }
}

async function handleInitiateCopyAssessment(assessment: CreatedAssessment) {
    if (!teacherProfile) return;
    currentAssessmentToCopy = assessment;
    
    // 1. Ensure we have the latest roster data for filtering
    if (allTeacherRosters.length === 0) {
        toggleLoading(true, "Loading class data...");
        allTeacherRosters = await syncAllRostersInBackground(teacherProfile.uid, teacherProfile.schoolName);
        toggleLoading(false);
    }

    // 2. Reset inputs
    copyAssessmentFormEl.reset();
    
    // 3. Populate Class & Subject Dropdowns
    populateClassDropdowns([copyAsClassSelectEl]);
    populateSubjectDropdownForHomeworkCreation([copyAsSubjectSelectEl]);
    
    // 4. Pre-fill Subject (from the assessment being copied)
    copyAsSubjectSelectEl.value = assessment.subject;

    // 5. Attach Change Listeners to trigger section updates
    // Remove old listeners to prevent duplicates (cloning is a quick hack for this)
    const newClassSelect = copyAsClassSelectEl.cloneNode(true) as HTMLSelectElement;
    copyAsClassSelectEl.parentNode?.replaceChild(newClassSelect, copyAsClassSelectEl);
    copyAsClassSelectEl = newClassSelect;

    const newSubjectSelect = copyAsSubjectSelectEl.cloneNode(true) as HTMLSelectElement;
    copyAsSubjectSelectEl.parentNode?.replaceChild(newSubjectSelect, copyAsSubjectSelectEl);
    copyAsSubjectSelectEl = newSubjectSelect;

    copyAsClassSelectEl.addEventListener('change', updateCopyModalSections);
    copyAsSubjectSelectEl.addEventListener('change', updateCopyModalSections);

    // 6. Initial render of sections (will likely be empty until class is picked)
    updateCopyModalSections();

    toggleModal('copy-assessment-modal', true);
}

async function handleConfirmCopyAssessment(event: Event) {
    event.preventDefault();
    if (!teacherProfile || !currentAssessmentToCopy) return;

    const targetClass = copyAsClassSelectEl.value;
    const targetSubject = copyAsSubjectSelectEl.value;
    
    // Get all checked checkboxes directly
    const checkboxes = copyAsSectionContainerEl.querySelectorAll('input[name="copy-section"]:checked');
    
    if (!targetClass || !targetSubject || checkboxes.length === 0) {
        showFeedbackMessage("Please select Class, Subject, and at least one Section.", "error");
        return;
    }

    toggleLoading(true, `Copying assessment to ${checkboxes.length} section(s)...`);

    try {
        // Iterate over the actual checkbox elements to get the composite values
        const copyPromises = Array.from(checkboxes).map(async (checkbox: any) => {
            const rawValue = checkbox.value; // Format: "teacherUid::sectionName"
            
            let targetTeacherUid = teacherProfile!.uid;
            let targetSection = rawValue;

            // Parse the composite key
            if (rawValue.includes('::')) {
                const parts = rawValue.split('::');
                targetTeacherUid = parts[0];
                targetSection = parts[1];
            }

            // CRITICAL FIX: Save to the TARGET TEACHER'S collection, not the current user's
            const newAssessmentRef = fbFirestore.collection('teachers').doc(targetTeacherUid).collection('assessmentHistory').doc();
            const newAssessmentId = newAssessmentRef.id;
            
            // Deep copy questions
            const questionsCopy = JSON.parse(JSON.stringify(currentAssessmentToCopy!.questions));

            const newAssessment: CreatedAssessment = {
                ...currentAssessmentToCopy!,
                assessmentId: newAssessmentId,
                creationTimestamp: new Date().toISOString(),
                className: targetClass,
                section: targetSection,
                subject: targetSubject,
                questions: questionsCopy,
                // Update ownership metadata to the target teacher
                createdByTeacherUid: targetTeacherUid, 
                // We keep the original teacher name or we could fetch the new one. 
                // Keeping original name preserves "created by" context, 
                // but usually copying implies transfer of ownership.
                // For safety in this specific flow, we leave teacherName as is or set it to 'Assigned Teacher' 
                // to avoid fetching extra data.
                teacherName: currentAssessmentToCopy!.teacherName, 
                schoolName: teacherProfile!.schoolName,
                board: teacherProfile!.board
            };

            return newAssessmentRef.set(sanitizeObjectForFirestore(newAssessment));
        });

        await Promise.all(copyPromises);

        showFeedbackMessage(`Assessment copied successfully!`, "success");
        toggleModal('copy-assessment-modal', false);
        await handleLoadAssessmentHistory(); 

    } catch (error) {
        console.error("Assessment copy failed:", error);
        showFeedbackMessage("Failed to copy the assessment. Please try again.", "error");
    } finally {
        toggleLoading(false);
    }
}

