    const handleAutoActivate = (e: Event) => {
        const target = e.target as HTMLElement;
        // Find the parent card
        const card = target.closest('.bloom-level-card');
        // If we changed an input (like number of questions) but NOT the toggle itself
       if (card) {
            const toggle = card.querySelector('.bloom-level-toggle') as HTMLInputElement;
            const details = card as HTMLDetailsElement;
            
            // If it's currently off, turn it on!
            if (toggle && !toggle.checked) {
                toggle.checked = true;
                card.classList.add('level-active');
            }
            // Ensure the card is expanded visually
            if (details && !details.open) {
                details.open = true;
            }
        }
    };

