(document.getElementById('add-missing-question-form') as HTMLFormElement).addEventListener('submit', async (event) => {
    event.preventDefault();
    const questionNumberInput = document.getElementById('missing-question-number-input') as HTMLInputElement;
    const rawInput = questionNumberInput.value.trim();
    if (!rawInput) return;

    // 1. Parse multiple question numbers (split by comma)
    const questionNumbers = rawInput.split(',').map(s => s.trim()).filter(s => s !== "");

    if (questionNumbers.length === 0) return;

    const isHomework = currentStage === 'teacher_homework_ai_review';
    const temporaryData = isHomework ? temporaryHomeworkData : temporaryAssessmentData;
    const displayFn = isHomework ? displayAIQuestionsForReview : displayAssessmentQuestionsForReview;

    toggleModal('add-missing-question-modal', false);

    const questionFiles = uploadedQuestionImages;
    const solutionFiles = Array.from((isHomework ? hwMyQSolutionInputEl : asMyQSolutionInputEl).files || []);
    
    // Process files once
    toggleLoading(true, `Preparing images...`);
    const processedQuestionFiles = await Promise.all(questionFiles.map(processImageFile));
    const processedSolutionFiles = await Promise.all(solutionFiles.map(processImageFile));
    const questionImageParts = await Promise.all(processedQuestionFiles.map(fileToPart));
    const solutionImageParts = await Promise.all(processedSolutionFiles.map(fileToPart));

    let addedCount = 0;
    let failedList: string[] = [];

    // 2. Loop through each number and fetch sequentially
    for (let i = 0; i < questionNumbers.length; i++) {
        const qNum = questionNumbers[i];
        toggleLoading(true, `Finding Question ${qNum} (${i + 1}/${questionNumbers.length})...`);

        try {
            const newQuestion = await getSingleQuestionFromImages(qNum, temporaryData, questionImageParts, solutionImageParts);

            if (newQuestion.text === "NOT_FOUND") {
                failedList.push(qNum);
            } else {
                // Determine source type for tagging if missing
                if (!newQuestion.type) {
                    if (newQuestion.options && newQuestion.options.length > 0) newQuestion.type = 'MCQ';
                    else if ((newQuestion.text.includes('Assertion') && newQuestion.text.includes('Reason'))) newQuestion.type = 'Assertion-Reason';
                    else newQuestion.type = 'Subjective';
                }

                temporaryData.questions?.push(newQuestion);
                temporaryData.questions?.sort(naturalSortQuestions); // Add this line
addedCount++;
                addedCount++;
            }
        } catch (error) {
            console.error(`Error finding question ${qNum}:`, error);
            failedList.push(qNum);
        }
    }

    // 3. Finalize
    if (addedCount > 0) {
        temporaryData.questions?.sort(naturalSortQuestions);
        displayFn(); // Re-render the list
    }

    toggleLoading(false);
    questionNumberInput.value = '';

    // 4. Show summary feedback
    if (failedList.length === 0) {
        showFeedbackMessage(`Successfully added ${addedCount} question(s)!`, "success");
    } else {
        const msg = `Added ${addedCount} questions. Could not find: ${failedList.join(', ')}. Please check the numbers.`;
        showFeedbackMessage(msg, addedCount > 0 ? "info" : "error", true);
    }
});

