window.handleDownloadCSV = function() {
    if (!currentAssessmentForReportView || assessmentReports.length === 0) {
        showFeedbackMessage('No report data to export.', 'info');
        return;
    }
    const school = teacherProfile?.schoolName || '';
    const cls = currentAssessmentForReportView.className || '';
    const section = currentAssessmentForReportView.section || '';
    const test = currentAssessmentForReportView.assessmentTitle || '';
    const subject = currentAssessmentForReportView.subject || '';
    const date = new Date().toLocaleDateString('en-IN');

    const headers = ['Student Name', 'Roll Number', 'School', 'Class', 'Section', 'Subject', 'Test Name', 'Date', 'Score', 'Max Marks', 'Percentage', 'Status'];
    const rows = assessmentReports.map(r => {
        const pct = r.maximumMarks > 0 ? Math.round(r.overallScore / r.maximumMarks * 100) : 0;
        const status = pct >= 75 ? 'Excellent' : pct >= 50 ? 'Average' : 'Needs Attention';
        return [
            r.studentName,
            r.rollNumber || '',
            school,
            cls,
            section,
            subject,
            test,
            date,
            r.overallScore,
            r.maximumMarks,
            pct + '%',
            status
        ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(',');
    });

    const csv = [headers.join(','), ...rows].join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${sanitizeForFilename(test)}_${cls}${section}_Results.csv`;
    a.click();
    URL.revokeObjectURL(url);
};

