    // HW Regen Modal
confirmRegenerationBtnEl.addEventListener('click', () => {
    if (!temporaryHomeworkData) return;

    const newQuestionsCount = parseInt(regenNumQuestionsSelectEl.value, 10);
    const regenType = regenQuestionTypeSelectEl.value as QuestionType;
    const regenDifficulty = regenDifficultySelectEl.value;

    // --- NEW: Read Bloom's Selection ---
    const bloomLevelIndex = parseInt((document.getElementById('regen-bloom-level') as HTMLSelectElement).value, 10) - 1;
    const bloomLevelData = [
        { name: "Remember", target: "Recall facts, terms, definitions" }, 
        { name: "Understand", target: "Explain, interpret, summarize" },
        { name: "Apply", target: "Use concepts in new contexts" }, 
        { name: "Analyze", target: "Break down, infer patterns, compare" },
        { name: "Evaluate", target: "Judge, justify using evidence" }, 
        { name: "Create", target: "Design, propose, construct new ideas" }
    ];
    const selectedBloom = bloomLevelData[bloomLevelIndex];
    // -----------------------------------

    // Add the new number of questions to the total for summary purposes
    temporaryHomeworkData.numberOfQuestions = (temporaryHomeworkData.numberOfQuestions || 0) + newQuestionsCount;
    const keptQuestions = temporaryHomeworkData.questions?.filter(q => q.kept) || [];

    const regenerationOptions = {
        count: newQuestionsCount,
        questionType: regenType,
        difficultyLevel: regenDifficulty,
        bloomLevel: bloomLevelIndex + 1,
        bloomName: selectedBloom.name,
        cognitiveTarget: selectedBloom.target
    };

    toggleModal('regeneration-options-modal', false);
    startQuestionGenerationStream(keptQuestions, regenerationOptions);
});

