fileInputsToPreview.forEach(({ input, preview }) => {
    input.addEventListener('change', () => {
        if (!input.files) {
            preview.innerHTML = `<p class="file-preview-placeholder">No files selected.</p>`;
            return;
        }
        const allFiles = Array.from(input.files);
        const validFiles = allFiles.filter(file => ALLOWED_IMAGE_TYPES.includes(file.type));

        if (validFiles.length !== allFiles.length) {
            showFeedbackMessage(`Some files were invalid and were ignored. Allowed formats are images and PDF.`, 'info');
        }
        
        if (validFiles.length > 0) {
            // Update the input's files property to only contain valid files.
            const dataTransfer = new DataTransfer();
            validFiles.forEach(file => dataTransfer.items.add(file));
            input.files = dataTransfer.files;

            preview.innerHTML = validFiles.map(f => `<span class="file-chip">${f.name}</span>`).join('');
        } else {
            input.value = ''; // Clear the input if no valid files were selected
            preview.innerHTML = `<p class="file-preview-placeholder">No valid files selected.</p>`;
        }
    });
});
