// Solution Key Preview Listeners
    // hw-myq-solution-upload is static HTML in index.html — wire it here
    // as-myq-solution-upload is dynamic (built by buildMyQFormHtml) — wired in wireAssessmentTabListeners()
    (() => {
        const input = document.getElementById('hw-myq-solution-upload') as HTMLInputElement;
        const preview = document.getElementById('hw-myq-solution-preview') as HTMLDivElement;
        if (input && preview) {
            input.addEventListener('change', () => {
                if (!input.files?.length) { preview.innerHTML = ''; return; }
                preview.innerHTML = Array.from(input.files).map(f =>
                    `<span class="file-chip" style="background:#e0f7fa;color:#006064;border:1px solid #b2ebf2;">📎 ${f.name}</span>`
                ).join('');
            });
        }
    })();

    // ── Assignment "My Questions" → Excel upload ──────────────────────────────
    // Mirrors the Exams Excel flow (see the as-myq-excel-upload handler in
    // wireAssessmentTabListeners) using the exact same parseExcelToQuestions()
    // parser, so the workbook format is identical for Exams and Assignments.
    // hw-myq-excel-upload is static HTML in index.html, so it is wired once here.
    (() => {
        const excelInput = document.getElementById('hw-myq-excel-upload') as HTMLInputElement;
        if (!excelInput) return;
        excelInput.addEventListener('change', async () => {
            const file = excelInput.files?.[0];
            if (!file) return;

            const subjectEl = document.getElementById('hw-myq-subject-select') as HTMLSelectElement;
            const classEl = document.getElementById('hw-myq-class-select') as HTMLSelectElement;
            const sectionSelectEl = document.getElementById('hw-myq-section-select') as HTMLSelectElement;
            const section = sectionSelectEl?.value === 'Other'
                ? (document.getElementById('hw-myq-section-custom-input') as HTMLInputElement)?.value || ''
                : sectionSelectEl?.value || '';

            // Assignments have no title field, so validate the fields that
            // handleConfirmSaveHomework() actually requires.
            if (!subjectEl?.value || !classEl?.value || !section) {
                showFeedbackMessage('Select Subject, Class and Section first.', 'error');
                excelInput.value = '';
                return;
            }

            // The AI-extraction path (question_images source, see ~line 26640) already
            // requires a question paper upload before proceeding — the Excel path must
            // too, so students always have the original paper to view, regardless of
            // which method built the question list.
            if (uploadedQuestionImages.length === 0) {
                showFeedbackMessage('Please upload the original question paper (image/PDF) before uploading the Excel file — students need to see the original paper.', 'error');
                excelInput.value = '';
                return;
            }

            toggleLoading(true, 'Parsing Excel...');
            try {
                const questions = await parseExcelToQuestions(file);
                if (questions.length === 0) { showFeedbackMessage('No questions found in Excel.', 'error'); return; }

                temporaryHomeworkData = {
                    createdByTeacherUid: teacherProfile!.uid,
                    teacherName: teacherProfile!.name,
                    schoolName: teacherProfile!.schoolName,
                    board: currentClassForHomeworkCreation?.board || teacherProfile!.board,
                    source: 'question_images',
                    subject: subjectEl.value,
                    className: classEl.value,
                    section,
                    customTopic: (document.getElementById('hw-myq-topic-input') as HTMLInputElement)?.value.trim() || '',
                    dueDate: (document.getElementById('hw-myq-due-date-input') as HTMLInputElement)?.value || '',
                    checkingStrictness: (document.getElementById('hw-myq-checking-strictness-select') as HTMLSelectElement)?.value || 'Moderate',
                    totalMarks: parseInt((document.getElementById('hw-myq-total-marks') as HTMLInputElement)?.value || '0', 10),
                    questions: [],
                };

                displayHomeworkReviewSummary();
                updateUIVisibility('teacher_homework_ai_review');
                const container = document.getElementById('ai-questions-preview-container') as HTMLDivElement;
                container.innerHTML = '';
                for (let i = 0; i < questions.length; i++) {
                    temporaryHomeworkData.questions!.push(questions[i]);
                    await appendAndRenderQuestionCard(questions[i], i, container, []);
                }
                showFeedbackMessage(`✅ ${questions.length} questions loaded. Review and save.`, 'success');
            } catch (err: any) {
                showFeedbackMessage('Excel parse failed: ' + err.message, 'error');
            } finally {
                toggleLoading(false);
                excelInput.value = '';
            }
        });
    })();

